UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის ჯანსაღი ზრდისა და განვითარებისთვის სწორი კვება ძალიან მნიშვნელოვანია. დაბადების მომენტიდან მან ცილები, ნახშირწყლები, ცხიმები, ვიტამინები და მინერალები დაბალანსებულად და ასაკის შესაბამისი რაოდენობით უნდა მიიღოს. ვინაიდან 0-12 თვე ყველაზე სწრაფი ზრდის პერიოდია, ბავშვს ამ დროს მეტი ენერგია სჭირდება. ამ პერიოდში მის ორგანიზმში ახალი ქსოვილების წარმოქმნისა და კუნთების განვითარების გამო ცილების, მინერალებისა და ვიტამინების საჭიროება იზრდება. სხეულის ქსოვილების ზრდა ცილების უწყვეტ სინთეზს მოითხოვს, ამიტომ თქვენი ბავშვისთვის ხარისხიანი ცილების მიღება აუცილებელია. თქვენი რძე ბავშვისთვის ცილების შესანიშნავი წყაროა და მასში არსებული ცილების ათვისების მაჩვენებელმა შეიძლება 95%-ს მიაღწიოს. ამიტომ ძუძუთი კვების პერიოდში თქვენი ჯანსაღი და დაბალანსებული კვებაც ძალიან მნიშვნელოვანია ბავშვის უწყვეტი განვითარებისთვის.') WHERE id = '896cbb45-0cf7-4486-ad2b-a52c32d44051';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მაშინაც კი, თუ ამჟამად განვითარების რომელიმე კრიზისულ ეტაპზე არ იმყოფებით, თქვენს ბავშვს შეიძლება ჩაძინება გაუჭირდეს. 5 თვის ბავშვის ძილის რეჟიმი შეიძლება ოდნავ დაირღვეს, რადგან ის ყოველდღიურად მოძრაობის ახალ უნარებს იძენს. ამ ახალი უნარების გამოსაცდელად ბავშვმა შეიძლება უარი თქვას ძილსა და კვებაზე და დილით ადრე გაგაღვიძოთ. თუ თქვენი ბავშვი გაღვიძებისას არ ტირის და საწოლში დამოუკიდებლად თამაშით ერთობა, საღამოს დაძინებისას შეგიძლიათ გვერდით ძილის სათამაშო დაუდოთ. გარკვეული დროის შემდეგ, ამ სათამაშოს დანახვისას ბავშვს ძილის რეფლექსი გაუჩნდება. ამ ჩვევის სწორად ჩამოსაყალიბებლად ძილის სათამაშო საწოლიდან არ უნდა გამოიტანოთ და ბავშვს მხოლოდ ძილის დროის მოახლოებისას უნდა დაუდოთ. ძილის სათამაშოს არჩევისას დარწმუნდით, რომ ის ორგანული ძაფისგან ან ქსოვილისგანაა დამზადებული და არ შეიცავს მავნე საღებავებს ან წვრილ დეტალებს, რომელთა გადაყლაპვაც ბავშვს შეუძლია.') WHERE id = '1fa3a9be-2b21-41b0-8e90-923545dc6c0e';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვებში კბილების ამოჭრის პერიოდი, ჩვეულებრივ, მე-5 თვიდან იწყება. თუ თქვენს ბავშვს ჯერ კბილი არ ამოსვლია, შესაძლოა, ამ თვის განმავლობაში კბილების ამოჭრით გამოწვეული ტკივილი დაეწყოს. კბილების ამოჭრა ბუნებრივი პროცესია, თუმცა ამ პერიოდში ბავშვი შეიძლება საკმაოდ მოუსვენარი იყოს. დისკომფორტს ღრძილების ქავილი იწვევს და დროდადრო მას ტკივილიც შეიძლება ახლდეს. ბავშვის პირის ღრუში პირველი კბილები, ჩვეულებრივ, მე-5-9 თვეებს შორის ჩნდება. ზოგ ბავშვს პირველი კბილი შეიძლება მე-3 თვეში ამოუვიდეს, ზოგისთვის კი ეს პროცესი მე-13-14 თვემდე გაგრძელდეს. თუ ბავშვს ჯანმრთელობის პრობლემა არ აქვს, კბილების ამოჭრის სიჩქარე მის ზრდასა და განვითარებასთან პირდაპირ კავშირში არ არის. ეს უფრო გენეტიკურად არის განპირობებული და, სავარაუდოდ, თქვენი და ბავშვის მეორე მშობლის ჩვილობის პერიოდის მსგავსად წარიმართება.') WHERE id = '2b63b86d-359a-4b54-8d2d-d3bc2859ca20';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის თმა ძალიან ნაზი და სათუთია, ამიტომ თმის მოვლა ყოველდღიური ჰიგიენის მნიშვნელოვანი ნაწილი უნდა იყოს. თქვენი ბავშვი შეიძლება ხშირი ან თხელი თმით დაბადებულიყო. შესაძლოა, უთმოდაც დაიბადა და თმა ახლა იწყებს ამოსვლას. ნებისმიერ შემთხვევაში, ბავშვის თმასა და თავის კანს განსაკუთრებული მოვლა სჭირდება. ზაფხულში შეგიძლიათ ბავშვი ყოველდღე აბანაოთ, ზამთარში კი — ორ ან სამ დღეში ერთხელ. ალერგიის, სიწითლისა და ქავილის თავიდან ასაცილებლად ქიმიური ინგრედიენტების შემცველ მასობრივი წარმოების პროდუქტებს უნდა მოერიდოთ. უნდა გამოიყენოთ პროდუქტები, რომლებიც არ შეიცავს პარაბენებს, სულფატებს, სინთეზურ სურნელოვან ნივთიერებებსა და ბავშვის კანის გამაღიზიანებელ მავნე ინგრედიენტებს. თუ სუფთა შემადგენლობის პროდუქტის პოვნა გიჭირთ, შეგიძლიათ უპირატესობა მიანიჭოთ ხარისხიან ბუნებრივ მყარ საპონს ან თხევად კასტილიურ საპონს.') WHERE id = '9f4a8a9d-785a-42f3-bcb2-0880d1571c96';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის დამატებით კვებაზე გადასვლის დრო მისი დაბადების სავარაუდო თარიღიდან 180 დღის შემდეგ დგება. ეს ნიშნავს, რომ დამატებითი საკვების გასაცნობად ყველაზე შესაფერისი დრო მე-6 თვის ბოლოა. ზოგიერთ შემთხვევაში, ექიმის რეკომენდაციით, დამატებით კვებაზე უფრო ადრე გადასვლაც შესაძლებელია, რადგან ბავშვს ყლაპვის რეფლექსი უკვე ჩამოყალიბებული აქვს. მიუხედავად ამისა, ნაწლავის მიკროფლორის ჯანმრთელობისთვის, თუ ბავშვს განვითარებაში შეფერხება არ აქვს, უმჯობესია, ცოტა კიდევ მოიცადოთ. მე-5 თვეში ბავშვისთვის მისაცემი დამატებითი საკვები აუცილებლად თხევადი უნდა იყოს; პიურესთვის ჯერ კიდევ ცოტა ხნით მოცდაა საჭირო. ბუნებრივად მომზადებული ბოსტნეულის სუპის ნახარში და არაალერგენული ხილის წვენები შეიძლება თქვენი ბავშვისთვის შესაფერისი იყოს. საკვებისმიერი ალერგიის რისკის გამო რეკომენდებულია, ბავშვს ახალი საკვები პირველად ძალიან მცირე რაოდენობით — 1 ჩაის კოვზის ოდენობით — მისცეთ.') WHERE id = '57b7991c-272a-4ed5-898c-f9700be1db2a';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვისთვის მასაჟის გაკეთება ხელს უწყობს სისხლის მიმოქცევის გაუმჯობესებას და კუნთებისა და ძვლების უკეთ განვითარებას. ის ასევე ეხმარება გაზებისა და ჭვალის (კოლიკის) შემსუბუქებას და ამშვიდებს ბავშვს. ბავშვის მასაჟის მთავარი მიზანია, სწორი ტექნიკის გამოყენებით მოადუნოთ ბავშვი და რეგულარული მასაჟით ხელი შეუწყოთ მის ზრდას, გონებრივ და მოტორულ განვითარებას. განსაკუთრებით მნიშვნელოვანია ბავშვის განვითარებისთვის მარტივი ვარჯიშები, რომელთა შესრულებაც მე-4 თვის შემდეგ შეიძლება. მასაჟი ყოველდღე უნდა გააკეთოთ, როდესაც ბავშვს არ შია, მშვიდადაა და მასაჟისთვის მზად არის. ამისთვის საუკეთესო დრო კვებიდან 1-1.5 საათის შემდეგაა. მასაჟის დაწყებამდე არ დაგავიწყდეთ ხელებიდან სამკაულების მოხსნა, დარწმუნდით, რომ ფრჩხილები გრძელი არ გაქვთ, ხელები კი სუფთა და თბილი უნდა იყოს. მასაჟის დროს ოთახის ტემპერატურაც სათანადოდ უნდა დაარეგულიროთ და ბავშვი არასდროს დატოვოთ მარტო. სასიამოვნო დროის გატარებას გისურვებთ! 😊') WHERE id = '98edcdb5-d642-4617-8cc5-e7bd1fc8f734';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'კბილების ამოჭრის პერიოდის შესამსუბუქებლად ხშირად იყენებენ კბილის გელებს. თუმცა ტკივილგამაყუჩებლებისა და გელების გამოყენების გარეშეც არსებობს კბილების ამოჭრის სიმპტომების შემცირების მრავალი ეფექტური გზა. კბილების მოსაფხანი სათამაშოები სასარგებლო საშუალებებია, რომლებიც ბავშვს ძალიან მოეწონება. გახსოვდეთ, რომ ისინი უფრო ეფექტურია, როდესაც მაცივარშია გაგრილებული. 😊 ამ სათამაშოების ღრძილებთან შეხება მასაჟის ეფექტსა და სიგრილეს ქმნის, რაც ბავშვს ტკივილს უმსუბუქებს. კიდევ ერთი მეთოდია, ბავშვის პირის გასაწმენდი ნაჭერი სველ ან მშრალ მდგომარეობაში ნახევარი საათით მაცივარში მოათავსოთ და შემდეგ ბავშვს დასაღეჭად მისცეთ. ცივი საგნის ღრძილებთან შეხებამ შეიძლება შეამციროს ბავშვის ტკივილი, შეშუპება და წნევის შეგრძნება. თუმცა ორივე მეთოდის გამოყენებისას, მიკრობებით ინფიცირების რისკის გათვალისწინებით, გირჩევთ, ჰიგიენისა და სტერილიზაციის წესები მკაცრად დაიცვათ. 😊') WHERE id = '61a39689-4f67-40ed-b7d3-3829e2076603';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ თვის განმავლობაში თქვენს ბავშვს დღე-ღამეში საშუალოდ 15 საათი სძინავს. აქედან, ჩვეულებრივ, 10 საათი ღამის ძილია, 5 საათი კი — დღის. თუმცა სხვადასხვა მიზეზის გამო ბავშვს შეიძლება ნაკლებად ეძინოს, ჩაძინება უჭირდეს ან ძილის დროს ხშირად იღვიძებდეს. ძილის წინ ბავშვის დაბანა ერთ-ერთი საუკეთესო რუტინაა, რომელიც მას ჩაძინებას უადვილებს. გარდა ამისა, ძილის რუტინაში შეგიძლიათ ჩართოთ დამამშვიდებელი მასაჟი, ზღაპრის წაკითხვა ან ფერადი წიგნის ილუსტრაციების ერთად დათვალიერება. ძილისთვის მომზადებისას ოთახში მკრთალი, ბინდბუნდის მსგავსი განათება ბავშვს ჩაძინებას მნიშვნელოვნად უადვილებს. ჩვეულებრივ პირობებში, თუ ღამით ბავშვს მოშივდება, შეიძლება საკვების მისაღებად გაიღვიძოს. ღამით კვება ჯერ კიდევ ძალიან მნიშვნელოვანია ბავშვის განვითარებისთვის. ამიტომ არ უნდა ინერვიულოთ და უნდა გახსოვდეთ, რომ ბავშვი ჯერ კიდევ სწრაფი ზრდის პერიოდშია.') WHERE id = '388b1d4a-2870-47fb-8a38-2987cb7bbaf9';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვისთვის თამაში და თამაშში გატარებული დრო არა მხოლოდ ძალიან სახალისო აქტივობაა, არამედ მისი განვითარებისთვის უაღრესად მნიშვნელოვანი პროცესიც. ამიტომ თამაშს მხოლოდ ბავშვთან ერთად დროის მხიარულად გატარების საშუალებად ნუ აღიქვამთ. თამაშში გატარებული დრო შეუცვლელი სწავლებისა და შემეცნების პერიოდია. ამასთან, რადგან ბავშვის გრძნობები უკვე კარგად არის ჩამოყალიბებული, თამაშის საშუალებით ის ენერგიას სწორად ხარჯავს და გარესამყაროსაც ეცნობა. ბავშვისთვის თამაშის კიდევ ერთი ფუნქციაა, დაეხმაროს მას საგნების, ცნებებისა და საგნებს შორის მსგავსებებისა და განსხვავებების შესწავლაში. შესაბამისად, თამაშის დროს ბავშვი სხვადასხვა უნარს ივითარებს და ბევრ რამეს სწავლობს. ასაკის შესაბამისად ფერების, ფორმების, სახელებისა და ზომების სწორად აღქმა მომავალში დაეხმარება მას ურთიერთობების, სოციალური როლებისა და მიბაძვის შესწავლაში, რაც მისი პიროვნების განვითარებას შეუწყობს ხელს.') WHERE id = '64ce3005-26f0-4a9c-b4db-77907d346329';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენს ბავშვს აქვს მსუბუქი სიცხე, პირში იდებს და ღეჭავს ყველაფერს, რაც ხელში მოხვდება, ყურს ისრესს, მადა დაუქვეითდა ან უხვად მოსდის ნერწყვი? თუ პასუხი დადებითია, გილოცავთ! მარგალიტივით პირველი კბილების ამოსვლამდე სულ ცოტა დარჩა. 😊 ეს კბილების ამოჭრის ნიშნებია და მას შემდეგ, რაც ბავშვი 5 თვის გახდება, კბილები ნებისმიერ დროს შეიძლება ამოუვიდეს. პირველი კბილების გამოჩენამდე მტკივნეულმა, გაწითლებულმა და შეშუპებულმა ღრძილებმა შესაძლოა ბავშვი შეაწუხოს. ეს სიმპტომები ჩვეულებრივ ჩნდება კბილის ამოჭრამდე დაახლოებით 3-7 დღით ადრე, როდესაც ამოსასვლელად მომზადებული კბილი ღრძილს არღვევს. კარგი ამბავი ისაა, რომ როგორც კი კბილი ღრძილიდან პირველად გამოჩნდება, ეს შემაწუხებელი ნიშნები სწრაფად გაივლის. გახსოვდეთ: თუ დარწმუნებული არ ხართ, რომ ბავშვის ეს სიმპტომები კბილების ამოჭრას უკავშირდება, აუცილებლად მიმართეთ ექიმს.') WHERE id = 'd5ac321f-14e0-45ad-ab92-652807702fa6';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მიუხედავად იმისა, რომ თქვენი ბავშვი მოკლე დროში სწრაფად განვითარდა, სასარგებლო მიკროორგანიზმები, რომლებიც მის სხეულს მავნე ზემოქმედებისგან იცავს, ანუ კანის ფლორა, ჯერ ბოლომდე არ არის ჩამოყალიბებული. მისი კანის pH ჯერ კიდევ მაღალია, ხოლო კანის დამცავი კერატინის შრე სრულად არ არის განვითარებული. ამის გამო ბავშვის კანი, რომელსაც დაბალი მჟავიანობა აქვს და რომლის დამცავი ბარიერიც ჯერ ბოლომდე არ არის ჩამოყალიბებული, მიკრობებისა და ქიმიური ნივთიერებების მიმართ უფრო მგრძნობიარეა. ამიტომ განსაკუთრებული ყურადღება უნდა მიაქციოთ ბავშვის კანთან შეხებაში მყოფი ტანსაცმლის რეცხვის ტემპერატურას, სარეცხი საშუალებისა და დამარბილებლის არჩევას. მაგალითად, ბავშვის მგრძნობიარე კანზე სიწითლისა და ქავილის თავიდან ასაცილებლად მნიშვნელოვანია, ტანსაცმლის რეცხვისას უპირატესობა ბუნებრივი შემადგენლობის სარეცხ საშუალებებს მიანიჭოთ. ასევე თავი უნდა აარიდოთ ქსოვილის დამარბილებლებს, რადგან ისინი ბევრ ქიმიურ ნივთიერებას, მათ შორის სურნელოვან დანამატებს შეიცავს. ბავშვის ტანსაცმლიდან მიკრობების სრულად მოსაშორებლად, გარეცხვის შემდეგ მისი დაუთოება არ დაგავიწყდეთ.') WHERE id = 'd86eb88e-f066-48c6-be2d-d43e207dbd2c';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ ვაჟი გყავთ, ალბათ გაქვთ კითხვები იმის შესახებ, თუ როდის უნდა ჩაუტარდეს მას წინადაცვეთა. წინადაცვეთა მსოფლიოში უძველესი დროიდან ჩატარებული ერთ-ერთი ქირურგიული პროცედურაა. ამ პროცედურის დროს იკვეთება და შორდება კანის ნაოჭი, რომელიც შარდსადენის ბოლოს ფარავს. სტატისტიკის მიხედვით, მსოფლიოში ყოველი სამი კაციდან ერთს წინადაცვეთა აქვს ჩატარებული. ძალიან მნიშვნელოვანია, როდის, როგორ და ვის მიერ ჩატარდება წინადაცვეთა. ამ საკითხთან დაკავშირებით, რომელიც ბავშვის დაბადებისთანავე ხდება აქტუალური, იდეალურ ასაკზე განსხვავებული მოსაზრებები არსებობს. მიუხედავად იმისა, რომ ყველაზე შესაფერისი ასაკობრივი შუალედის შესახებ დამაჯერებელი სამეცნიერო მტკიცებულება არ არსებობს, ზოგი სპეციალისტი, განსაკუთრებით ფსიქოლოგიური ტრავმის თავიდან ასაცილებლად, მის ადრეულ ასაკში ჩატარებას გირჩევთ.') WHERE id = '05f311d5-ad4e-4d35-963b-6bea5a4bcff4';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის თავზე არსებული ყიფლიბანდის გამო, შესაძლოა ამ უბანზე შეხებას ერიდებოდეთ. თავზე სულ 6 ყიფლიბანდია და, რადგან ეს უბნები დანარჩენი ადგილებივით მყარი არ არის, დედებს ხშირად ეშინიათ მათზე შეხების. თუმცა ყიფლიბანდი მტკიცე შემაერთებელი ქსოვილისგან შედგება და ბავშვის ტვინს საიმედოდ იცავს. ამიტომ ბავშვის ბანაობისას, თმის დავარცხნისას ან თავის დაჭერისას შეშფოთებისა და ამ უბანზე შეხებისგან თავის არიდების საჭიროება არ არსებობს. ყიფლიბანდი არა მხოლოდ მნიშვნელოვანია ბავშვის უსაფრთხოებისთვის, არამედ თავის ქალის ტრავმებისგან დამცავი ჩაფხუტის როლსაც ასრულებს. ყიფლიბანდი, ჩვეულებრივ, 9-18 თვის ასაკში, ყოველგვარი ჩარევის გარეშე, თავისით იხურება. ეს პერიოდი შესაძლოა 24 თვემდე გაგრძელდეს ან ყიფლიბანდი უფრო ადრეც დაიხუროს. ასეთი შემთხვევები, როგორც წესი, პრობლემას არ ქმნის, თუმცა სიფრთხილისთვის სასარგებლო იქნება ექიმთან კონსულტაცია.') WHERE id = '8c311ff4-c1cb-4399-88d9-4dbb31f984b6';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის ტვინის უჯრედებს შორის კავშირების ჩამოყალიბების შედეგად მისი აღქმა საგრძნობლად განვითარდა. ამის წყალობით თქვენი ბავშვი უკვე ახალ უნარებს იძენს. ყველაზე საინტერესო კი ისაა, რომ უკვე ხვდება, როდის წარმოთქვამთ მის სახელს და როდის ეძახით! 😊 დაბადებიდანვე სახელით მიმართვა ბავშვს ეხმარება, ეს ბგერები გონებაში აღიბეჭდოს და დაიმახსოვროს. ერთი და იმავე ბგერების ხშირად მოსმენის შედეგად თქვენს ბავშვს უკვე საკუთარი სახელის ამოცნობა შეუძლია. განვითარების კიდევ ერთი შედეგია ის, რომ მას უკვე შეუძლია ოჯახის წევრებისა და უცხო ადამიანების ერთმანეთისგან გარჩევა. ამიტომ უცხო ადამიანის დანახვისას შესაძლოა ბავშვი დაიბნეს, სიტუაციის გარკვევის მცდელობისას ტუჩები მოპრუწოს და ატირდეს. შეიძლება ხმამაღალი ტირილიც კი ატეხოს. მზად იყავით — ჩვენ გაგაფრთხილეთ! 😊') WHERE id = '2af2018e-44d1-408e-a2eb-5673d76e91c6';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ვიცით, რომ ამ პერიოდში ბავშვის დაძინება გიჭირთ. ახალშობილობის პერიოდში ბავშვის დანაყრება და საფენის სისუფთავის უზრუნველყოფა საკმარისი იყო, რომ მას კარგად დაეძინა. თუმცა ახლა, როცა ბავშვი გარესამყაროს უკეთ აღიქვამს და მისი გრძნობებიც ვითარდება, ძილისთვის მისი მომზადება შეიძლება შედარებით რთული გახდეს. ამიტომ მხოლოდ ფიზიკური საჭიროებების დაკმაყოფილება უკვე აღარ არის საკმარისი, რომ მან დამოუკიდებლად დაიძინოს. ბავშვის ტვინი ძალიან აქტიურად მუშაობს, ამიტომ ძილისთვის მომზადებისას ის ყველანაირი ხმაურისგან უნდა დაიცვათ. ტელევიზორის ან საუბრის ხმამ შეიძლება მას დაძინებაში ხელი შეუშალოს. ბავშვის მშვიდად დასაძინებლად ეს ფაქტორები უნდა აღმოფხვრათ. ამასთანავე, ზედმეტად თბილმა ან ცივმა ოთახმა შეიძლება დაძინება გააჭიანუროს და ძილის ხარისხი შეამციროს. ოთახში, სადაც ბავშვს სძინავს, იდეალური ტემპერატურაა 22-24°C. ტკბილი ძილი! 😊') WHERE id = '1a8c9918-d018-4b4c-8f7f-c8a0898c2b43';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ თვის განმავლობაში ბავშვის განვითარების შესაბამისად ბევრი აქტივობის ერთად შესრულება შეგიძლიათ. სასიამოვნო გართობას გისურვებთ! 😊 პირველ რიგში, რას იტყვით სარკესთან თამაშზე თქვენი ბავშვისთვის, რომელიც სარკეების მიმართ დიდ ინტერესს იჩენს? აიღეთ სარკე, დადექით მის წინ და ბავშვს სათამაშო ბურთი მონაცვლეობით მიაწოდეთ ორივე ხელში. ასე გარკვეული დროის შემდეგ ბავშვი სათამაშოს ერთი ხელიდან მეორეში გადატანას ისწავლის. კიდევ ერთი აქტივობისთვის იატაკზე ზემოთ-ქვემოთ ახტუნავეთ ფერადი ბურთი, რომელიც ბავშვის ყურადღებას მიიპყრობს. ბავშვი მალე ისწავლის მისთვის საინტერესო ბურთისთვის თვალის გაყოლებას. შემდეგ ხელში დაჭერილი ბურთი კედლისკენ გააგორეთ ისე, რომ კედელს მოხვდეს და უკან დაბრუნდეს. კედლიდან ბურთის ასხლეტაზე დაკვირვებით ბავშვი ახალ გამოცდილებას მიიღებს.') WHERE id = 'd9644453-95a5-4346-bbea-e0599b06e143';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ახლა, როდესაც დამატებით კვებაზე გადასვლის პერიოდს უახლოვდებით, ერთ-ერთი ყველაზე მნიშვნელოვანი საკითხი, რომელსაც ყურადღება უნდა მიაქციოთ, ბავშვის მიერ საკმარისი რაოდენობის პრებიოტიკების მიღებაა. პრებიოტიკები ხელს უწყობს ბავშვის ორგანიზმის იმუნური ფუნქციების განვითარებას, ზრდის დაავადებების მიმართ მის წინააღმდეგობას და სასარგებლოა საჭმლის მომნელებელი სისტემისთვისაც. ამასთანავე, დამატებით საკვებთან ერთად მიღებული პრებიოტიკები ხელს უწყობს დედის რძის — პრებიოტიკების უმდიდრესი წყაროს — ფუნქციებსაც. პრებიოტიკებითა და პრობიოტიკებით მდიდარ პროდუქტებს შორის ერთ-ერთი გამორჩეულია მაწონი. მაწონი რძის შედედების შედეგად მიღებული თეთრი, სქელი კონსისტენციის რძის პროდუქტია. ის წარმოიქმნება რძის შაქრის — ლაქტოზის — მაწვნის დედის მოქმედებით რძემჟავად ნაწილობრივ გარდაქმნისა და რძის შედედების შედეგად. კალციუმით, ცილებითა და B12 და B6 ვიტამინებით მდიდარი მაწონი დედის რძესთან ერთად ერთ-ერთი მნიშვნელოვანი საკვებია, რომელიც ბავშვის ორგანიზმის გამძლეობას უწყობს ხელს.') WHERE id = '67e55468-7559-4a60-ab60-67f55f552e34';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის ტანსაცმლის რეცხვისას რამდენიმე საკითხს უნდა მიაქციოთ ყურადღება. მათ შორის ყველაზე მნიშვნელოვანია სარეცხი საშუალებების მახასიათებლები და მათი სწორად შერჩევა. თუ გავითვალისწინებთ, რომ გაყიდვაში არსებული ზოგიერთი სარეცხი საშუალება და საპონი ზრდასრულებშიც კი შეიძლება ალერგიას იწვევდეს, ბავშვის მგრძნობიარე კანთან შეხებისას ეს რისკი კიდევ უფრო მაღალია. სპეციალისტები განსაკუთრებით აღნიშნავენ, რომ ჩვილობის პერიოდში გამოყენებულმა ზოგიერთმა ქიმიურმა ნივთიერებამ შეიძლება ალერგიული რეაქცია წლების შემდეგაც კი გამოიწვიოს. ამიტომ ბავშვის ტანსაცმლის რეცხვისას თავი უნდა აარიდოთ ქსოვილის დამარბილებლებს, მათეთრებლებსა და სურნელოვან პროდუქტებს, რომლებიც კანს აღიზიანებს. გაყიდვაში ჩვილებისთვის სპეციალურად წარმოებული ბევრი სარეცხი საშუალება და გრანულირებული საპონია ხელმისაწვდომი. მათ შორის უსუნო საშუალებებისთვის უპირატესობის მინიჭება კანის შესაძლო გაღიზიანების თავიდან აცილებაში დაგეხმარებათ.') WHERE id = 'abaadbfc-c35e-4cb0-b8bc-31d98a9f8ecf';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'დღის ძილი თქვენი ბავშვისთვის ძალიან მნიშვნელოვანია და ამ ეტაპზე მას დღის განმავლობაში 4-5 საათი უნდა ეძინოს. კვლევების თანახმად, ბავშვი, რომელსაც თავისი ასაკის შესაბამისად დღისით საკმარისად სძინავს, ღამით გაცილებით ხანგრძლივად იძინებს. სპეციალისტების აზრით, განსაკუთრებით სასარგებლოა დღის პირველი ორი ძილი. ამ პირველ ორ ძილს ბავშვისთვის უფრო მეტად აღმდგენი და ორგანიზმის გამაძლიერებელი ეფექტი აქვს. ამასთანავე, ბავშვები დღის განმავლობაში პირველად უფრო ადვილად იძინებენ, ვიდრე მომდევნო ჯერზე. ამიტომ დღის პირველ საათებში ძილისთვის ხელსაყრელი ეს პერიოდი არ უნდა გამოტოვოთ და ბავშვს დაძინებაში მისი მხრიდან ძილის ნიშნების გამოვლენისთანავე უნდა დაეხმაროთ. თუმცა უნდა გახსოვდეთ, რომ დღისით ბავშვის საჭიროებაზე მეტხანს ძილმა შეიძლება ღამის ძილზე უარყოფითად იმოქმედოს.') WHERE id = '59732708-2d13-4639-9614-435d122c79cb';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მე-6 თვე ბავშვის ცხოვრებაში ერთ-ერთი ყველაზე მნიშვნელოვანი გარდამტეხი ეტაპია. თქვენი ბავშვი უკვე აცნობიერებს, რომ დამოუკიდებელი არსებაა და სხვებთან ურთიერთობის ნიუანსების შესწავლასაც იწყებს. ამ მხრივ ის პირველად იწყებს საკუთარი პიროვნების შესახებ მინიშნებების მიღებას. ეს ძალიან მნიშვნელოვანი გონებრივი განვითარებაა. 😊 მიუხედავად იმისა, რომ ბავშვი გრძნობებს აქტიურად იყენებს, ახლა ის მეხსიერებაში დაგროვილი გამოცდილების საფუძველზე საკუთარი დასკვნების გამოტანასაც იწყებს. მაგალითად, უკვე შეუძლია სათამაშოებიდან ყველაზე საყვარელი აირჩიოს და თქვენც მიგახვედროთ, რომ სწორედ ის მოსწონს. ამასთანავე, მიუხედავად იმისა, რომ ბავშვმა მკაფიოდ დანახვა უკვე გარკვეული ხნის წინ დაიწყო, ამ თვიდან მას საკმაოდ რთული გამოსახულებების აღქმაც შეუძლია. ამის წყალობით ის ახალ ფორმებსა და ტექსტურებსაც ეფექტურად გაარჩევს.') WHERE id = 'b6d7faf8-f7c6-4e9e-a7ff-43facd4aa9db';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ თვეში თქვენ და თქვენს ბავშვს ახალი გამოცდილებები და ცვლილებები გელით. ბავშვის დაავადებებისგან დასაცავად ძალიან მნიშვნელოვანია, დაბადებიდანვე ყველა აცრა დროულად ჩაუტარდეს. ვაქცინაციის დროს ბავშვის ორგანიზმში შეჰყავთ იმ დაავადების გამომწვევი ბაქტერიის ან ვირუსის დასუსტებული ფორმა, რომლისგან დაცვაც არის მიზანი. ეს პროცესი იმუნიტეტის ჩამოყალიბებას ემსახურება და ბავშვის ორგანიზმი ამ დაავადებების საწინააღმდეგო ანტისხეულების გამომუშავებას იწყებს. შედეგად, მომავალში ამ მიკრობებთან შეხვედრისას მის ორგანიზმს უკვე ძლიერი დამცავი მექანიზმი ექნება. მე-6 თვის აცრების კალენდარი მოიცავს B ჰეპატიტის ვაქცინის მესამე დოზას, ხუთკომპონენტიანი კომბინირებული ვაქცინის მესამე დოზასა და OPA-ს (ორალური პოლიომიელიტის ვაქცინის) პირველ დოზას. ამ ჩამონათვალს ასევე ემატება პოლიომიელიტის საწინააღმდეგო ვაქცინა, რომელსაც ბავშვი პირველად მიიღებს. ამით თქვენი ბავშვის პირველი 6 თვის აცრების კალენდარი სრულდება.') WHERE id = '95f9ad1b-63d6-45ba-b708-bf282b104620';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მართალია, ვაქცინებმა ზოგჯერ შეიძლება გამოიწვიოს მოუსვენრობა, ღებინება, სიცხე ან ტირილი, მაგრამ ისინი აუცილებელია ბავშვის იმ მძიმე დაავადებებისგან დასაცავად, რომლებზეც ქვემოთ ვისაუბრებთ. პოლიომიელიტს „პოლიო“ ვირუსი იწვევს. ეს ვირუსი აზიანებს ნერვულ სისტემას და შეიძლება მუდმივი დამბლა ან სიკვდილიც კი გამოიწვიოს. მიუხედავად იმისა, რომ დაავადება ნებისმიერ ასაკში გვხვდება, განსაკუთრებული რისკის ქვეშ არიან 3 წლამდე ბავშვები, რომელთა იმუნური სისტემა ჯერ სრულად არ არის ჩამოყალიბებული. საბედნიეროდ, ჯანდაცვის ორგანოების მკაცრი კონტროლისა და ვაქცინაციის კამპანიების წყალობით, ამ დაავადების გავრცელება დიდწილად აღიკვეთა. დიფტერია კი მძიმე დაავადებაა, რომელიც აზიანებს სასუნთქ გზებს, საჭმლის მომნელებელ სისტემასა და გულს და შესაძლოა სიკვდილით დასრულდეს. ტეტანუსი საშიში დაავადებაა, რომელიც შეიძლება განვითარდეს ჟანგიანი ლითონით, დაბინძურებული მიწით ან მჩხვლეტავი საგნით მიყენებული ჭრილობის შედეგად და პირდაპირ ნერვულ სისტემაზე მოქმედებს. მენინგიტმა კი, სიკვდილის მაღალი რისკის გარდა, შესაძლოა ისეთი მძიმე შედეგები გამოიწვიოს, როგორიცაა შეზღუდული შესაძლებლობა, გონებრივი განვითარების შეფერხება, სიყრუე და სიბრმავე. ამიტომ ვაქცინაცია თქვენი ბავშვის ჯანსაღი მომავლისთვის ყველაზე საიმედო ფარია.') WHERE id = '2ec370c7-9d55-4f76-86f5-a1d0c2080600';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი, რომელიც ყოველდღე ახალი მოძრაობებით გაოცებთ, ზურგის კუნთების განვითარების წყალობით უკვე დამოუკიდებლად დასაჯდომად ემზადება. თუ ამჩნევთ და დარწმუნებული ხართ, რომ ის დასაჯდომად მზადაა, შეგიძლიათ ცოტათი დაეხმაროთ. თავდაპირველად კალთაში დაისვით, ხელებზე მოკიდეთ და აკონტროლეთ, რომ თავი სწორად ეჭიროს. შემდეგ შეგიძლიათ დივანზე დასვათ და გარშემო ბალიშები შემოუწყოთ, რათა წონასწორობის შენარჩუნებაში დაეხმაროთ. თუ ამ ვარჯიშების დროს ბავშვი ზოგჯერ დაიღლება და გვერდზე გადაიხრება, ნუ ინერვიულებთ. კუნთების გაძლიერებასა და წონასწორობის შეგრძნების განვითარებასთან ერთად, ის უფრო დიდხანს შეძლებს ჯდომას. ცოტა ხანში დაინახავთ, რომ წონასწორობას დამოუკიდებლად ინარჩუნებს და საყრდენის გარეშე ზის. აი, მაშინ ბალიშები აღარ დაგჭირდებათ! 😊') WHERE id = '4613232a-c667-47df-9951-c91586b62ee3';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მე-6 თვე თქვენთვისაც და თქვენი ბავშვისთვისაც სიახლეებითა და სიურპრიზებით სავსე გარდამტეხი ეტაპია. ვიცით, როგორ გახარებთ ის, რომ ბავშვს დამატებით კვებას უნდა გააცნობთ! ჯანმო და ჯანდაცვის სპეციალისტები აღნიშნავენ, რომ 180 დღის შესრულების შემდეგ ბავშვის საჭმლის მომნელებელი სისტემა დამატებითი კვებისთვის მზადაა. პირველი 6 თვის განმავლობაში ბავშვს მხოლოდ დედის რძით ან ხელოვნური ნარევით კვებავდით. ახლა კი მისი ორგანიზმი განსხვავებული შემადგენლობის საკვებს გაეცნობა, რის გამოც შესაძლოა ზოგიერთი ალერგიული რეაქცია გამოვლინდეს. ამიტომ გირჩევთ, დამატებით კვებაზე თანდათან გადახვიდეთ და არ იჩქაროთ, რათა საჭმლის მომნელებელი სისტემა ზედმეტად არ დაიტვირთოს. ჩვენი „რეცეპტების“ განყოფილება ამ გემრიელ თავგადასავალში ძალიან დაგეხმარებათ. გემრიელად მიირთვით! 😊') WHERE id = '1057a1b2-3687-4581-b2fe-6f0fca8b4778';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'დადგა დამატებითი კვების პერიოდი, რომელიც თქვენთვისაც და თქვენი ბავშვისთვისაც ძალიან საინტერესოა! მაგრამ ყველაფერი მზად გაქვთ? ბავშვის დამატებითი კვებისთვის მზადყოფნის ყველაზე მნიშვნელოვანი ნიშანი, რა თქმა უნდა, ისაა, რომ მას უკვე ჯდომა შეუძლია. ამიტომ კარგი საბავშვო კვების სკამი დაგჭირდებათ. ნუ ჩათვლით, რომ ეს უბრალოდ სკამია — ბავშვისთვის ის მხოლოდ საკვების მისაღები ადგილი არ არის. ბავშვის კვების სკამზე ჭამას მიჩვევას მრავალი მნიშვნელოვანი მიზეზი აქვს. უპირველეს ყოვლისა, ასეთი სკამი ბავშვს საშუალებას აძლევს, თქვენთან ერთად ერთ მაგიდასთან იჯდეს. ოჯახის წევრებთან ერთად სუფრასთან ყოფნა გეხმარებათ, ბავშვთან მეტი ურთიერთობა გქონდეთ და თქვენ შორის კავშირი გაძლიერდეს. კვების სკამის არჩევისას აუცილებლად მიაქციეთ ყურადღება, რომ ის უსაფრთხო, კომფორტული, მსუბუქი და ხარისხიანი მასალისგან დამზადებული იყოს.') WHERE id = 'f8f5f75d-b030-4498-b7d5-7b4bc417016c';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ თვიდან ბავშვს დღე-ღამეში დაახლოებით 13 საათი უნდა ეძინოს. მოსალოდნელია, რომ დღის განმავლობაში ორჯერ დაიძინებს, ღამით კი შეიძლება 6-7 საათი უწყვეტად ეძინოს. ბავშვის ზრდასთან ერთად ძილის მოთხოვნილება გარკვეულწილად შემცირდება. ძილი მნიშვნელოვანია, რადგან ზრდის ხელშემწყობი ჰორმონები სწორედ ღამის ძილის დროს გამოიყოფა. ამ ეტაპზე მოსალოდნელია, რომ ბავშვი დამოუკიდებლად დაძინებასაც მიეჩვევა. ანუ, თუ მას ჯერ კიდევ რწევით, ძუძუთი კვებით ან ხელში ტარებით აძინებთ, გირჩევთ, ეს ჩვევები მოკლე დროში თანდათან შეამციროთ და შეწყვიტოთ. ზოგიერთი სპეციალისტი გვირჩევს, რომ ბავშვის ყოველი ტირილისას მაშინვე არ ჩავერიოთ, რათა მან ღამის ძილის ჯანსაღი რეჟიმის ჩამოყალიბება შეძლოს. ამ მხრივ, თუ დარწმუნებული ხართ, რომ ბავშვი დანაყრებულია, საფენი სუფთა აქვს და სხვა პრობლემა არ აწუხებს, ყოველი ტირილისას დაუყოვნებლივ არ უნდა ჩაერიოთ. ბავშვი, რომელსაც ყოველი ტირილისას ხელში იყვანენ, დამოუკიდებლად დაძინებას ვერ ისწავლის.') WHERE id = '790745e1-b64b-4611-b8ea-ced2bd5bd141';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'რადგან თქვენს ბავშვს უკვე უფრო გამართულად ჯდომა შეუძლია, მისი მხედველობის არე ფართოვდება და გარემოსთან უფრო აქტიურად ურთიერთობს. ეს ასევე ხელს უწყობს სენსორული და მოტორული უნარების განვითარებას. განვითარებასთან ერთად, ბავშვის ინტერესი იმ ყველაფრის მიმართ იზრდება, რაც გართობისა და აღმოჩენების შესაძლებლობას აძლევს. მაგალითად, წვრილი მოტორული უნარების განვითარებასთან ერთად, მას უკვე შეუძლია პატარა საგნების თითებით ან ცერა თითით დაჭერა. ასევე შეუძლია დაჭერილი ნივთის ერთი ხელიდან მეორეში გადატანა. შესაძლოა, მისგან მოშორებით, მაგრამ მხედველობის არეში მდებარე სათამაშოსკენ გაიწიოს და მის აღებას შეეცადოს. თუ დაგდებულ ან ხელიდან გაშვებულ სათამაშოს თავად ვერ აიღებს, შესაძლოა, ჟესტით მიგანიშნოთ, რომ სათამაშო მიაწოდოთ. თუმცა შესაძლოა, თქვენს ბავშვს განვითარების ამ ეტაპებიდან ზოგიერთი ჯერ არ ჰქონდეს გამოვლენილი. ეს იმითაა განპირობებული, რომ ყველა ბავშვი ინდივიდუალურად ვითარდება, ამიტომ სანერვიულო არაფერია.') WHERE id = '6730fee9-c4d4-4db1-af73-50d999349b75';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ თვის განმავლობაში, ექიმის რეკომენდაციით, თქვენი ბავშვისთვის რკინის პრეპარატის მიცემა უნდა დაიწყოთ, რომლის მიღებაც პოლიკლინიკაშიც შეგიძლიათ. რკინის დეფიციტი მსოფლიოში ყველაზე გავრცელებული კვებითი დეფიციტია და განსაკუთრებით მნიშვნელოვან ჯანმრთელობის პრობლემას წარმოადგენს განვითარებად ქვეყნებში. ანემიის გარდა, რკინის დეფიციტით გამოწვეული ერთ-ერთი უმნიშვნელოვანესი პრობლემა ბავშვის გონებრივ განვითარებაზე მისი უარყოფითი გავლენაა. ჩვილობის პერიოდში, როდესაც ტვინი სწრაფად იზრდება და ბავშვი ძირითად ფსიქომოტორულ უნარებს იძენს, რკინის დეფიციტმა შესაძლოა გონებრივი განვითარება შეაფერხოს. კვლევების თანახმად, IQ-ის მაჩვენებელი შესაძლოა მუდმივად დაახლოებით 5 ქულით დაბალი დარჩეს, ვიდრე მოსალოდნელი დონეა. ამიტომ ჯანმო 6-12 თვის ბავშვებისთვის რკინის პრეპარატის მიცემას უწევს რეკომენდაციას. ამერიკის პედიატრიის აკადემია ასევე გვირჩევს, რომ 9-12 თვის ასაკში ბავშვს ერთხელ ჩაუტარდეს სისხლის ანალიზი რკინის დონის შესამოწმებლად.') WHERE id = 'da861e51-ae52-40b6-a6f0-c4e0e3afd9bf';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'დამატებით კვებაზე გადასვლისას ყაბზობა ხშირად გვხვდება, განსაკუთრებით იმ ბავშვებში, რომლებიც ადვილად მოსანელებელი დედის რძით ან ხელოვნური ნარევით იკვებებიან. თუ ეჭვი გაქვთ, რომ თქვენს ბავშვს ყაბზობა აქვს, გირჩევთ, ყურადღებით გაეცნოთ შემდეგ საკითხებს. უპირველესად, ყველა ბავშვის საჭმლის მომნელებელი სისტემა ერთნაირი სისწრაფით არ ვითარდება. ყაბზობა შესაძლოა მაშინაც განვითარდეს, თუ დამატებითი კვება მე-6 თვის დასრულების შემდეგ დაიწყეთ. ამიტომ შეგიძლიათ, დამატებითი საკვების მიცემა გარკვეული დროით შეწყვიტოთ და მოგვიანებით კვლავ სცადოთ. ამ პერიოდში ბავშვს შეგიძლიათ თხელი სუპები ან ხილის წვენები მისცეთ. დამატებითი კვების დაწყებისას სიფრთხილე უნდა გამოიჩინოთ ისეთი პროდუქტების მიმართ, რომლებმაც შესაძლოა ყაბზობა გამოიწვიოს, მაგალითად, ბანანისა და კარტოფილის მიმართ. თუ ფიქრობთ, რომ ამ საკვების მიცემის შემდეგ ბავშვს ყაბზობა დაეწყო, ისინი გარკვეული დროით რაციონიდან უნდა ამოიღოთ. ამასთან, თუ ბავშვს ყაბზობა აქვს და დეფეკაციისას უჭირს, შესაძლოა ანალური ნახეთქი ჰქონდეს. ასეთ შემთხვევაში მნიშვნელოვანია, ექიმს დაუკავშირდეთ.') WHERE id = '9037133c-00b1-4728-bfa8-d12451129dad';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის ნაწლავური ფლორა, რომელსაც მიკრობიოტა ეწოდება, ფორმირების დასრულების ეტაპზეა. ამ ბალანსის შესანარჩუნებლად რამდენიმე საკითხს უნდა მიაქციოთ ყურადღება. თუ მშობიარობა საკეისრო კვეთით ჩატარდა, ბავშვის ნაწლავურ ფლორაში საჭმლის მონელების ხელშემწყობი ბაქტერიები მე-8 დღიდან იწყებს წარმოქმნას, ხოლო ბუნებრივი მშობიარობის შემთხვევაში — მე-4 დღიდან. ნაწლავურ ფლორაში არსებული ამ მიკროორგანიზმების ნაწილი სასარგებლო, ნაწილი კი მავნე ბაქტერიაა. ორივე ტიპის ბაქტერიის არსებობა ხელს უშლის ერთმანეთის ჭარბ გამრავლებას და საჭმლის მომნელებელ სისტემაში წონასწორობას ქმნის. ბავშვის ნაწლავური ფლორის მხარდასაჭერად შეგიძლიათ პრობიოტიკები და პრებიოტიკები გამოიყენოთ. ეს დანამატები ასევე ასტიმულირებს სეროტონინის გამოყოფას, რომელიც ბედნიერების ჰორმონის სახელითაცაა ცნობილი. ბავშვის კვებაში შეგიძლიათ შეიტანოთ ამ სასარგებლო ბაქტერიების შემცველი პროდუქტები, ხოლო შეფუთული პრობიოტიკების შესახებ ინფორმაცია ექიმისგან მიიღოთ.') WHERE id = '9e82ffd7-d409-49b6-a002-4b2672efef01';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის ვაქცინაციის კალენდარში შეტანილი ვაქცინები მის ორგანიზმში ხელოვნურად ქმნის იმუნიტეტს. იმუნიტეტი წარმოიქმნება მაშინ, როდესაც ბავშვის ორგანიზმში დაავადების გამომწვევი მიკროორგანიზმები შეჰყავთ, რაც იმუნურ სისტემას აფრთხილებს და ააქტიურებს. ამიტომ, როდესაც ბავშვის ორგანიზმი ამ მიკრობებს პირველად ხვდება, შესაძლოა მან მსუბუქი დისკომფორტი იგრძნოს, თუმცა ამავდროულად მისი ორგანიზმი შესაბამისი დაავადების მიმართ იმუნიტეტს გამოიმუშავებს. მეხსიერების უჯრედების წყალობით, ბავშვი იმავე დაავადებით ხელახლა აღარ ინფიცირდება. ვაქცინაციისას ბავშვის ორგანიზმში დასუსტებული ან განეიტრალებული მიკროორგანიზმები შეჰყავთ. ამ გზით იმუნური სისტემა წინასწარ იღებს ინფორმაციას და მომავალში, რეალურ მიკრობთან შეხვედრისას, ბავშვის ორგანიზმი აქტიური თავდაცვისთვის მზად არის. მიუხედავად იმისა, რომ ვაქცინები ბავშვს დაავადებებისგან 100%-ით ვერ იცავს, მის ორგანიზმში უკვე არსებული ანტისხეულების წყალობით დაავადება გაცილებით მსუბუქად მიმდინარეობს.') WHERE id = '6a597987-e8b8-4f14-a6ec-55936a1409ea';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, '6 თვის ასაკში თქვენს ბავშვს დღე-ღამეში დაახლოებით 11 საათი შეიძლება ეძინოს. ძილის ეს საშუალო ხანგრძლივობა არ ნიშნავს, რომ ბავშვი მხოლოდ ღამით დაიძინებს — დღის ძილიც მისთვის ჯერ კიდევ ძალიან მნიშვნელოვანია. ამერიკის პედიატრიის აკადემიის თანახმად, ბავშვის საკუთარ ოთახში გადაყვანისა და თქვენგან განცალკევებით დაძინებისთვის იდეალური პერიოდი სწორედ ამ თვიდან იწყება. ამის მიზეზი ისაა, რომ დამატებით კვებაზე გადასვლის შემდეგ ბავშვის დამოკიდებულება დედის რძეზე, პირველ თვეებთან შედარებით, გარკვეულწილად მცირდება. თუმცა ამ გადასვლის ზედმეტად სწრაფად განხორციელებამ შესაძლოა ბავშვის ემოციურ განვითარებაში გარკვეული პრობლემები გამოიწვიოს. განსაკუთრებით ხშირია შემთხვევები, როდესაც ღამით გაღვიძებულ ბავშვს ეშინია და ტირის. ახალ გარემოსთან შესაგუებლად ბავშვს დრო უნდა მისცეთ და ეს პროცესი ნელა, ეტაპობრივად და მოთმინებით წარმართოთ.') WHERE id = '68a677bc-c6fd-496b-bd7c-d65d75f316ae';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვისთვის საკვების ყველაზე მნიშვნელოვანი წყარო კვლავ თქვენი რძე ან ხელოვნური ნარევია. დამატებით კვებაზე გადასვლის პერიოდში ძუძუთი კვებას ყურადღება არ უნდა მოაკლოთ და მისი სიხშირე არ უნდა შეამციროთ. თუ ექიმი სხვაგვარად არ გირჩევთ, 6-8 თვის ასაკში დამატებითი საკვები მხოლოდ ახალი გემოების გასასინჯად და ეტაპობრივი გადასვლისთვის უნდა მისცეთ; ამ პერიოდში დედის რძე კვლავ ძირითად საკვებად რჩება. დამატებით კვებაზე გადასვლისას ბავშვის განვითარების ზოგიერთ ნიშანსაც უნდა დააკვირდეთ. მაგალითად, ამ პერიოდში მოსალოდნელია, რომ მან თავი სწორად დაიჭიროს, ჯდომა შეძლოს და ხელისა და თვალის კოორდინაცია განუვითარდეს. განსხვავებული გემოების პირველად გასინჯვისას ბავშვმა შესაძლოა საკვები ენით გამოაგდოს ან ჭამაზე უარი თქვას. ეს სრულიად ნორმალური რეფლექსია და დროთა განმავლობაში გაივლის. თანდათან ბავშვს პირის გაღების, ყლაპვისა და ღეჭვის უნარები განუვითარდება. ამიტომ გარდამავალ პერიოდში ბავშვს ჭამა არ უნდა დააძალოთ და უნდა გახსოვდეთ, რომ დამატებითი საკვები მხოლოდ დედის რძის შემავსებელია.') WHERE id = '28ae02f7-da1a-49dd-85b2-b82676a86611';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ ეტაპზე თქვენი ბავშვი ფიზიკური, შემეცნებითი და მეტყველების განვითარების მხრივ ძალიან სწრაფად პროგრესირებს. ალბათ, მის მიერ აღმოჩენილი ყოველი ახალი მოძრაობა და ქცევა თქვენც ძალიან გახარებთ. უფროსებისგან განსხვავებით, ბავშვებს განვითარების მნიშვნელოვანი ეტაპების გავლა ძალიან მოკლე დროში შეუძლიათ. მაგალითად, ბავშვი, რომელიც გუშინ დამოუკიდებლად ვერ იჯდა, დღეს შეიძლება თავისუფლად მჯდომარე ნახოთ! 😊 ამასთანავე, თქვენმა ბავშვმა შესაძლოა უკვე აითვისა 6 თვის ასაკისთვის მოსალოდნელი უნარების ნაწილი, ხოლო დანარჩენი — ჯერ არა. ეს არ უნდა გაღელვებდეთ, რადგან ყველა ბავშვი ინდივიდუალური ტემპით ვითარდება. თუ ფიქრობთ, რომ თქვენი ბავშვი ჯერ კიდევ ვერ ზის დამოუკიდებლად ან წონასწორობას სრულად ვერ ინარჩუნებს, მოთმინება გამოიჩინეთ; ძალიან მალე დაინახავთ, რომ მან ეს უნარებიც შეიძინა! 😊') WHERE id = '6188303f-604c-4619-8980-cdb921290253';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'დამატებით კვებაზე გადასვლის პერიოდში ბავშვის შეკრულობის თავიდან ასაცილებლად შეგიძლიათ რამდენიმე მნიშვნელოვან საკითხს მიაქციოთ ყურადღება. უპირველეს ყოვლისა, ექიმთან გაიარეთ კონსულტაცია, რათა დადგინდეს, ხომ არ უკავშირდება შეკრულობა განვითარებასთან ან ჯანმრთელობასთან დაკავშირებულ რაიმე პრობლემას. გარდა ამისა, ბავშვის თბილ წყალში დაბანა და მუცლის მასაჟი ნაწლავების უფრო აქტიურად მუშაობას შეუწყობს ხელს. ექიმის რეკომენდაციით, მენიუში შეგიძლიათ დაამატოთ შეკრულობის დროს სასარგებლო პროდუქტები, როგორიცაა გარგარის ჩირი, ქლიავის ჩირი, მუქი მწვანე ფოთლოვანი ბოსტნეული და მსხალი. სასარგებლოა ჩირის თბილ წყალში დაყენება და დღის განმავლობაში ბავშვისთვის ამ წყლის მიცემაც. მთელი ამ პერიოდის განმავლობაში ბავშვი ხშირად უნდა აწოვოთ ძუძუს; თუ ძუძუთი არ კვებავთ, ხელოვნური ნარევის რაოდენობა არ უნდა შეამციროთ და სითხის მიღებას უნდა მიაქციოთ ყურადღება. ასევე, ბავშვის მოსადუნებლად ანუსის მიდამოში ჩარევა (გაღიზიანება) რეკომენდებული არ არის, რადგან ეს შესაძლოა ჩვევად იქცეს და ამიტომ მისგან თავი უნდა შეიკავოთ.') WHERE id = 'e2db0876-de2c-4046-9525-ff64acf7b248';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენს 6 თვის ბავშვს უკვე შეუძლია საყრდენით ან დამოუკიდებლად ჯდომა, გადაბრუნება და ფეხზე დგომაც კი, თუმცა ძალიან მცირე ხნით. რადგან ეს მოძრაობები ყველა ბავშვს სხვადასხვა დროს უვითარდება, შესაძლოა საჭირო გახდეს, შესაფერის დროს გარკვეული აქტივობებით დაეხმაროთ. შეგიძლიათ ბავშვი ზურგზე დააწვინოთ იატაკზე ან საწოლზე და, მის გვერდით ყოფნისას, გადაბრუნებაში დაეხმაროთ. ჩაიხუტეთ პატარა, რომელიც თქვენკენ გამოშვერას ცდილობს, და შეაქეთ წარმატებისთვის. თუ არ მოძრაობს, მის გასამხნევებლად შეგიძლიათ მუცელზე გადააბრუნოთ, შემდეგ კი კვლავ ზურგზე დააწვინოთ. გარდა ამისა, ხელებით თამაში შეხების შეგრძნებასაც ავითარებს და ბავშვის დამოუკიდებლად გართობის შესანიშნავი საშუალებაცაა. შეგიძლიათ ბავშვი თქვენ წინ დასვათ, თითები ზუსტად მისი თვალების დონეზე მიიტანოთ, რიგრიგობით აჩვენოთ და სათითაოდ დაითვალოთ. კარგად გაერთეთ! 😊') WHERE id = '8d36fd03-563f-4c3d-92c7-c802cd459f32';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ დღეებში, როდესაც დამატებით კვებაზე გადადიხართ, შეგიძლიათ ბავშვს მისცეთ ისეთი ხილის პიურე და წვენი, როგორიცაა ვაშლი, ატამი და მსხალი, აგრეთვე ისეთი ბოსტნეულის პიურე და წვენი, როგორიცაა კარტოფილი, სტაფილო და გოგრა. ასევე, ექიმის რეკომენდაციით, სახლში მომზადებულ მაწონში შეგიძლიათ დაამატოთ აფთიაქში შეძენილი პრობიოტიკის ფხვნილი. დამატებითი კვებისას, უპირველეს ყოვლისა, უნდა მოერიდოთ ძროხის რძეს, შაქრიან და მარილიან საკვებს. ადრეულ ასაკში ძროხის რძემ შესაძლოა ნაწლავებში ფარული სისხლდენა გამოიწვიოს. გარდა ამისა, რკინის არასაკმარისი შემცველობისა და მასში არსებული უცხო ცილების გამო ალერგიის განვითარების რისკიც არსებობს, ამიტომ ბავშვს ძროხის რძე 1 წლის ასაკამდე არ უნდა მისცეთ. ასევე გახსოვდეთ, რომ მზა პროდუქტებს ბავშვის მენიუში ადგილი არ აქვს. ამასთანავე, ბავშვისთვის განკუთვნილი საკვების დასატკბობად შაქრის ნაცვლად უმჯობესია ბექმეზი ან ხილი გამოიყენოთ.') WHERE id = 'bdbf69c9-7362-46c7-9230-c6195ba35de7';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'კვლევების თანახმად, ბავშვები უკეთ ვითარდებიან გარემოში, სადაც ზომიერი რაოდენობის სტიმულს იღებენ. ამიტომ ბავშვისთვის სხვადასხვა ტექსტურის, ფორმისა და ხმის გაცნობა მის ტვინში ახალი ინფორმაციის ნაკადს ქმნის. ამგვარი სენსორული აქტივობები თქვენი 6 თვის ბავშვის გონებრივი განვითარებისთვის ძალიან მნიშვნელოვანია. ამ პერიოდში ჭიტას თამაში, რითმული იავნანები და თითის თოჯინები ბავშვისთვის სახალისოც იქნება და მის განვითარებასაც შეუწყობს ხელს. ბავშვს შესაძლებლობა უნდა მისცეთ, მის წინ დადებული ყოველი ახალი ნივთი თავად გამოიკვლიოს, და საკმარისი დრო დაუთმოთ მისი თვისებების აღმოსაჩენად. მაგალითად, შეგიძლიათ გამოიყენოთ მინის ჭიქა და კოვზი. მიეცით ეს ნივთები ბავშვს ორივე ხელში, საშუალება მიეცით, დაათვალიეროს ისინი, და დაეხმარეთ გაარკვიოს, როგორ გამოსცეს მათი საშუალებით ხმა. დარწმუნებული ვართ, რომ ეს აქტივობა ბავშვს ძალიან გაართობს. კარგად ითამაშეთ! 😊') WHERE id = 'e926ea15-a8f6-4559-a5e9-18bd81abc58e';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'დამატებითი კვების შესახებ ინფორმაციის მოძიებისას შესაძლოა „სამი დღის წესს“ შეხვედროდით. სამი დღის წესი ძალიან მნიშვნელოვანია დამატებითი კვების დაწყების პერიოდში ბავშვის საკვების მიმართ შესაძლო ალერგიული რეაქციის გამოსავლენად. მისი დახმარებით, თუ ბავშვს ალერგია განუვითარდება, ადვილად შეძლებთ განსაზღვროთ, რომელმა საკვებმა გამოიწვია ის. ამ წესის გამოყენებით შეგიძლიათ ბავშვს 3 დღის განმავლობაში დააკვირდეთ და გაიგოთ, აქვს თუ არა თქვენ მიერ შეთავაზებულ საკვებს რაიმე უარყოფითი გავლენა. ამასთანავე, რადგან ამ პერიოდში მხოლოდ ერთ პროდუქტს მისცემთ, ადვილად მიხვდებით, მოსწონს თუ არა ის ბავშვს. დამატებითი საკვების მიღების შემდეგ ალერგიული რეაქცია შეიძლება გამოვლინდეს კანის სიწითლითა და გამონაყარით. გარდა ამისა, შესაძლო ალერგიის ნიშნებია გაზებით გამოწვეული ტკივილი და მასთან დაკავშირებული ტირილი, ღებინება, დიარეა, მოუსვენრობა და მუცლის ტკივილი.') WHERE id = 'e67b6585-697c-442b-94c4-f4bcc520b28d';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენს ბავშვს უკვე აღარ მოსწონს ერთ ადგილზე მშვიდად ყოფნა. ამიტომ სრულიად ნორმალურია, რომ ის მუდმივად მოძრაობს! 😊 ამ პერიოდში ბავშვის ყურადღებას კვლავ იზიდავს საკუთარი ხელები და ფეხები. მან შეიძლება რიგრიგობით დააკვირდეს ხელებსა და თითებს და სიამოვნებით აღმოაჩინოს, რისი გაკეთება შეუძლია მათი დახმარებით. ფეხების ჰაერში აწევა და ხელებით მათი დაჭერის მცდელობა კი მისი ერთ-ერთი საყვარელი საქმიანობაა. ამ თამაშის უფრო გასახალისებლად შეგიძლიათ ფერადი, ხმიანი წინდები შეუძინოთ. ბავშვი ეცდება ფეხზე ჩაცმულ ამ მხიარულ წინდას მისწვდეს და მასთან თამაშით თავადაც გაერთობა. ასევე არ დაგავიწყდეთ, მოძრაობის მოყვარულ პატარას თავისუფალი და კომფორტული ტანსაცმელი ჩააცვათ! 😊') WHERE id = '6e15d298-df96-4ac7-b6a2-ef5c565ec39c';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბოლო წლებში ნაწლავების ჯანმრთელობის შესახებ ჩატარებულმა დეტალურმა კვლევებმა პრობიოტიკების მნიშვნელობა წარმოაჩინა. ნაწლავებს უკვე „მეორე ტვინსაც“ უწოდებენ და, რადგან ისინი მთელ ორგანიზმზე ახდენენ გავლენას, მათი ჯანმრთელობა ბავშვის ჯანსაღი განვითარებისთვის მნიშვნელოვანია. პრობიოტიკები ნაწლავის მიკროფლორის ბალანსს უზრუნველყოფს და მავნე მიკროორგანიზმების გამრავლებას უშლის ხელს. გარდა ამისა, დედის რძესთან ერთად პრობიოტიკები ხელს უწყობს იმუნური სისტემის ჩამოყალიბებას და ბავშვის შინაგანი წონასწორობის — ჰომეოსტაზის შენარჩუნებას. პრობიოტიკები ასევე აუმჯობესებს ზოგიერთი მინერალისა და ვიტამინის შეწოვას, არეგულირებს ლიპიდების დონესა და ნაწლავის გამტარობას. ამ სარგებლის მისაღებად რეკომენდებულია პრობიოტიკური პროდუქტების სათანადო რაოდენობითა და რეგულარულად მიღება. დამატებითი კვების პერიოდში ბავშვის მიერ პრობიოტიკების შემცველი პროდუქტების, მაგალითად, იოგურტის, კეფირისა და ტარჰანას სუპის რეგულარულად მიღება ნაწლავების ჯანმრთელობისთვის ძალიან მნიშვნელოვანია.') WHERE id = '092895c9-69ca-40db-8ca1-d44efd327a7d';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი 6 თვის ბავშვი უკვე რეაგირებს ხმის ტონის ცვლილებაზე და მისი ყურადღება განსაკუთრებით იზიდავს ნებისმიერ საგანს, რომელიც ხმას გამოსცემს! ბავშვის გონებრივი განვითარება და უნარი, დააკვირდეს სახის გამომეტყველებას და მისი მნიშვნელობის გაგება სცადოს, უკვე საკმაოდ კარგად არის განვითარებული. ეს ნიშნავს, რომ ბავშვმა შესაძლოა უკვე რეაგირება მოახდინოს, როცა ეუბნებით „არას“. თქვენი სახის გამომეტყველების დახმარებით მას შეუძლია მიხვდეს, რომ სიტყვა „არა“ უარყოფით მნიშვნელობას ატარებს. თუმცა, თუ ბავშვს ხშირად ეტყვით „არას“, მან შეიძლება სამყარო უარყოფით და ნეგატიურ ადგილად აღიქვას. ამ დროს ხშირად გვესმის ფრაზა: „ჯერ ძალიან პატარაა და ვერ გაიგებს“. თუმცა, ეს მეცნიერულად დადასტურებული ფაქტია. მართალია, ბავშვს ჯერ არ შეუძლია სრულად გაიაზროს ყველაფერი, რასაც ისმენს, ხედავს და გრძნობს, მაგრამ ამ ინფორმაციას ტვინში ინახავს, რათა მოგვიანებით გამოიყენოს. ამიტომ ბავშვის მუდმივად შეზღუდვამ და სიტყვა „არას“ მიჩვევამ შეიძლება მომავალში ნეგატიურ ადამიანად ჩამოაყალიბოს და ლიდერის როლის აღებისგან თავის შეკავება გამოიწვიოს.') WHERE id = '2d11a5b6-a9e7-427f-af80-602cab8874a2';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვი, რომელიც დაბადებიდან ამ თვემდე მხოლოდ რძით იკვებებოდა, დამატებით კვებაზე გადასვლის დაწყებისას შესაძლოა მყარ საკვებზე უარს ამბობდეს. ამიტომ მისი ყურადღების გადასატანად არ უნდა ჩამოუყალიბოთ ისეთი არასწორი ჩვევა, როგორიც ჭამის დროს ტელევიზორის წინ დასმაა. დამატებითი კვების დაწყება უნდა იყოს პერიოდი, როდესაც ბავშვს დროს მისცემთ და გაგებით მოეკიდებით. მაგალითად, ჭამის დროს საკვების სახელებისა და ფერების დასახელება მის აღქმას ავითარებს და საკვების მეტი ხალისით მიღებაში ეხმარება. იმისათვის, რომ ბავშვს ჭამა შეუყვარდეს, საკმარისია, ცოტა შემოქმედებითად მიუდგეთ საკითხს. საკვებით შექმნილი ფიგურები მის ინტერესს გამოიწვევს და ერთად დროის სასიამოვნოდ გატარებაში დაგეხმარებათ. რადგან ბავშვი ახლა განსაკუთრებით აქტიურად ეცნობა გემოებს, სხვადასხვა საკვების ცალ-ცალკე ჭურჭელში შეთავაზება გემოების აღქმისთვის მნიშვნელოვანია. ამ პერიოდში ასევე უფრო უსაფრთხო იქნება არამტვრევადი თეფშის, ჩანგლისა და კოვზის გამოყენება.') WHERE id = 'b5fa9ff8-3ed0-4d85-920b-ca982ac76fc8';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ვიცით, რომ ზოგჯერ ბავშვი საკმაოდ რთულ მდგომარეობაში გაყენებთ. ეს ნორმალურია, განსაკუთრებით თუ გავითვალისწინებთ, რომ ახლა ის ძალიან მოძრავია და მუდმივად ახალი რამეების აღმოჩენა სურს. თუმცა, როგორი რთულიც არ უნდა იყოს, გახსოვდეთ, რომ ის ჯერ კიდევ მთლიანად თქვენზე დამოკიდებული, ემოციების მქონე ბავშვია. ყველა ცოცხალი არსების მსგავსად, თქვენს ბავშვსაც შეუძლია გარკვეული გზითა და გარკვეული დროის განმავლობაში გაუმკლავდეს სტრესს. მაგალითად, როდესაც ბავშვს საფენი აქვს დასვრილი ან შია, მისი სხეული ამას ავტომატურად საფრთხედ აღიქვამს. თავდაპირველად ის მოძრაობას იწყებს და მოუსვენარი ხდება, ხოლო თუ მისი საჭიროება არ დაკმაყოფილდა, ორგანიზმი ჰორმონ კორტიზოლს გამოყოფს. სტრესის ეს მექანიზმი ბავშვის ორგანიზმში არტერიული წნევისა და სისხლის ნაკადის სიჩქარის მატებას იწვევს. ამ თვეებში, როდესაც ბავშვი ინტენსიური განვითარების ეტაპზეა, კორტიზოლის ჭარბმა გამოყოფამ გარკვეული დროის შემდეგ შეიძლება გადაღლა, საკუთარ თავში ჩაკეტვა და გარემოსგან განრიდება გამოიწვიოს.') WHERE id = '79821ac2-93ff-4cf4-a7f8-8aab07a2bcca';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ თვეში ბავშვის აცრების კალენდრით არცერთი ვაქცინაცია არ არის გათვალისწინებული. თუმცა ექიმთან გეგმური ვიზიტებისას მას წონას, სიმაღლესა და თავის გარშემოწერილობას გაუზომავენ. 7-ci თვისთვის ბავშვის წონა, ჩვეულებრივ, 5900 გრამი ile 9000 გრამი დიაპაზონშია. 7 თვის ბავშვების საშუალო წონა კი 8100 გრამია. თუმცა უნდა გახსოვდეთ, რომ განსაკუთრებით ნაადრევად დაბადებული ბავშვების შემთხვევაში ეს საშუალო მაჩვენებელი შესაძლოა უფრო დაბალი იყოს. ამ თვეში ბავშვის სიმაღლე 61 sm ile 75 sm ფარგლებში მერყეობს, საშუალო მაჩვენებელი კი დაახლოებით 67 sm-ია. თავის გარშემოწერილობა, რომელიც ბავშვის ტვინის განვითარების შესახებ ზოგად წარმოდგენას გვიქმნის, ამ თვეში 42.8 sm ile 44 sm დიაპაზონშია. თუ ფიქრობთ, რომ ბავშვის ფიზიკური განვითარება ამ მაჩვენებლებს არ შეესაბამება, ზუსტი ინფორმაციის მისაღებად შეგიძლიათ ექიმს მიმართოთ.') WHERE id = '7ae42d6a-0c42-4144-b394-cfd8c4804b24';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის შიმშილისა და დანაყრების მექანიზმი დაბადებისთანავე იწყებს ფუნქციონირებას და იგი აუცილებლად მიგანიშნებთ, შია თუ დანაყრებულია. ამიტომ ჭამის დროს ბავშვი არ უნდა აიძულოთ და არც მაშინ უნდა შეშფოთდეთ, როცა საკვებზე უარს ამბობს. მიუხედავად იმისა, რომ თქვენი ბავშვი გარკვეული ხანია დამატებით კვებაზეა გადასული, სრულად შესაგუებლად შესაძლოა ჯერ კიდევ გარკვეული დრო დასჭირდეს. ბავშვს, რომელიც დაბადებიდან დედის რძით ან ხელოვნური ნარევით იკვებებოდა, შესაძლოა მყარი საკვებისა და განსხვავებული გემოების მიღება თავიდან გაუჭირდეს. თუ ფიქრობთ, რომ ბავშვს მცირე წონა აქვს ან საკმარისად არ იკვებება, მხოლოდ წონის მოსამატებლად ნუ მისცემთ მაღალკალორიულ, მაგრამ უსარგებლო საკვებს. ბავშვის განვითარება მხოლოდ მიღებული კალორიების რაოდენობითა და წონით არ განისაზღვრება. ამიტომ ცარიელი კალორიების შემცველი საკვების ნაცვლად მას მაღალი კვებითი ღირებულების მქონე ჯანსაღი საკვები უნდა შესთავაზოთ.') WHERE id = 'c7406d7d-33c9-4160-91a7-a354953cf5b3';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში ბავშვისთვის დამოუკიდებლად, საყრდენის გარეშე ჯდომა გაცილებით მარტივი ხდება. როცა დამოუკიდებლად ჯდომასა და თქვენი დახმარების გარეშე სათამაშოებით თამაშს დაიწყებს, განსაკუთრებით საყვარელი მოგეჩვენებათ. ბავშვისთვის, რომელმაც ჯდომა აღმოაჩინა და უკვე თავისუფლად შეუძლია ეს, ეს პერიოდი განვითარების მნიშვნელოვანი ეტაპია: იგი სამყაროს ახალი რაკურსით ხედავს და მეტ დამოუკიდებლობასაც იძენს. ამის წყალობით ბავშვისთვის ახალი აღმოჩენების შესაძლებლობები გაჩნდება და იგი გარემოს განსხვავებული კუთხით დანახვას დაიწყებს. ზურგისა და კისრის კუნთების გაძლიერების შედეგად ბავშვი უკვე საკმარისად აკონტროლებს თავსა და ფეხებს. ეს კი მომავალში მისთვის ხოხვას, ფეხზე დგომასა და სიარულს გაამარტივებს. თუმცა თუ შეამჩნევთ, რომ ბავშვს დიდხანს გამართულად ჯდომა არ შეუძლია და ზოგჯერ წონასწორობას კარგავს, ნუ შეშფოთდებით. 😊') WHERE id = 'c06b62a5-8d7b-4555-9d57-8340da61ad39';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ თვისთვის თქვენს ბავშვს დამატებითი კვების დაწყებიდან უკვე ერთი თვე შეუსრულდა. ამ ერთთვიანი გამოცდილების შედეგად მას შესაძლოა უკვე შეეძინა ღეჭვის, ყლაპვის, ხელში აღებული საკვების პირთან მიტანისა და დამოუკიდებლად ჭამის უნარები. თუ ეს პერიოდი ისე არ მიმდინარეობს, როგორც წარმოგედგინათ, მაშინვე ნუ შეშფოთდებით. არ არსებობს წესი, რომ ყველა ბავშვმა ეს პროცესი მარტივად უნდა გაიაროს. გახსოვდეთ, რომ ბევრი დედა თქვენ მსგავსად გრძნობს თავს. თუ ფიქრობთ, რომ ბავშვს დამატებითი საკვების მიმართ მადა არ აქვს, შეგიძლიათ რამდენიმე თამაში მოიფიქროთ, რათა უფრო ხალისით ჭამოს და საკვებთან ჯანსაღი დამოკიდებულება ჩამოუყალიბდეს. მაგალითად, შეგიძლიათ ითამაშოთ თამაში „თვითმფრინავი მოფრინავს“ ან სიმღერების თანხლებით აჭამოთ. ამ საკითხში ერთ-ერთი უმთავრესი წესია: როცა თქვენს ბავშვს გაჩერება მოუნდება, თქვენც უნდა შეჩერდეთ და ცოტა ხნით შეისვენოთ.') WHERE id = 'ca27271b-d34b-4ce7-b5f9-f4505e118771';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ თვეში ბავშვის სოციალური უნარები მნიშვნელოვნად განვითარდება. ამიტომ იგი ყურადღებით იწყებს იმ ოჯახის წევრებზე დაკვირვებას, რომლებთანაც ურთიერთობს. ამ ეტაპამდე დამახსოვრებული ინფორმაციის წყალობით თქვენი ბავშვი მიზეზშედეგობრივი კავშირების დანახვას სწავლობს. ნუ გაგიკვირდებათ, თუ თქვენი ხელებისა და ფეხების მოძრაობების ან თუნდაც მიმიკების გამეორებას შეეცდება! 😊 რა თქმა უნდა, ეს გარკვეულ პასუხისმგებლობასაც გაკისრებთ: კარგი მაგალითი უნდა მისცეთ! ბავშვის ცნობისმოყვარეობა ძალიან ძლიერია და იგი დიდი მონდომებით ცდილობს ყველაფრის აღმოჩენას. შეგიძლიათ შეზღუდვები დაუწესოთ ისეთ სიტუაციებში, რომლებმაც შესაძლოა ზიანი მიაყენოს, თუმცა ზედმეტი არ უნდა მოგივიდეთ. მაგალითად, თუ მისი ყურადღება მიიპყრო იმდენად პატარა ნივთმა, რომ შესაძლოა გადაყლაპოს, და მან იგი დასათვალიერებლად აიღო, ნაცვლად იმისა, რომ მაშინვე გამოართვათ ან მკაცრად მოექცეთ, ყურადღებით დააკვირდით და მხოლოდ მაშინ ჩაერიეთ, როცა ეს ნამდვილად აუცილებელია.') WHERE id = '84211613-fc78-4c1f-a816-22b155e0b89d';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'რადგან 7-ci თვეში ბავშვი ჯერ კიდევ სხვადასხვა საკვებს აგემოვნებს, იგი კვლავ დამატებით კვებაზე გადასვლის ეტაპზეა. ეს ძალიან მნიშვნელოვანი და კრიტიკული პერიოდია, რომელიც გავლენას მოახდენს ბავშვის კვებით ჩვევებზე მომდევნო წლებში და ზრდასრულ ასაკშიც კი. თქვენმა ბავშვმა შესაძლოა ზოგჯერ პირველად გასინჯულ საკვებზე უარი თქვას. ეს არ ნიშნავს, რომ მას ეს საკვები არასდროს მოეწონება. ასეთ შემთხვევაში ეს საკვები დროებით გვერდზე გადადეთ და რამდენიმე დღის შემდეგ კვლავ შესთავაზეთ. შესაძლოა იმავე დღეს შეთავაზების ფორმის ან მომზადების მეთოდის შეცვლაც ეფექტიანი აღმოჩნდეს. ამ პერიოდში, მაშინაც კი, თუ ბავშვს კბილები ჯერ არ ამოსვლია, მას შეუძლია მარცვლოვანი ტექსტურის საკვები ღრძილებით დასრისოს და მიირთვას. ამიტომ ნუ მოერიდებით მენიუში ასეთი ტექსტურის საკვების შეტანას. ამგვარი კვება პირისა და ენის კუნთების განვითარებასაც უწყობს ხელს და ბავშვს მეტყველების განვითარებაშიც დაეხმარება.') WHERE id = 'b07bfb17-d3e7-4626-8576-6365ec3ad72a';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის გონებრივი განვითარების მნიშვნელოვანი წინსვლის წყალობით, მას უკვე შეუძლია თავისი ქცევით მიგანიშნოთ, სურს თუ არა ჭამა. ძალიან მნიშვნელოვანია, ყურადღებით დააკვირდეთ მის ქცევას და ეცადოთ, გაუგოთ ბავშვს. როცა შია, ბავშვი, როგორც წესი, ჭირვეულობს, უგუნებოდ არის და ტირის. თუ ძალიან მოშივდა ან კვება დაგვიანდა და ჭამის დროს ტირის ან თავს გვერდზე აბრუნებს, ნუ დააძალებთ — ცოტა ხანს მოიცადეთ და შემდეგ კვლავ სცადეთ. კვების დასაწყისში ბავშვებს ხშირად ძალიან შიათ, ამიტომ შეიძლება იტირონ და ისე მოიქცნენ, თითქოს ვერ ხვდებიან, რა გააკეთონ. ასეთ შემთხვევაში სიმშვიდე შეინარჩუნეთ. სავარაუდოდ, თქვენი მშვიდი ქცევის ფონზე, რამდენიმე ლუკმის შემდეგ ისიც დამშვიდდება. როცა ბავშვი დანაყრდება ან რომელიმე საკვები აღარ სურს, სახესა და თავს გვერდზე მიაბრუნებს. ამ დროს გირჩევთ, შეწყვიტოთ კვება, რათა ბავშვს ჭამის მიმართ უარყოფითი დამოკიდებულება არ ჩამოუყალიბდეს.') WHERE id = 'b20385d7-4579-4424-bf85-74e142637de4';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მიუხედავად იმისა, რომ ბავშვმა დამატებითი საკვების გასინჯვა დაიწყო, გახსოვდეთ, რომ ამ პერიოდში მისი კვების ძირითადი წყარო კვლავ თქვენი რძე ან ხელოვნური ნარევია. ასევე, შესაძლოა სიფრთხილე დაგჭირდეთ ბავშვისთვის ხილის წვენების მიცემისას. განსაკუთრებით მაშინ, თუ ბავშვს კბილები უკვე ამოუვიდა, ხილის წვენში შემავალმა ფრუქტოზამ შეიძლება კარიესი გამოიწვიოს. ამიტომ გირჩევთ, შაქრის შემცველი ასეთი საკვები ბავშვს ბოთლით კი არა, კოვზით და თქვენი მეთვალყურეობით მისცეთ. ბავშვისთვის მომზადებული პიურეები და მარცვლოვანი, თხელი საკვებიც შეგიძლიათ კოვზით აჭამოთ და ამ დროს ყურადღებით დააკვირდეთ. ახლა უკვე შეგიძლიათ მისცეთ ბანანის, ვაშლისა და ატმის მსგავსი ხილის პიურეები, კარტოფილის, სტაფილოსა და ბროკოლის მსგავსი ბოსტნეულის პიურეები, ასევე მარცვლეულის ფაფები და იოგურტი. ყველაზე მნიშვნელოვანი კი ისაა, რომ ამ საკვებს არავითარ შემთხვევაში არ უნდა დაუმატოთ მარილი, შაქარი ან სანელებლები. გემრიელად მიირთვით! 😊') WHERE id = '6bf67fbd-887e-4592-8237-816fbe1d635c';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ სისუფთავის მიმართ ზედმეტად მგრძნობიარე ხართ, დამატებით კვებაზე გადასულმა ბავშვმა შეიძლება ცოტა დაგღალოთ. ამ პერიოდში ბავშვები აუცილებლად დასვრიან როგორც საკუთარ თავს, ისე გარშემო ყველაფერს. ამას ხელი არ უნდა შეუშალოთ, რადგან ამ გზით ისინი სამყაროს შეისწავლიან. გახსოვდეთ, რომ ზედმეტმა სიფაქიზემ და ჭამისას მომხდარ პატარა შემთხვევებზე თქვენმა უარყოფითმა რეაქციამ შეიძლება ბავშვი დაძაბოს. რა თქმა უნდა, შეგიძლიათ გამოიყენოთ წინსაფარი ან სხვა მარტივი დამცავი საშუალებები, თუმცა ბავშვი მაინც მოახერხებს ყველაფრის დასვრას. მომავალში, როცა ჭიქის დაჭერას, კოვზის გამოყენებასა და თითებით ჭამას დაიწყებს, გარემო კიდევ უფრო მეტად დასვრება. ბევრი ბავშვისთვის ჭურჭლის, კოვზებისა და საკვების ერთმანეთში არევა და მათი იატაკზე გადაყრა სახალისო თამაშია, რომელიც მადასაც კი უმატებს. ამიტომ გირჩევთ, ბავშვი ზედმეტად არ შეზღუდოთ, დასუფთავების გასამარტივებლად კი უბრალოდ იატაკზე სუფრა ან სხვა საფარი დააფინოთ! 😊') WHERE id = 'f21f46f4-fb93-42c1-b00e-d167770d53ea';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'დაბადების დღიდან 8 თვის ასაკამდე ბავშვი ყოველდღიურ ცხოვრებაში თქვენ მიერ გამოყენებულ თითოეულ სიტყვას ხანგრძლივ მეხსიერებაში ინახავს. დამახსოვრებული სიტყვები მნიშვნელოვნად უწყობს ხელს მისი მეტყველებისა და, შესაბამისად, გონებრივ განვითარებას. იმისათვის, რომ ეს პროცესი უფრო ეფექტიანი იყოს, ხშირად ესაუბრეთ ბავშვს და საუბრისას გამოიყენეთ მისთვის ჯერ კიდევ უცნობი, განსხვავებული სიტყვები. მაგალითად, როცა საყიდლებზე ერთად მიდიხართ, შეგიძლიათ პროდუქტები აჩვენოთ და აუხსნათ, რა არის თითოეული მათგანი. გააცანით ახალი სიტყვები ნივთების ფერზე, ფორმასა და ზომაზე საუბრით! იმ დღეებში კი, როცა გარეთ გასვლას ვერ ახერხებთ, შეგიძლიათ თქვენი საყვარელი წიგნი წაუკითხოთ, ახალი სიმღერა წაუღიღინოთ ან მოკლე ზღაპარი მოუყვეთ. ამგვარად, ბავშვს მოსმენის უნარს განუვითარებთ და, ამასთანავე, ერთად გართობით მის მომავალშიც ჩადებთ ინვესტიციას! 😊') WHERE id = '6715507c-2cf7-4220-9f23-3cb7294e08b4';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ვიცით, რამდენად გიყვართ ბავშვი და როგორ ყურადღებით ეკიდებით მის ჯანმრთელობას. თუმცა, რაც უნდა ჯანსაღად კვებავდეთ, დღეს სულ უფრო გავრცელებული კვებითი ალერგიების გამო ბავშვის იმუნურმა სისტემამ შეიძლება ყველა საკვები ვერ მიიღოს. განსაკუთრებით დამატებითი კვების პერიოდში, როცა ბავშვი სხვადასხვა საკვებს ეცნობა, ამ მხრივ მას ყურადღებით უნდა დააკვირდეთ. ალერგიის ნიშნები შეიძლება საკვების მიღებისთანავე ან 72 საათის განმავლობაში გამოვლინდეს. კვებითი ალერგია შეიძლება გამოვლინდეს კანზე გამონაყარით, ანუსის მიდამოს სიწითლით, ტუჩების გალურჯებით, მსტვენავი სუნთქვით ან კუჭ-ნაწლავის პრობლემებით. ალერგენთან შეხებისას საჭმლის მომნელებელი სისტემის რეაქცია შეიძლება იყოს ღებინება, დიარეა, სისხლიანი განავალი ან ყაბზობა. ამიტომ გირჩევთ, სიფრთხილე გამოიჩინოთ იმ საკვების მიმართ, რომელსაც ბავშვს პირველად ასინჯებთ, ხოლო ნებისმიერი არასასურველი სიმპტომის გამოვლენისას დაუყოვნებლივ დაუკავშირდეთ ექიმს.') WHERE id = 'd5afcb47-37bb-45af-b1be-9bc9b6cc67d8';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ეს ის თვეა, როცა ბავშვის აღმოჩენის სურვილი და ცნობისმოყვარეობა უმაღლეს დონეს აღწევს. მიუხედავად იმისა, რომ ის ჯერ კიდევ თქვენზეა დამოკიდებული, თანდათან საკუთარი თავისუფლების სივრცის გაფართოებას იწყებს. ამ თვის განმავლობაში შეიძლება მისი ხოხვის მცდელობების შედეგიც იხილოთ 😊 ამ მცდელობებისას ბავშვი უკეთ გააცნობიერებს, რომ დამოუკიდებელი არსებაა. ხოხვის გარდა, მისთვის კიდევ ერთი სიახლეა ის, რომ ახლა უკვე ნივთებისკენ უფრო ეფექტიანად შეუძლია ხელის გაწვდენა. მოძრაობის არეალის გაფართოებასთან ერთად ბავშვს აღმოჩენების სურვილიც უმძაფრდება. თუმცა გახსოვდეთ, რომ ამჟამად ბავშვი ორალურ პერიოდს გადის, ანუ ყველა ნივთის, რომლის გაცნობაც სურს, პირში ჩადებას ეცდება. ამიტომ გვსურს შეგახსენოთ, რომ უსაფრთხოების აუცილებელი ზომები მიიღოთ.') WHERE id = '79d6e9ac-e4be-4d51-9c67-149f74a4f03c';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მეშვიდე თვეში გადასული ბავშვის გრძნობის ორგანოები თითქმის ისევეა განვითარებული, როგორც ზრდასრული ადამიანის. ამ მხრივ, ბავშვის მხედველობა უკვე სრულად ჩამოყალიბებულად ითვლება. ამის წყალობით, ის შორს მყოფ ადამიანებსა და საგნებს საკმაოდ მკაფიოდ ხედავს და არჩევს. ასევე შეუძლია თვალყური ადევნოს ირგვლივ მიმდინარე სწრაფ და რთულ მოვლენებს და ზუსტად აღიქვას ისინი. რადგან სიღრმის აღქმა სრულად აქვს ჩამოყალიბებული, შეუძლია დააკვირდეს შორიდან მისკენ მოძრავ საგანს და მის დასაჭერად წინ გაიწიოს. 7 თვის ბავშვის სმენაც მხედველობის მსგავსად კარგად არის განვითარებული. ის უკვე მაშინვე ხვდება, საიდან მოდის ხმა და პირდაპირ მისკენ შეუძლია მიბრუნება. თუმცა ჩუმი და შორიდან მომავალი ხმების მოსასმენად შეიძლება ცოტა ხნით გაჩუმდეს და რეაქცია არ გამოხატოს.') WHERE id = 'e80c4140-2676-446b-a5dc-f1e0f240ee47';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'დამატებით კვებაზე გადასვლისას ერთ-ერთი ყველაზე გავრცელებული შეცდომაა ბავშვისთვის თითქმის ყოველ კვებაზე წვნიანის მსგავსი თხევადი საკვების მიცემა. განსაკუთრებით ძვლის ბულიონით მომზადებული წვნიანის სასარგებლო თვისებები, რა თქმა უნდა, მრავალრიცხოვანია. თუმცა ბავშვის კვების რაციონში მთავარი ადგილი წვნიანებს არ უნდა დაუთმოთ. მარცვლოვანი ტექსტურის მქონე და ღეჭვის უნარის განვითარებისთვის საჭირო საკვების დაგვიანებით მიცემამ შესაძლოა გარკვეული უარყოფითი შედეგები გამოიწვიოს. ასეთი საკვები არა მხოლოდ ბავშვის კვების ჩვევებს აყალიბებს, არამედ პირისა და ენის კუნთებსაც ავითარებს. ამიტომ ბლენდერით სრულად დაქუცმაცებული, პიურეს მსგავსი საკვებით კვება ზედმეტად დიდხანს არ უნდა გააგრძელოთ. წინააღმდეგ შემთხვევაში, კბილების ამოჭრის პერიოდში მყარ საკვებზე გადასვლა შეიძლება გართულდეს და ბავშვმა მისთვის უჩვეულო მარცვლოვანი საკვების ჭამაზე უარი თქვას.') WHERE id = '0eb37995-3090-4435-b8b9-edf48f0b68fb';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი, წინა თვეებისგან განსხვავებით, უკვე მხოლოდ ცალკეულ ხმოვნებს ან თანხმოვნებს აღარ წარმოთქვამს. მეშვიდე თვეში ის ხმოვნებსა და თანხმოვნებს აერთიანებს, მარცვლებს ქმნის და შეუძლია წარმოთქვას ისეთი ბგერათა კომბინაციები, როგორიცაა babababa, mamamama და kakakaka. ბავშვის მეტყველების განვითარების მხარდასაჭერად და წასახალისებლად რამდენიმე აქტივობის შესრულება შეგიძლიათ. მაგალითად, როდესაც ბავშვი კარგ ხასიათზეა, შეგიძლიათ მის მიერ წარმოთქმული ბგერები გაიმეოროთ. როცა ბავშვი გიყურებთ, ის ყურადღებით აკვირდება, როგორ საუბრობთ, და ცდილობს მოგბაძოთ. მნიშვნელოვანია, მეტყველებისთვის საჭირო მოძრაობები ოდნავ უფრო მკაფიოდ შეასრულოთ, რათა ბავშვმა ბგერების წარმოთქმისას თქვენი ენის, ტუჩებისა და სასის მოძრაობებს დააკვირდეს. ამიტომ საქმეები ერთი-ორი საათით გადადეთ და მოემზადეთ ბავშვთან ერთად მხიარული დროის გასატარებლად! კარგ გართობას გისურვებთ 😊') WHERE id = '50599786-43fc-4007-9b26-bc49949f135e';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენმა ბავშვმა დედის რძესთან ან ხელოვნურ ნარევთან ერთად დამატებითი საკვების მიღებაც უკვე დაიწყო. ამიტომ შეიძლება ფიქრობდეთ, რომ მან მეტი წონა უნდა მოიმატოს. თუმცა სინამდვილეში ეს ასე არ არის. ბავშვი უკვე საკმაოდ აქტიურია და მიუხედავად იმისა, რომ ზრდას განაგრძობს, მოსალოდნელი არ არის, პირველ თვეებთან შედარებით ბევრი წონა მოიმატოს. ამ თვეში ბავშვი საშუალოდ 350-400 გრამს მოიმატებს. ეს რიცხვები განვითარების შესაფასებლად გამოყენებული საშუალო მაჩვენებლებია. გახსოვდეთ, რომ ყველა ბავშვი ინდივიდუალურად ვითარდება; განსხვავება შესაძლოა გენეტიკამ, სქესმა და მეტაბოლიზმმა განაპირობოს. ზოგადად მიღებული წესის თანახმად, მოსალოდნელია, რომ ბავშვის წონა 5 თვის ასაკში დაბადების წონასთან შედარებით გაორმაგდეს, ხოლო 12 თვის ასაკში გასამმაგდეს.') WHERE id = '0bf43d37-a329-4f54-80f4-b9fdb2e13965';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენს ბავშვს აქამდე ბევრი ახალი გემო გააცანით. თუმცა შეიძლება კითხვები გაგიჩნდეთ, რატომ არ უნდა მისცეთ მას ჯერ კიდევ ზოგიერთი საკვები. ეს მთლიანად ბავშვის საჭმლის მომნელებელი სისტემის განვითარებასა და ნაწლავების მზაობას უკავშირდება. მაგალითად, ბევრ მშობელს აინტერესებს, რატომ არის მნიშვნელოვანი რაციონში ძროხის რძის არშეტანა. მიუხედავად იმისა, რომ ძროხის რძე მდიდარია ვიტამინებითა და მინერალებით, ის ბავშვის ჯერ კიდევ ჩამოუყალიბებელ თირკმელებს ზედმეტად ტვირთავს. ამასთანავე, ძროხის რძე ბავშვის ორგანიზმისთვის საჭირო ვიტამინების მოთხოვნილებას სრულად ვერ აკმაყოფილებს, რამაც შესაძლოა განვითარების შეფერხება და ზრდის შენელება გამოიწვიოს. გარდა ამისა, ძროხის რძე მცირე რაოდენობით იოდსა და თუთიას შეიცავს, რამაც შეიძლება ბავშვის გონებრივ განვითარებაზე უარყოფითად იმოქმედოს. ყველა ამ მიზეზის გამო, უმჯობესია ძროხის რძე ბავშვის კვების რაციონში ნელ-ნელა მხოლოდ 12 თვის ასაკის შესრულების შემდეგ შეიტანოთ.') WHERE id = 'e49d6509-b260-4b7c-8420-cc63289843b1';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენმა ბავშვმა მოკლე დროში განვითარების მართლაც დიდი გზა გაიარა და კვლავაც გააგრძელებს თქვენს გაოცებას! 😊 სამწუხაროდ, ამ ცვლილებებიდან ყველა ყოველთვის სასიამოვნო არ იქნება. მაგალითად, შეიძლება შეამჩნიოთ, რომ ბავშვს თქვენთან განშორება აღარ სურს და ამაზე მძაფრად რეაგირებს. ეს მდგომარეობა, რომელმაც შესაძლოა შეგაწუხოთ, ბავშვში განშორების შფოთვის ჩამოყალიბებაზე მიუთითებს. ზოგიერთი დედისთვის ეს შეიძლება პრობლემად არ ჩანდეს, თუმცა სათანადო ზომების მიუღებლობის შემთხვევაში მომავალში სირთულეები გამოიწვიოს. გარკვეული დროის შემდეგ ამან შეიძლება გამოიწვიოს ის, რომ ბავშვი თქვენი არყოფნისას თავს უბედურად და დაუცველად გრძნობდეს. ამის თავიდან ასაცილებლად ბავშვის მოვლაში ოჯახის წევრების დახმარება უნდა მიიღოთ და ის ამ მდგომარეობას თანდათან შეაჩვიოთ. მაგალითად, დღეს საღამოს თქვენ ნაცვლად ბავშვს ვახშამი თქვენმა მეუღლემ აჭამოს და ჭამის შემდეგ მასთან პირისპირ გაატაროს დრო.') WHERE id = 'ee5d1f29-7924-4191-bd02-dbcf16926418';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ სამსახურში დაბრუნება გიწევთ, შესაძლოა ბავშვის ფსიქოლოგიურ მდგომარეობასა და მოვლასთან დაკავშირებით გარკვეული წუხილი გქონდეთ. განშორების შიში ბავშვებში, როგორც წესი, მე-6 თვიდან იწყება და პიკს მე-12 თვეში აღწევს. ამის გამო თავი ცუდად არ უნდა იგრძნოთ, რადგან ეს ბავშვის განვითარების ნორმალურ პროცესად მიიჩნევა. სამსახურში დაბრუნებამდე ცოტა ხნით ადრე სასარგებლო იქნება ხანმოკლე განშორებების პრაქტიკა. მაშინაც კი, თუ ბავშვი ვერ ხვდება, რომ მიდიხართ, თბილად და ხალისიანად უნდა დაემშვიდობოთ და უთხრათ, რომ დაბრუნდებით. ამ პრაქტიკის დროს, რომ ბავშვმა თავი უცხოდ არ იგრძნოს, შეგიძლიათ ის თქვენთვისაც და მისთვისაც კარგად ნაცნობ ახლობელს დაუტოვოთ. ამ ადამიანთან წინასწარ ერთად დროის გატარება პროცესს მნიშვნელოვნად გაამარტივებს.') WHERE id = '99e99257-b0ed-4e0f-b789-5eb260e3fd9d';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'კვება ბავშვის ერთ-ერთი უმნიშვნელოვანესი ფიზიკური საჭიროებაა. ამიტომ სწორი და საკმარისი კვება ბავშვის განვითარების შეფერხების თავიდან ასაცილებლად და მისი ჯანსაღი ზრდისთვის აუცილებელი პირობაა. თუმცა ბავშვი ყოველთვის უპირობოდ არ დათანხმდება ჭამას. თქვენ მიერ დიდი მონდომებით მომზადებული ჯანსაღი კერძები ზოგჯერ ხელუხლებელი შეიძლება დარჩეს და გადასაყრელი გახდეს. ასეთ დროს უპირველესად არ უნდა დაუპირისპირდეთ ბავშვს. თუ გაჯიუტდებით, შესაძლოა ბავშვი კიდევ უფრო დააშოროთ ისეთ ბუნებრივ და ფიზიოლოგიურ საჭიროებას, როგორიც კვებაა. ამან ასევე შეიძლება თქვენსა და ბავშვს შორის გაუცხოება გამოიწვიოს. ამიტომ მოთმინება უნდა გამოიჩინოთ და საჭიროების შემთხვევაში ექიმს გაესაუბროთ, თუ როგორ უნდა მოიქცეთ.') WHERE id = '2f28f952-bd75-47db-822c-9ba614e24ba2';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის კვებისა და სუფრასთან ქცევის ჩვევების ჩამოყალიბებისას მნიშვნელოვანია, როდის დაიწყებს ის ოჯახთან ერთად სუფრასთან ჯდომას. სპეციალისტების აზრით, ბავშვი არაუგვიანეს მე-9 თვისა მშობლებთან ერთად უნდა იჯდეს სუფრასთან. ამიტომ ჭამის დროს, განსაკუთრებით მაშინ, როცა მთელი ოჯახი ერთად უსხედხართ სუფრას, შეგიძლიათ ბავშვიც შემოგიერთოთ. ამისთვის იდეალურია მაგიდასთან მისთვის განკუთვნილი საბავშვო კვების სკამი. კვების სკამში მჯდომი ბავშვი დააკვირდება, როგორ მიირთმევთ თქვენ და ოჯახის სხვა წევრები, რაც მისთვის ძალიან სასარგებლო გამოცდილება იქნება. სპეციალისტების აზრით, დაკვირვება და მიბაძვა ბავშვის სწავლის უმნიშვნელოვანესი საშუალებებია. ამასთანავე, ჭამის დროს ტელევიზორის გამორთვა და სუფრასთან სასიამოვნო გარემოს შექმნა ბავშვს კვებისადმი კიდევ უფრო მეტ ინტერესს გაუჩენს.') WHERE id = '2c9b0188-9d07-406a-bc48-6a8ce20aef72';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'სათამაშო ხალიჩა, რომელიც ბავშვს სიცოცხლის პირველ თვეებში ძალიან უყვარდა, საზღვრებს გასცდენილი პატარასთვის უკვე მოსაწყენი ხდება. ბავშვისთვის, რომელმაც აქტიურად მოძრაობა დაიწყო და რომლის საყვარელი საქმიანობაც ახალი რაღაცების აღმოჩენაა, შეზღუდვა ძალიან მოსაბეზრებელია. ამიტომ, როცა სათამაშო ხალიჩაზე დასვამთ, შესაძლოა იქ დარჩენა არ მოინდომოს და გააპროტესტოს! ასეთ დროს ნორმალურად უნდა მიიღოთ, რომ ბავშვი თავისუფლების მოთხოვნას ხმამაღლა გამოხატავს და რეაქციის გამოხატვის თავისუფლება უნდა მისცეთ. შეგიძლიათ ბავშვისთვის უსაფრთხოდ მოაწყოთ სახლის ერთი ოთახი ან, თუ შესაძლებელია, მთელი სახლი. თუმცა მომზადებული გარემო უსაფრთხოც რომ იყოს, მუდმივად ფხიზლად უნდა იყოთ და ბავშვს ყოველ წამს აკვირდებოდეთ. თუ აქტიური ბავშვის გამო საქმეების შესრულება გიჭირთ, მათი ნაწილი შეგიძლიათ მაშინ გააკეთოთ, როცა მას სძინავს ან სხვა ადამიანი უვლის.') WHERE id = '45a8e0d6-4932-4235-9823-06f0b7e8f85a';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მე-7 თვე ერთ-ერთი ის პერიოდია, როდესაც ბავშვის ახალი მოძრაობითი უნარები მნიშვნელოვნად ვითარდება. ამიტომ განსაკუთრებული ყურადღება უნდა მიაქციოთ, რა შეიძლება იყოს სახლში სახიფათო აღმოჩენების დიდი სურვილის მქონე პატარასთვის. შეგიძლიათ დამცავი ხუფებით დაფაროთ ელექტროროზეტები, რომლებიც ბავშვისთვის საფრთხეს წარმოადგენს, რადგან მას ყველაფრის დათვალიერება სურს, რაც ყურადღებას მიიქცევს. ასევე იატაკი სველი არ უნდა დატოვოთ და მთლიანად უნდა მოაშოროთ ისეთი საფრთხეები, როგორებიცაა ელექტროსადენები და ბასრი საგნები, რომლებმაც ბავშვს შეიძლება სერიოზული ზიანი მიაყენოს. ავეჯისა და ფანჯრის რაფების ბასრი კუთხეებისთვის შეგიძლიათ ხელმისაწვდომ ფასად შეძენილი დამცავები გამოიყენოთ. თუ სახლში არის კიბე, რომელსაც ბავშვი შეიძლება მისწვდეს, მის თავსა და ბოლოში აუცილებლად უნდა დაამონტაჟოთ უსაფრთხოების ბარიერები. ყველა ამ ზომის მიზანია, ბავშვმა თქვენ მიერ განსაზღვრულ უსაფრთხო საზღვრებში თავისუფლად შეძლოს გარემოს აღმოჩენა.') WHERE id = '616cd1ae-8a43-46fd-8952-aef7ae090d0b';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'დამატებით კვებაზე გადასვლის პერიოდში შეიძლება მოისურვოთ, ბავშვის განვითარებისა და ჯანმრთელობისთვის მას უმაღლესი კვებითი ღირებულების მქონე საკვები მისცეთ. თუმცა პროდუქტი, რომელიც თქვენთვის სასარგებლოა, ბავშვს შესაძლოა სარგებელზე მეტი ზიანი მოუტანოს. ამიტომ უნდა დაიცვათ ექიმთან ერთად შედგენილი გეგმა და ბავშვის საჭმლის მომნელებელი სისტემის განვითარების შესაბამისად იმოქმედოთ. მაგალითად, ვის არ მოუვა აზრად, რომ უგემური არ იყოს, მომზადებულ კარტოფილის პიურეს ცოტა მარილი დაუმატოს? თუმცა სპეციალისტები 1 წლამდე ბავშვებისთვის მარილის დამატების საკითხთან დაკავშირებით ძალიან მკაცრ რეკომენდაციას იძლევიან. ამ ეტაპზე ბავშვისთვის ბოსტნეულში ბუნებრივად არსებული მარილიც საკმარისია. ორგანიზმში ზედმეტი მარილის მოხვედრამ შესაძლოა ბავშვის თირკმელების ფუნქციაზე უარყოფითად იმოქმედოს. დიდი სიფრთხილე გამოიჩინეთ!') WHERE id = '6b656aed-9031-4b22-b6b9-5ed9b49d2799';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'დამატებითი კვების შესახებ ინფორმაციის მოძიებისას, ალბათ, შეგხვედრიათ ცნება BLW. „Baby Led Weaning“, შემოკლებით BLW, ბოლო წლებში მშობლებს შორის ერთ-ერთი ყველაზე ხშირად განხილული თემაა. BLW ჩვენს ენაზე შეიძლება ითარგმნოს, როგორც „ბავშვის მიერ მართული დამატებითი კვება“. ეს მიდგომა ეფუძნება ბავშვის მიერ დამოუკიდებლად ჭამის პრინციპს. BLW მეთოდი შესაფერისია ბავშვებისთვის, რომლებსაც შეუძლიათ თავის მყარად დაჭერა, კვების სკამზე დაუხმარებლად ჯდომა და ხელში მიცემული საკვების პირთან მიტანა. ამგვარად, თქვენს ბავშვს დახმარების გარეშე შეუძლია მიირთვას მისთვის სასურველი საკვები და თავად განსაზღვროს რაოდენობა. მიუხედავად იმისა, რომ BLW შედარებით ახალი მეთოდია, დაკვირვებები აჩვენებს, რომ ის ბავშვის განვითარებაზე დადებითად მოქმედებს.') WHERE id = '3224c721-5217-4489-ba14-724ab5302d3d';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი თვალსა და ხელს შუა ძალიან სწრაფად იზრდება, არა? თუ დაინახავთ, რომ მან ცოცვა დაიწყო, სულაც ნუ გაგიკვირდებათ! 😊 მართალია, იშვიათად, მაგრამ ზოგიერთმა ბავშვმა შეიძლება ამ თვეშივე დაიწყოს ცოცვა. თუმცა, თუ ამას ჯერ არ ამჩნევთ, ეს არ ნიშნავს, რომ თქვენი ბავშვი განვითარებას ჩამორჩება, ამიტომ ნუ ინერვიულებთ. ბავშვის ხელების, ფეხებისა და ზურგის კუნთები მნიშვნელოვნად გაძლიერდა, რის შედეგადაც მან საკუთარი ღერძის გარშემო გადაბრუნების უნარი თითქმის სრულად აითვისა. გარდა ამისა, როდესაც ბავშვს მუცელზე დააწვენთ, მას შეუძლია თავი სწრაფად ასწიოს და ხელებზე დაყრდნობით თავისუფლად გადაბრუნდეს. ზოგჯერ ამ ასაკში ბავშვებს ჯერ კიდევ არ შეუძლიათ დაუხმარებლად ჯდომა. ამ შემთხვევაშიც თქვენი ბავშვი განვითარებას არ ჩამორჩება. ჩვეულებრივ, ბავშვებს დაუხმარებლად ჯდომის უნარი სრულად დაახლოებით მე-8 თვეში უვითარდებათ.') WHERE id = '2f3bbf20-95fe-4b29-88f7-dede7edfcc73';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'კვლევების თანახმად, ბავშვები, რომლებსაც მშობლები ხშირად უმღერიან სიმღერებსა და იავნანებს, მომდევნო თვეებში მეტყველების რიტმს უკეთ აღიქვამენ. თქვენი ბავშვისთვის, რომელიც ყველაფერს, მათ შორის მეტყველებასაც, მიბაძვით სწავლობს, ძალიან მნიშვნელოვანია, რომ სიტყვები სწორად და შესაბამის სიტუაციაში გამოიყენოთ. მაგალითად, ცივ დღეს შეგიძლიათ თქვათ, რომ ცივა და აჩვენოთ, თითქოს შეგცივდათ. ამგვარად, თქვენი ბავშვი ამ სიტყვას უკეთ დაიმახსოვრებს და მიზეზშედეგობრივ კავშირსაც უფრო ადვილად გაიგებს. გარდა ამისა, ბავშვს კარგი მაგალითი რომ მისცეთ, რაც უნდა საყვარლად ჟღერდეს, მას დამახინჯებული სიტყვებით, ე.წ. ბავშვური ენით არ უნდა ელაპარაკოთ. მიეცით საშუალება, მოსმენილი სიტყვები მკაფიოდ და გასაგებად დაიმახსოვროს. ეს პროცესი უფრო სახალისო რომ გახადოთ, შეგიძლიათ ბავშვის მიერ გამოცემული ბგერები გაიმეოროთ. ეს მას ძალიან მოეწონება და ერთად მხიარულად გაატარებთ დროს.') WHERE id = '015590a4-be89-40bd-9634-b5bb65d23d50';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'დამატებით კვებაზე გადასვლის პერიოდში BLW-ის (ბავშვის მიერ მართული კვების) მეთოდის გამოყენება თქვენი ბავშვის განვითარებას მნიშვნელოვნად შეუწყობს ხელს. ამ მეთოდს გარკვეული წესები აქვს. ტრადიციული მეთოდისგან განსხვავებით, მთავარი ისაა, რომ ბავშვს დედამ კი არ აჭამოს, არამედ მან დამოუკიდებლად მიირთვას. თქვენს ბავშვს, რომელიც პირველი 6 თვის განმავლობაში მხოლოდ დედის რძეს ან ადაპტირებულ რძის ნარევს იღებდა, განსაკუთრებით გარდამავალ ეტაპზე, დამატებითი საკვები თავიდანვე დღეში 3-ჯერ არ უნდა შესთავაზოთ. ასევე, არ უნდა ეცადოთ ბავშვს საკვები ძალით აჭამოთ და თუ უარს ამბობს, არ უნდა დააძალოთ. დაიწყეთ დღეში ერთხელ და რაოდენობა თანდათან გაზარდეთ, ხოლო შესათავაზებელი საკვები ისე მოამზადეთ, რომ ბავშვმა მისი ხელში დაჭერა ადვილად შეძლოს. მთელი ამ პერიოდის განმავლობაში ბავშვი არასდროს დატოვოთ მარტო და მის ყოველ მოქმედებას ყურადღებით დააკვირდით. ამ მეთოდის მიზანია, ბავშვმა გემოები დამოუკიდებლად აღმოაჩინოს, განივითაროს ხელისა და თვალის კოორდინაცია და დამოუკიდებლად კვება ისწავლოს.') WHERE id = 'b805a548-3277-455e-8a43-b5228959fd35';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'განვითარებული აღქმის წყალობით, თქვენს ბავშვს უკვე შეუძლია მკაფიოდ განიშნოთ, როდის არის კმაყოფილი და როდის აწუხებს რამე. ის ამის გამოხატვას მოძრაობებითა და მიმიკებით იწყებს. ურთიერთობის დასამყარებლად კვლავ გამოსცემს ხმებს, რომლებიც მის მხიარულ ან მოუსვენარ განწყობაზე მიგანიშნებთ. თუ აქამდე ბავშვის კომუნიკაციის ძირითადი საშუალება ტირილი იყო, ახლა, მეტყველების განვითარებასთან ერთად, საკუთარი თავის გამოსახატავად შეიძლება რამდენიმე ჯერ კიდევ უშინაარსო სიტყვაც წარმოთქვას. რადგან საუბრისთვის პირის მოძრაობებს უფრო ეფექტურად იყენებს, ამ სიტყვებსაც უფრო მკაფიოდ გამოთქვამს. სხვადასხვა სიტყვის წარმოთქმის უნარი, თუნდაც მათ ჯერ მნიშვნელობა არ ჰქონდეთ, თქვენი ბავშვისთვის მნიშვნელოვანი ეტაპია. ეს ხმები მისთვის ნამდვილი დიალოგის დასაწყისია — ბავშვი გამოცემული ბგერებით ექსპერიმენტებს ატარებს, რეაგირებს და სოციალური კავშირების დამყარებას იწყებს.') WHERE id = '811dc858-78e1-4c23-aea6-584681b23792';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'დამატებითი კვების პერიოდში, განსაკუთრებით დასაწყისში, ბავშვისთვის საკვების გადაცდენა, ალბათ, თქვენი ერთ-ერთი ყველაზე დიდი შიში იქნება. თუ სასუნთქ გზებში რამე მოხვდება, თქვენი ბავშვი მის მოსაშორებლად ყველაფერს გააკეთებს. თუ საკვები ყელში გაეჩხირა, მაგრამ ბავშვი ახველებს, ტირის და ხმის გამოცემა შეუძლია, ეს ნიშნავს, რომ სასუნთქი გზა სრულად არ არის დახშული. დიდი ალბათობით, ბავშვი ამ მდგომარეობას თავად გაუმკლავდება. ასეთ შემთხვევაში საუკეთესო, რაც შეგიძლიათ გააკეთოთ, სიმშვიდის შენარჩუნება და ბავშვისთვის უსაფრთხოების განცდის შექმნაა. თუმცა, თუ ბავშვს დახრჩობის უფრო მძიმე ნიშნები აქვს, დაუყოვნებლივ უნდა დარეკოთ 112-ზე და სასუნთქი გზის გასახსნელად პირველადი დახმარება აღმოუჩინოთ. ამიტომ ძალიან მნიშვნელოვანია, სანდო წყაროებიდან ისწავლოთ ბავშვებისთვის პირველადი დახმარების გაწევის წესები.') WHERE id = '880904da-8e52-4e39-93ed-5f35ec843a62';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'როდესაც ბავშვი ლაპარაკს იწყებს, ამავდროულად მისი ენობრივი უნარებიც ვითარდება. თავდაპირველად მას შეიძლება თავადაც არ ჰქონდეს წარმოდგენა, რას ან როგორ ამბობს, თუმცა ზოგიერთი უაზრო ბგერა დროთა განმავლობაში ნამდვილ სიტყვებად გადაიქცევა. ასეთი ღუღუნი არა მხოლოდ აჩქარებს მის გონებრივ განვითარებას, არამედ ეხმარება, ბგერების გამეორებასა და დამახსოვრებაში გამოცდილება შეიძინოს. ამგვარად, ბავშვი შედის ეტაპზე, როდესაც ნათქვამის შერჩევამდე მოცდას იწყებს და სწავლობს, როგორ გამოიყენოს მეტყველება და მოძრაობები საკუთარი სურვილებისა და საჭიროებების გამოსახატავად. მიუხედავად ამისა, ნამდვილი სიტყვების წარმოთქმამდე მას შეიძლება ჯერ კიდევ გარკვეული დრო დასჭირდეს. ამ პერიოდში ბავშვი ენის წესების შესწავლას თქვენზე დაკვირვებითა და თქვენი მიბაძვით განაგრძობს. ამიტომ ძალიან მნიშვნელოვანია, სიტყვები სწორად, მკაფიოდ და სათანადო კონტექსტში გამოიყენოთ.') WHERE id = '8f6d0ab5-b074-476e-95ce-1532c933bec4';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის ჩონჩხის სიმტკიცე მხოლოდ ძვლების ჯანსაღი განვითარებით მიიღწევა. ეს პროცესი ჯერ კიდევ დაბადებამდე იწყება და განსაკუთრებით სწრაფად მიმდინარეობს სიცოცხლის პირველი წლის განმავლობაში. რადგან 6-თვიანი ასაკიდან ბავშვი დამატებით საკვებზე გადადის, მისი ძვლების გასაძლიერებლად ზრუნვა უკვე ახლა უნდა დაიწყოთ. ამ ეტაპზე ბავშვის ძირითად საკვებად კვლავ დედის რძე ან ხელოვნური ნარევი რჩება, თუმცა დამატებით საკვებთან ერთად მან კალციუმით მდიდარი პროდუქტებიც უნდა მიიღოს. დამატებითი კვების პერიოდის წინსვლასთან ერთად, დედის რძით მიღებული ვიტამინებისა და მინერალების რაოდენობა თანდათან მცირდება. ამიტომ კალციუმი, როგორც ბავშვის ძვლების გაძლიერებაში მნიშვნელოვანი წვლილის შემტანი მინერალი, განსაკუთრებით აუცილებელია. იმისთვის, რომ ბავშვის ორგანიზმმა საკმარისი კალციუმი მიიღოს, შეგიძლიათ შეუდგინოთ მენიუ, რომელშიც შევა ისეთი პროდუქტები, როგორებიცაა იოგურტი და მწვანე ფოთლოვანი ბოსტნეული.') WHERE id = '2697c6e2-7952-4ec2-98c7-54307a2fe921';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში თქვენი ცხოვრება შეიძლება ჩვეულებრივზე მეტად დატვირთული და ქაოსური გახდეს. განსაკუთრებით ახლა, როცა ბავშვი უკვე საკმაოდ აქტიურია, შეიძლება გაგიჭირდეთ ყველაფრის მოსწრება და გეგმების განხორციელება. ამ ეტაპზე არსებობს ბევრი რჩევა, რომელიც ცხოვრებას გაგიმარტივებთ. ზოგიერთი მათგანის გათვალისწინებით ცოტათი მაინც შეძლებთ შვებას. უპირველეს ყოვლისა, შეეცადეთ ბავშვის მოვლა, საკუთარ თავზე ზრუნვა და საოჯახო საქმეები ორგანიზებულად დაგეგმოთ. ბავშვის მოვლისთვის რეგულარულად გამოყენებულ ნივთებს მუდმივი ადგილი მიუჩინეთ. სახლში შეგიძლიათ გამოყოთ სივრცე, სადაც მხოლოდ ბავშვის საფენს გამოცვლით. ასე ყოველ ჯერზე აღარ მოგიწევთ საფენის, სველი ხელსახოცების, გამოსაცვლელი საფენისა და სხვა საჭირო ნივთების ცალ-ცალკე ძებნა. ასევე, ბავშვთან ერთად გარეთ გასვლისთვის საჭირო ნივთების მომზადება ბოლო წუთამდე არ გადადოთ. შეგიძლიათ კართან ახლოს ყოველთვის გქონდეთ გამზადებული დედისა და ბავშვის ჩანთა.') WHERE id = 'f71171e4-2818-49d6-8552-7761b12126d4';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ დღეებში თქვენს ბავშვს შესაძლოა განვითარების ხანგრძლივი ნახტომის პერიოდი დაეწყოს. ამიტომ შეიძლება შეამჩნიოთ ძილსა და საკვებზე უარის თქმა, ჭირვეულობა და ხელში ხშირად აყვანის სურვილი. განვითარების მეექვსე ნახტომი ბავშვის სავარაუდო დაბადების თარიღიდან 34-37-ე კვირებს შორის ხდება. ამ პერიოდის საკვანძო სიტყვაა „კატეგორია“. თქვენი ბავშვი, რომელიც უკვე გარკვეული ხანია პატარა მკვლევრად იქცა და გარშემო დანახულ ყველა ცოცხალ თუ უსულო ობიექტს აკვირდება, ახლა მათ გონებაში კატეგორიებად დაყოფას იწყებს. მაგალითად, წარმოიდგინეთ, რომ ბავშვთან ერთად ძაღლს შეხვდით. თქვენ მას ძაღლზე მიუთითეთ და უთხარით „ჰამ-ჰამ“. ბავშვი ამას გონებაში თავისებურად აკუთვნებს გარკვეულ კატეგორიას. რამდენიმე დღის შემდეგ, როდესაც გარეთ კატას შეხვდებით, შეიძლება შეამჩნიოთ, რომ ბავშვი მასზეც „ჰამ-ჰამით“ რეაგირებს. მიზეზი ისაა, რომ თავის წარმოდგენაში მან ოთხ ფეხზე მოსიარულე არსებები ერთ კატეგორიას მიაკუთვნა. ალბათ ფიქრობთ, რომ ეს სწორი არ არის. თუმცა ის, რომ ბავშვს ჯერ კიდევ არ შეუძლია ასეთი განსხვავებების ზუსტად გარჩევა, სრულიად ბუნებრივი შეცდომაა.') WHERE id = '18fded6c-68c1-4a2f-8a8c-2cce06aa19e7';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვისთვის მისაცემი სითხის რაოდენობა შეგიძლიათ ექიმის რჩევისა და საკუთარი დაკვირვებების საფუძველზე განსაზღვროთ. თუ ბავშვი დღის განმავლობაში მოდუნებულია, აღებინებს ან საკვების მიღებაზე უარს ამბობს, შესაძლოა გაუწყლოება ივარაუდოთ. გარდა ამისა, ორგანიზმის გაუწყლოებისას სხეულის ტემპერატურაც ფიზიოლოგიურად იმატებს. ამიტომ ტემპერატურის გარკვეული ინტერვალებით შემოწმება ძალიან სასარგებლო იქნება. გაუწყლოების ზოგადი ნიშნებია: იშვიათი და მუქი ფერის შარდი, პირის სიმშრალე და ცრემლების გარეშე ტირილი. ამ პერიოდში დედის რძის ან ხელოვნური ნარევის რაოდენობის მკვეთრად შემცირებამაც შეიძლება ბავშვის ორგანიზმის გაუწყლოება გამოიწვიოს. გაუწყლოების თავიდან ასაცილებლად ერთ-ერთი ყველაზე მნიშვნელოვანი ნაბიჯია, ყოველდღიურად ბავშვისთვის საჭირო რაოდენობის სითხის მიწოდება არ გამოტოვოთ.') WHERE id = '61c2e7d6-1d91-41c2-969b-396148013b25';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი განუწყვეტლივ და საოცარი სისწრაფით განაგრძობს განვითარებას! ახლა, როცა 8-ე თვეში გადახვედით, ის უკვე უფრო გაცნობიერებულად და კონკრეტული მიზნის შესაბამისად იწყებს მოქმედებას. სხვა სიტყვებით რომ ვთქვათ, ბავშვს უკვე შეუძლია, სხვადასხვა სურვილი ტირილის გარეშე გამოხატოს. მაგალითად, როცა შია, მოუსვენრობის, წუწუნისა და ტირილის ნაცვლად შეიძლება მკაფიოდ თქვას „ნამ-ნამ“ (საჭმელი). როდესაც სწყურია, თავისი ჭიქის დანახვა ახარებს, ხოლო როცა შია, საჭმლის მომზადების დანახვაზე ძალიან აღელვდება. ეს თქვენი ბავშვისთვის გარდამტეხი ეტაპია — ახლა მას უკვე შეუძლია, მარტივად გაგაგებინოთ, რა სურს. როდესაც უმანკო თვალებით რამეს გთხოვთ, მას ესმის, რას ნიშნავს თქვენი პასუხი „კი“ ან „არა“. თუმცა ამ პასუხის შემდეგ როგორ მოიქცევა, მთლიანად მასზეა დამოკიდებული. 😊') WHERE id = '1886ab50-5a60-4760-b927-fa91d9c42779';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენს ბავშვს უკვე ადვილად შეუძლია მარტივი, მისი განვითარების დონის შესაბამისი ახალი თამაშების სწავლა. ასე რომ, არ შევცდებით, თუ ვიტყვით, რომ ნამდვილი თამაშების ეპოქაში შეაბიჯეთ. წარმატებებს გისურვებთ! 😊 ამ უნარის გასავითარებლად შეგიძლიათ ბავშვს ხშირად ეთამაშოთ. ის ინტერესით დაგაკვირდებათ და ყურადღებით მოგისმენთ. გარდა ამისა, თქვენს პატარას, რომლის ხელის მოტორული უნარებიც საგრძნობლად განვითარდა, შეუძლია იატაკზე ნაპოვნი სათამაშო გააზრებულად აიღოს და თავისუფლად ითამაშოს. პირველ თვეებთან შედარებით პატარა თავს უფრო დამოუკიდებლად გრძნობს, დაკარგულ ან დაგდებულ სათამაშოებს ეძებს და, ნაცვლად იმისა, რომ თქვენ მოგთხოვოთ, თავად იღებს. მას შეუძლია სათამაშოები და გარშემო ნაპოვნი ნივთები შეანჯღრიოს, დაარტყას ან გადააგდოს, რათა შეამოწმოს, გამოსცემენ თუ არა ხმას. მეტიც, თუ სათამაშოთი თამაში ჯერ არ დაუსრულებია, უფლებას არ მოგცემთ, ხელიდან გამოართვათ და ამას გააპროტესტებს.') WHERE id = 'fe525d42-0a0a-48cc-aa11-ecad88d56b2a';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'შესაძლოა, გაინტერესებდეთ, როდის უნდა დაიწყოთ თქვენი ბავშვისთვის სასწავლო ჭიქის (საწრუპიანი ჭიქის) გამოყენება. შესაფერისი დროის დადგომას მხოლოდ ბავშვზე დაკვირვებით მიხვდებით. თუ ბავშვს ენით გამოდევნის რეფლექსი გაუქრა, ეს ნიშნავს, რომ ის უკვე მზადაა სასწავლო ჭიქისთვის. ენით გამოდევნის რეფლექსი ნიშნავს, რომ პირველ თვეებში ბავშვი პირში მოხვედრილ უცხო საგანს ავტომატურად ენით გარეთ უბიძგებს. სინამდვილეში, ეს რეფლექსი ბავშვისთვის სასიცოცხლოდ მნიშვნელოვანია, რადგან მას გადაცდენისა და დახრჩობის საფრთხისგან იცავს. საშუალოდ, 4-ე თვიდან ეს რეფლექსი სუსტდება, ხოლო 6-8-ე თვეებს შორის მთლიანად ქრება. ამ რეფლექსის გაქრობა ასევე პირველი ნიშანია იმისა, რომ ბავშვს უკვე შეუძლია ბოთლის ნაცვლად ჭიქიდან წყლის დალევა.') WHERE id = '52c260d9-9803-4e1b-9fc5-0c188ff2d7d3';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, '8 თვის ბავშვების წონა საშუალოდ დაახლოებით 8000 გრამია. ამასთან, ბავშვის წონა შეიძლება 6300-დან 11000 გრამამდე მერყეობდეს. თუმცა, განსაკუთრებით ამ თვეში, მომატებული აქტიურობის გამო, წონის მატება შეიძლება შენელდეს და თვის ბოლოს სასწორმა საშუალოდ 250-650 გრამით მეტი აჩვენოს. თუ თქვენი ბავშვი ნაადრევად დაიბადა, შესაძლოა უკვე დაეწიოს თანატოლებს, მაგრამ თუ ჯერ ვერ დაეწია, ნუ ინერვიულებთ — ჯერ გვიანი არ არის. წონის ასეთი ფართო დიაპაზონი გოგოებისა და ბიჭების სიმაღლისა და წონის განვითარების განსხვავებებსაც უკავშირდება. ბავშვის წონის მატებასთან ან მისი შენელებასთან დაკავშირებით ექიმის ინფორმირებისა და რჩევის გარეშე არანაირი ნაბიჯი არ უნდა გადადგათ. გახსოვდეთ, რომ თითოეული ბავშვის განვითარება ინდივიდუალურია; ქვედა ან ზედა ზღვარზე მყოფი ბავშვებიც შეიძლება სრულიად ჯანმრთელები იყვნენ.') WHERE id = '639ac35e-714a-47fc-b5c3-a25af9dcd029';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი უკვე საკმაოდ მიეჩვია დამატებით კვებას, რომელიც გარკვეული ხნის წინ დაიწყეთ, თუმცა კვლავ აგრძელებს დედის რძის ან ხელოვნური ნარევის მიღებას. განსაკუთრებით ამ პერიოდში დამღლელი შეიძლება იყოს იმის გამოთვლა, თუ რამდენი დამატებითი საკვები უნდა მიიღოს ბავშვმა ან რამდენი რძე უნდა დალიოს. თუმცა უნდა გახსოვდეთ, რომ კიდევ გარკვეული დროის განმავლობაში ბავშვის ძირითად საკვებად თქვენი რძე ან ხელოვნური ნარევი დარჩება. ამ თვიდან, აქტიურობისა და მეტაბოლიზმის სიჩქარის მიხედვით გარკვეული განსხვავებების მიუხედავად, მას დღეში საშუალოდ 850 კალორია სჭირდება. ნაწლავების ჯანმრთელობის დასაცავად ბავშვმა ამ კალორიების ნახევარზე მეტი კვლავ რძიდან უნდა მიიღოს. ამ ბალანსის შესანარჩუნებლად და დაბნეულობის თავიდან ასაცილებლად, როცა ბავშვს მოშივდება, ჯერ ძუძუთი კვებეთ ან რძე მიეცით. შემდეგ მოუმზადეთ ზომიერი ულუფა, რომელიც კვებითი ღირებულების მხრივ დაბალანსებული იქნება. ამ ეტაპზე ულუფა ბავშვის საჭიროების შესაბამისად შეგიძლიათ გაზარდოთ.') WHERE id = 'aaf40c8d-b2ab-4458-8b62-ca1e766f4975';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მიუხედავად იმისა, რომ თქვენმა ბავშვმა დამატებითი საკვების მიღება დაახლოებით 2 თვის წინ დაიწყო, 2 წლის ასაკამდე მის ძირითად საკვებად კვლავ დედის რძე რჩება. დამატებითი საკვები, რომელსაც აძლევთ, მხოლოდ შუალედურ კვებას ანაცვლებს. ამიტომ რძის რაოდენობის შემცირებამ შესაძლოა ბავშვის განვითარება შეაფერხოს. თუ ამ ბოლო დროს ფიქრობთ, რომ ბავშვს მადა არ აქვს, გვინდა შეგახსენოთ, რომ მარტო არ ხართ. 😊 აქტიური თამაშის პერიოდში გადასვლის გამო, ბავშვს შეიძლება არ სურდეს დიდი დრო დაუთმოს ისეთ საჭიროებებს, როგორიცაა კვება და ძილი. ამიტომ შეგიძლიათ მისი საყვარელი საქმიანობა — თამაში — კვების დროს შეუთავსოთ! იმისათვის, რომ კვება სახალისო გახადოთ, შეგიძლიათ საკვები საინტერესოდ გაუფორმოთ და ჭამისას ითამაშოთ ისეთი თამაშები, როგორებიცაა „ჭიტა“ ან „თვითმფრინავი მოფრინავს“. ასევე შეგიძლიათ თითის თოჯინებიც გამოიყენოთ. კარგად გაერთეთ! 😊') WHERE id = 'd21c1f6a-5fc9-4cad-8563-f3edc47a4f56';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ თვიდან ბავშვის თავის გარშემოწერილობის ქვედა ზღვარი 41 სმ-ია, ხოლო ზედა — 47 სმ. 8 თვის ბავშვის თავის გარშემოწერილობა საშუალოდ დაახლოებით 44 სმ-ია. რადგან თავის გარშემოწერილობის ზრდა ტვინის განვითარების მაჩვენებელია, ის რეგულარულად უნდა გაიზომოს. 8 თვის ბავშვის სიმაღლე შეიძლება 62 სმ-დან 77 სმ-მდე იყოს. ამ პერიოდში შესაძლოა ასევე შენიშნოთ, რომ ბავშვის ყიფლიბანდი გამკვრივებას იწყებს. ჩვეულებრივ, ყიფლიბანდი 12-18 თვეებს შორის იხურება, თუმცა ზოგიერთ ბავშვთან მისი დახურვა შესაძლოა უკვე 8-ე თვიდან დაიწყოს. თუ ტვინის განვითარება გრძელდება, ეს მდგომარეობა ფიზიოლოგიურად ნორმად ითვლება და შეშფოთების მიზეზი არ არსებობს.') WHERE id = '4019cfbc-4717-4ff6-83d7-b0dd34ad99d7';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი არა მხოლოდ კარგად თამაშობს, არამედ უკვე კარგი დამკვირვებელიც გახდა. ის ყურადღებით აკვირდება თქვენ და ოჯახის სხვა წევრებს და მოკლე დროში შეუძლია ქცევებისა და ბგერების მიბაძვა. მაგალითად, როცა მამა სამსახურში მიდის და თქვენ ხელის დაქნევით ემშვიდობებით, ამან შეიძლება ბავშვის ყურადღება მიიქციოს და მანაც მიმავალს ხელი დაუქნიოს. ეს იმიტომ, რომ მის მიერ გამოცემული ბგერები და მიმიკები მისთვის უკვე გარკვეულ მნიშვნელობას იძენს. ამიტომ, როცა რამე სჭირდება, უფრო ხშირად იწყებს მარცვლების წარმოთქმას. ბავშვი უკვე აცნობიერებს გარშემომყოფებსა და მიმდინარე მოვლენებს, ხოლო თანდაყოლილ რეფლექსებს თანდათან სრულად გააზრებული და მიზანმიმართული მოძრაობები ანაცვლებს. ეს კი იმის დასტურია, თუ რამდენად სწრაფად განვითარდა იგი მოკლე დროში. 😊') WHERE id = '980f8f43-3138-49d0-a45d-59c21bfd0cd3';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი ახლა უფრო მოძრავია, ვიდრე ოდესმე, და სხვა ბავშვების მსგავსად, შესაძლოა, საფენის გამოცვლა საერთოდ არ მოსწონდეს. 😊 განსაკუთრებით მაშინ, როცა ჭუჭყიან საფენს ხსნით, ბავშვი შვებას გრძნობს. ამიტომ, როდესაც დაინახავს, რომ სუფთა საფენის ჩაცმას აპირებთ, შეიძლება ხელებითა და ფეხებით წინააღმდეგობა გაგიწიოთ. 😊 თუ თქვენმა ბავშვმა უკვე დაიწყო ხოხვა, შესაძლოა, საფენის შესაკრავად ცოტა ხანს მისდევდეთ კიდეც. თუ წინააღმდეგობის გაწევისას ბავშვს დაჟინებით აიძულებთ, ამან შეიძლება მასში სტრესი გამოიწვიოს. ამიტომ, საფენის გამოცვლის პროცესი უფრო სახალისო გახადეთ და საქმეც გაგიადვილდებათ. ამის უმარტივესი გზა, რა თქმა უნდა, მისი ყურადღების გადატანაა. საფენის გამოცვლისას უმღერეთ, მოუყევით, რას აკეთებთ, ან მიეცით საყვარელი სათამაშო — ეს საქმეს მნიშვნელოვნად გაგიადვილებთ. 😊') WHERE id = 'fe2747a5-5b02-4aab-bf69-6b7fa1ec81f8';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი გონებრივი განვითარების ერთ-ერთ ყველაზე აქტიურ ეტაპზე გადავიდა. მას არა მხოლოდ ახლომდებარე ხმების მკაფიოდ მოსმენა შეუძლია, არამედ სმენაც იმდენად აქვს განვითარებული, რომ უფროსების მსგავსად შორიდან მომავალი ხმებიც გაარჩიოს. ბავშვის მხედველობა, სმენა და სიღრმის აღქმა მნიშვნელოვნად განვითარდა, ამიტომ სამყაროს აქტიურად შესწავლას განაგრძობს. სწორედ ამიტომ მისი ხელები და ფეხები მუდმივად მოძრაობს. მას უკვე შეუძლია ყველა თითი მიზანმიმართულად გამოიყენოს და საგნებს მაგრად ჩაეჭიდოს. ასევე იწყებს საჩვენებელი თითის აქტიურად გამოყენებას, რათა მისაწვდომ საგნებს უბიძგოს და პატარა ღრიჭოები გამოიკვლიოს. ამიტომ შესაძლოა დაგჭირდეთ უსაფრთხოების ზომების მიღება, განსაკუთრებით ბავშვისთვის საშიში ადგილების, მაგალითად, ელექტროროზეტების დასაცავად.') WHERE id = '0856b508-32f1-46be-891e-90f4409ee60b';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი დამატებითი კვების პროცესს უკვე საკმაოდ შეეჩვია. თუ საკვებს ჯერ კიდევ პიურეს სახით აძლევთ, შეგიძლიათ თანდათან უფრო ტექსტურიან საკვებზე გადახვიდეთ. სპეციალისტები ამ თვიდან შედარებით მკვრივი საკვების შეთავაზებას გირჩევენ, რადგან ბავშვს ღეჭვის უნარი უვითარდება. მხოლოდ პიურეთი და ძალიან რბილი საკვებით დიდხანს კვებამ მომავალში შეიძლება კვებასთან დაკავშირებული დარღვევები გამოიწვიოს. თუმცა საკვების კონსისტენცია ერთბაშად არ უნდა შეცვალოთ, რადგან სწრაფმა გადასვლამ შეიძლება შეკრულობა და საჭმლის მომნელებელი სისტემის ზოგიერთი პრობლემა გამოიწვიოს. ამიტომ საკვების ტექსტურა ყოველდღიურად ოდნავ გაამკვრივეთ, რათა გადასვლა თანდათანობით და მსუბუქად მოხდეს.') WHERE id = '72760305-9a29-4db8-960b-c7c0f371cc22';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ თვიდან თქვენს ბავშვს უკვე შეუძლია ყოველგვარი დახმარების გარეშე დამოუკიდებლად ჯდომა. ხელებისა და ფეხების კუნთების გაძლიერების გამო მისთვის ხოხვა უფრო ადვილი ხდება. თუმცა გახსოვდეთ, რომ ეს არ ნიშნავს, თითქოს ყველა ბავშვმა აუცილებლად უნდა იხოხოს; თუ თქვენი ბავშვი არ ხოხავს, ეს განვითარების შეფერხებად არ ითვლება. ამასთან, თუ სახლში კიბე გაქვთ, შესაბამისი უსაფრთხოების ზომები უნდა მიიღოთ, რადგან მოძრავ ბავშვს მასზე აცოცება უფრო ადვილად შეუძლია. ამ თვეში ბავშვმა შეიძლება მჯდომარე მდგომარეობიდან რომელიმე საგანზე მოჭიდებით წამოდგომა სცადოს და, ჩვეულებრივ, საყრდენის დახმარებით მცირე ხნით ფეხზე დგომაც შეძლოს. მიუხედავად იმისა, რომ ჯერ სიარული არ შეუძლია, იღლიებში ხელის მოკიდებისას შეიძლება ნაბიჯების გადადგმის რეფლექსი გამოავლინოს. თუმცა ამას ნუ აიძულებთ — ბავშვის სურვილი მიგანიშნებთ, როგორ მოიქცეთ სწორად.') WHERE id = 'a563d702-5875-4391-a1d5-846178e0f653';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ახლა უკვე შეგიძლიათ ბავშვის კვების რაციონში ხმელი პარკოსნები, ოსპი და თევზი დაამატოთ. ღეჭვის უნარის განვითარებისა და საჭმლის მომნელებელი სისტემის თანდათანობით ჩამოყალიბების წყალობით, თქვენი ბავშვი მზადაა ამ პროდუქტების მისაღებად. ხმელი პარკოსნები ძალიან მნიშვნელოვანია, რადგან ისინი ცილის საჭიროების დაკმაყოფილებას უწყობს ხელს და ვიტამინებისა და მინერალების უხვი წყაროა. ოსპი კი მდიდარია რკინით, B ჯგუფის ვიტამინებით, ფოლიუმის მჟავითა და სხვადასხვა მინერალით. ოსპს თითქმის ისეთივე კვებითი ღირებულება აქვს, როგორიც წითელ ხორცს, ამიტომ ის ბავშვის ჯანსაღი კვებისთვის მეტად ღირებული პროდუქტია. გარდა ამისა, ბავშვისთვის, რომელიც ახალ უნარებს იძენს, ომეგა-3 ცხიმოვანი მჟავები ძალიან საჭიროა. თევზი, რომელსაც მის რაციონში დაამატებთ, A და D ვიტამინებთან ერთად დიდი რაოდენობით ომეგა-3 ცხიმოვან მჟავებსაც შეიცავს.') WHERE id = '5436fc4f-86ab-41cc-af9e-5a2f20f1be86';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'შესაძლოა, ფიქრობთ, რომ ბავშვი თავისი ასაკისთვის დამახასიათებელ განვითარების ზოგიერთ ნიშანს არ ავლენს. ეს შეიძლება განსხვავდებოდეს, რადგან თითოეულ ბავშვს ზრდისა და განვითარების ინდივიდუალური ტემპი აქვს. განვითარების შეფერხება ნიშნავს ისეთი უნარების შედარებით ნელა განვითარებას, როგორებიცაა ჯდომა, ხოხვა, სიარული, გამართულად დგომა და ლაპარაკი. ხშირად ეს დროებითი შეფერხებაა და ბავშვების უმეტესობა ამ სხვაობას მოკლე დროში აღმოფხვრის. მიუხედავად იმისა, რომ ახალი უნარების შეძენა გარკვეული თანმიმდევრობით ხდება, არ უნდა დაგვავიწყდეს, რომ თითოეულ ბავშვს განვითარების საკუთარი რიტმი აქვს. მაგალითად, ზოგ ბავშვს მსხვილი მოტორული უნარები, როგორიცაა ჯდომა, უფრო ადრე უვითარდება, სხვებს კი — საგნების ხელში აღებისა და ჩაჭიდების უნარები. მიუხედავად ამისა, სიმშვიდისთვის შეგიძლიათ, თქვენთვის შემაშფოთებელ საკითხებზე ექიმს გაესაუბროთ.') WHERE id = '66787d5e-85c6-4974-9795-692e078d138d';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვი ფხიზლად ყოფნის დროის უმეტეს ნაწილს ახალი აღმოჩენებისთვის იყენებს. თუ ამ აღმოჩენების დროს ბავშვი რაიმეს ეყრდნობა და ფეხზე დგება, მნიშვნელოვანია, რომ მისი ტერფის ქუსლი იატაკს ეხებოდეს. ეს ბავშვის ფეხის კუნთების განვითარებისთვის ძალიან მნიშვნელოვანია და, გავრცელებული მოსაზრების საპირისპიროდ, ბრტყელტერფიანობას არ იწვევს. თუმცა გლუვ ზედაპირზე მოსრიალებისა და უბედური შემთხვევების თავიდან ასაცილებლად შეგიძლიათ გამოიყენოთ მოცურების საწინააღმდეგო ძირიანი ჩუსტები. გარეთ გასვლისას კი, მაშინაც კი, თუ ბავშვი ჯერ დამოუკიდებლად კარგად ვერ დადის, მისი ფეხების სიცხისა და სიცივისგან დასაცავად შესაძლოა ფეხსაცმელი დაგჭირდეთ. ამ ეტაპზე სპეციალური „პირველი ნაბიჯების“ ფეხსაცმლის შეძენა აუცილებელი არ არის. საკმარისია, თქვენ მიერ შერჩეული ფეხსაცმელი ბავშვის ფეხს კარგად ერგებოდეს, კოჭს ფარავდეს და სათანადოდ უჭერდეს მხარს.') WHERE id = 'b84764db-feb1-47bf-b057-d7266054d43f';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ორსულობის პერიოდში შესაძლოა, ერთ-ერთი საკითხი, რომელიც ყველაზე მეტად გაინტერესებდათ, ბავშვის თვალის ფერი იყო. 😊 დაბადების შემდეგ ბავშვის თვალები, როგორც წესი, მონაცრისფრო-მოლურჯო შეფერილობისაა. მიუხედავად იმისა, რომ ეს ფერები ძალიან ლამაზად გამოიყურება, სამწუხაროდ, ისინი დროებითია. ამის მიზეზი ისაა, რომ თვალის ფერადი გარსი ჯერ სრულად არ არის განვითარებული და სინათლეს თითქმის უცვლელად ირეკლავს. ამ თვიდან კი, პიგმენტაციის თითქმის დასრულების შედეგად, ბავშვის თვალები თავის ნამდვილ ფერს იღებს. თუ ბავშვის თვალები ყავისფერი გახდა, მათი სხვა ფერად შეცვლის ალბათობა აღარ არსებობს. თუმცა, თუ ისინი ჯერ კიდევ ღია ან ფერადი შეფერილობისაა, გახსოვდეთ, რომ 12 თვის ასაკამდე შესაძლოა ფერი კვლავ შეიცვალოს.') WHERE id = 'afcad808-5171-4e03-8941-cb9235ad0674';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'როდესაც ბავშვი ნაკლებ დედის რძეს ან ხელოვნურ ნარევს იღებს, შესაძლოა ინერვიულოთ, იღებს თუ არა ის საკვებიდან საკმარისი რაოდენობის ვიტამინებს. უპირველეს ყოვლისა, უნდა აღვნიშნოთ, რომ ნებისმიერი ვიტამინის ან საკვები დანამატის მიცემამდე აუცილებლად უნდა გაიაროთ კონსულტაცია ექიმთან. ამასთანავე, უნდა მოერიდოთ ბავშვის ერთფეროვან კვებას და იზრუნოთ, რომ მისი მენიუ მრავალფეროვანი იყოს. ბავშვის ვიტამინებისა და მინერალების საჭიროების დაკმაყოფილება განსაკუთრებით სეზონური ხილისა და ბოსტნეულის მიღებას უკავშირდება. გახსოვდეთ, რომ D ვიტამინი და სისხლწარმოქმნის ხელშემწყობი პრეპარატები (რკინის წვეთები), როგორც წესი, რუტინულად ინიშნება და ეს სტანდარტული პროცედურაა. თუ ბავშვი დღენაკლული დაიბადა, მცირე წონა აქვს ან განვითარების შეფერხება აღენიშნება, ექიმმა შესაძლოა დამატებითი საშუალებები გირჩიოთ. თუმცა ყველა ბავშვი განსხვავებულია, ამიტომ ყველაზე სწორ რჩევას მხოლოდ თქვენი და თქვენი ბავშვის მდგომარეობის მცოდნე ექიმისგან მიიღებთ.') WHERE id = 'a7e33135-d849-4e1d-b626-072569cf1acd';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენს ბავშვს უკვე შეუძლია საყრდენის გარეშე დამოუკიდებლად ჯდომა. ეს უნარი ხელს უწყობს, რომ უფრო მარტივად გადაბრუნდეს, ჩაიმუხლოს და იხოხოს. შესაძლოა, მან უკვე დაიწყო ხოხვა. 😊 თუმცა ისიც სრულიად ნორმალურია, რომ ზოგიერთმა ბავშვმა ხოხვის ეტაპი გამოტოვოს და პირდაპირ სიარული დაიწყოს. თქვენი მუდამ მოძრავი პატარა, როცა რაიმე საინტერესოს დაინახავს, ეცდება, იმ მიმართულებით გახოხდეს ან გადაადგილდეს. მისთვის საინტერესო საგნის პოვნის შემდეგ კი ხელში აიღებს, დაათვალიერებს და პირში ჩაიდებს, რათა უკეთ გაეცნოს. სწორედ ამიტომ, მას უფრო ყურადღებით უნდა დააკვირდეთ და, თუ ჯერ არ გაგიკეთებიათ, სახლში უსაფრთხოების აუცილებელი ზომები მიიღოთ.') WHERE id = 'f711661c-b42b-4a2c-9389-6ca7cb481b26';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი, სავარაუდოდ, ჯერ კიდევ განვითარების ნახტომის პერიოდშია, ამიტომ გარკვეული სირთულეების განცდა ბუნებრივია. სწრაფმა ზრდამ და ახალი უნარების შეძენამ ზოგჯერ შესაძლოა მადის დაქვეითება გამოიწვიოს, თუმცა ზოგ ბავშვში, პირიქით, მადა საგრძნობლად იმატებს. ამიტომ თქვენს პატარას დღის განმავლობაში შესაძლოა უფრო ხშირად მოუნდეს ძუძუს წოვა. ამ პერიოდში შეგიძლიათ, სურვილის შესაბამისად დამატებითი საკვებიც შესთავაზოთ, რადგან სწრაფი განვითარებისთვის მის ორგანიზმს დამატებითი ენერგია სჭირდება; თუ ეს მოთხოვნილება არ დაკმაყოფილდება, ბავშვი შესაძლოა მოუსვენარი გახდეს. ამასთანავე, ამ პერიოდში გაძლიერებული განშორების შფოთვის გამო მას შესაძლოა არ სურდეს თქვენგან მოშორება. ასეთ მომენტებში გირჩევთ, ბავშვის ფსიქოლოგიურ კეთილდღეობაზე იზრუნოთ, შეეცადოთ მის გაგებას და მოთმინება გამოიჩინოთ. 😊') WHERE id = 'a8e0d4f7-6afa-42e9-8b05-07856071a068';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის ძილის რეჟიმი გარკვეულ პერიოდებში შეიძლება შეიცვალოს. ამ თვეში თქვენი ბავშვი დღე-ღამეში დაახლოებით 14-15 საათს ძილში ატარებს და ამ დროის დიდი ნაწილი ღამის ძილზე მოდის. თუმცა, რადგან დღის ძილი დადებითად მოქმედებს ბავშვის განვითარებაზე და ახალი უნარების შეძენაში ეხმარება, მას დღისით დაძინებაც სჭირდება. უახლესი კვლევები აჩვენებს, რომ დღის განმავლობაში პირველი ორი ძილი ბავშვის განვითარებაში განსაკუთრებით მნიშვნელოვან როლს ასრულებს. ბევრი ბავშვი დღის განმავლობაში იმდენად აქტიურია, რომ ღამით უკვე გაღვიძების გარეშე შეუძლია ძილი. თუ თქვენი ბავშვი ღამით ჯერ კიდევ იღვიძებს, ნუ ინერვიულებთ — ესეც სრულიად ნორმალურია.') WHERE id = '71a3cc6c-7792-4d5e-b2d9-206c74922dd9';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი ჯერ კიდევ მყარ საკვებზე გადასვლის ეტაპზეა და ყოველი ახალი კერძი, რომელსაც ის სინჯავს, მისთვის ახალი აღმოჩენაა. თუ BLW-ს (ბავშვის მიერ დამოუკიდებლად კვების) მეთოდს იყენებთ, ეს პერიოდი თქვენთვის უფრო სახალისო შეიძლება გახდეს. ამ მეთოდით ბავშვი საკვებს დამოუკიდებლად, ბუნებრივად და გამოცდილების მიღების გზით აღმოაჩენს. მართალია, ეს პროცესი შეიძლება ცოტა ქაოსური და ჭუჭყიანი იყოს, მაგრამ თქვენი პატარა საკვების გემოს, სტრუქტურასა და სუნს უკეთ განასხვავებს და ეფექტურად სწავლობს. ამ პროცესის წყალობით ის ზომის, ფორმის, წონისა და ტექსტურის მსგავს ცნებებს ბევრ ძვირადღირებულ განმავითარებელ სათამაშოზე უკეთ აღიქვამს. გარდა ამისა, ხელისა და თვალის კოორდინაციის განვითარებით ბავშვი სამომავლო ნატიფი მოტორული უნარების საფუძველს ქმნის. და რაც მთავარია, თქვენ ეხმარებით ბავშვს თავდაჯერებულობის მოპოვებაში! 😊') WHERE id = '55eccf49-79d1-4243-b6f7-4417e0ce8446';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვისთვის უკვე შეგიძლიათ საწვრთნელი ჭიქა შეიძინოთ! 😊 ზოგადად, ბავშვის ბოთლიდან ჭიქაზე გადასვლის პროცესი შეიძლება ცოტა რთული იყოს. ის ხომ ჯერ კიდევ დაბადებამდე მიეჩვია თითების წოვას, დაბადების შემდეგ კი — თქვენგან ძუძუთი კვებას ან ბოთლის წოვას. თუმცა ბოთლის ხანგრძლივად გამოყენებამ გარკვეული ასაკის შემდეგ შეიძლება ბავშვის პირის ღრუსა და კბილების განვითარებას ზიანი მიაყენოს. ამიტომ, ბოთლის გამოყენება თანდათან უნდა შეამციროთ და ჭიქიდან წყლის სმის ეტაპზე გადასასვლელად ისეთი დამხმარე საშუალებები გამოიყენოთ, როგორიცაა საწვრთნელი ჭიქა. სპეციალისტები, როგორც წესი, ბოთლის გამოყენების შემცირებას მე-9 თვიდან გვირჩევენ. თუმცა, თუ საწვრთნელ ჭიქას ბავშვის ყოველდღიურობაში უკვე ახლა ჩართავთ, გადასვლა უფრო მარტივი და თანდათანობითი იქნება.') WHERE id = 'b7595fc9-0616-4fd7-9f1c-a33935df996a';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის საჭმლის მომნელებელი სისტემა და ფერმენტების მუშაობა უკვე უფრო განვითარებულ ეტაპზეა. ეს ნიშნავს, რომ დროა, ბავშვი ახალ საკვებს გააცნოთ! 😊 მაგალითად, ექიმთან შეთანხმებით, ამ თვეში ბავშვის კვების რაციონს შეგიძლიათ ზეთისხილი, წიწაკა, მწვანე ლობიო, ყვავილოვანი კომბოსტო, ძაძა და ბუნებრივი სანელებლები დაამატოთ. ბევრი ექიმი მიიჩნევს, რომ ამ თვეში ბავშვის რაციონში ფქვილის ნაწარმის დამატებაც შეიძლება. თუმცა, რადგან თქვენი ბავშვის განვითარებისა და ფიზიკური ზრდის თავისებურებები ყველაზე უკეთ მისმა ექიმმა იცის, გირჩევთ, ამ საკვების მიცემა ექიმის თანხმობის გარეშე არ დაიწყოთ. ასევე შეგიძლიათ ისეთი სასარგებლო ბოსტნეული, როგორიცაა ბროკოლი და ყვავილოვანი კომბოსტო, პატარა ნაჭრებად დაჭრათ, ორთქლზე მოარბილოთ და ბავშვს შესთავაზოთ. ამ ბოსტნეულის მიცემისას საშუალება მიეცით, თავად დაიჭიროს და ჭამოს. გემრიელად მიირთვას! 😊') WHERE id = '8e3dae32-3e2f-4ba0-b882-845b799e8f32';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ზოგიერთი ბავშვისთვის კბილების ამოჭრა საერთოდ არ წარმოადგენს პრობლემას, თუმცა უმრავლესობისთვის ეს პერიოდი საკმაოდ შემაწუხებელია. ბავშვებს პირველი კბილები, როგორც წესი, 4-8 თვის ასაკში ამოსდით, თუმცა თითოეული ბავშვი განსხვავებულია და დროც შეიძლება იცვლებოდეს. შესაძლოა, თქვენი ბავშვის პირში მარგალიტის მარცვლებივით გამოჩენილი კბილები უკვე კარგა ხნის წინ ამოიჭრა. კბილების ამოჭრის პერიოდში ბავშვს მოუნდება, ხელები და ყველაფერი, რასაც იპოვის, პირში ჩაიდოს. ამის მიზეზი ისაა, რომ ქავილის მქონე ღრძილებზე ზეწოლით ხანმოკლე შვებას გრძნობს. ამ პერიოდში ბავშვის დასახმარებლად შეგიძლიათ მისცეთ მყარი და ცივი საკვები, რომელიც გარკვეული ხნით მაცივარში გქონდათ შენახული. ასევე, პროცესის გასამარტივებლად კარგი იქნება, თუ ყოველთვის ხელთ გექნებათ კბილების სპეციალური საღეჭი რგოლი.') WHERE id = 'fb599c82-fab1-4307-ae9d-156ed7a53d22';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ნატიფი მოტორული უნარების განვითარების შედეგად ბავშვს უკვე შეუძლია ნივთების ხელით დაჭერა. ამ პერიოდში შეიძლება შეამჩნიოთ, რომ ის ცდილობს, მის წინ დადებული კოვზი აიღოს და გამოიყენოს. სავარაუდოდ, ამას ჯერ სრულად ვერ შეძლებს, ცოტა ხანში დაიღლება და კვლავ ხელებით დაიწყებს ჭამას. ამ პერიოდში საკვების ხელით მოსრესა და მისი შესწავლის მცდელობა ბავშვს საკვების სტრუქტურასთან შეგუებაში ეხმარება. ამიტომ, ჯერ კიდევ არ არის საჭირო, ბავშვს ხელით ჭამაში ხელი შეუშალოთ. შეგიძლიათ, გარემოს ცოტათი დასვრის უფლება მისცეთ, თუმცა ჭამის სწავლებისას ბავშვისთვის წინსაფრის გაკეთებასა და მისი სკამის ქვეშ საფენის დაგებაში ცუდი არაფერია. გვსურს შეგახსენოთ, რომ თქვენ მიერ განსაზღვრულ ამ სივრცეში ბავშვს სასურველი მოძრაობის საშუალება მისცეთ და საჭიროების გარეშე არ ჩაერიოთ. 😊') WHERE id = '42d35bcf-5e08-438b-ab99-312796c2146c';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენს ბავშვს უკვე ძალიან სურს ფეხზე დგომა და სიარული. 😊 ამ ეტაპზე შეიძლება იფიქროთ, რომ მას პირველი ნაბიჯებისთვის განკუთვნილი ფეხსაცმელი სჭირდება. სიარულის დამწყები ბავშვისთვის სწორად შერჩეული პირველი ფეხსაცმელი ძალიან მნიშვნელოვანია ტერფებისა და ხერხემლის განვითარებისთვის. ბავშვის მთელი სხეული და, შესაბამისად, ჩონჩხიც სწრაფად იზრდება, ამიტომ სიარულის დაწყებისას მას ყველაზე მეტად ისეთი ფეხსაცმელი სჭირდება, რომელიც ამ განვითარებას ხელს შეუწყობს. თუმცა მნიშვნელოვანია, ფეხსაცმლის ჩაცმა არ იჩქაროთ. სპეციალისტები გვირჩევენ, რომ სიარულისთვის მომზადების პერიოდში ბავშვმა სახლში ფეხშიშველმა იაროს. ამგვარად, ის უკეთ შეიგრძნობს ზედაპირს და სიარულზე გადასვლის პერიოდსაც უფრო მარტივად გაივლის.') WHERE id = '073f0168-833f-4ba2-9b9a-e5fecf81e92a';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვისთვის ჭამის დროს ყურება, ალბათ, მრავალი დედის მსგავსად, თქვენთვისაც ძალიან სახალისოა. თუმცა ბავშვის ტვინის უჯრედები ინფორმაციის დასამუშავებლად მზადაა და ის ემოციების შეცნობისადმი ახლა განსაკუთრებით გახსნილია. ამიტომ მასზე დაკვირვებისას ძალიან მნიშვნელოვანია, ყურადღება მიაქციოთ საკუთარ მიმიკებსა და რეაქციებს. მაგალითად, თუ ბავშვი ჭამის ნაცვლად დიდხანს თამაშობს, თქვენმა რეაქციამ შეიძლება წაახალისოს, რომ საკვებით კიდევ უფრო მეტად ითამაშოს. ანალოგიურად, თუ ის საკვებს აქეთ-იქით ყრის და ამით ერთობა, თქვენმა უჩვეულო ან მკაცრმა რეაქციამ შეიძლება მდგომარეობა კიდევ უფრო გააუარესოს. გადაჭარბებული რეაქცია ბავშვისთვის ძალიან საინტერესოა და მან შეიძლება საკვები უფრო ხშირად მიმოფანტოს მხოლოდ იმისთვის, რომ თქვენს რეაქციას კვლავ დააკვირდეს. თუ არ გსურთ, ეს ჩვევად ექცეს, შეგიძლიათ საკვები ცოტა ხნით მოაშოროთ ან თავად აჭამოთ.') WHERE id = '27035cad-7cd4-42d9-90d6-1a67f36eaafc';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ფიქრობთ, ბავშვს სიარულში დასახმარებლად ჭოჭინა უყიდოთ? თუმცა ბავშვისთვის ჭოჭინის ყიდვა ფეხზე დგომის დაწყებისთანავე დიდი შეცდომაა. კვლევებმა აჩვენა, რომ ჭოჭინა სიარულის დაწყებას არ აჩქარებს და, პირიქით, შესაძლოა რამდენადმე შეაფერხოს კიდეც. ჭოჭინაში ჩასმულ ბავშვებს სხეულის არასწორი პოზისა და წონის არათანაბარი განაწილების გამო ხერხემლის პრობლემები შეიძლება განუვითარდეთ. ასევე, მენჯ-ბარძაყის სახსარზე ზეწოლისა და იატაკამდე მიუწვდომლობის გამო ფეხის თითებით ბიძგის შედეგად შესაძლოა ფეხის კუნთები არათანაბრად განვითარდეს. ამერიკის შეერთებულ შტატებში ჩატარებულმა კვლევამ აჩვენა, რომ სიცოცხლის პირველი წლის განმავლობაში ბავშვებში თავის ქალის ტრავმების მიზეზთა 90% ჭოჭინასთან დაკავშირებული უბედური შემთხვევები იყო. ჩვენს ქვეყანაშიც თითქმის ყველა ექიმი თანხმდება, რომ ჭოჭინის გამოყენება რეკომენდებული არ არის.') WHERE id = '98a525b0-85c4-44ad-bd1f-bf93b8cfb809';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში ბავშვის კვების რაციონი უკვე მყარი საკვების საფუძველზე იწყებს ჩამოყალიბებას. თუ ჯერ კიდევ აძლევთ პიურეს სახით მომზადებულ საკვებს, უკვე მყარი ფორმით და ისე უნდა შესთავაზოთ, რომ ბავშვმა მისი ხელში დაჭერა შეძლოს. ამგვარად, ღეჭვისა და მოჭიდების უნარების განვითარებასთან ერთად, ხელს შეუწყობთ ხელისა და თითების კუნთების გაძლიერებასაც. ზოგიერთმა მყარმა საკვებმა ბავშვის ორგანიზმში შეიძლება მოულოდნელი რეაქცია გამოიწვიოს. ამიტომ მყარი საკვები ერთმანეთში შერევის გარეშე უნდა მისცეთ და სხვა პროდუქტზე მხოლოდ სულ მცირე სამი დღის შემდეგ გადახვიდეთ, როცა დარწმუნდებით, რომ ალერგიული რეაქცია არ გამოვლენილა. ალერგია, ჩვეულებრივ, ბავშვის სხეულზე გამონაყარითა და განავლის კონსისტენციის ცვლილებით ვლინდება. ამიტომ განსაკუთრებით მნიშვნელოვანია, არ მისცეთ ისეთი პროდუქტები, რომელთა ალერგიის გამოწვევის მაღალი რისკიც დადასტურებულია, ხოლო ახალი საკვები სათითაოდ გაასინჯოთ.') WHERE id = 'e4b85e6a-69c4-455d-9f99-5bcc0f9dfafa';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'იმის დანახვა, თუ როგორ წარმოუდგენელი სისწრაფით იზრდება თქვენი ბავშვი, ალბათ, თქვენც და თქვენს ახლობლებსაც დიდ ბედნიერებას განიჭებთ. და რას იტყვით იმაზე, რომ მის ღიმილს უკვე სიცილიც დაემატა? 😊 განსაკუთრებით ამ პერიოდში ბავშვმა მრავალი ახალი უნარი შეიძინა და შესაძლოა ყველა მათგანისთვის თვალის მიდევნება გაგიჭირდეთ. მაგალითად, მას უკვე შეუძლია ყოველგვარი დახმარებისა და საყრდენის გარეშე თავისუფლად ჯდომა. თუ გავითვალისწინებთ, რომ ხოხვასაც კარგად მიეჩვია, ბუნებრივია, ამ ახლად შეძენილი უნარის მუდმივად გამოყენება სურდეს. ამ კვირებში ბევრი დედა ამბობს, რომ მათ ბავშვებს რაიმეზე მოჭიდებით მცირე ხნით ფეხზე დგომა შეუძლიათ. თუმცა ფეხზე დგომის დაწყების დრო თითოეულ ბავშვში კუნთების განვითარების მიხედვით განსხვავდება. ამიტომ გირჩევთ, ბავშვს ეს არ დააძალოთ, სანამ თავად არ ეცდება. 😊') WHERE id = 'e8faa9c0-7a4a-4a69-af25-bd6473750397';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ახლა იმ თვეებში ხართ, როდესაც ბავშვი თანდათან დამოუკიდებლობის შეგრძნებით ტკბობას იწყებს. თუ მან უკვე დაიწყო ხოხვა, წინ საკმაოდ აქტიური პერიოდი გელით. თუ ჯერ არ ხოხავს, დიდი ალბათობით, ამ თვეში დაიწყებს. ხოხვის წყალობით, ბავშვს უკვე შეუძლია სასურველ დროს მისწვდეს სათამაშოებს და ისე ითამაშოს, როგორც თავად სურს. თუმცა ამ ასაკიდან ზოგიერთ ბავშვს შეიძლება მობეზრდეს სათამაშოები, რომლებითაც გარკვეული ხანია თამაშობს. ანუ, თუ ჩვეულებრივი სათამაშოები მის ყურადღებას აღარ იპყრობს, შესაძლოა სახლში აღმოჩენილი ყველა კარადის და უჯრის ქექვა დაიწყოს! თქვენი ბავშვი უკვე ახალი აღმოჩენების ძიებაშია და დიდი ენთუზიაზმით ცდილობს ყველა იმ ნივთის გაცნობას, რომელიც აქამდე არ უნახავს. ამიტომ გირჩევთ, ბავშვის უსაფრთხოება უპირველესად უზრუნველყოთ და შეძლებისდაგვარად მუდმივად ადევნოთ თვალი.') WHERE id = '5cb2c5a3-52c5-4353-87cf-7a048de6a6ae';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ჯანმრთელობის მსოფლიო ორგანიზაცია (ჯანმო) ევროპის რეგიონის სხვადასხვა ქვეყანაში გავრცელებული ეპიდემიების გამო რეგულარულად გასცემს რეკომენდაციებს. იმუნიზაციის საკონსულტაციო საბჭოს გადაწყვეტილებების საფუძველზე, კონტროლის სტრატეგიის ფარგლებში განიხილება 9-11 თვის ჩვილების ვაქცინაცია. დადგენილი წესების თანახმად, 9 თვეზე უფროს და 12 თვეზე უმცროს ჩვილებს ექიმის რეკომენდაციით შეიძლება ჩაუტარდეთ წითელას საწინააღმდეგო დამატებითი ვაქცინაცია. ეს დოზა შეჰყავთ წითელას წინა ვაქცინაციიდან არანაკლებ ოთხი კვირის ინტერვალით. ვინაიდან ეს გეგმური დოზა არ არის, სისტემაში ჩვეულებრივ დამატებით აცრად აღირიცხება. ამ საკითხზე ყველაზე ზუსტი ინფორმაციის მისაღებად აუცილებლად მიმართეთ თქვენს უბნის ექიმს.') WHERE id = 'b6d3d34d-c066-4ccc-9ded-29b02d7dbff4';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ თვეში გეგმური შემოწმებისას ექიმმა ბავშვის ზოგადი მდგომარეობის შესაფასებლად შესაძლოა გარკვეული ანალიზების ჩატარება მოითხოვოს. ზოგიერთმა ექიმმა ეს ანალიზები შეიძლება მე-12 თვეშიც დანიშნოს; ეს მთლიანად ბავშვის განვითარებისა და ზრდის ტემპზეა დამოკიდებული. პირველ რიგში, ექიმი ბავშვის სიმაღლესა და წონას გაზომავს. თუ შეამჩნევთ, რომ ბავშვმა ცოტაოდენი წონა მოიმატა, ნუ შეშფოთდებით. ამ თვეებში ბავშვების წონის მატება საგრძნობლად ნელდება, რადგან ახლა ისინი ისე აქტიურად მოძრაობენ და იკვლევენ გარემოს, როგორც არასდროს. მუდმივი მოძრაობის გამო მიღებული კალორიების დიდ ნაწილს ხარჯავენ. 9 თვის ბავშვის საშუალო წონა 8400 გრამია, თუმცა ეს მაჩვენებელი შეიძლება 6600 გრამიდან 10.000 გრამამდე მერყეობდეს. თვის განმავლობაში კი დაახლოებით 250-600 გრამის მომატება ნორმალურია. გახსოვდეთ, რომ ყველა ბავშვი განსხვავებულია და ეს მაჩვენებლებიც თითოეულ ბავშვთან შეიძლება განსხვავდებოდეს.') WHERE id = '4fead597-2916-4787-ba40-6051f71308e8';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'დამატებით კვებაზე გადასვლის პერიოდში ბავშვისთვის პიურეს სახით რბილი საკვების მიცემა ამ პროცესთან შეგუებაში ეხმარება. თუმცა მისი საჭმლის მომნელებელი სისტემა და მოტორული უნარები უკვე გარკვეული ხანია უფრო მყარი საკვებისთვისაც მზად არის. მაგალითად, ბავშვისთვის ხელში ადვილად დასაჭერ ნაჭრებად დაჭრილი ბანანი შესანიშნავი არჩევანია, რადგან მისი მომზადება მარტივია და მოხარშვა არ სჭირდება. ვაშლიც ერთ-ერთი ხილია, რომელსაც დედები ამ პერიოდში ხშირად იყენებენ. რადგან ბანანზე უფრო მაგარია, შეგიძლიათ ორთქლზე ოდნავ დაარბილოთ, ნაჭრებად დაჭრათ და ბავშვს უხვად შესთავაზოთ. ვახშმისთვის კი სპეციალურად მისთვის მომზადებული პატარა კატლეტის ნაჭრები ძალიან გემრიელი არჩევანი იქნება. გემრიელად მიირთვით! 😊') WHERE id = '366b1717-cbe7-42c2-825f-799a14209342';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ თვიდან ბავშვის მეტყველების უნარებში შესაძლოა მნიშვნელოვანი წინსვლა შეამჩნიოთ. ამ პერიოდში თითქმის ყველა ბავშვი იწყებს ბევრი აზრიანი თუ უაზრო სიტყვის წარმოთქმას. თუ გაღვიძებისას მის გვერდით არ იქნებით, შესაძლოა გააზრებულად თქვას „დედა“ და ატირდეს კიდეც. მოემზადეთ! 😊 ამ პერიოდში ბავშვის საკუთარი თავის გამოხატვის უნარი საგრძნობლად ვითარდება. მაგალითად, როცა სიყვარულს გამოხატავთ, მანაც შეიძლება თავისი სიყვარული გაჩვენოთ, ხოლო როცა მოწყენილია, ამას აუცილებლად გაგრძნობინებთ. თუ დაინახავს, რომ თქვენ ხართ მოწყენილი, შეიძლება მოგიახლოვდეთ, დაგაკვირდეთ და სიტუაციაში გარკვევა სცადოს. მიუხედავად იმისა, რომ ჯერ კიდევ ბევრი სიტყვის წარმოთქმა არ შეუძლია, ეს არ ნიშნავს, რომ მათი მნიშვნელობა არ იცის! 😊') WHERE id = '248a2f1b-11a9-4475-98d2-8e5dbff40ba0';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'განსაკუთრებით კბილების ამოჭრის პერიოდში ბავშვის ღრძილები ამ კვირებში ძალიან მგრძნობიარე ხდება. ამიტომ კოვზის ან საკვების ღრძილთან შეხებამ შეიძლება დისკომფორტი გამოიწვიოს. ამის გამო ბავშვს შესაძლოა ჭამა არ მოუნდეს და ძუძუს წოვაზეც კი უარი თქვას. ზოგადად, კბილების ამოჭრის პერიოდში ბავშვებში მადის დაქვეითება ნორმალურად ითვლება. თუ ეს პროცესი ზედმეტად დიდხანს არ გაგრძელდება, სანერვიულო არაფერია. როდესაც ბავშვი ჭამაზე უარს ამბობს, არასოდეს აჭამოთ ძალით, თუ მას ეს არ სურს. ამან შეიძლება საკვების მიმართ უარყოფითი დამოკიდებულება ჩამოუყალიბოს და მომავალში კვებასთან დაკავშირებული პრობლემები გამოიწვიოს. ამ რთული პერიოდის შედარებით მარტივად გადასატანად შეგიძლიათ იოგურტიანი წვნიანები და ახლად გამოწურული ხილის წვენები გამოიყენოთ.') WHERE id = '2db32885-0a8a-4d2a-bc4e-74c38a2ae5a1';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის გონებრივი განვითარებისთვის ამ თვეში შეგიძლიათ მისი ასაკის შესაბამისი განმავითარებელი სათამაშოებით დაინტერესდეთ. განსაკუთრებით ასაწყობ-დასაშლელი სათამაშოები დაეხმარება მას ზომის ცნების აღქმაში. ბავშვი ამ სათამაშოებზე ხელის დარტყმით ან მათი ერთმანეთზე მიჯახებით ახალ ხმებს აღმოაჩენს. ნაწილების შეერთებისას კი მისი ნატიფი მოტორული უნარებიც მნიშვნელოვნად განვითარდება. თუმცა ამისთვის ძვირადღირებული სათამაშოების შეძენა სულაც არ არის აუცილებელი. მაგალითად, შეგიძლიათ ბავშვთან ერთად სარკის წინ დადგეთ, თითები სათითაოდ აჩვენოთ და მათი სახელები ჩამოუთვალოთ. ამ ერთობლივი აქტივობის წყალობით ის გაერთობა და თან ისწავლის. სასიამოვნო გართობას გისურვებთ! 😊') WHERE id = '39e8f843-aca7-42e5-9c7e-60770bf6f46e';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'კბილების ამოჭრის გამო ამ პერიოდში თქვენი ბავშვი შეიძლება ოდნავ მოუსვენარი იყოს. მაქსიმალურად მშვიდ და კომფორტულ გარემოში ყოფნა ამ პროცესს გაამარტივებს. სპეციალური კბილების ამოსაჭრელი სათამაშოებით შეგიძლიათ ბავშვს ღრძილებზე მასაჟი გაუკეთოთ. რადგან ცივი ნივთები განსაკუთრებით ამშვიდებს, უპირატესობა მიანიჭეთ წყლით სავსე კბილების ამოსაჭრელ სათამაშოებს, რომელთა შენახვაც მაცივარში შეიძლება. კბილების ამოჭრის პერიოდში შესაძლოა ბავშვის კვებისა და ძილის რეჟიმი დაირღვეს. ამან შეიძლება მისი იმუნური სისტემა დაასუსტოს და ინფექციებისადმი უფრო მგრძნობიარე გახადოს. თუ ბავშვს 38 გრადუსზე მაღალი ტემპერატურა, ძლიერი მოუსვენრობა ან დიარეა აქვს, აუცილებლად მიმართეთ ექიმს. გავრცელებული შეხედულების მიუხედავად, ეს ნიშნები ყოველთვის კბილების ამოჭრასთან არ არის დაკავშირებული.') WHERE id = 'fd3bdcfc-5254-4510-b9f7-837898a606a0';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის განვითარებისთვის ძალიან მნიშვნელოვანია ხარისხიანი ურთიერთობა ადამიანთან, რომელიც მასზე ზრუნავს. ბევრმა მშობელმა არ იცის, როგორ დაამყაროს ასეთი ურთიერთობა და როგორ გაატაროს ბავშვთან დრო. სინამდვილეში, ამ მიზანს ისეთი მარტივი თამაშიც კი ემსახურება, როგორიცაა „ჭიტა“. თამაში ხელს უწყობს ბავშვის გონებრივი ფუნქციების განვითარებას და სამკურნალო ეფექტიც კი შეიძლება ჰქონდეს. ბავშვთან თამაში ძალიან მნიშვნელოვანია მისი სოციალური, ემოციური, ფიზიკური, გონებრივი და მეტყველების განვითარებისთვის. გარდა ამისა, ბავშვთან ხშირი ურთიერთობა, მისთვის სიმღერებისა და იავნანების შესრულება და გულწრფელი ღიმილიც კი მის გონებრივ აქტივობას ასტიმულირებს. ასეთი გონებრივი სტიმულაცია მნიშვნელოვნად უწყობს ხელს ტვინის განვითარებას. ამიტომ გირჩევთ, ამისთვის ყოველი შესაძლებლობა გამოიყენოთ.') WHERE id = '8bad6496-e337-421c-9a82-679470e2639c';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მე-9 თვიდან ღეჭვის რეფლექსის გასავითარებლად ბავშვმა უფრო მეტი მარცვლოვანი და ნაჭრებად დაჭრილი საკვები უნდა მიიღოს. ამიტომ დამატებითი საკვები ისე უნდა მოამზადოთ, რომ ბავშვმა მისი ხელით მარტივად აღება და ლუკმებად ჭამა შეძლოს. ამ გზით იგი დამოუკიდებლად ჭამის უნარებსაც განივითარებს. თუ ბავშვს კბილები ჯერ არ ამოსვლია, შეიძლება იფიქროთ, რომ კბილების გარეშე ღეჭვას ვერ შეძლებს. თუმცა ეს მცდარი მოსაზრებაა — ბავშვს განსაკუთრებით მოხარშული ბოსტნეულისა და ხილის მსგავსი საკვების ღრძილებით მარტივად დაჭყლეტა შეუძლია. ამ მხრივ მარცვლოვანი და ნაჭრებად დაჭრილი საკვები ძალიან სასარგებლოა როგორც ღეჭვის, ისე ხელით დაჭერის უნარის განვითარებისთვის. ამისთვის შეგიძლიათ უპირატესობა მიანიჭოთ საკვებს, რომელსაც განსაკუთრებით BLW-ის (ბავშვის მიერ დამოუკიდებლად კვების) მეთოდის დროს იყენებენ.') WHERE id = '01dbba01-d87e-4015-9ad4-7f2d6dcf5bd6';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის კვების რეჟიმი, რომლის ჩამოყალიბებასაც აქამდე ცდილობდით, ამ თვიდან შეიძლება მთლიანად შეიცვალოს. ამის ერთ-ერთი მთავარი მიზეზი ბავშვის მიერ დამოუკიდებლობისკენ სწრაფვაა. განსაკუთრებით მაშინ, როცა კოვზით მისაცემ პიურეს ბავშვი ისეთი საკვებით ანაცვლებს, რომლის ჭამაც თავად შეუძლია, შესაძლოა კვების რეჟიმის თავიდან ჩამოყალიბება გახდეს საჭირო. ზოგიერთი ბავშვი ამ პროცესს ადვილად ვერ ეგუება. ამიტომ შესაძლოა თქვენ მიერ შეთავაზებულ საკვებზე კატეგორიული უარი თქვას ან კოვზით ჭამა აღარ მოინდომოს. ასეთ დროს დიდი მოთმინება უნდა გამოიჩინოთ და თუ ბავშვს დამოუკიდებლად ჭამა სურს, მის სურვილს გაგებით მოეკიდოთ. შეგიძლიათ მისთვის შესაფერისი გარემო მოაწყოთ და საკვების ნაწილი ან მთლიანად მის წინ დადოთ. თავდაპირველად ბავშვმა შეიძლება ლუკმების ზომა სწორად ვერ განსაზღვროს. როცა იგრძნობთ, რომ დახმარება სჭირდება, შეგიძლიათ მხარი დაუჭიროთ.') WHERE id = 'f4238778-2de3-481f-be1b-95a62161c1ba';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი სწრაფად ვითარდება როგორც თამაშების, ისე ახლად შეძენილი უნარების, მაგალითად, ხოხვის წყალობით. ამ მოძრაობების შესრულებისას მის სხეულში სხვადასხვა კუნთი უწყვეტად მუშაობს. წვრილი კუნთების ჯგუფების გამააქტიურებელი თამაშების დროს (მაგალითად, საგნების აწყობა და დაშლა, ღილების შეკვრა) ნატიფი მოტორული უნარებიც იწყებს განვითარებას. მსხვილი კუნთების ჯგუფების მუშაობა კი საფუძველს უქმნის ისეთ სამომავლო მოძრაობებს, როგორებიცაა სიარული, ხტომა და კიბეზე ასვლა. მოძრაობისას სუნთქვის გაღრმავებისა და გახშირების შედეგად ბავშვის ორგანიზმი მეტ ჟანგბადს იღებს. ამასთანავე, ასეთი მეტაბოლური ცვლილებების დროს სისხლის მიმოქცევა ჩქარდება, რაც ქსოვილებისთვის მეტი საკვები ნივთიერების მიწოდებას უზრუნველყოფს. ყოველივე ამის საფუძველზე შეგვიძლია ვთქვათ, რომ ბევრი თამაში ბავშვის როგორც გონებრივი, ისე ფიზიკური განვითარებისთვის ძალიან მნიშვნელოვანია.') WHERE id = 'a8bbe7da-d7ed-4f71-bc81-f38a911b0996';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ თვიდან შეგიძლიათ ბავშვი ოჯახურ სუფრასთან მიიწვიოთ. ეჭვი არ გვეპარება, რომ ეს ძალიან სახალისო იქნება! 😊 სუფრასთან ერთად ჯდომის ჩვევის ჩამოყალიბება ბავშვს აგრძნობინებს, რომ ოჯახის წევრია და მის სოციალიზაციასაც უწყობს ხელს. გარდა ამისა, ოჯახის სხვა წევრების ჭამის ყურებამ შეიძლება ბავშვს თქვენ მიერ შეთავაზებული საკვების მიღებისკენ უბიძგოს. შესაძლოა, გარკვეული დროის განმავლობაში ბავშვს ჭამის ნაცვლად სხვებზე დაკვირვება მოუნდეს. ასეთ შემთხვევაში მას ჭამა არ უნდა დააძალოთ. შეგიძლიათ მცირე პაუზა გააკეთოთ და საკვები მოგვიანებით კვლავ შესთავაზოთ, რათა ბავშვი ბოლომდე დანაყრდეს. გახსოვდეთ, რომ თქვენთან ერთად სუფრასთან ჯდომა არ ნიშნავს, რომ ბავშვს სახლში მომზადებული ნებისმიერი კერძის ჭამა შეუძლია. განსაკუთრებით 3 წლის ასაკამდე ბავშვის საჭმლის მომნელებელი სისტემისთვის შესაფერისი საკვებით კვება მომავალში ჯანმრთელობასთან დაკავშირებული მრავალი პრობლემის თავიდან აცილებას შეუწყობს ხელს.') WHERE id = '88647028-f25e-4ac9-8691-df916cfbec6e';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მიუხედავად იმისა, რომ თქვენმა ბავშვმა მოკლე დროში განვითარების დიდი გზა გაიარა, ის ჯერ კიდევ ჩვილობის ასაკშია. ამ პერიოდში მისი საყვარელი საქმიანობა საკუთარი სხეულის ნაწილებითა და გარშემო არსებული საინტერესო ნივთებით თამაშია. ამიტომ გარემოში, სადაც ბავშვი იმყოფება, შეგიძლიათ ფერადი, ხმოვანი და მოძრავი ნივთები დაამატოთ. კიდევ ერთი სასიამოვნო აქტივობა, რომელიც ერთად შეგიძლიათ შეასრულოთ, არის ბანაობის შემდეგ ბავშვისთვის საშუალების მიცემა, ტანსაცმლის გარეშე აღმოაჩინოს საკუთარი სხეული. მიეცით საშუალება, სათითაოდ დააკვირდეს ფეხის თითებს, პირთან მიიტანოს და ასე შეისწავლოს ისინი. საკუთარი თავის აღმოჩენა ბავშვს ეხმარება, გააცნობიეროს თავისი შესაძლებლობების საზღვრები და შეიძინოს თავდაჯერება. ამის შემდეგ კი შეგიძლიათ უმღეროთ და მსუბუქი, დამამშვიდებელი მასაჟი გაუკეთოთ. სასიამოვნო გართობას გისურვებთ! 😊') WHERE id = '15555c9e-8608-4e1e-a198-d3137b747de5';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მართალია, თქვენი ბავშვი ისე სწრაფად აღარ იზრდება, როგორც პირველ თვეებში, თუმცა ზრდასა და განვითარებას კვლავ აქტიურად განაგრძობს. მისი განვითარების ხელშესაწყობად და ჯანმრთელობის დასაცავად ასაკის შესაბამისი, სწორი საკვები ყურადღებით უნდა შეარჩიოთ. კვების რაციონში კვლავ ყველაზე დიდი წილი დედის რძეს ან ხელოვნურ ნარევს უნდა ეკავოს. დამატებით, მენიუში შეგიძლიათ შეიტანოთ არაპიურირებული, მცირე ნაჭრებად დაჭრილი ხილი და ბოსტნეული, ჯანსაღი მარცვლეულისგან დამზადებული მაკარონი, შინ გამომცხვარი ორცხობილა და ნებისმიერი ადვილად მოსანელებელი საკვები, რომლის ხელში დაჭერასაც შეძლებს. სწრაფად განვითარებული კუნთებისთვის ასევე საჭიროა ცილის ყოველდღიური მოთხოვნილების სწორად განსაზღვრა. ბავშვის კვების რაციონში შეგიძლიათ შეიტანოთ თევზი, კარგად მომზადებული ხორცი, ოსპი და ლობიო. ამ პერიოდში იმის გასარკვევად, აქვს თუ არა ბავშვს ალერგია ახალ საკვებზე, ყოველ ჯერზე მხოლოდ ერთი ახალი პროდუქტი უნდა მისცეთ და ნელ-ნელა გააგრძელოთ.') WHERE id = '89bec816-5357-4575-bfde-092fc39e99a9';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'როდესაც ბავშვს აჭმევთ ან მასთან ერთად სუფრასთან ზიხართ, გვერდზე უნდა გადადოთ ყველაფერი, რამაც შეიძლება როგორც თქვენი, ისე მისი ყურადღება გაფანტოს. ეს წესი არა მხოლოდ ამჟამინდელ პერიოდს ეხება, როცა ბავშვი აქტიურად სწავლობს, არამედ ყოველთვის მოქმედებს. განსაკუთრებით მნიშვნელოვანია სუფრასთან ერთად ყოფნა, რადგან ეს არის გარემო, სადაც ოჯახური ურთიერთობა მტკიცდება და უკეთ აცნობიერებთ, რამდენ საკვებს მიირთმევთ. ამიტომ ჭამის დროს ყურადღება მიაქციეთ, რომ ტელევიზორი გამორთული იყოს, ბავშვს კი ხელში ტელეფონი ან პლანშეტი არ ეჭიროს. ასევე, საჭმლის მომზადების წინარე ეტაპები რომ დაინახოს, ბავშვი გვერდით გყავდეთ. მიბაძვის ძლიერი უნარის მქონე თქვენი ბავშვისთვის ეს ცოცხალი სასწავლო პროცესია. ჭამის წინ ხელების დაბანა, ოჯახის წევრებთან ერთად სუფრის გაშლა და ალაგება, კარგ განწყობაზე სადილობა — ეს ის ჩვევებია, რომლებიც ბავშვს განსაკუთრებული ძალისხმევის გარეშე, უბრალოდ პირადი მაგალითით შეგიძლიათ გამოუმუშაოთ.') WHERE id = '6cc71e92-a6d5-4d2d-bf55-9c74e24a03af';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის გონებრივი ფუნქციების გასააქტიურებლად შეგიძლიათ მასთან ერთად სენსორული განვითარების თამაშები ითამაშოთ. ერთი შეხედვით ეს ტერმინი შეიძლება რთულად მოგეჩვენოთ, თუმცა სინამდვილეში ეს ბავშვის განვითარების ხელშემწყობი ერთ-ერთი საუკეთესო მეთოდია, რომელსაც თერაპიული ეფექტიც კი აქვს. ამ გზით შეგიძლიათ ბავშვს აქტიურ სწავლასა და სხვადასხვა სფეროში განვითარებაში დაეხმაროთ. მოდით, ამას მარტივი მაგალითით აგიხსნით: შეგიძლიათ ბავშვი ცენტრში მოათავსოთ და გარშემო შემოუაროთ, ან მის წინ დადგეთ და საინტერესო ნივთები მოქაჩოთ ან უბიძგოთ. შეგიძლიათ ბავშვი ზურგზე დააწვინოთ და ფეხზე მიბმულ ბუშტებზე დარტყმის საშუალება მისცეთ. შეხების შეგრძნების განსავითარებლად კი შეგიძლიათ ბეწვიან და სხვადასხვა ფაქტურის მქონე ზედაპირებს შეახოთ. დარწმუნებული ვარ, თქვენი ბავშვი ძალიან გაერთობა! 😊') WHERE id = '69152415-f884-484c-9ae7-d7f46f63d572';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მიუხედავად იმისა, რომ ბავშვის საჭმლის მომნელებელი სისტემა მზად არის, მომავალში უფრო ჯანსაღი ცხოვრებისთვის ძალიან მნიშვნელოვანია, რომ მან ზოგიერთი საკვები ჯერ არ მიიღოს. მაგალითად, ჯანსაღი კვების ერთ-ერთი პირველი პირობა ბავშვის რაციონიდან თეთრი ფქვილით მომზადებული ნებისმიერი საკვების ამოღებაა. პურისა და მაკარონის არჩევისას უპირატესობა შეგიძლიათ მიანიჭოთ ქატოს ან ჭვავის შემცველ პროდუქტებს. ასევე, თუ ამ პერიოდში ბავშვს მზა შეფუთულ პროდუქტებსა და ტკბილეულს არ გააცნობთ, მომავალში საქმე გაცილებით გაგიმარტივდებათ. მაგალითად, თუ ფიქრობთ, რომ ბავშვს ზოგიერთი ბოსტნეული მისი გემოს გამო არ მოსწონს, საკვებს შაქარი არ უნდა დაუმატოთ. ბავშვის გემოვნების რეცეპტორები ჯერ კიდევ არ არის სრულად შეჩვეული სხვადასხვა გემოს, ამიტომ მას შეიძლება მოეწონოს ის, რაც თქვენ უგემურად გეჩვენებათ. თუ საწყის ეტაპზე ბავშვს შაქრით დატკბობილ საკვებს მისცემთ, მოგვიანებით მისი შეზღუდვა რთული, ზოგჯერ კი შეუძლებელიც იქნება.') WHERE id = 'f1f06dfe-2ed9-46d2-a946-2592a01f6371';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ თქვენი ბავშვი ჯერ არ ხოხავს, დიდი ალბათობით, ამისთვის უკვე გარკვეულ ვარჯიშებს ასრულებს. ამ ვარჯიშების დროს მისი ხოხვის მცდელობები, ალბათ, საკმაოდ სახალისო და საინტერესო მოგეჩვენებათ. 😊 ამის მიზეზი ისაა, რომ ბავშვს ხოხვის უნარი ჯერ სრულად არ აუთვისებია. ის შეეცდება, თავისთვის ყველაზე მოსახერხებელი პოზა იპოვოს და, სხვა ბავშვების მსგავსად, თავდაპირველად მხოლოდ ხელების გამოყენებით გადაადგილდეს. ამის მიზეზი, რა თქმა უნდა, ისაა, რომ ხელის კუნთები ჯერ ფეხის კუნთებზე ძლიერი აქვს. ძალიან მალე ეს თანაფარდობა ფეხების სასარგებლოდ შეიცვლება, თუმცა ბავშვს ჯერ კიდევ დრო სჭირდება. ამიტომ ნუ შეშფოთდებით, თუ დაინახავთ, რომ ბავშვი იატაკზე მუცლით ხოხავს, დაღლისას კი ცოტა ხნით იქვე ისვენებს.') WHERE id = '53bde760-576b-4b67-a81b-6b925c4d3fda';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ თვეში ბავშვის განვითარების ტემპი დაახლოებით ისეთივეა, როგორიც გასულ თვეში იყო. ნუ შეშფოთდებით, თუ ის ისე სწრაფად აღარ იზრდება, როგორც პირველ თვეებში. ვინაიდან თქვენი ბავშვი უკვე ძალიან აქტიურია, ამ თვის განმავლობაში მან შეიძლება საშუალოდ 300-500 გრამი მოიმატოს. ჯანმოს მიხედვით, 10 თვის ბავშვის საშუალო წონა დაახლოებით 8800 გრამია. თუმცა ეს მაჩვენებელი შეიძლება განსხვავდებოდეს ბავშვის სქესის, აქტიურობის, დაბადებისას წონისა და განვითარების თავისებურებების მიხედვით. ანუ თქვენი ბავშვი შეიძლება 6500 გრამსაც იწონიდეს ან 12500 გრამსაც აღემატებოდეს. ამ თვიდან ბავშვის სიმაღლე კვლავ საშუალოდ 1 სმ-ით მოიმატებს. თავის გარშემოწერილობაც იმავე ტემპით გაიზრდება.') WHERE id = '789568fd-44f2-4cb3-9877-cd0130c94687';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი უკვე საკმაოდ აქტიურია. მისი ღიმილი, გადაბრუნება, ხოხვა და ლაპარაკის მცდელობები დაუსრულებელია! 😊 დაბადების მომენტიდან შეძენილი ახალი უნარები ერთდროულად გაოცებთ, აღგაფრთოვანებთ და გაბედნიერებთ. ფეხზე დადგომის მცდელობები და სიარულზე გადასვლის ეტაპიც ამ ამაღელვებელი განვითარების ნაწილია... ამ პერიოდშიც, როგორც ყოველთვის, ბავშვის ყველაზე დიდი მხარდამჭერები თქვენ და თქვენი მეუღლე ხართ. შეგიძლიათ დაეხმაროთ, რომ სიარულის სწავლის პროცესით უფრო მეტად ისიამოვნოს და თავდაჯერებულად, გაბედულად გადადგას ნაბიჯები. ამ დროს მოსალოდნელი მცირე ტრავმების გათვალისწინებით, უსაფრთხოების გარკვეული ზომების მიღებაა საჭირო. მაგალითად, შეგიძლიათ დაიწყოთ იმით, რომ ბავშვი საჭირო უსაფრთხოების ზომების გარეშე მარტო არ დატოვოთ ისეთ მაღალ ადგილებზე, როგორებიცაა საწოლი, გამოსაცვლელი მაგიდა და დივანი. 😊') WHERE id = 'b038be51-87de-40aa-81e8-34eb440fed27';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ ეტაპზე ბავშვმა დღეში 3-5-ჯერ უნდა განაგრძოს დედის რძის ან ხელოვნური ნარევის მიღება. გახსოვდეთ, რომ მხოლოდ მყარ საკვებზე სრულად გადასასვლელად მას ჯერ კიდევ დრო სჭირდება. ამ პერიოდში შეგიძლიათ ბავშვის დამატებითი კვების რეჟიმი 3 ძირითადი და 3 შუალედური კვებისგან შეადგინოთ. თუ ძუძუთი კვებავთ, დღის განმავლობაში შეგიძლიათ იმდენჯერ მისცეთ რძე, რამდენჯერაც მოინდომებს. ხელოვნურ კვებაზე მყოფი ბავშვებისთვის კი დღეში სულ მცირე სამჯერ 200 მლ ნარევი საკმარისი იქნება. ზოგიერთმა დედამ შეიძლება იფიქროს, რომ ბავშვი უკვე საკმარის დედის რძეს იღებს და ძუძუთი კვების თანდათან შემცირება მოინდომოს. თუმცა ეს მცდარი მოსაზრებაა, რადგან ბავშვს თქვენი რძისგან ჯერ კიდევ ბევრი სარგებლის მიღება შეუძლია. სარძევე ჯირკვლები რძის შემადგენლობას ბავშვის განვითარების შესაბამისად ცვლის. მაგალითად, ამ თვეებში თქვენი რძის ცხიმიანობა გაცილებით მაღალია, ვიდრე პირველ თვეებში.') WHERE id = '40235f48-568d-4e7c-b429-24fa27331c60';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ზოგჯერ ბავშვს მადა შეიძლება მოულოდნელად გაეზარდოს ან საერთოდ დაეკარგოს, შეიძლება საერთოდ არ მოინდომოს ძილი ან საათობით ეძინოს, მისი განწყობაც კი შეიძლება უეცრად შეიცვალოს. თუ ეს ყველაფერი თქვენთვის ნაცნობია, ამას მხოლოდ ერთი მიზეზი აქვს: ჯერ კიდევ განვითარების ნახტომის (კრიზისის) პერიოდში ხართ! ეს პერიოდი, რომელსაც „კრიზისს“, „ნახტომს“ ან „ზრდის“ პერიოდს უწოდებენ, რეჟიმის დარღვევის გამო შეიძლება შემაშფოთებლად ჟღერდეს. თუმცა ყველაფერს თავისი მიზეზი აქვს: განვითარების ყოველი ნახტომისას თქვენი ბავშვი ახალ უნარებს იძენს და გონებრივად ვითარდება. მოკლედ რომ ვთქვათ: „ზრდა ადვილი არ არის!“ ამიტომ, ამ პერიოდების დადებით მხარეებსა და ბავშვის ახალ უნარებზე ფიქრი დაგეხმარებათ, ეს პროცესი უფრო მშვიდად გაიაროთ. მაგალითად, განვითარების ამ ნახტომის პერიოდში თქვენი ბავშვი თქვენზე ეჭვიანობას იწყებს. ძალიან საყვარლად ჟღერს, არა? როცა თქვენი მეუღლე სამსახურიდან დაბრუნდება, მისმა კოცნამ შეიძლება ბავშვი გააბრაზოს, რადგან მას არ სურს, ვინმესთან გაგიყოთ.') WHERE id = 'b4a75895-ae96-4823-9d66-151563acf366';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ თვის განმავლობაში ბავშვს დღეში სულ მცირე 500 მლ დედის რძე უნდა მისცეთ, ხოლო თუ დედის რძე არ გაქვთ, ექიმთან კონსულტაციის შემდეგ მისთვის ყველაზე შესაფერისი შემდგომი ფორმულა უნდა გამოიყენოთ. ბავშვის საჭმლის მომნელებელი სისტემა უკვე იმდენად განვითარებულია, რომ თხევადი საკვებიდან მყარ საკვებზე გადასვლას მეტწილად გაუმკლავდება. თუმცა ნაწლავების ზედმეტად დასატვირთად, მან დღეში დამატებითი საკვების მაქსიმუმ 3 საბავშვო ქილა უნდა მიიღოს. ამაზე მეტი დამატებითი საკვების მიცემამ შეიძლება ხელი შეუშალოს მისი ძირითადი საკვების — დედის რძის — საკმარისი რაოდენობით მიღებას. მყარ საკვებსა და დედის რძეს შორის (ან მისი არარსებობისას, შემდგომ ფორმულასთან) ბალანსის დამყარების შემდეგ, ბავშვის ჯანსაღი ზრდისთვის კვების იდეალური რეჟიმი უნდა შეადგინოთ. საკვების რაოდენობასთან ერთად ძალიან მნიშვნელოვანია მისი მომზადების ჯანსაღი მეთოდიც. ამიტომ ბავშვის საკვების მომზადებისას უპირატესობა ისეთ ჯანსაღ მეთოდებს უნდა მიანიჭოთ, როგორებიცაა ორთქლზე მომზადება, მოხარშვა ან ღუმელში გამოცხობა.') WHERE id = '2fad46fb-e452-4335-9758-a95de808e8f1';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი უკვე გარკვეული ხანია ხოხავს და შეიძლება ერთსა და იმავე გარემოში მუდმივად ყოფნა მობეზრდა. განსაკუთრებით მაშინ, როცა ხედავს, რომ მის გარშემო ყველა დადის, თავადაც დაიწყებს ფეხზე წამოდგომის მცდელობას. ამისთვის თავდაპირველად რაიმეზე დაყრდნობით შეეცდება წამოდგომას. შეიძლება გარკვეული დროის განმავლობაში მისი მცდელობები წარუმატებელი იყოს, ან შესაძლოა პირველივე ცდაზე გამოუვიდეს. ეს თითოეული ბავშვის განვითარების თავისებურებებსა და გარემოზეა დამოკიდებული. დაინახავთ, რომ თავდაპირველად ბავშვი ახლომდებარე ავეჯზე დაყრდნობით შეეცდება ფეხზე წამოდგომას. როცა მიხვდება, რომ ეს შეუძლია, დაუხმარებლად დგომასაც ეცდება. თუმცა ამის მისაღწევად მას ჯერ კიდევ ცოტა დრო სჭირდება. ამ ეტაპზე ბავშვის მხარდასაჭერად შეგიძლიათ მისთვის საინტერესო სათამაშოები ისეთ ნივთებზე დადოთ, რომლებსაც შეიძლება დაეყრდნოს, მაგალითად, სავარძელზე ან სკამზე.') WHERE id = '02985c47-f203-4125-957b-15eb60906ec2';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის საჭმლის მომნელებელი სისტემა უკვე საკმაოდ განვითარებულია და არ არსებობს მიზეზი, რომ ოჯახურ საუზმეზე მისთვისაც არ გამოყოთ ადგილი. მაგალითად, ძუძუთი კვების შემდეგ (ან, თუ ხელოვნურ ნარევს იღებს, ერთ ჭიქა ნარევთან ერთად) შეგიძლიათ ბავშვს მისცეთ ყველი, ზეთისხილი, მარცვლეულის პური და ნატურალური კარაქიც კი. თუმცა ბავშვი ჯერ ყველა საკვების მისაღებად მზად არ არის. ამიტომ ამ პერიოდშიც თავი უნდა აარიდოთ ბადრიჯანს, კვერცხის ცილას, თაფლს, ძროხისა და თხის რძეს, ასევე ალერგენად ცნობილ ხილს. ბავშვში ალერგიის რისკის შესამცირებლად მოერიდეთ გენეტიკურად მოდიფიცირებულ, ძლიერი პესტიციდებით დამუშავებულ და დამოკიდებულების გამომწვევი არომატიზატორებისა თუ კონსერვანტების შემცველ საკვებს. ასეთი დამუშავების შედეგად პროდუქტი ბუნებრივ თვისებებს სრულიად კარგავს და ბავშვის მეტაბოლიზმისთვის უცხო ნივთიერებად იქცევა. ალერგიის ყველაზე ხშირად გამომწვევ პროდუქტებს შორისაა გადამუშავებული კონსერვები, ზოგიერთი გენეტიკურად მოდიფიცირებული ხორბლის პროდუქტი, ქიმიური ნივთიერებებით დამუშავებული ხილი და რძის ნაწარმი. ამიტომ ბავშვისთვის კონსერვირებული საკვებისგან თავის არიდება და ნატურალური ხილისა და ბოსტნეულის შერჩევა ალერგიის რისკის შესამცირებლად ძალიან მნიშვნელოვანია.') WHERE id = '7dcfd4f4-9aee-4c8d-9828-a2d3f2df221d';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ ბავშვთან ერთად მოგზაურობა მოგიწევთ, მზად უნდა იყოთ მცირე სირთულეებისთვის. ის უკვე საკმაოდ მიეჩვია თავის გარემოს, სახლსა და ოჯახის წევრებს, რომლებსაც ყოველდღე ხედავს, და ამ გარემოში საკუთარი რეჟიმიც ჩამოუყალიბდა. გზაში ყოფნა, ჩვეული გარემოს დატოვება და ახალ ადგილებში წასვლა თავიდან ბავშვისთვის შესაძლოა ცოტა საშიში აღმოჩნდეს. ბევრი უცხო ადამიანის დანახვამაც შეიძლება თავი დაუცველად აგრძნობინოს და შეაწუხოს. მოგზაურობისას ბავშვის დასამშვიდებლად შეგიძლიათ თან წაიღოთ ნივთები, რომლებიც მის ყურადღებას გადაიტანს. ეს შეიძლება იყოს ილუსტრირებული წიგნები, ხმოვანი სათამაშოები, თითის თოჯინები და მისი საყვარელი საკვები. თუ ყველაფრის მიუხედავად ბავშვი მაინც მოუსვენრადაა, შეგიძლიათ ესაუბროთ და, მიუხედავად იმისა, რომ მოგზაურობის არსი ჯერ სრულად არ ესმის, შეძლებისდაგვარად აუხსნათ, რა ხდება.') WHERE id = '4ae1b5f1-3350-4a7e-9ecb-70e54028f264';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის კვების, ჯანმრთელობისა და ფიზიკური განვითარების მსგავსად, კიდევ ერთი მნიშვნელოვანი საკითხია, რომ მომავალში მან კარგი განათლება მიიღოს. განათლება ბავშვის მომავლისთვის ძალიან მნიშვნელოვანია და ვიცით, რომ ამაზე უკვე ბევრს ფიქრობთ. მაგრამ იცით, რისი გაკეთება შეგიძლიათ ამ მიმართულებით? თუ სიტყვა „მონტესორი“ ჯერ არ შეგხვედრიათ, გვსურს ამ საგანმანათლებლო სისტემის შესახებ მოგიყვეთ. მონტესორის საგანმანათლებლო სისტემა არის მეთოდი, რომელიც ბავშვის სწავლის ტემპის, უნარებისა და ინტერესების ცვალებადობის გათვალისწინებით გამოიყენება. თუ ამ მეთოდის გამოყენებას გადაწყვეტთ, ბავშვის გარშემო მოწესრიგებულად დაჯგუფებული განმავითარებელი მასალები უნდა მოამზადოთ. ეს შეიძლება იყოს კვანძის შეკვრისა და გახსნის სავარჯიშოები, ფორმების შესაბამის ჭრილებში მოთავსების ბლოკები ან ერთმანეთში ჩასაწყობი ფერადი ჭიქები. მნიშვნელოვანია, რომ მომზადებული მასალები სწორად დააჯგუფოთ და ბავშვისთვის ადვილად მისაწვდომ ადგილებში განათავსოთ.') WHERE id = 'b4fbd7bc-5bea-4328-9444-1bbb7e0b93ab';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თვალის დახამხამებაში თქვენი ბავშვი გაიზარდა და მე-9 თვის დასრულება, როცა მან დედის რძესთან ერთად დამატებითი საკვების მიღებაც დაიწყო, ნიშნავს, რომ კვების გარდამავალი ეტაპი უკვე უკან მოიტოვეთ. ამ თვიდან შეგიძლიათ ბავშვს გაასინჯოთ ხორცი და თევზი, ასევე ხორბლისგან მომზადებული კერძები, სხვადასხვა მარცვლეული და კვერცხი. ცილა ძალიან მნიშვნელოვანია ბავშვის კვებაში, რადგან მისი კუნთები სწრაფად ვითარდება. ამიტომ ყოველდღიურ რაციონში შეგიძლიათ ერთხელ აუცილებლად მისცეთ ხორცი ან ხორცპროდუქტი. თუმცა არ დაგავიწყდეთ, რომ თქვენი ბავშვის განვითარების ტემპი, ისევე როგორც ყველა ბავშვისა, ინდივიდუალურია. ამ მნიშვნელოვან პერიოდში ზოგი ბავშვი კარგი მადითა და ენთუზიაზმით ჭამს, ზოგი კი — უხალისოდ. ამ ეტაპზე ბავშვის მიერ ახლად გასინჯული საკვების უარყოფაც კი ნორმალურად მიიჩნევა. ამიტომ კარგად უნდა დააკვირდეთ ბავშვს და მის საჭიროებებს მოერგოთ. თითოეული ახალი საკვები კვლავ სამდღიანი წესის დაცვით მიეცით, რათა ორგანიზმის რეაქციას დააკვირდეთ. დამატებითი საკვების რაოდენობის ზრდასთან ერთად შეკრულობა, აირები და რეფლუქსიც შეიძლება გამოვლინდეს, რაც ასევე ნორმალურად მიიჩნევა. თუმცა დროთა განმავლობაში ეს უსიამოვნებები შემცირდება.') WHERE id = '38f9d9e1-4776-4187-abf9-e1f1ad116098';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ ამ ეტაპამდე ბავშვს ჯერ კიდევ არ დაუწყია ხოხვა, შეგიძლიათ ამ უნარის ათვისებაში დაეხმაროთ. ხოხვის წასახალისებლად ყველაზე გავრცელებული მეთოდია საინტერესო ნივთების ან მისი საყვარელი სათამაშოს ისეთ მანძილზე დადება, რომ მისწვდეს. ასევე შეგიძლიათ უზრუნველყოთ, რომ ბავშვმა დღის განმავლობაში იატაკზე ბევრი დრო გაატაროს. ამისთვის ბავშვი არც ზედმეტად მყარ და არც ზედმეტად რბილ ზედაპირზე მოათავსეთ და მიეცით საშუალება, თქვენ მიერ განსაზღვრულ უსაფრთხო სივრცეში თავისუფლად იმოძრაოს. ზურგის კუნთების განვითარებაც მნიშვნელოვნად ეხმარება ბავშვს ხოხვის დაწყებაში. ამ მიზნით შეგიძლიათ მუცელზე წოლის ვარჯიშები გააკეთებინოთ. გარდა ამისა, გირჩევთ, თავი აარიდოთ ისეთ საშუალებებს, როგორიცაა ჭოჭინა, რადგან მან შეიძლება ბავშვის ხოხვის დაწყება შეაფერხოს.') WHERE id = 'c3473c70-f7b4-432f-afbf-5ede71de258f';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'კეთილი იყოს თქვენი მობრძანება აქტიურ და ფუსფუსით სავსე თვეებში! თითქოს თქვენი ბავშვი სულ გუშინ დაიბადა... დრო რა სწრაფად გადის, არა? სანამ ბავშვის მოახლოებული დაბადების დღის წვეულებას გეგმავთ, მან შესაძლოა ამ თვეში ფეხზე წამოდგომით გაგაოცოთ. ამ პერიოდში ბავშვი იწყებს ფეხზე წამოდგომას, რამდენიმე წამის განმავლობაში დამოუკიდებლად დგომასა და ერთი-ორი ნაბიჯის გადადგმას. ამასთან ერთად, საგნები, რომლებიც ბავშვს დიდად ეჩვენებოდა, თითქოს პატარავდება და მას თავდაჯერებულობა ემატება. ზოგიერთმა ბავშვმა ამ თვეში სიარულიც კი შეიძლება დაიწყოს. თუმცა სიარულისთვის ჯერ ადრეა და ბავშვს ამის გაკეთება არ უნდა აიძულოთ. თუ თქვენი ბავშვი სიარულს დიდი მონდომებით ცდილობს, ალბათ ფიქრობთ, როგორ შეუწყოთ ხელი მის განვითარებას. ამიტომ ექიმთან კონსულტაციის შემდეგ შეგიძლიათ გაეცნოთ პროდუქტებს, რომლებიც „პირველი ნაბიჯების ეტლის“ ან „სიარულის დამხმარის“ სახელით იყიდება.') WHERE id = '8ad14916-224e-43df-b050-f067ba32923b';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მოუსვენარი და ენერგიით სავსე ბავშვისთვის, რომელიც მუდმივად მოძრაობს, ტანსაცმლის გამოცვლა, სხვა დედების მსგავსად, თქვენთვისაც შეიძლება საკმაოდ დამღლელი იყოს. სავარაუდოდ, თქვენს ბავშვს ჩაცმა არ უყვარს და ტანსაცმლის ყოველი გამოცვლა თქვენ ორს შორის ჭიდაობის შეჯიბრად იქცევა. 😊 ამ სიტუაციასთან გასამკლავებლად რამდენიმე სასარგებლო ხრიკი არსებობს. რადგან თქვენი ბავშვი უკვე დამატებით საკვებზე გადავიდა, ტანსაცმელს ხშირად ისვრის. ამიტომ ტანსაცმლის ყიდვისას ლაქებისადმი მდგრადი ქსოვილების არჩევა საქმეს მნიშვნელოვნად გაგიმარტივებთ. ჩაცმის დროს ყურადღების გადასატანად შეგიძლიათ ხელში საყვარელი სათამაშო ან საინტერესო ნივთი მისცეთ. ასევე სასურველია, მაისურებისა და პერანგების ყელის ნაწილი ფართო ან ელასტიკური ქსოვილისგან იყოს დამზადებული.') WHERE id = '80933d1b-7705-420b-8df2-38fff58443d1';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'კბილების მოვლა თქვენი ბავშვისთვისაც ისეთივე მნიშვნელოვანია, როგორც ნებისმიერი სხვა ადამიანისთვის. განსაკუთრებით მნიშვნელოვანია, რომ ახლად ამოსული კბილები ჯანსაღად განვითარდეს, რადგან ეს მის მომავალ ჯანმრთელობაზე აისახება. იმისთვის, რომ ბავშვს კბილების გახეხვის ჩვევა ჩამოუყალიბდეს, საჭიროა, ახლავე დაიწყოთ და ეს ყოველდღიურ რუტინად აქციოთ. თავდაპირველად შეიძლება კითხვები გაგიჩნდეთ, როგორ უნდა მოუაროთ მის კბილებს. ბავშვის პირველი კბილის ამოსვლისას მისი გაწმენდა შეგიძლიათ დოლბანდით ან თითზე ჩამოსაცმელი ჯაგრისით. 1 წლის შემდეგ კი შეგიძლიათ ბავშვის კბილის ჯაგრისი ხელში მისცეთ, მის წინ დადგეთ და აჩვენოთ, როგორ უნდა გაიხეხოს კბილები. შესაძლოა, თავიდან ვერ შეძლოს, მაგრამ თქვენი მიბაძვით ამას მალე ისწავლის. თუმცა გახსოვდეთ, რომ კბილის პასტის გამოყენება ჯერ ნაადრევია.') WHERE id = '37f66307-1b67-498c-b0b6-20e87a8898b8';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'რადგან თქვენი ბავშვი საკმაოდ აქტიურია, უბედური შემთხვევების თავიდან ასაცილებლად უსაფრთხოების გარკვეული ზომები უნდა მიიღოთ. მაგალითად, იატაკზე დავარდნილი წამლები, თხილეული, მომძვრალი ღილები, მონეტები და სხვა პატარა საგნები უნდა აიღოთ და ყურადღებით იყოთ, რადგან ბავშვმა შეიძლება ისინი გადაყლაპოს. ბავშვისთვის, რომელიც ავეჯზე დაყრდნობით ფეხზე დგომას ცდილობს, მაგიდისა და ჟურნალების მაგიდის მსგავსი ავეჯის ბასრი კუთხეები შეიძლება სახიფათო იყოს. ამიტომ ასეთი ავეჯი შეგიძლიათ იმ ოთახიდან გაიტანოთ, სადაც ბავშვია, ან მის კუთხეებზე სპეციალური დამცავები დაამაგროთ. ბავშვისთვის, რომელსაც ყველაფრის ქექვა აინტერესებს, ელექტროროზეტებზე დამცავი ხუფები შეგიძლიათ დააყენოთ. ასევე უნდა მოაშოროთ ღრმა სათამაშოების კალათები, რომლებშიც ბავშვი შეიძლება ჩავარდეს, ცელოფნის პარკები, რომლებიც შეიძლება თავზე ჩამოიცვას, და დახრჩობის საფრთხის შემცველი კაბელები. კარების დაკეტილად დატოვება და ფანჯრებზე, კარადებსა და უჯრებზე უსაფრთხოების საკეტების დამაგრებაც პოტენციურ საფრთხეებს შეამცირებს.') WHERE id = '6dba7d69-27ca-40ac-b3c1-c74bcff813bb';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'კარტოფილის მომზადებას დიდხანს ანდომებთ, ის კი ჭყლეტს, ხელს სუპში ყოფს, თქვენ მიერ მიცემულ სტაფილოს კი იატაკზე აგდებს... ნაცნობი სიტუაციაა? ნუ ღელავთ, ამაში მარტო არ ხართ! 😊 ამ ეტაპზე კვება თქვენი ბავშვისთვის შეიძლება მხოლოდ დანაყრება კი არა, თამაშიც იყოს. შესაძლოა, გაგაოცოთ, რომ თქვენ მიერ გულმოდგინედ მომზადებული საკვები მის კუჭში კი არ ხვდება, არამედ ირგვლივ იფანტება. თუმცა ამის გამო ბავშვის მიმართ მკაცრმა რეაქციამ შეიძლება მას საკვებისადმი ინტერესი დაუკარგოს. ამიტომ შესაძლოა, მოინდომოთ, საკვები წინიდან აუღოთ და თავად აჭამოთ. მიუხედავად ამისა, გახსოვდეთ, რომ ეს ყველაფერი განვითარების პროცესის ნაწილია და ბავშვი ასეთი აღმოჩენების წყალობით ახალ რამეებს სწავლობს.') WHERE id = 'cffb22db-240d-4023-8834-7c4c580e8149';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ ეტაპზე ბავშვის კუჭის ტევადობა საშუალოდ დაახლოებით 230 ml-ია. ამიტომ ნუ ინერვიულებთ იმის გამო, რომ ბავშვი ცოტას ჭამს. თქვენს ბავშვს ჯერ კიდევ სჭირდება მცირე ულუფებით და ხშირად კვება, ამიტომ ის თქვენ მიერ მომზადებულ ყველაფერს ერთ ჯერზე ვერ შეჭამს. იმის ნაცვლად, რომ მისთვის დიდი რაოდენობით საკვების მიცემა სცადოთ, შეგიძლიათ შეუდგინოთ დაბალანსებული კვების გეგმა მაღალი კვებითი ღირებულების მქონე პროდუქტებით. მაგალითად, ამ პერიოდში ბავშვს სხეულის წონის ყოველ კილოგრამზე ყოველდღიურად 1.02 გრამი ცილა (პროტეინი) სჭირდება. ეს ნიშნავს, რომ საშუალოდ 9000 გრამი წონის ბავშვისთვის ყოველდღიურად მისაღები ცილის რაოდენობა 9.2 გრამია. დედის რძის 100 გრამში დაახლოებით 1 გრამი ცილაა. ხელოვნურ საკვებში ეს თანაფარდობა შეიძლება განსხვავდებოდეს. ბავშვის ცილის ყოველდღიური საჭიროება ასევე შეგიძლიათ პარკოსნებითა და ხორცპროდუქტებით დააკმაყოფილოთ.') WHERE id = '338a7b7c-cd77-4384-ba83-6dc7af52489b';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ ფიქრობთ, რომ თქვენი ბავშვი ჯერ ვერ დგება ფეხზე და სიარულს არ ცდილობს, იცოდეთ, რომ ამის გამო ღელვა საჭირო არ არის. ყველა ბავშვი სიარულს მისთვის ინდივიდუალურ ასაკში იწყებს, ამიტომ ამ პროცესის დაჩქარება ან შემოკლება შეუძლებელია. ბავშვისთვის შეიძლება ძალიან სახალისო იყოს, როცა ხელებში მოჰკიდებთ, ფეხზე დადგომაში დაეხმარებით და ნაბიჯების გადადგმას შეეცდებით. ასეთი მოძრაობები შეგიძლიათ მცირე ხნით, თამაშის სახით გააკეთოთ, თუმცა არ უნდა ელოდოთ, რომ ამის შედეგად ბავშვი უფრო ადრე დაიწყებს სიარულს ან ფეხზე დგომას. ექიმები 1 წლამდე ბავშვების ფეხებზე რეგულარული დატვირთვისა და ფეხზე დაყენებით ნაბიჯების გადადგმის ვარჯიშების ჩატარებას დიდად არ გირჩევენ. ასეთი ვარჯიშები ბავშვის კუნთების ზოგად განვითარებას არ უწყობს ხელს. მეტიც, აღნიშნულია, რომ სარგებლის არქონის გარდა, მათ შეიძლება ზოგიერთი ანატომიური დარღვევაც გამოიწვიონ. ამიტომ გირჩევთ, ამ საკითხში ბავშვს ზედმეტად ნუ დაატვირთავთ.') WHERE id = '4cd9c678-a1f8-4663-9ede-462dc0cff3d9';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის ნაწლავების ჯანმრთელობისთვის არსებობს საკვები, რომელიც მას ჯერ კიდევ გარკვეული ხნის განმავლობაში არ უნდა მისცეთ. ამ საკვების რაციონიდან გამორიცხვა ალერგიის რისკის მინიმუმამდე შემცირების ერთ-ერთი ფაქტორია. მაგალითად, თხილი, მიწის თხილი, კეშიუ, ნუში და ნიგოზი ძალიან სასარგებლოა, თუმცა ეს ზეთოვანი თესლეული ბავშვის ნაწლავებში რთულად შეიწოვება და ძნელად მოსანელებელია. ასევე უნდა მოერიდოთ ბადრიჯანსა და ლობიოს მსგავს ბოსტნეულს, რადგან მათ ბავშვის ორგანიზმზე გარკვეული ტოქსიკური ზემოქმედების მოხდენა შეუძლიათ. რაც უნდა უყვარდეს ბავშვს, ტკბილეული და შაქრიანი პროდუქტები მისთვის თითქმის ყოველგვარ კვებით ღირებულებას მოკლებული „ცარიელი კალორიების“ წყაროა. ამიტომ, რაც უფრო გვიან გააცნობთ ბავშვს ასეთი ცარიელი კალორიების შემცველ საკვებს, მით უკეთესი იქნება მისი ჯანმრთელობისთვის. გარდა ამისა, ჯერ კიდევ განვითარებადი ნაწლავების გამო ბავშვს არ უნდა მისცეთ ტოქსოპლაზმოზის რისკის შემცველი ხორცპროდუქტები, როგორიცაა ძეხვი და სოსისი.') WHERE id = 'ac0487c0-d4c6-4175-ad05-4bab8a727217';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში ბავშვს უნდა მისცეთ შესაძლებლობა, გაეცნოს კატეგორიების ცნებას. ზოგი ბავშვი დაჯგუფებას საგნების მიხედვით სწავლობს, ზოგი კი — იმ ადამიანების მიხედვით, რომლებსაც ხშირად ხედავს გარშემო. მას შემდეგ, რაც ერთ ან ორ ძირითად კატეგორიას აღმოაჩენს, დანარჩენის სწავლა ბავშვისთვის ბევრად მარტივი გახდება. ამ პერიოდში, როდესაც ბავშვი ცდილობს გაიგოს, რას ნიშნავს დაჯგუფება, ის გონებაში ამ საგნების თვისებების აღმოჩენასაც იწყებს. მაგალითად, როდესაც ბავშვი საკვების დაჯგუფებას იწყებს, ის დამოუკიდებლად სწავლობს, რომ საკვები ჩანგლით ან ხელით უნდა ჭამოს. ამ ეტაპზე ბავშვი მისთვის საინტერესო საგნებს ხელით ეხება და ასე ცდილობს მათ გაცნობას. ამგვარად, მას შეუძლია განასხვაოს ისეთი მახასიათებლები, როგორიცაა ხორკლიანი, წებოვანი, სველი, მყარი და რბილი. ამ პერიოდში შეგიძლიათ ბავშვს სხვადასხვა საგანი გააცნოთ და ამით მის განვითარებას ხელი შეუწყოთ! 😊') WHERE id = '12e7c82f-2e58-40ab-94b2-fcc7a8bcfde0';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მუდმივად მოძრავი ბავშვის განვითარებისა და პოტენციური საფრთხეებისგან დაცვისთვის რამდენიმე საკითხს უნდა მიაქციოთ ყურადღება. გაღვიძებისას ბავშვი უკვე შეეცდება, საწოლიდან დამოუკიდებლად წამოდგეს. ამიტომ სასარგებლო იქნება დაბალი საწოლის შერჩევა და მის გვერდით რბილი ხალიჩის ან ღრუბლის დაფენა, რომელიც დაცემისას დაიცავს. მაღალი საწოლები დაცემის შემთხვევაში თავის ქალის ტრავმის რისკს ზრდის, ამიტომ ამ საკითხს განსაკუთრებული ყურადღება უნდა მიაქციოთ. ასევე, თუ ბავშვი უკვე გარკვეული ხანია საყრდენზე მოჭიდებით ცდილობს წამოდგომას, მოაშორეთ ყველა ისეთი ნივთი, რომელსაც მისაწვდომ მანძილზე განთავსებულ გადასაფარებელზე მოქაჩვით გადმოაგდებს. თუ კარი ან ფანჯარა ისეთ ადგილასაა, რომელსაც ბავშვი როგორღაც მისწვდება, მათზე დამცავი ჩამკეტები (stopper) შეგიძლიათ დაამონტაჟოთ. გარდა ამისა, თუ თქვენს ბავშვსაც, სხვა ბავშვების მსგავსად, უყვარს უჯრების ქექვა, შეგიძლიათ დროებით მოხსნათ იმ უჯრების სახელურები, რომლებსაც აღებს და მათზე აძრომას ცდილობს. ბავშვის უსაფრთხოებისთვის ოთახიდან უნდა გაიტანოთ მინის მაგიდა, ბასრკუთხიანი დაბალი ავეჯი და ქვედა თაროებზე მოთავსებული ისეთი პატარა სუვენირები თუ აქსესუარები, რომელთა გადაყლაპვაც მას შეუძლია.') WHERE id = '2dd356c6-11e2-445d-9935-897ed781f383';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ფიქრობთ, რა აქტივობებით შეგიძლიათ დაკავდეთ ბავშვთან ერთად მისი გონებრივი განვითარების შესაბამისად? ამისთვის არსებობს მეთოდები, რომლებიც ბავშვის გრძნობებსაც გაააქტიურებს და ერთად დროის სასიამოვნოდ და ნაყოფიერად გატარებაშიც დაგეხმარებათ. მაგალითად, გასაყიდად ხელმისაწვდომი ილუსტრირებული, ხმოვანი და მოძრავი წიგნები შეიძლება სწორედ ის საშუალება აღმოჩნდეს, რომელსაც ეძებთ! წიგნში მოცემული სურათები ბავშვის ყურადღებას მიიპყრობს, თქვენ კი შეგიძლიათ მათი მნიშვნელობის ახსნა დაიწყოთ. გარდა ამისა, ამ პერიოდში ბავშვს სხვადასხვა ზღაპარი შეგიძლიათ წაუკითხოთ, განსაკუთრებით ძილისთვის მომზადებისას. რადგან ბავშვს ჯერ სიტყვების მნიშვნელობა სრულად არ ესმის, შესაძლოა ყოველთვის ვერ გაიგოს თქვენი ნათქვამი და ზოგჯერ მოსმენაც მობეზრდეს. ამიტომ გირჩევთ, მოთმინებით განაგრძოთ კითხვა. ასეთი კითხვის სესიები შესანიშნავი დასაწყისი იქნება იმისთვის, რომ ბავშვს მომავალში წიგნები შეუყვარდეს.') WHERE id = '55011ab1-9f0a-4b61-aab6-1ab8d3c3412e';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ ბავშვს ძუძუთი კვებავთ ან რძის ნარევს აძლევთ, ამ ეტაპზე მისი ყოველდღიური კალორიული მოთხოვნილების დაახლოებით ნახევარი კვლავ რძით ივსება. დედის რძის კვებითი შემადგენლობა საშუალოდ 88% წყლისგან, 55% ცხიმისგან, 37% ნახშირწყლებისა და 8% ცილისგან შედგება. რძეში ძირითადად ლაქტოზად წოდებული ნახშირწყალია. ეს ნივთიერება რძიდან მიღებული კალორიების დაახლოებით 40%-ს უზრუნველყოფს. ეს ენერგიის მნიშვნელოვანი წყარო ნაწლავებში ისეთ მჟავე გარემოსაც ქმნის, რომელიც ხელს უშლის მავნე ბაქტერიების გამრავლებას. სასარგებლო ნაწლავური ბაქტერიების წარმოქმნის დაჩქარებით ის ხელს უწყობს დაბალანსებული ნაწლავური ფლორის ჩამოყალიბებას. ამიტომ მნიშვნელოვანია, სწრაფი განვითარების ეტაპზე მყოფი ბავშვი შეძლებისდაგვარად დიდხანს კვებოთ ძუძუთი. დედის რძის არარსებობის შემთხვევაში კი სპეციალისტები რეკომენდაციას უწევენ შემდგომი კვების რძის ნარევის ანალოგიურად, სულ მცირე 1 წლის ასაკამდე მიცემას.') WHERE id = '005de367-3aa8-4500-87f0-c7f5b37b1fe4';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'როგორ სწრაფად გაიზარდა თქვენი ბავშვი, არა? წარსულს რომ გადახედავთ, ხედავთ, რამდენად დიდი გზა გაიარეთ, თუმცა დრომ მაინც წყალივით სწრაფად ჩაიარა. ბავშვის დაბადებიდან ჯერ 1 წელიც არ გასულა, მაგრამ ამ დროის განმავლობაში მან საოცარ პროგრესს მიაღწია. მაგალითად, ბავშვი ტირილიდან სხვადასხვა ბგერის წარმოთქმაზე გადავიდა, ბგერებიდან კი — აზრიან სიტყვებზე. ახლა უკვე საუბრის დაწყების დროც თანდათან ახლოვდება. შეგიძლიათ დაეხმაროთ, რომ ამ სწრაფად მოახლოებულ პერიოდს მომზადებული შეხვდეს. მაგალითად, სახლში ან გარეთ შეგიძლიათ დაასახელოთ თითოეული ნივთი, რომელსაც იყენებთ ან შეხვდებით. იმისთვის, რომ ბავშვმა ამ ნივთების სახელები უფრო მარტივად დაიმახსოვროს, შეგიძლიათ გარკვეული მსგავსებებიც გამოიყენოთ. მაგალითად, როდესაც ძაღლს დაინახავთ, შეგიძლიათ მასზე მიუთითოთ, უთხრათ „ძაღლი“, შემდეგ კი მისი ხმა „ჰავ-ჰავ“ წარმოთქვათ.') WHERE id = '19fabca3-1b22-4b94-9659-be47ebeb9069';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ თვიდან ბავშვის მეხსიერება განვითარების საკმაოდ მაღალ საფეხურს აღწევს. ამიტომ არსებობს რამდენიმე საკითხი, რომელიც თქვენგან მეტ ყურადღებას მოითხოვს. თქვენს ბავშვს უკვე შეუძლია დაიმახსოვროს კონკრეტული ინფორმაცია, მაგალითად, სად დევს მისი სათამაშოები. ასევე შეუძლია გაიხსენოს და გაიმეოროს ცოტა ხნის წინ ნანახი მოქმედებები. მაგალითად, თუ სადილის დროს დაინახავს, რომ კოვზს იყენებთ, საღამოს შესაძლოა ხელით ჭამის ნაცვლად თავადაც კოვზით ჭამა სცადოს. მას ახსოვს ყუთი, რომელშიც სათამაშოებს ინახავთ, ან უჯრა, სადაც მათ დებთ, და პირველივე შესაძლებლობისას შეიძლება მათ მისაწვდომად მოქმედება დაიწყოს. მართალია, ეს ყველაფერი განვითარების ძალიან სასიამოვნო ნიშნებია, თუმცა ამავდროულად შეიძლება ითქვას, რომ გარკვეული რისკების შემცველ პერიოდშიც შედიხართ. მაგალითად, თუ თქვენი ბავშვი დაინახავს ადამიანს, რომელიც ეწევა, მოგვიანებით კი სიგარეტის მსგავს საგანს იპოვის, შესაძლოა ის პირთან მიიტანოს და ნანახის გამეორება სცადოს. ამიტომ ახლა განსაკუთრებული ყურადღება უნდა გამოიჩინოთ და ყველაფერი გააკეთოთ იმისთვის, რომ თქვენს ბავშვს კარგი მაგალითი მისცეთ.') WHERE id = 'e01a8401-6796-4fd1-8eb2-bb5e93fe04db';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'უკვე გარკვეული ხანია, თქვენი ბავშვი დღეებს ისე აღარ ატარებს, როგორც ახალშობილობისას — მხოლოდ ჭამასა და ძილში. მისი დაბადებიდან ზუსტად 9 თვე გავიდა და ის დღითიდღე უფრო შესამჩნევად იწყებს სოციალიზაციას, თქვენთან და გარშემო მყოფ ადამიანებთან ურთიერთობას. თქვენს ბავშვს უკვე უყალიბდება საკუთარი ჩვევები, რაც მისი ხასიათის ფორმირების დაჩქარებას ნიშნავს. თუ ბავშვს განვითარების ნახტომი, კბილების ამოჭრა ან ჯანმრთელობასთან დაკავშირებული რაიმე პრობლემა არ აწუხებს, შესაძლოა, მისი ღამის ძილი უკვე მოწესრიგებას იწყებდეს. განსაკუთრებით იმის გამო, რომ დღის განმავლობაში ენერგიას აქტიურად ხარჯავს, ღამით, როგორც წესი, აღარ იღვიძებს ან ძალიან იშვიათად იღვიძებს. ამიტომ, თუ თქვენს ბავშვს ძილის რეჟიმი ჯერ კიდევ არ ჩამოუყალიბდა, გვინდა შეგახსენოთ, რომ ახლა მის დასამყარებლად ძალიან ხელსაყრელი პერიოდია. შესაძლოა, ბავშვს ძილის დროის განსაზღვრაშიც დასჭირდეს თქვენი დახმარება. მაგალითად, შეგიძლიათ ყოველდღე ერთსა და იმავე დროს შეიყვანოთ თავის ოთახში და დაძინებამდე ცოტა ხნით მის გვერდით დარჩეთ.') WHERE id = '4172e48e-6df4-4725-923e-07d5217e37c6';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ თვიდან ბავშვის ყოველდღიური კვების 50% დედის რძე (ან ხელოვნური ნარევი), ხოლო დანარჩენი 50% დამატებითი საკვები უნდა იყოს. თუ აქამდე ბავშვს დამატებით საკვებს დღეში ორჯერ აძლევდით, შეგიძლიათ ეს რაოდენობა სამამდე გაზარდოთ. ასევე, თუ ექიმს სხვაგვარად არ უთქვამს, ბავშვს შეგიძლიათ მისცეთ იმდენი საკვები, რამდენიც სურს. თუმცა დამატებითი საკვების რაოდენობის ზრდასთან ერთად, თუ ბავშვს ძუძუთი კვებავთ, შესაძლოა, მან ნაკლები დედის რძე მიიღოს. ამის თავიდან ასაცილებლად შეგიძლიათ ბავშვს დამატებითი საკვების მიღებამდე არაუმეტეს ერთი საათით ადრე ძუძუ აწოვოთ. ზოგიერთი დედა აღნიშნავს, რომ მომზადებულ ბოსტნეულისა და ხილის პიურეს საკუთარ გამოწველილ რძეს უმატებს. ამ მეთოდით ბავშვს უფრო ჯანსაღ საკვებს შესთავაზებთ და ის ამგვარად მომზადებულ კერძებსაც მადიანად მიირთმევს.') WHERE id = 'da5cb5a7-cf3b-4e4d-80b2-ebbc83c6520d';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის შერჩევითი აღქმა უკვე მნიშვნელოვნად არის განვითარებული. ამის წყალობით, მას შეუძლია ხმის წყაროს გარჩევა მაშინაც კი, თუ თავს არ მიაბრუნებს და მის ძებნას არ დაიწყებს. თუ ეს ჯერ არ დაწყებულა, ამ თვიდან თქვენმა ბავშვმა შესაძლოა უცხო ადამიანების მიმართ სიფრთხილე გამოიჩინოს და მათთან თავი უხერხულად იგრძნოს. ამ პერიოდში ბავშვები შეიძლება საკმაოდ განსხვავებულ და საინტერესო ქცევებს ავლენდნენ. თუმცა, ზოგადად, ისინი უცნობი ადამიანების გარემოცვაში შფოთავენ და საკუთარ რეაქციას ტირილით გამოხატავენ. ეს თქვენი ბავშვისთვის დროებითი ეტაპია და ამ პერიოდში არ უნდა აიძულოთ, მიუახლოვდეს უცხო ადამიანებს, რომლებზეც ტირილით რეაგირებს. განსაკუთრებით, თუ ახალ გარემოში ბავშვი შფოთავს და სხვის ხელში გადასვლა არ სურს, პატივი უნდა სცეთ მის გადაწყვეტილებას და სხვებსაც სთხოვოთ, იგივე გააკეთონ. ამასთანავე, სრულიად ბუნებრივია, რომ ამ პერიოდში ბავშვს გვერდით მხოლოდ თქვენ და მამა სურდეთ. გირჩევთ, განშორების შიშის გაძლიერებისას ბავშვი დიდხანს მარტო არ დატოვოთ და, საჭიროების შემთხვევაში, საერთოდ არ მოშორდეთ.') WHERE id = '21e5fb9b-957f-4246-8c1d-e631e7b5dd81';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მყარი საკვების მიღების პერიოდში სრულიად ბუნებრივია, რომ ბავშვს ზოგიერთი სასარგებლო ბოსტნეულის ჭამა არ სურდეს. ბავშვის გემოვნების აღქმა უკვე დიდი ხანია ჩამოყალიბებულია, ამიტომ მან შეიძლება უარი თქვას საკვებზე, რომლის გემოც არ მოსწონს. ასეთ შემთხვევებში ზოგიერთი ექიმი გვირჩევს, დამხმარე საშუალებად გამოვიყენოთ ბავშვისთვის კარგად ნაცნობი დედის რძე ან ხელოვნური ნარევი. ამგვარად, რძე საკვებს ნაცნობ გემოს სძენს და ბავშვს იმ საკვების მიღებას უადვილებს, რომელზეც მანამდე უარს ამბობდა. ამისთვის შეგიძლიათ ბავშვისთვის არასასურველი საკვების ძალიან მცირე რაოდენობა შეურიოთ რძეს ისე, რომ მისი გემო არ შეიცვალოს, შემდეგ კი დროთა განმავლობაში რაოდენობა გაზარდოთ. მაგალითად, თუ თქვენს ბავშვს სტაფილო არ მოსწონს, შეგიძლიათ ეს რეცეპტი სცადოთ: მცირე რაოდენობის თბილი წყალი და შვრიის ფქვილი აურიეთ და მოხარშეთ. შესქელების შემდეგ დაუმატეთ კარაქი, ოდნავ რომ გაგრილდება კი ნარევი დედის რძით ან ხელოვნური ნარევით გაათხელეთ. მასში დამატებულ მცირე რაოდენობის სტაფილოს ბავშვი, დიდი ალბათობით, ვერც კი შეამჩნევს. გემრიელად მიირთვას!') WHERE id = 'b6baae80-bfde-4969-a04d-a53ffef941a8';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'დროთა განმავლობაში, თუ ბავშვს რაიმე დისკომფორტი არ აწუხებს, მისი ძილის რეჟიმი უფრო მოწესრიგებული გახდება. თუ თქვენი ბავშვი ხშირად იღვიძებს და ხელახლა ჩაძინება უჭირს, თქვენთვის სასიხარულო ამბავი გვაქვს: ამ თვიდან მისი ძილი ძალიან იშვიათად შეწყდება! 😊 ამ რეჟიმის მოწესრიგებას მრავალი მიზეზი აქვს. მაგალითად, ბავშვის ტვინში ძილის ფაზები ახლა უკვე უფრო ხანგრძლივი დროის განმავლობაში სრულდება. ამის შედეგად ის, განსაკუთრებით ღამით, უფრო იშვიათად გაიღვიძებს და გაღვიძების შემდეგაც უფრო ადვილად დაიძინებს. ზოგჯერ ბავშვს განვითარების ნახტომის პერიოდში ან სხვა მიზეზით გამოწვეული დისკომფორტის დღეებში ჩაძინება შეიძლება გაუჭირდეს. ასეთ შემთხვევაში გირჩევთ, დაამშვიდოთ ბავშვი და მასთან ერთად შედარებით ბნელ ოთახში გაატაროთ დრო. ძილის წინ თბილი, დამამშვიდებელი აბაზანა და შემდეგ ზეთით გაკეთებული მასაჟიც ბავშვს ჩაძინებას გაუადვილებს.') WHERE id = '9263dfdf-7d11-40a3-a89c-aa51842213c4';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის კბილების მოვლა ძალიან მნიშვნელოვანია. ვინაიდან მისი კბილები ძალზე მგრძნობიარეა, მოვლის საშუალებები ყურადღებით უნდა შეარჩიოთ. უპირველეს ყოვლისა, კბილის ჯაგრისის არჩევისას აუცილებლად მიაქციეთ ყურადღება, რომ ის ბავშვის პირის ღრუს აგებულებას შეესაბამებოდეს. ზრდასრულებისთვის განკუთვნილი ჯაგრისები, როგორი ხარისხიანიც უნდა იყოს, ბავშვის პირის ღრუსთვის შესაფერისი არ არის. ამასთანავე, რადგან ბავშვის ღრძილები ჯერ კიდევ ძალიან მგრძნობიარეა, უპირატესობა რბილჯაგრიან ჯაგრისს უნდა მიანიჭოთ. ამ პერიოდში ძალიან მოსახერხებელია ჩვილებისთვის განკუთვნილი, თითზე ჩამოსაცმელი კბილის ჯაგრისები. თუ თქვენს ბავშვს კბილების გახეხვა არ მოსწონს, მოვლის დროს მისი ყურადღების მისაპყრობად შეგიძლიათ საყვარელი სათამაშოები გამოიყენოთ. პირის ღრუს სახლში მოვლასთან ერთად, მომავალში ჯანსაღი კბილები რომ ჰქონდეს, ძალიან მნიშვნელოვანია, ბავშვი რეგულარულად ატაროთ მისი ექიმის მიერ რეკომენდებულ სტომატოლოგთან.') WHERE id = '56bcb0b3-2ef0-42fc-b5f4-45a3b8d99519';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი გარემოს უკვე საკმაოდ მკაფიოდ ხედავს. ამ თვეში მას დაახლოებით 5-6 მეტრის მანძილიდანაც კი შეუძლია ნაცნობი ადამიანების გარჩევა. ბავშვის მოძრაობის უნარი მნიშვნელოვნად განვითარდა, ხოლო მოსმენის უნარი უფრო ყურადღებიანი გახდა. შედეგად, მისი შეგრძნებები ახლა უკვე ერთმანეთთან შეთანხმებულად მუშაობს. მაგალითად, როდესაც ვინმე ლაპარაკობს, ბავშვს შეუძლია ერთდროულად დააკვირდეს მას და მის საუბარსაც მოუსმინოს. ეს ერთ-ერთი უმნიშვნელოვანესი ფაქტორია, რომელიც ბავშვს გარემოში მიმდინარე მოვლენების უფრო ზუსტად გაგებაში ეხმარება. ამის წყალობით თქვენ შორის ურთიერთობაც გაძლიერდება. ამ პერიოდში იმისთვის, რომ ბავშვმა მოგისმინოთ და მისი ყურადღება მიიპყროთ, დიდი ძალისხმევა აღარ დაგჭირდებათ. როდესაც გსურთ, ბავშვს რამე აუხსნათ, ან როცა ის პოტენციურად სახიფათო მოძრაობას აკეთებს, შეგიძლიათ მის თვალის დონეზე დაიხაროთ, თვალებში შეხედოთ და ისე ესაუბროთ.') WHERE id = '34bce004-091a-42c4-b036-d6f0fb49caaf';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ თქვენს ბავშვს ალერგიისადმი მიდრეკილება აქვს, გარკვეული საკვების ჭამა, შეხება ან თუნდაც მისი სუნის შესუნთქვა შეიძლება სახიფათო იყოს. ასეთ შემთხვევებში, როგორც კი ბავშვი ალერგენთან კონტაქტში შედის, იმუნური სისტემა ამ ნივთიერებას ორგანიზმისთვის საზიანოდ აღიქვამს. ბავშვის ორგანიზმი საზიანო ნივთიერებებთან საბრძოლველად ალერგიული რეაქციის გამომწვევ ანტისხეულებს წარმოქმნის. ანუ ალერგია მაშინ ვითარდება, როდესაც იმუნური სისტემა სინამდვილეში უვნებელ ნივთიერებას ვირუსის მსგავს საფრთხედ აღიქვამს. ბავშვს ალერგია შეიძლება გენეტიკური ფაქტორების, გარემოსა და არაჯანსაღი კვების გამო განუვითარდეს. მიუხედავად იმისა, რომ ზუსტი მიზეზები უცნობია, ყველაზე მნიშვნელოვან ფაქტორად ერთ ან ორივე მშობელში ალერგიის არსებობა მიიჩნევა. მაგალითად, თუ თქვენ და თქვენს მეუღლეს პენიცილინზე ალერგია გაქვთ, ბავშვს მასზე ალერგიის განვითარების რისკი 70%-მდე ეზრდება.') WHERE id = 'e455730e-1689-4a02-baeb-f13c6f81e7b6';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ თქვენი ბავშვი შარდვისას ტირის, მის შარდს უსიამოვნო სუნი აქვს და ხშირად ეწყება ძლიერი ტირილის ეპიზოდები, საშარდე გზების ინფექცია უნდა ივარაუდოთ. საშარდე გზების ინფექცია არის მდგომარეობა, რომლის დროსაც საშარდე გზებში მავნე ბაქტერიები ანთებას იწვევს. მიუხედავად იმისა, რომ ამ ტიპის ინფექცია ორივე სქესის ბავშვებში გვხვდება, ჩვეულებრივ, ის გოგონებში უფრო ხშირია. ამის მიზეზი ისაა, რომ გოგონებს შარდსადენი ბიჭებთან შედარებით უფრო მოკლე აქვთ. ეჭვის შემთხვევაში აუცილებლად უნდა გაიაროთ კონსულტაცია ექიმთან და ბავშვს შარდის საერთო ანალიზი და ბაქტერიოლოგიური კვლევა (კულტურა) ჩაუტაროთ. თუ ანალიზებში ანთების ნიშნები გამოვლინდა, ფართო სპექტრის ანტიბიოტიკით მკურნალობა იწყება. მკურნალობის ხანგრძლივობა სულ მცირე 10 დღეა. მკურნალობის დასრულების შემდეგ ანტიბიოტიკის მოქმედების გასვლას 3 დღე უნდა დაელოდოთ, შემდეგ კი შარდის ანალიზი გაიმეოროთ, რათა დარწმუნდეთ, რომ ბავშვი სრულად გამოჯანმრთელდა.') WHERE id = 'a8d0a258-4dfc-44d2-9a7b-064e2b1e8568';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ თქვენი ბავშვი ხშირად ავადდება, ამის გამო თავს ნუ დაიდანაშაულებთ და ნუ იფიქრებთ, რომ სათანადოდ ვერ უვლით. რადგან ბავშვის იმუნური სისტემა ჯერ ბოლომდე არ არის ჩამოყალიბებული, გაციება და გრიპი შეიძლება ხშირად შეგხვდეთ. ბავშვების უმეტესობა სიცოცხლის პირველი ორი წლის განმავლობაში დაახლოებით ათჯერ ცივდება. ეს პროცესი, რომელიც პირველ თვეებში რთულად გეჩვენებათ, იმ მომენტში ბავშვს მხოლოდ დისკომფორტს უქმნის. ამ პერიოდის რაც შეიძლება მარტივად გადასატანად თქვენი მთავარი ამოცანაა, ბავშვი შეძლებისდაგვარად კომფორტულად აგრძნობინოთ. მაგალითად, ავადმყოფობის დროს ბავშვის ორგანიზმს მეტი ძილი სჭირდება. ამიტომ აბაზანის შემდეგ გაკეთებული დამამშვიდებელი მასაჟი მას ჩაძინებას მნიშვნელოვნად გაუადვილებს. თუ ცხვირი გაჭედილი აქვს, ძილის დროს შეგიძლიათ მის თავს ჩვეულებრივზე ოდნავ მაღალი ბალიში დაუდოთ. გახსოვდეთ, რომ გაციებისას ბავშვის ორგანიზმს მეტი სითხე სჭირდება, ამიტომ უზრუნველყავით, რომ მან საკმარისი წყალი დალიოს და დედის რძე (ან ხელოვნური ნარევი) მიიღოს.') WHERE id = '0c97a7c0-87cb-4c6d-bccc-18d59ae9a64f';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'რადგან ბავშვის მოტორული უნარები, გრძნობები და გონებრივი განვითარება მნიშვნელოვნად წინ წავიდა, ის ცხოვრების მეტად აქტიურ ეტაპზე გადადის. ამ პერიოდში თქვენმა ბავშვმა შესაძლოა ახალი უნარები გამოიმუშაოს, მათ შორის ხელმისაწვდომი ნივთების ხელში აღება. მან შეიძლება დაიწყოს ყველა იმ ნივთის ქნევა, ერთმანეთზე დარტყმა, ძირს დაგდება და გადაგდება, რომლის დაჭერა და აწევაც შეუძლია. როდესაც აღმოაჩენს, რომ ნივთებზე ასეთი ზემოქმედება შეუძლია, შესაძლოა ერთი და იგივე მოქმედებები გარკვეული დროის განმავლობაში დაუღალავად გაიმეოროს. ამიტომ არ დაგავიწყდეთ, რომ ამ ეტაპზე განსაკუთრებული ყურადღება გმართებთ. თავის ქალის ტრავმების დიდი ნაწილი სწორედ ამ თვეებში ხდება. შესაბამისად, შეგიძლიათ სახლში ბავშვისთვის გარკვეული საზღვრები დააწესოთ. მაგალითად, ბავშვი არ უნდა გავიდეს იმ ოთახიდან, რომელშიც თქვენ იმყოფებით; შეგიძლიათ დაიწყოთ ოთახიდან იმ ნივთების გატანით, რომლებმაც შესაძლოა მას ზიანი მიაყენოს.') WHERE id = 'af4167d5-e075-447d-a653-bf92fb79d76e';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'საწოვარას საკითხი საკმაოდ სადავოა და თითოეულ სპეციალისტს განსხვავებული მოსაზრება აქვს. თუ თქვენი ბავშვი საწოვარას იყენებს, ალბათ გაწუხებთ კითხვები: როდემდე უნდა გამოიყენოს და როგორ უნდა გადააჩვიოთ? საწოვარას დანიშნულება წოვის რეფლექსის დაკმაყოფილებაა, ამიტომ ის მოუსვენრობის დროს დიდ დახმარებას გვიწევს. თუმცა მისი გამოყენებისადმი დადებითად განწყობილი სპეციალისტებიც კი თანხმდებიან, რომ ხანგრძლივმა გამოყენებამ შეიძლება პრობლემები გამოიწვიოს. საწოვარას ხანგრძლივად გამოყენებამ შესაძლოა ბავშვის ყბის არასწორი ფორმირება, მომავალში კი მეტყველებისა და ყლაპვის პრობლემები გამოიწვიოს. ამიტომ სპეციალისტები გვირჩევენ, რომ ბავშვმა 2 წლის ასაკამდე საწოვარას გამოყენება სრულად შეწყვიტოს. თუმცა ეს პროცესი დროში უნდა გაიწეროს და ბავშვისთვის სტრესის თავიდან ასაცილებლად უეცრად არ უნდა მოხდეს. მაგალითად, თუ ბავშვი საწოვარას დაძინებისას იყენებს, კარგი დასაწყისი იქნება, თუ ჩაძინების შემდეგ მას პირიდან ფრთხილად გამოაცლით.') WHERE id = 'ea3db4c3-dcac-405e-b393-93a579b49517';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი უკვე იყენებს რამდენიმე გააზრებულ სიტყვას და როგორღაც ახერხებს, გაგაგებინოთ, რა აწუხებს. თუმცა მისთვის მიბაძვა კვლავ სწავლის ძალიან მნიშვნელოვანი საშუალებაა. ამიტომ თითოეული სიტყვა, რომელსაც ეუბნებით, მის ლექსიკურ მარაგს კიდევ უფრო ამდიდრებს. მართალია, ამ პერიოდში ფიზიკური განვითარებაც სწრაფად მიმდინარეობს, მაგრამ გონებრივი განვითარება უფრო მეტად იკვეთება. გახსოვდეთ, რომ ახლა ბავშვის ენობრივი და მეტყველების უნარები სწრაფად ვითარდება. ის უკვე იგებს თქვენს მარტივ დავალებებს ან სულ მალე დაიწყებს მათ გაგებას. მისი ენობრივი და მეტყველების უნარების გასავითარებლად რამდენიმე სასარგებლო ხერხი არსებობს. მაგალითად, როცა მისგან რამეს ითხოვთ, კარგი დასაწყისი იქნება მისთვის „მადლობის“ თქმა. ხოლო როდესაც ის ისეთ რამეს აკეთებს, რაც არ გსურთ, მკაცრად „არას“ თქმისა და ჩარევის ნაცვლად შეგიძლიათ სხვა მიმართულება შესთავაზოთ ისეთი ფრაზებით, როგორებიცაა: „გთხოვ“, „ამით სხვა დროს ხომ არ დავინტერესდეთ?“ ან „მოდი, ერთად ვითამაშოთ“. ეს ხელს შეუშლის ბავშვის პროტესტის ჩვევად ჩამოყალიბებას.') WHERE id = '177ea1b8-c76a-4b5a-9e15-051e313ce518';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მყარი საკვების რაოდენობა და მრავალფეროვნება, რომელსაც თქვენი ბავშვი მიირთმევს, მნიშვნელოვნად გაიზარდა. თუმცა ერთი რამ უცვლელია: დედის რძე. მიუხედავად იმისა, რომ ბავშვი ყოველდღიურად მეტ დამატებით საკვებს იღებს, თქვენი რძე მისი განვითარებისთვის კვლავ ძალიან მნიშვნელოვანია. თუ ამ ეტაპზე ძუძუთი აღარ კვებავთ, შესაძლოა კვებაში მთავარი ადგილი მყარ საკვებს დაუთმეთ. თუმცა ამ პერიოდში ბავშვის მყარი საკვების დღიური საჭიროება დაახლოებით 3-4 ქილა საბავშვო საკვებს შეადგენს. ამაზე მეტი მყარი საკვების მიღებამ შეიძლება უარყოფითად იმოქმედოს ჯერ კიდევ განვითარებად საჭმლის მომნელებელ სისტემასა და ნაწლავის მიკროფლორაზე. ამასთანავე, მომავალში ამან შესაძლოა ჯანმრთელობის მრავალი პრობლემა, პირველ რიგში კი სიმსუქნე გამოიწვიოს. ამიტომ, თუ ბავშვს ძუძუთი არ კვებავთ, სასიცოცხლოდ მნიშვნელოვანია ერთადერთი ალტერნატივის — ადაპტირებული რძის ნარევის (ფორმულის) გამოყენება.') WHERE id = '1a9bf277-b2e7-4c8a-a929-8d4f4f669610';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ გადაწყვიტეთ, რომ ბავშვმა ცალკე ოთახში დაიძინოს, ჩვეულებრივზე მეტად თანმიმდევრული უნდა იყოთ. ზოგიერთი სპეციალისტის აზრით, ბავშვის ცალკე ოთახში გადაყვანა 1 წლის ასაკამდე უნდა მოხდეს. ამ ასაკის შემდეგ ბავშვისთვის ახალი ჩვევის ჩამოყალიბება რთულდება და შესაძლოა გამოვლინდეს ტირილის შეტევები, დაძინებაზე უარის თქმა და მიტოვების შიში. ბავშვის ცალკე ოთახში გადაყვანისას ეტაპობრივი მიდგომა როგორც თქვენ, ისე თქვენს პატარას სიმშვიდეს მოგიტანთ. პირველ რიგში, როდესაც თავს მზად იგრძნობთ და ჩათვლით, რომ დრო მოვიდა, მტკიცედ უნდა დაიცვათ თქვენი გადაწყვეტილება. პროცესის დასაწყისში სწორი ნაბიჯი იქნება, თუ ბავშვის ოთახში მის ჩაძინებამდე დარჩებით, ხოლო ღამით გაღვიძებისას თქვენს საწოლში გადაყვანის ნაცვლად მასთან მიხვალთ და დაელოდებით, სანამ კვლავ დაიძინებს. ოთახის ბავშვისთვის სასიამოვნოდ მოწყობაც დაეხმარება, რომ იქ ყოფნა მოუნდეს. გარდა ამისა, ღამით გაღვიძებისას რომ არ შეშინდეს, გარკვეული დროის განმავლობაში მკრთალი განათების (ღამის სანათის) გამოყენებაც გამოგადგებათ.') WHERE id = '2cdfd82a-b781-4b01-bce5-c70071e76784';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'იმისთვის, რომ ბავშვს ჯანსაღი კვების ჩვევები ჩამოუყალიბდეს, ძალიან მნიშვნელოვანია, ჭამის დროს მთელი ყურადღება საკვებზე ჰქონდეს გადატანილი, დედიკო. ამიტომ ჭამისას ბავშვის ყურადღება სხვა რამეებმა არ უნდა გაფანტოს. სპეციალისტები განსაკუთრებით არ გვირჩევენ ბავშვის კვებას გარემოში, სადაც ტელევიზორია ჩართული. როდესაც ბავშვის ყურადღება საკვების ნაცვლად ტელევიზორზეა გადატანილი, ის სათანადოდ ვერ აცნობიერებს, რომ დანაყრდა. შედეგად, შეიძლება ჭამა დანაყრებამდე შეწყვიტოს ან, პირიქით, დანაყრების მიუხედავად განაგრძოს. იმისთვის, რომ ბავშვმა ყურადღება მიღებულ საკვებზე გაამახვილოს და დანაყრების მომენტი იგრძნოს, გარკვეული უნარია საჭირო. ამ უნარს უდიდესი მნიშვნელობა აქვს ბავშვისთვის ჯანსაღი კვების გრძელვადიანი ჩვევის ჩამოყალიბებაში.') WHERE id = '415ce321-e862-4b3b-9a4e-2e689e0f9a0f';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ ჯერ არ შეგიძენიათ, უსაფრთხოების მიზნით შეგიძლიათ ბავშვის მონიტორის (რადიოძიძის) შერჩევა დაიწყოთ. მის შესაძენად აუცილებელი არ არის, ბავშვის ცალკე ოთახში გადაყვანის დროს დაელოდოთ. ეს მოწყობილობები ძალიან სასარგებლოა ბავშვის მეთვალყურეობისთვის, როცა მის გვერდით მუდმივად ყოფნას ვერ ახერხებთ, და საჭიროების შემთხვევაში დაუყოვნებლივ რეაგირებისთვის. შეგიძლიათ აირჩიოთ როგორც მხოლოდ ხმის გადამცემი მოდელი, ისე ვიდეომონიტორი. ბავშვის მონიტორის შეძენისას ყველაზე მნიშვნელოვანია, რომ მისი მოქმედების დიაპაზონი ოთახებს შორის მანძილს შეესაბამებოდეს. თუ მოწყობილობას ბავშვის ცალკე ოთახში გადაყვანის შემდეგ გამოსაყენებლად ყიდულობთ, შეგიძლიათ ღამის ხედვის ფუნქციის მქონე მოდელები განიხილოთ. ამასთანავე, მონიტორი ადვილად გადასატანი უნდა იყოს და მგრძნობიარე მიკროფონი ჰქონდეს.') WHERE id = '66e0fb2c-314f-41f3-bf17-cb60663f6d11';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი სწრაფად ზრდასა და განვითარებას განაგრძობს. ამ პერიოდში შეიძლება შეამჩნიოთ, რომ ის ისე აქტიურია, როგორც არასდროს. ბავშვის ჯანსაღი განვითარებისთვის, რომელიც უკვე ნამდვილ პატარა მოთამაშედ იქცა, მოსალოდნელია, რომ მისი მეტყველება, აზროვნება, ნატიფი და მსხვილი მოტორული უნარები, ასევე სოციალური უნარები ასაკის შესაბამისად ვითარდებოდეს. ბავშვის ასაკის შესაბამისი აქტივობები, რომლებსაც მასთან ერთად განვითარების თითოეულ ეტაპზე შეასრულებთ, მისი განვითარების ხელშემწყობი ერთ-ერთი უმნიშვნელოვანესი ფაქტორია. ვიცით, რომ ძალიან გიყვართ თქვენი ბავშვი და გსურთ, ყველა შესაძლო საფრთხისგან დაიცვათ. თუმცა, ზედმეტად მზრუნველი და შემზღუდველი აღზრდის მიდგომა ბავშვის განვითარებას მნიშვნელოვნად აფერხებს. მაგალითად, თუ გარეთ გასვლისას დაცემის შიშით ბავშვს თავისუფლად მოძრაობის საშუალებას არ მისცემთ, ეს მის განვითარებას შეანელებს და გარკვეული დროის შემდეგ საკუთარი შესაძლებლობების მიმართ დაურწმუნებლობას გაუჩენს. ამიტომ ბავშვს უნდა მისცეთ საშუალება, ჩაერთოს ისეთ აქტივობებში, რომლებიც მისი განვითარების დონის შესაბამისი უნარების შეძენაში დაეხმარება, და საჭიროების გარეშე არ უნდა ჩაერიოთ.') WHERE id = '037a24b5-120f-42ab-b763-b5da751da157';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვისთვის სათამაშოების შერჩევა მისი განვითარებისა და ახლად შეძენილი უნარების შესაბამისად, ყოველ ეტაპზე იცვლება. მაგალითად, ამ პერიოდში, როდესაც თქვენს ბავშვს ნატიფი მოტორული უნარები უვითარდება, ფერადი ფანქრებისა და გასაფერადებელი წიგნების შეძენა შესანიშნავი იდეაა! 😊 ასეთი აქტივობები ბავშვს არა მხოლოდ ძალიან ართობს, არამედ თითების გამოყენებასაც უკეთ ასწავლის, რაც ნატიფი მოტორიკის განვითარებასა და შემოქმედებითი უნარების გაუმჯობესებას უწყობს ხელს. ამასთანავე, ბავშვის გონებრივი განვითარებისთვის შეგიძლიათ შეარჩიოთ მსხვილნაწილიანი LEGO-ს კონსტრუქტორები, რომელთა გადაყლაპვასაც ვერ შეძლებს, ასევე დასაშლელი და ასაწყობი სათამაშოები. ამ პერიოდში თქვენს ბავშვს თქვენთან დროის გატარებაც ისევე უყვარს, როგორც სათამაშოებით თამაში. ამიტომ შეგიძლიათ ბავშვთან ერთად სარკის წინ დადგეთ და სახის სასაცილო გამომეტყველებები მიიღოთ. ასე ბავშვი არა მხოლოდ ძალიან გაერთობა, არამედ შესაძლებლობაც ექნება, უკეთ აღმოაჩინოს და შეისწავლოს თქვენ, საკუთარი თავი და გარემო. სასიამოვნო გართობას გისურვებთ! 😊') WHERE id = '27c8f700-edb4-4233-8b6f-05e91bb19bd4';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'შესაძლოა, თქვენმა ბავშვმა უკვე დაიწყო სიარული. თუ ჯერ არ დადის, პირველი ნაბიჯების გადადგმა მხოლოდ დროის საკითხია! თუმცა ზოგჯერ სიარულის დაწყებას შეიძლება ცოტა მეტი დრო დასჭირდეს. ეს დაგვიანება აუცილებლად პრობლემაზე არ მიუთითებს. მაგალითად, თუ ბავშვი ძალიან სწრაფად ხოხავს, ეს სიარულის დაგვიანების ერთ-ერთი მთავარი მიზეზი შეიძლება იყოს. რადგან ხოხვით სასურველ ადგილამდე მარტივად აღწევს, სიარულისადმი მისი ინტერესი მცირდება. ჭარბი წონაც ერთ-ერთი მიზეზია, რომელმაც შეიძლება სიარულის დაწყება შეაფერხოს. ამან შესაძლოა არა მხოლოდ სიარულის, არამედ გადაბრუნებისა და ხოხვის მსგავსი მოძრაობების ათვისებაც ჩვეულებრივზე მეტად შეანელოს. ამიტომ, თუ ბავშვს ოდნავ ჭარბი წონა აქვს, სიარულის დასაწყებად შეიძლება ცოტა მეტი დრო დასჭირდეს.') WHERE id = '704954bf-6728-49ee-8d83-22a42aaa6a0b';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის განვითარებისა და ახალი უნარების შეძენისთვის ძილის ხანგრძლივობასა და ხარისხს უდიდესი მნიშვნელობა აქვს. ამ ეტაპზე თქვენ მიერ ჩამოყალიბებული ძილის თანმიმდევრული რეჟიმი ერთ-ერთი მთავარი ფაქტორია, რომელიც ბავშვის ძილის ხარისხზე მთელი ცხოვრების განმავლობაში მოახდენს გავლენას. ახალშობილობის პერიოდში ბავშვი თითქმის მთელ დღეს ძილში ატარებდა. თვეების გასვლასთან ერთად ძილის ეპიზოდების რაოდენობა და ხანგრძლივობა მცირდება, ღამით გაღვიძებაც იშვიათდება. მე-11 თვიდან ბავშვს ღამით საშუალოდ 10-11 საათი, დღისით კი დაახლოებით 2-3 საათი სძინავს. თუ ფიქრობთ, რომ ბავშვს ამაზე ნაკლები სძინავს, ამას შეიძლება ორი მიზეზი ჰქონდეს. პირველი — ბავშვმა ჯერ არ იცის, როგორ დაიძინოს დამოუკიდებლად, დახმარების გარეშე. მეორე — შესაძლოა, დროულად ვერ ამჩნევთ, რომ ეძინება, რის გამოც გადაღლილობის გამო ჩაძინება უჭირს. ამიტომ გირჩევთ, უკეთ დააკვირდეთ ბავშვს და, თუ ჯერ კიდევ რწევით, ძუძუთი კვებით ან მსგავსი მეთოდებით აძინებთ, თანდათან უარი თქვათ ამ არასასურველ ჩვევებზე.') WHERE id = '7be3db50-1dd0-41ad-aa34-ad5ba68d390b';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ჯანსაღი ძვლები ბავშვის ჯანმრთელი ცხოვრების საფუძველია. მტკიცე ჩონჩხის ჩამოყალიბება, ჯანსაღი კვების ჩვევები და ცხოვრების წესი გადამწყვეტ როლს ასრულებს, რათა მომავალში ბავშვს ცხოვრების უკეთესი ხარისხი ჰქონდეს. კალციუმი აუცილებელია როგორც კუნთების თავისუფლად მოძრაობისთვის, ისე ორგანიზმში სისხლის მიმოქცევის სათანადო ფუნქციონირებისთვის. ამ თვალსაზრისით, ბავშვის კუნთებისა და ძვლების ჯანმრთელობისთვის ყველაზე მნიშვნელოვანი მინერალი, რა თქმა უნდა, კალციუმია. ძვლებში საკმარისი რაოდენობის კალციუმის დაგროვება ძირითადად სიცოცხლის პირველი 20 წლის განმავლობაში ხდება. თუმცა ეს პროცესი ჩვილობის პერიოდში განსაკუთრებით სწრაფად მიმდინარეობს, შემდეგ კი მისი ტემპი თანდათან მცირდება. ამიტომ ძალიან მნიშვნელოვანია, რომ ბავშვმა საკვებიდან საკმარისი რაოდენობის კალციუმი მიიღოს. დედის რძის ან ადაპტირებული ნარევის გარდა, კალციუმის მისაღებად მნიშვნელოვანია ბავშვის რაციონში კეფირის, იოგურტის, კარაქის, ბოსტნეულისა და ხილის სათანადო ბალანსის დაცვა.') WHERE id = 'b5d04c21-7460-44fc-9948-e2c4d43a3411';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ ეტაპზე თქვენი ბავშვი შესაძლოა ჯერ კიდევ ვერ იყენებდეს სრულად გააზრებულ სიტყვებს. მიუხედავად ამისა, როცა თქვენთვის რაიმეს თქმა სურს, უკვე ახერხებს მიზნის მიღწევას. ბავშვს, რომლის გონებრივი განვითარებაც მნიშვნელოვნად დაჩქარდა, შეუძლია მიგანიშნოთ, რომ ბედნიერია, ან მარტივად გაგაგებინოთ, რომ რაღაც არ სურს. ზოგჯერ ამას ყვირილით აკეთებს, ზოგჯერ კი ჩურჩულის მსგავსი ბგერებით. ამ პერიოდში ბავშვი ცდილობს ლექსიკური მარაგის გაფართოებას და თქვენი ნათქვამის უფრო მკაფიოდ გაგებას. ამ განვითარების ხელშესაწყობად, როცა ბავშვი რაიმეს გთხოვთ, შეგიძლიათ მაშინვე მიცემის ნაცვლად ჰკითხოთ: "წყალი გინდა?", "გინდა, სათამაშო მოგაწოდო?". ამ გზით ბავშვს დაეხმარებით, უკეთ გაარჩიოს ყოველდღიურ ცხოვრებაში ხშირად გამოყენებული საგნების სახელები. სიტყვების მნიშვნელობის უკეთ გასაგებად სასარგებლო იქნება ისიც, თუ ბავშვს სთხოვთ, რაიმე მოგიტანოთ.') WHERE id = '170d06eb-e49e-4fd4-a248-7ff0e64baa15';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'შესაძლოა, ამის დაჯერება გიჭირდეთ, მაგრამ თქვენმა ბავშვმა გარე სამყაროში ცხოვრების პირველი წელი უკვე დაასრულა. მიუხედავად იმისა, რომ იცით, ჯერ კიდევ დაუცველია, დროა, ზედმეტად მფარველ ქცევაზე უარი თქვათ. გადაჭარბებულმა მზრუნველობამ შეიძლება მომავალში გამოიწვიოს ის, რომ პრობლემის გადაჭრის გზის ძიების ნაცვლად ბავშვმა ტირილით დაიწყოს დახმარების მოლოდინი. სირთულის წარმოქმნისას ის შესაძლოა კვლავ თქვენგან ელოდებოდეს დახმარებას და თვალებში შემოგხედოთ. თუმცა არ უნდა ჩაერიოთ მანამ, სანამ ბავშვს სირთულესთან დამოუკიდებლად გამკლავების შესაძლებლობას არ მისცემთ. მაგალითად, კარგი დასაწყისი იქნება, თუ ყოველი დაცემისას მაშინვე არ წამოაყენებთ და ამის ნაცვლად თავად წამოდგომას წაახალისებთ. ამ ასაკში შეძენილი ჩვევები უკვე იწყებს იმ პიროვნების ჩამოყალიბებას, რომელიც ბავშვს მთელი ცხოვრების განმავლობაში გაჰყვება.') WHERE id = 'f135783e-e842-4807-b9fe-4cad5e477cf1';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვს ამ თვემდე უკვე შეძენილი აქვს მრავალი ნატიფი და მსხვილი მოტორული უნარი, ამ თვეშიც კი ახალ უნარებს აითვისებს. მარტივად რომ ვთქვათ, მოტორული განვითარება ბავშვის მიერ მოძრაობის უნარის შეძენაა. ამისთვის მან გონების დახმარებით კუნთების მოძრაობები კოორდინირებულად უნდა მართოს. მსხვილი მოტორული უნარები კუნთების დიდი ჯგუფების მუშაობას ეფუძნება. მათ, რა თქმა უნდა, რეფლექსები კი არა, გონება უნდა აკონტროლებდეს. ნატიფი მოტორული უნარები კი ბავშვის მიერ კუნთების მცირე ჯგუფების მოძრაობის უნარია. მასში ძირითადად ხელებისა და თითების მოძრაობები შედის. მაგალითად, ამ თვიდან ბავშვს შეუძლია, სასურველი საგანი საჩვენებელი თითით გაჩვენოთ. მას შეუძლია მარტივად მოსაჭიდი საგნების დახმარებით ფეხზე წამოდგეს. რადგან უკვე შეუძლია თითების ცალ-ცალკე გამოყენება, შეუძლია კოვზის ხმარებაც დაიწყოს. მიუხედავად იმისა, რომ ამ ეტაპზე კოვზს ჯერ კიდევ მოუქნელად იყენებს, ბავშვი უკვე სწავლობს მის დანიშნულებას. ამიტომ ბავშვს მოტორული უნარების განვითარების შესაძლებლობა უნდა მისცეთ, სწავლის პროცესში ცალკეულ პიროვნებად აღიქვათ და ის საქმეები, რომელთა შესრულებაც თავად შეუძლია, დამოუკიდებლად გააკეთებინოთ.') WHERE id = '0fd161d0-cd50-4708-86e8-1b252aeca43a';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ყურის ანთება ბავშვებში ერთ-ერთი ყველაზე გავრცელებული პრობლემაა. ამ მდგომარეობამ შეიძლება ბავშვს ყურის ტკივილი და მოუსვენრობა გამოიწვიოს. იმის დასადგენად, აქვს თუ არა ბავშვს ყურის ანთება, ძალიან მნიშვნელოვანია მისი ნიშნების ცოდნა. თუ ბავშვს აღენიშნება მოუსვენრობა, ტირილი, სიცხე, ყურიდან გამონადენი ან ჯდომისას წონასწორობის შენარჩუნება უჭირს, შესაძლოა, საჭირო იყოს, რაც შეიძლება მალე დაუკავშირდეთ ექიმს. ასევე, ბავშვის მიერ ყურის გამუდმებით მოქაჩვა ან ყურზე ხელის მოკიდება ყურის ინფექციის ერთ-ერთი ყველაზე გავრცელებული ნიშანია. ბავშვის ყურის მტკივნეული ანთებისგან დასაცავად სათანადო ყურადღება უნდა მიაქციოთ ძუძუთი კვებას ან ხელოვნურ ნარევს. გარდა ამისა, დამატებითი კვებისას უპირატესობა უნდა მიანიჭოთ მინერალებითა და ვიტამინებით მდიდარ საკვებს, რომელიც ბავშვის იმუნიტეტს გააძლიერებს. არ უნდა გადადოთ გეგმური ვაქცინაცია და ბავშვი უნდა მოარიდოთ მეტისმეტად ხმაურიან გარემოსა და თამბაქოს კვამლს.') WHERE id = '5293d4ac-e8d7-4284-a254-315f58215b5f';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის ფიზიკური და გონებრივი განვითარებისთვის ძალიან მნიშვნელოვანია, როგორ იკვებება ის და როგორი კვების რეჟიმი აქვს. ყოველი კვებისას ბავშვს სჭირდება როგორც დედის რძე, ისე მყარი საკვები. თუ დედის რძე არ არის, ხელოვნური კვება უნდა გაგრძელდეს. ამ თვის განმავლობაში ბავშვის მიერ მიღებული მყარი საკვების რაოდენობა 3 ჩაის ჭიქას არ უნდა აღემატებოდეს. ამჟამად თქვენი ბავშვის კუჭის მოცულობა 230-250 ml-ია, თუმცა ეს იმას არ ნიშნავს, რომ ის ძალიან დიდ ულუფებს შეჭამს. ზოგიერთ შემთხვევაში ნორმალურია, თუ ბავშვი გარკვეული პერიოდის განმავლობაში დამატებით საკვებზე უარს ამბობს. თუმცა, თუ ეს მდგომარეობა მე-8 თვიდანაც გაგრძელდება, შესაძლოა სპეციალისტის დახმარება დაგჭირდეთ. თუ თქვენს ბავშვს ასეთი რამ ემართება, შეგიძლიათ ჯერ მცირე რაოდენობით დამატებითი საკვები მისცეთ, შემდეგ კი რძე დაალევინოთ ან ძუძუთი გამოკვებოთ. ცოტა ხნის შემდეგ შეგიძლიათ კვლავ მისცეთ მცირე რაოდენობით დამატებითი საკვები, რათა ბავშვი თანდათან შეაჩვიოთ შერეულ კვებას.') WHERE id = 'c996cd60-4f83-4508-84b8-0749f1791d8f';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის ვაქცინაციის კალენდრის მიხედვით, ამ თვეში არცერთი აცრა არ არის დაგეგმილი. თუმცა, ბავშვის ზოგადი მდგომარეობის შესაფასებლად ექიმმა შეიძლება გეგმურ შემოწმებაზე დაგიბაროთ. ამ ასაკში მოსალოდნელია, რომ თავის გარშემოწერილობა გარკვეულ სტანდარტულ დიაპაზონში იყოს, თუმცა სიმაღლისა და წონის შემთხვევაში ასეთი ზუსტი საზღვრები არ არსებობს. ბავშვების სიმაღლისა და წონის მაჩვენებლები შეიძლება მნიშვნელოვნად განსხვავდებოდეს მათი განვითარების, გენეტიკისა და სქესის მიხედვით. მაგალითად, ჩვეულებრივ, ბიჭები გოგოებთან შედარებით უფრო მძიმეები და მაღლები არიან. 11 თვის ასაკიდან ბავშვის წონა შეიძლება 7000 გრამიდან 11.000 გრამამდე, ხოლო სიმაღლე 65 სმ-დან 82 სმ-მდე მერყეობდეს. ამ მაჩვენებლების ყველაზე დაბალ ან ყველაზე მაღალ ზღვარზე ყოფნა არ ნიშნავს, რომ თქვენს ბავშვს განვითარების პრობლემა აქვს. ასევე, ზოგიერთი გადატანილი დაავადების ან ნაადრევი დაბადების შემთხვევაში ექიმებმა შეიძლება ოდნავ დაბალი მაჩვენებლებიც ნორმალურად მიიჩნიონ.') WHERE id = '96a6abff-366a-4a26-9826-e1f53726a843';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ძროხის რძე, კვერცხი, არაქისი, ხორბალი და თევზის ზოგიერთი სახეობა ბავშვებში ხშირად გავრცელებულ საკვებ ალერგიებს იწვევს. კვერცხზე ალერგია ძროხის რძეზე ალერგიის შემდეგ ბავშვებში ერთ-ერთი ყველაზე გავრცელებული საკვები ალერგიაა. ამ ტიპის ალერგია ბავშვის ორგანიზმში მრავალგვარი სიმპტომით შეიძლება გამოვლინდეს. არაქისზე ალერგიაც ბავშვებში ხშირად გვხვდება. ამასთანავე, არაქისზე ალერგიის მქონე ბავშვებს შესაძლოა ზოგადად პარკოსნებზეც ჰქონდეთ ალერგია. ხორბალზე ალერგიას ხშირად გლუტენის აუტანლობაში ურევენ, თუმცა ეს ორი განსხვავებული მდგომარეობაა. ამ ტიპის ალერგია ზოგიერთ ბავშვს შეიძლება ჰქონდეს, მაგრამ, ჩვეულებრივ, 3 წლის ასაკამდე სრულად ქრება. თევზზე ალერგია კი, სხვა ტიპის ალერგიებისგან განსხვავებით, გარკვეული დროის შემდეგ არ ქრება — არსებული მონაცემების მიხედვით, ის მთელი სიცოცხლის განმავლობაში გრძელდება. ორაგული და თინუსი თევზზე ალერგიის გამომწვევ ყველაზე გავრცელებულ სახეობებს მიეკუთვნება. თუ თქვენ ან თქვენს მეუღლეს ჩამოთვლილთაგან რომელიმე ალერგია გაქვთ, ამის შესახებ აუცილებლად უნდა აცნობოთ თქვენს ექიმს და ბავშვის კვებას განსაკუთრებული ყურადღება მიაქციოთ.') WHERE id = '4a785b8e-be1a-4a99-b508-d2a08ac29f86';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენს ბავშვს, სავარაუდოდ, დაბადების დღიდანვე თქვენთან ერთად სძინავს. შესაძლოა, გაინტერესებთ, როდის უნდა გადაიყვანოთ ის ცალკე ოთახში. სინამდვილეში, ბავშვის ცალკე ოთახში გადაყვანა მკაცრად განსაზღვრული ვადების მქონე პროცესი არ არის. შესაძლოა, თავადაც ჯერ არ გინდათ მისგან განცალკევებით ძილი. თუმცა სპეციალისტები გირჩევენ, ეს პროცესი ძალიან არ გააჭიანუროთ. როგორც ყველა ახალი ჩვევის შემთხვევაში, არც ცალკე ძილის ჩვევის გამომუშავება იქნება აუცილებლად მარტივი. ცალკე ძილის უნარის დროულად შეძენა ერთ-ერთი ფაქტორია, რომელიც მომავალში ბავშვის პიროვნულ განვითარებაზე დადებითად აისახება. ამიტომ, თუ მის ცალკე ოთახში გადაყვანაზე ფიქრობთ, შეგიძლიათ ეს პროცესი ნელ-ნელა უკვე დაიწყოთ. მთავარია, ეტაპობრივად იმოქმედოთ, რათა ბავშვისთვის ტრავმული ვითარება არ შეიქმნას.') WHERE id = 'ca8c37f8-65b8-4e4c-a7a3-3378e6f4aec7';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'დაბადების დღისთვის მზადება უკვე დაიწყეთ? 😊 ბავშვთან ერთად გატარებული პირველი წელი თითქმის დასრულდა. ამიტომ, თუ მისი დაბადების დღის აღსანიშნავად თქვენთვის სასურველი წვეულების მოწყობას აპირებთ, გირჩევთ, მზადება ახლავე დაიწყოთ. ამისთვის, უპირველეს ყოვლისა, ყველაფერი წინასწარ და გეგმაზომიერად უნდა მოაწყოთ. დასაწყისშივე შეგიძლიათ განსაზღვროთ, რა თანხის გამოყოფას აპირებთ დაბადების დღის წვეულებისთვის. ბაზარზე დაბადების დღის გაფორმებისთვის უამრავი განსხვავებული სტილისა და ნებისმიერი ბიუჯეტისთვის შესაფერისი პროდუქტი არსებობს. სწორი დაგეგმვით შეძლებთ, ბიუჯეტს არ გადააჭარბოთ და ამავდროულად ისეთი დაბადების დღე მოაწყოთ, რომელიც ნამდვილად მოგეწონებათ. ასევე ძალიან გამოგადგებათ სტუმრების სიის შედგენა, რათა მარტივად გამოთვალოთ შესაძენი პროდუქტებისა და მოსამზადებელი კერძების ხარჯები.') WHERE id = 'd15257f7-39ad-4735-966b-96fe4a154fa1';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვს დიდი დრო სჭირდება ხელისა და თვალის კოორდინაციის სრულად ასათვისებლად. ამიტომ ის თვალებსა და ხელებს თითქოს ერთმანეთისგან დამოუკიდებლად იყენებს — შეიძლება შეხედვის გარეშე შეეხოს ან შეხების გარეშე მხოლოდ უყუროს საგნებს. ამ ე.წ. პასიურ პერიოდში ბავშვს ჯერ არ ესმის, რომ ყურებისა და შეხების შეთანხმებას კოორდინაცია სჭირდება. ამ კოორდინაციის განვითარება ბავშვისთვის ერთ-ერთი ყველაზე რთული უნარია. მისი წვრილი მოტორიკისა და ხელისა და თვალის ეფექტური კოორდინაციის გასავითარებლად შეგიძლიათ რამდენიმე აქტივობა შესთავაზოთ. მაგალითად, შეგიძლიათ უყიდოთ სათამაშოები, რომლებსაც ხელით უბიძგებს, ერთად ითამაშოთ ბურთით ან სთხოვოთ, სათამაშოების კალათიდან რომელიმე სათამაშო მოგიტანოთ. მთავარია, ბავშვის განვითარების დონის შესაბამისი თამაშები შეარჩიოთ და მას საკუთარი შესაძლებლობების რწმენა და წარმატების განცდა ჩამოუყალიბოთ.') WHERE id = 'c4276da3-ca88-407e-9c07-409f5af9f487';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის ტერფების ჯანმრთელობისთვის ძალიან მნიშვნელოვანია სწორად შეარჩიოთ ფეხსაცმელი და მისი ზომა. ამ ეტაპზე ბავშვის კუნთები და ძვლები ჯერ კიდევ ვითარდება, ტერფები კი ძირითადად ხრტილოვანი ქსოვილისგან შედგება. ვინაიდან ხრტილოვანი ქსოვილი ძვალზე უფრო მგრძნობიარეა, არასწორად შერჩეულმა ფეხსაცმელმა შეიძლება ბავშვის ტერფის ფორმა ადვილად დააზიანოს. ამიტომ ფეხსაცმლის შეძენისას ყურადღება მიაქციეთ, რომ ის ბავშვს არ უჭერდეს და თითების წინ დაახლოებით 1 სმ თავისუფალი ადგილი რჩებოდეს. შერჩეული ფეხსაცმელი უნდა იყოს რბილი, მოქნილი და გაწელვისადმი გამძლე. ეს თვისებები მნიშვნელოვანია, რათა ბავშვმა წონასწორობის შენარჩუნება მარტივად შეძლოს. ასევე, ფეხსაცმელი მოსინჯვის გარეშე არ შეიძინოთ და ჩაცმისას მოერიდეთ ისეთ მოძრაობებს, რომლებმაც შეიძლება ბავშვს ტკივილი მიაყენოს. ფეხსაცმლის გახდის შემდეგ შეამოწმეთ ბავშვის ტერფები და დარწმუნდით, რომ მათზე მოჭერის კვალი არ არის.') WHERE id = 'f60eb2d0-e0ee-46f9-817c-d2b511759488';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ ეტაპზე ბავშვის ორგანიზმში მოხვედრილი რკინის რაოდენობას დიდი მნიშვნელობა ენიჭება. რკინა — ორგანიზმში ჟანგბადის გადასატანად აუცილებელი მინერალი — ბავშვის იმუნური სისტემის გაძლიერებას უწყობს ხელს. ძლიერი იმუნიტეტის მქონე ბავშვი ადვილად არ ავადდება, რაც ჯანსაღი განვითარების უწყვეტობისთვის ძალიან მნიშვნელოვანია. გასული ერთი წლის განმავლობაში თქვენი ბავშვი საოცრად გაიზარდა. ამ სწრაფი ზრდის გამო რკინაზე გაზრდილი მოთხოვნილება შესაძლოა უკვე გამოვლინდეს. რკინის დეფიციტის თავიდან აცილების საუკეთესო გზა, რა თქმა უნდა, სწორი კვებაა. თქვენი ბავშვისთვის, რომელსაც უკვე თითქმის ყველა საკვების მიღება შეუძლია, სრულფასოვანი კვება რკინის საკმარის მარაგს უზრუნველყოფს. თუმცა ანემიისა და განვითარების შეფერხების თავიდან ასაცილებლად სპეციალისტებმა შესაძლოა ამ პროცესის დამატებით მხარდაჭერა გირჩიონ. თუ ანალიზების შედეგებით ამის საჭიროება გამოვლინდება, ექიმის მიერ რეკომენდებული რკინის პრეპარატის რეგულარული მიღება თქვენი ბავშვისთვის ძალიან სასარგებლო იქნება.') WHERE id = '73aac64a-d992-45f0-aa07-1a1807c3ef3b';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ თქვენი ბავშვი ღამით ხშირად იღვიძებს, იცოდეთ, რომ დედების უმეტესობაც იმავე მდგომარეობაშია. სიცოცხლის პირველ წელს ბავშვების ღამით გაღვიძება ძალიან გავრცელებული მოვლენაა. პრობლემის მიზეზის აღმოჩენის შემდეგ მისი მოგვარებაც უფრო ადვილი ხდება. გაღვიძების ყველაზე ხშირ მიზეზებს შორის შიმშილი და სველი საფენია. თუ ფიქრობთ, რომ მიზეზი სწორედ ეს არის, პრობლემის მოგვარება მარტივია. თუმცა, თუ თქვენი ბავშვი ამ ორი ფიზიკური საჭიროების გარდა სხვა მიზეზებით იღვიძებს, გირჩევთ, გადახედოთ თქვენს ჩვევებს. მაგალითად, თუ ბავშვს რწევით ან ძუძუთი კვებით დაძინებას მიაჩვიეთ, ის ძილს ამ ჩვევებს უკავშირებს და ყოველი გაღვიძებისას მათ გამეორებას ითხოვს. დღისა და ღამის ძილს შორის ბალანსის დარღვევამაც შეიძლება გამოიწვიოს ბავშვის ხშირი გაღვიძება ღამით. მოსალოდნელია, რომ ბავშვს, რომელსაც დღისით ძალიან ცოტა ან მეტისმეტად ბევრი სძინავს, ღამის ძილიც დაერღვევა. ამიტომ ძილის რეჟიმი და დღისა და ღამის ძილს შორის ბალანსი სწორად უნდა დაარეგულიროთ.') WHERE id = '23e7e900-4096-428a-bdc0-1aa6763f7f56';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის ნატიფი მოტორული უნარები უკვე მნიშვნელოვნად განვითარდა და ამის წყალობით მას თითების ეფექტურად გამოყენება შეუძლია. განსაკუთრებით საჩვენებელი და ცერა თითების გამოყენებით შეუძლია სათამაშოების მწკრივად დალაგება, ერთმანეთზე დაწყობა და ერთმანეთში მოთავსებაც მოსწონს. რამდენიც უნდა ეცადოთ, ჩაცმისთანავე შეიძლება წინდები გაიხადოს. თუ ამას მკაცრად არ დაუშლით, ასეთი ქცევა სიჯიუტეში არ გადაიზრდება და შესაძლოა დაინახოთ კიდეც, როგორ ცდილობს ბავშვი გახდილი წინდის ხელახლა ჩაცმას. ამ განვითარების დასაჩქარებლად ბავშვს უნდა დაეხმაროთ და საკუთარი მოძრაობების კონტროლში მიმართულება მისცეთ. მაგალითად, რადგან მან ხელების, ფეხებისა და თითების მიზანმიმართულად გამოყენება დაიწყო, სახლში მუდმივად წინდები არ უნდა ჩააცვათ. ხელებისა და ფეხების სრულად შეგრძნება ბავშვის კუნთებისა და უნარების განვითარებას მნიშვნელოვნად შეუწყობს ხელს.') WHERE id = '5a5a24f6-dfde-4cd0-9700-1725829fdabb';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი აცნობიერებს, რომ სახლში ყურადღების ცენტრშია და ეს ძალიან ახარებს. როდესაც მის მიმართ ყურადღებას არ იჩენთ, მის მისაპყრობად შეიძლება უცნაური მოძრაობებიც კი გააკეთოს. ყველა ბავშვის მსგავსად, თქვენს პატარასაც სჭირდება მშობლებისა და გარშემო მყოფების ყურადღება. მისთვის ყურადღების მიღება და მისი საჭიროება შეიძლება სიყვარულისა და პატივისცემის თვალსაჩინო გამოხატულება იყოს. ბავშვისთვის, რომელსაც აბსტრაქტული და კონკრეტული ცნებები ჯერ სრულად არ აქვს გააზრებული, ეს ნორმალურია. ამასთანავე, ბავშვის ყურადღების საჭიროების სათანადოდ დაკმაყოფილება დაეხმარება, თავი უსაფრთხოდ და ღირებულად იგრძნოს. ეს კი ერთ-ერთი უმნიშვნელოვანესი ფაქტორია იმისთვის, რომ მომავალში ფსიქოლოგიურად უფრო ჯანმრთელ ზრდასრულად ჩამოყალიბდეს.') WHERE id = 'a5cfafcf-5098-4fd7-b06b-9e5991ba4455';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'არსებობს მრავალი კვლევა, რომლის თანახმადაც საწოვარას გამოყენება, განსაკუთრებით სიცოცხლის პირველი ერთი წლის განმავლობაში, ჩვილის უეცარი სიკვდილის სინდრომის რისკს ამცირებს. თუმცა, თუ ბავშვისთვის საწოვარას იყენებთ, მისი შერჩევისა და გამოყენების ხანგრძლივობის შესახებ სათანადო ინფორმაცია უნდა გქონდეთ. ყველაზე მნიშვნელოვანი, რაც უნდა გაითვალისწინოთ, ბავშვის ასაკი და განვითარების ეტაპია, რადგან ასაკისა და განვითარების შეუსაბამო საწოვარამ შეიძლება პირის ღრუსა და კბილების სტრუქტურა ადვილად დააზიანოს. ასევე დიდი ყურადღება უნდა მიაქციოთ, რომ საწოვარა BPA-ს შემცველი პლასტმასისგან არ იყოს დამზადებული. კბილების ამოსვლის პერიოდში კი პლასტმასის საწოვარას ნაცვლად შეგიძლიათ რეზინის საწოვარა გამოიყენოთ, რათა ბავშვმა კბენის მოთხოვნილება დაიკმაყოფილოს და დამშვიდდეს. დღის განმავლობაში უპირატესობა შეგიძლიათ მიანიჭოთ ნახვრეტებიან პლასტმასის საწოვარას, რომელიც ბავშვს უფრო თავისუფლად სუნთქვაში ეხმარება.') WHERE id = '29360a2f-1179-4451-8558-fbdf819c9334';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის განვითარების კვალდაკვალ, ამ თვეში მისი ძილის რეჟიმი შეიძლება ისე შეიცვალოს, რომ თქვენ ნაკლებად დაგღალოთ. ჩვეულებრივ, დღის ძილი ხანმოკლე ხდება, ღამის ძილი კი ხანგრძლივდება. დღის განმავლობაში ძილის სიხშირე შეიძლება 2-3-ჯერიდან 1-ჯერამდე შემცირდეს, ხოლო 60-წუთიანი ძილი 15-20 წუთამდე შემოკლდეს. ამ გარდამავალ პერიოდში ბავშვი დღისით შესაძლოა გარკვეული ხნით მოუსვენარი იყოს და ტირილის შეტევებიც ჰქონდეს. ახალი რეჟიმის ჩამოყალიბებაში დასახმარებლად შეგიძლიათ ღამისა და დღის ძილს შორის საათობრივი ბალანსი დაარეგულიროთ. მაგალითად, თუ ბავშვი დილის 6 საათზე იღვიძებს და საღამოს 8 საათზე იძინებს, დღის ძილის დაახლოებით შუადღის 1 საათზე დაგეგმვა დაბალანსებულ რეჟიმს შექმნის. თუ თავდაპირველად გადაღლილობის გამო ღამით დაძინება უჭირს, თბილი აბაზანა მთელი ღამის განმავლობაში უწყვეტად დაძინებაში დაეხმარება.') WHERE id = '29be8b55-c3ca-46ad-9c7e-b1ccdcfeab74';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენს ბავშვს უკვე შეუძლია დამოუკიდებლად ჭამა. ამ დროს ყველაზე შემაშფოთებლად საკვების გადაცდენისა და სასუნთქი გზების დახშობის საფრთხე ჟღერს. თუმცა ბოლო წლებში ჩატარებულმა კვლევებმა აჩვენა, რომ ბავშვის მიერ დამოუკიდებლად ჭამის მეთოდი კვების კლასიკურ მეთოდთან შედარებით უფრო უსაფრთხოა. ამიტომ, სწორად გამოყენებისას ბავშვის დამოუკიდებლად კვება საკმაოდ დაბალი რისკის მქონე და უსაფრთხო მეთოდია. ამის მთავარი მიზეზი, რა თქმა უნდა, ისაა, რომ პროცესს მთლიანად თქვენ კი არა, თავად ბავშვი აკონტროლებს. საკვების პირში მოთავსების, ღეჭვის, ენის მოძრაობით ხახისკენ მიწევის და გადაყლაპვის ეტაპებს ყველაზე უკეთ თვითონ ბავშვი არეგულირებს. ამ ასაკში სასუნთქი გზების დახშობის რისკის შემცირების კიდევ ერთი მიზეზი ისაა, რომ ბავშვის ხახა უფრო წინ მდებარეობს, ენა კი — შუაში. ამიტომ, თუ საკვების ნაჭერი იმდენად დიდია, რომ ბავშვი ვერ ყლაპავს, ღებინების რეფლექსის წყალობით მას ადვილად უკან გამოაგდებს.') WHERE id = '8de7c43c-84d8-440a-a1bf-7f758e886f0f';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ თვიდან შეიძლება შეამჩნიოთ, რომ თქვენი ბავშვის გარშემო ბევრი მისი თანატოლი, შესაძლოა თავად თქვენი პატარაც, სიარულს იწყებს. თუ თქვენი ბავშვი ჯერ არ დადის, გახსოვდეთ, რომ სიარულის სავარჯიშოდ მას ჯერ კიდევ დაახლოებით 6 თვე აქვს. ბავშვები, რომლებმაც გვიან დაიწყეს ჯდომა, გადაბრუნება და ხოხვა, განვითარების ეტაპების შესაბამისად, შესაძლოა სიარულსაც გვიან იწყებდნენ. თუმცა ამ ეტაპებზე ჩამორჩენა რომც არ შეინიშნებოდეს, შესაბამისი გამოკვლევების ჩატარების შემთხვევაში შეგიძლიათ 18 თვემდე მშვიდად დაელოდოთ. ბავშვის სიარულისთვის მზადყოფნაზე მიუთითებს ის, რომ საყრდენზე ჩაჭიდებით ფეხზე დგება და მცირე ხნით მაინც წონასწორობის შენარჩუნება შეუძლია. მშობლების ზედმეტად მზრუნველმა ქცევამ ეს პროცესი შეიძლება რამდენიმე თვით შეაფერხოს. ამიტომ, თუ ბავშვს დაზიანებისა და წაქცევის შიშით უმეტესად ხელში ატარებთ, გვიან დაწყებული სიარულის ალბათობა შეიძლება კიდევ უფრო გაიზარდოს.') WHERE id = '52890d53-8d1e-42df-9458-72c4f9145d95';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ყბაყურა (ეპიდემიური პაროტიტი) ვირუსებით გამოწვეული დაავადებაა. ის ადვილად გადადის საუბრის, ცემინების, კოცნის ან ხველის დროს გამოყოფილი ნერწყვის მცირე წვეთებით. ეს ვირუსული ინფექცია აზიანებს სანერწყვე ჯირკვლებსა და ყბის გასწვრივ მდებარე ყბაყურა ჯირკვლებს. ჯანმოს მონაცემებით კი, წითელა უკიდურესად გადამდები და მძიმე დაავადებაა, რომელიც ყოველწლიურად მილიონობით აუცრელი ადამიანის სიკვდილს იწვევს. კანზე გამონაყარის გამომწვევი ეს დაავადება აუცრელი ჩვილებისთვის საფრთხეს წარმოადგენს. წითურაც ვირუსული წარმოშობის გადამდები დაავადებაა, რომელსაც ლაქოვანი და ამობურცული გამონაყარი ახასიათებს. აღნიშნული დაავადებები ადამიანიდან ადამიანს ადვილად გადაეცემა. თუმცა დღეს ვაქცინების დამცველობითი ეფექტი საკმაოდ მაღალია, ამიტომ გირჩევთ, აცრების კალენდარი დაიცვათ.') WHERE id = 'ec8978cf-052f-4504-a3c1-e0f1b9dc401e';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მიუხედავად იმისა, რომ თქვენი ბავშვი უკვე 12 თვისაა, დღის განმავლობაში მისი აქტიურობა ადრინდელთან შედარებით გაიზარდა, ამიტომ დღის ძილი კვლავ მნიშვნელოვანია. ამ ეტაპზე ბავშვისთვის დღის განმავლობაში საშუალოდ 1-ჯერ, 1-2 საათით დაძინება საკმარისი იქნება. დღის ძილის ნაკლებობამ ან სიჭარბემ შეიძლება ღამის ძილის რეჟიმსა და ხარისხზე იმოქმედოს, ამიტომ მნიშვნელოვანია წონასწორობის შენარჩუნება. თუ ბავშვისთვის რეჟიმი უკვე ჩამოაყალიბეთ, წინა თვეებთან შედარებით მისი ღამის ძილი უფრო მოწესრიგებული იქნება. ბავშვს, რომელსაც ღამით კვება აღარ სჭირდება, შესაძლოა უწყვეტად 12 საათამდე ეძინოს. ბავშვის ფიზიკური განვითარებისა და გონებრივი აქტივობისთვის აუცილებელია, რომ მას ღამით უწყვეტად ეძინოს. ამიტომ მის გასაღვიძებლად და გამოსაკვებად საჭიროება არ არსებობს. თუმცა, თუ თქვენი ბავშვი კვლავ იღვიძებს ღამით შიმშილის გამო, შესაძლოა ექიმის რეკომენდაციების გათვალისწინებით თანდათან გადააჩვიოთ ამ ჩვევას.') WHERE id = '21b97e51-16ae-47ca-a3b8-788c861f7d61';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ თვიდან იწყება პერიოდი, როდესაც ბავშვის ფიზიკური განვითარება მისი ცხოვრების პირველ წელთან შედარებით შენელდება. ამიტომ, უმეტეს შემთხვევაში, ბავშვის მიერ მცირედ წონაში მომატება ან ზოგიერთ თვეში წონის საერთოდ არმომატებაც კი ნორმალურად შეიძლება ჩაითვალოს. მე-12 თვეში ბავშვის წონა შეიძლება საკმაოდ ფართო, 7100-12500 გრამის ფარგლებში მერყეობდეს. ჩვენს ქვეყანაში არსებული მონაცემების მიხედვით, 12 თვის ბავშვის საშუალო წონა დაახლოებით 9600 გრამია. ამ თვეში ბავშვის სიმაღლე შეიძლება 64-81 სმ-ის ფარგლებში იყოს, ხოლო საშუალო მაჩვენებელი დაახლოებით 75 სმ-ია. უნდა გახსოვდეთ, რომ ყველა ეს მაჩვენებელი შეიძლება განსხვავდებოდეს სქესის, დაბადებისას წონის, გენეტიკისა და განვითარების თავისებურებების მიხედვით. ამასთანავე, ნაადრევად დაბადებული ბავშვებისთვის ეს რიცხვები სტანდარტულ კრიტერიუმს არ წარმოადგენს. თუ ფიქრობთ, რომ თქვენი ბავშვის მაჩვენებლები აღნიშნულ დიაპაზონებში არ ჯდება, ყველაზე ზუსტ ინფორმაციას ექიმთან კონსულტაციის შედეგად მიიღებთ.') WHERE id = '4117c981-d400-493d-b227-ec432d7ba8ac';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის მიერ გარე სამყაროში ცხოვრების პირველი წლის დასრულება მნიშვნელოვანი პერიოდია, როდესაც ინდივიდუალიზაციის საფუძვლები ყალიბდება. ინდივიდუალიზაცია გულისხმობს ბავშვის მიერ იმ თვისებების გაცნობიერებას, რომლებიც მას სხვა ადამიანებისგან განასხვავებს. ეს პროცესი ბავშვის მიერ საკუთარი იდენტობის ჩამოყალიბებად განიხილება. მიუხედავად იმისა, რომ ბავშვი ჯერ კიდევ ძალიან არის თქვენზე მიჯაჭვული და დამოკიდებული, საკუთარი განსხვავებულობის აღქმის დაწყება მისი პიროვნული განვითარების ერთ-ერთი საფუძველია. ამ მხრივ, 12 თვის ასაკში ბავშვი საკუთარი თავის უკეთ გაგებასა და გარემოს უფრო აქტიურად აღქმას იწყებს. ამ პერიოდში, როდესაც თავისუფლების განცდა ჩნდება, ბავშვის ცალკეულ ინდივიდად აღიარება მისი განვითარებისთვის ძალიან მნიშვნელოვანია. ამასთანავე, თქვენი ბავშვი სოციალურად უკვე უფრო აქტიურია, შესაბამისად, მისი ენერგიის საჭიროებაც იმავე პროპორციით გაიზრდება. ამიტომ ბავშვისთვის შესათავაზებელი საკვების კვებითი ღირებულება და სეზონთან შესაბამისობა სათანადოდ უნდა შეარჩიოთ.') WHERE id = '8be39fcb-46bd-46a8-bfbf-0293af3adc49';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის აცრების კალენდარში შეტანილ და ყველაზე მნიშვნელოვან ვაქცინებს შორის ჩუტყვავილას ვაქცინაცაა. ჩუტყვავილა უმეტესად ადრეულ ბავშვობაში გადატანილი, ხშირად ცხელებით მიმდინარე და ძალიან გადამდები დაავადებაა, რომელსაც სითხით სავსე, ქავილის გამომწვევი გამონაყარი ახასიათებს. Varisella zoster (VZV) ვირუსით გამოწვეული ეს დაავადება ერთ-ერთი ყველაზე ადვილად გავრცელებადი ინფექციაა. ამ უკიდურესად გადამდები დაავადების ერთადერთი წყარო ადამიანია. დაავადება ვირუსით ინფიცირებული ადამიანისგან ადვილად გადადის ჰაერწვეთოვანი გზით ან კანზე არსებული სითხით სავსე ბუშტუკების შიგთავსთან შეხებით. გადამდებლობის პერიოდი გამონაყარის გაჩენამდე 1-2 დღით ადრე იწყება და ყველა გამონაყარის ქერქით დაფარვამდე გრძელდება. განსაკუთრებით ოჯახში ახლო კონტაქტის დროს ინფიცირების ალბათობა 80-90%-მდე აღწევს. ჩუტყვავილა ჩვენს ქვეყანაშიც ფართოდ არის გავრცელებული და უფრო ხშირად ზამთარსა და გაზაფხულზე გვხვდება. მიუხედავად იმისა, რომ დაავადება ძირითადად 1-9 წლის ბავშვებში გვხვდება, ის შეიძლება მოზარდებსა და ზრდასრულებსაც დაემართოთ. ვაქცინაცია კი ჩუტყვავილასგან დაცვის ყველაზე ეფექტური საშუალებაა. ამიტომ ძალიან მნიშვნელოვანია ბავშვის აცრების კალენდრის დაცვა.') WHERE id = '6005eb52-15af-43d7-bcb9-cf624b6fbca5';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენმა ბავშვმა შესაძლოა უკვე დაიწყოს გარკვეული კვებითი ჩვევების ჩამოყალიბება იმ საკვების საფუძველზე, რომელსაც სთავაზობთ. განსაკუთრებით პირველი 12 თვის დასრულების შემდეგ ბავშვი უკვე მზად არის მრავალი პროდუქტის, მათ შორის ალერგენული საკვების მისაღებად. ეს ნიშნავს, რომ ის უკვე მზადაა ოჯახში მომზადებული კერძებისა და იმ საკვების მისაღებად, რომელსაც თქვენ მიირთმევთ. თუმცა ამ პერიოდში ბავშვს ზოგიერთი საკვების მიმართ შესაძლოა განუვითარდეს მდგომარეობა, რომელსაც "საკვებზე უარის თქმა" ეწოდება. ამასთანავე, ინდივიდუალიზაციის ეტაპზე გადასულმა ბავშვმა შეიძლება თავად მოისურვოს გადაწყვიტოს, როდის და რამდენს შეჭამს. გახსოვდეთ, რომ ადრეულ ასაკში ჩამოყალიბებული ჯანსაღი კვების ჩვევა მთელი ცხოვრების განმავლობაში შესანარჩუნებელ ქცევად იქცევა. ამიტომ გირჩევთ, ბავშვს ჯერ კიდევ არ მისცეთ შეფუთული პროდუქტები, რომლებიც საზიანოდ მიიჩნევა, დაბალი კვებითი ღირებულება აქვს და ცარიელი კალორიების წყაროა.') WHERE id = '28f50db1-faf4-4213-a827-8ee377ef26fc';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'როგორც ყველა ბავშვს, თქვენს პატარასაც არ მოეწონება, როცა ხელს უშლიან ან ზღუდავენ. ამ პერიოდში, როდესაც ბავშვი აქტიურად თამაშობს, მისთვის ხელის შეშლამ შესაძლოა გარკვეული პრობლემები გამოიწვიოს. სამყაროს შეცნობის ეტაპზე ბავშვმა შეიძლება ხშირად აურიოს გარშემო ყველაფერი და ეს ერთგვარ თამაშადაც აქციოს. თუ სახლში არეულობის თავიდან ასაცილებლად ბავშვს მუდმივად შეზღუდავთ, ამან შესაძლოა მასში აგრესიისკენ მიდრეკილება გააჩინოს. ზოგიერთი კვლევის თანახმად, აგრესიული ქცევა უფრო ხშირად შეინიშნება იმ მშობლების შვილებში, რომლებიც ბავშვის მიმართ შეზღუდვას, კრიტიკასა და ხელის შეშლას იყენებენ. ამიტომ ბავშვის ქცევაში მხოლოდ აუცილებლობის შემთხვევაში და სათანადო მეთოდებით უნდა ჩაერიოთ. როდესაც ბავშვი არასასურველად იქცევა, შეგიძლიათ დაელაპარაკოთ და მასთან ურთიერთობა სცადოთ. მიუხედავად იმისა, რომ ბავშვი ჯერ ვერ გიპასუხებთ, ის მიხვდება, რისი თქმა გსურთ.') WHERE id = 'e6a475d2-fe45-454c-a75a-76f9744ef10b';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენს ბავშვს უკვე შეუძლია სათამაშოებს შორის განსხვავებების მკაფიოდ აღქმა. ამიტომ ის სათამაშოებით უფრო გააზრებულად თამაშობს. მაგალითად, ნაცვლად იმისა, რომ ბურთი პირთან მიიტანოს ან ხელში აიღოს და რამდენიმე წუთის განმავლობაში ათვალიეროს, ახლა უკვე შეუძლია დანიშნულებისამებრ გადააგდოს და შემდეგ მის მოსატანად წავიდეს. მან იცის, რომ ბურთამდე მისაღწევად ხელებსა და მუხლებზე ხოხვა დაეხმარება. ამ პერიოდში, როდესაც თითის წვერებით საგნების დაჭერის უნარი მნიშვნელოვნად ვითარდება, თქვენი ბავშვი თითებს მიზანმიმართულად იყენებს. ყველა ეს ახალი უნარი მიუთითებს, რომ ბავშვი აქტიური სწავლის ეტაპზეა და საკუთარ მოქმედებებს ეფექტურად აკონტროლებს. ბავშვის განვითარება შეიძლება შეანელოს ტელევიზორმა, პლანშეტმა და ტელეფონმა, რომლებიც მას ახალი აღმოჩენებისგან ყურადღებას გადაატანინებს. ამიტომ გირჩევთ, ბავშვი კიდევ გარკვეული ხნით მოარიდოთ ასეთ მოწყობილობებს, რომლებმაც შესაძლოა არასასურველი ჩვევა ჩამოუყალიბოს.') WHERE id = '099e9644-c317-463e-9565-cf38395da13a';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'გონებრივი განვითარების წყალობით, თქვენი ბავშვი მიზეზ-შედეგობრივი კავშირის უკეთ გააზრებას იწყებს. მას უკვე შეუძლია, სურვილისამებრ გამოიყენოს გარშემო არსებული ნივთების გადაადგილების უნარი! ეს ჭუჭყიანი ტანსაცმლის კალათის დაცლასაც მოიცავს... 😊 როგორც ყველა ბავშვს, თქვენს პატარასაც ერთ-ერთი ყველაზე საყვარელი საქმიანობა ყველაფრის დაცლაა, რაც სავსეა! ეს შეიძლება იყოს უჯრები, კარადები, ჭუჭყიანი ტანსაცმლის კალათები, თქვენი კოსმეტიკის ჩანთა, მანქანაში არსებული ტანსაცმელი ან სათამაშოების კალათა. ამის მიზეზი ისაა, რომ ბავშვმა უკვე ისწავლა: თავისი მოქმედებით რაღაცის შეცვლა შეუძლია, ხოლო მიღებული შედეგი ახარებს და კიდევ უფრო მეტად უბიძგებს ამის გამეორებისკენ. მიუხედავად იმისა, რომ ბევრი დედისთვის ეს საკმაოდ დამღლელია, უნდა გაცნობოთ, რომ ასეთი მდგომარეობა კიდევ გარკვეული ხნის განმავლობაში გაგრძელდება. თუმცა ამ პერიოდში გირჩევთ, ბავშვს ხელი არ შეუშალოთ. მისთვის ხელის შეშლამ შესაძლოა ახალი რამეების გამოცდისა და სწავლის პროცესი შეანელოს.') WHERE id = 'de5be5b0-43b6-421c-9cf6-60c30a757402';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში, როდესაც ბავშვი ფიზიკურად ვითარდება — ცდილობს ფეხზე დადგომასა და სიარულს — მნიშვნელოვანია იცოდეთ რამდენიმე რამ, რაც მისი მეტყველების უნარის განვითარებას შეუწყობს ხელს. მიუხედავად იმისა, რომ მის მიერ წარმოთქმული ბგერების უმეტესობას ჯერ მნიშვნელობა არ აქვს, ამ ეტაპზე ბავშვი თქვენი საუბრის მოსმენით საკუთარი მეტყველების საფუძველს ქმნის. ამიტომ ძალიან მნიშვნელოვანია, ბავშვის თანდასწრებით სიტყვები ყოველთვის სწორად წარმოთქვათ. საუბრისა და ბგერების წარმოთქმისას ბავშვმა თქვენი პირისა და ენის მოძრაობები უნდა დაინახოს — ეს დაეხმარება მას გაიგოს, როგორ წარმოთქვას აზრიანი ბგერები. მაგალითად, როდესაც ბავშვს საჭმელს უმზადებთ, მოქმედებების თანმიმდევრულად ჩვენება და ახსნა შესაფერის და მეტად ეფექტიან სასწავლო გარემოს ქმნის. ამ ეტაპზე ბავშვისთვის კითხვების ხშირად დასმა მის ყურადღებას უფრო მეტად მიიპყრობს. მიუხედავად იმისა, რომ ჯერ ვერ გიპასუხებთ, მისი აღქმის უნარი უკვე საკმაოდ განვითარებულია და კარგად მიხვდება, რისი თქმა გსურთ.') WHERE id = 'b81a1e32-8dc9-494a-bc85-0cdde994004d';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'არსებობს რამდენიმე ხერხი, რომელთა გამოყენებითაც შეგიძლიათ ბავშვს სიარულის სურვილი გაუძლიეროთ. მთავარია, ყურადღებით დააკვირდეთ, არის თუ არა ბავშვი განვითარების თვალსაზრისით მზად სიარულისთვის. თუ ფიქრობთ, რომ ბავშვი უკვე მზად არის, საყვარელი სათამაშოები პირდაპირ მის გვერდით კი არ დაუდოთ, არამედ ოდნავ მოშორებით, თუმცა მის თვალსაწიერში მოათავსოთ. თუ ბავშვს ყველაფერს, რაც სურს, მუდმივად წინ დაუდებთ, შესაძლოა მოტივაცია შეუმცირდეს და სიარულის საჭიროება აღარ ჰქონდეს. შეგიძლიათ გაამაგროთ ნივთები, რომლებსაც ბავშვი დღის განმავლობაში ეყრდნობა, და საინტერესო საგნების გამოყენებით წაახალისოთ, რომ მათზე დაყრდნობით წამოდგეს. ასევე, ეცადეთ, სიფხიზლის პერიოდში ბავშვი დიდხანს არ იჯდეს და სახლში თუ გარეთ სიარულში ავარჯიშოთ — ეს მას კიდევ უფრო წაახალისებს. გარდა ამისა, სიარულის გასაადვილებლად და ტერფისა და წვივის კუნთების გასაძლიერებლად შეგიძლიათ სახლში ფეხშიშველი სიარულის ნება დართოთ.') WHERE id = '7a1e8c2b-10cc-434b-be5a-358025ea3b29';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ეს თვეები თქვენი ბავშვისთვის სოციალური თვალსაზრისით ყველაზე აქტიური პერიოდის დასაწყისია. ბავშვის სურვილი, დაამყაროს კავშირი გარშემომყოფებთან, ნიშნავს, რომ ის ცდილობს მიბაძოს ყველაფერს, რასაც ხედავს და ისმენს. მაგალითად, თუ ეს გარშემო შეუმჩნევია, შესაძლოა თქვენი ბავშვი უკვე მოიწყინოს ან ატირდეს კიდეც, როდესაც მისთვის საყვარელი ადამიანები მის გვერდით აღარ არიან. სოციალური განვითარების ამ ეტაპზე ბავშვმა შესაძლოა თავის გონებაში შექმნილი განსაკუთრებული ენის გამოყენებაც დაიწყოს. ამ პერიოდში მან შეიძლება ისეთი ძირითადი სიტყვები, როგორებიცაა სათამაშო, წყალი და საჭმელი, სრულიად განსხვავებულად წარმოთქვას. გარდა ამისა, ბავშვის სოციალურ განვითარებაზე ყურადღებით დაკვირვება ძალიან მნიშვნელოვანია სმენის შესაძლო დაქვეითების დროულად გამოსავლენად. თუ ბავშვი უკვე 12 თვისაა და ფიქრობთ, რომ ის ხმებსა და გარეგან გამღიზიანებლებზე არ რეაგირებს, შესაძლოა ექიმთან დაკავშირება დაგჭირდეთ.') WHERE id = '1b7f06dd-c2fb-4278-a493-16339dceb2f1';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბოლო წლებში გაჩნდა ადამიანთა ჯგუფი, რომელიც ამტკიცებს, რომ ზოგადად ვაქცინები, განსაკუთრებით კი წითელას, ყბაყურასა და წითურას საწინააღმდეგო (MMR) ვაქცინა, აუტიზმს იწვევს. გავრცელებული წარმოდგენის საპირისპიროდ, აუტიზმი ერთი კონკრეტული დაავადება არ არის. ეს არის აუტისტური სპექტრის აშლილობის (ასა) სახელით ცნობილი, თავის ტვინის განვითარებასთან დაკავშირებული დარღვევა, რომლის ნიშნებიც ადრეულ ბავშვობაში ვლინდება. ასა-ს დიაგნოზის მქონე ბავშვებში შეინიშნება სოციალურ-კომუნიკაციური სირთულეები, განმეორებადი ქცევები და ინტერესთა შეზღუდული სფერო. მართალია, ასა-ს გამომწვევი მიზეზები ჯერ სრულად დადგენილი არ არის, თუმცა მნიშვნელოვან როლს მრავალი გენეტიკური ფაქტორი და გენებსა და გარემოს შორის ურთიერთქმედება ასრულებს. ჯანმო და სხვა ავტორიტეტული ორგანიზაციები აცხადებენ, რომ ვაქცინებში შემავალი ნივთიერებები ტოქსიკური არ არის არც ჩვილებისთვის, არც ბავშვებისა და არც ზრდასრულებისთვის. იმ ადამიანების მტკიცების საპირისპიროდ, რომლებიც ვაქცინებს აუტიზმს უკავშირებენ, მსოფლიოში ამ საკითხზე მრავალი კვლევა ჩატარდა, თუმცა არცერთ მათგანში არ დადასტურებულა, რომ ვაქცინა უშუალოდ იწვევს აუტიზმს. ამიტომ კიდევ ერთხელ გვსურს შეგახსენოთ, რომ აუცილებელია ბავშვის აცრა და მისთვის შედგენილი ვაქცინაციის კალენდრის დაცვა, რადგან ვაქცინაცია უაღრესად გადამდები და სიცოცხლისთვის საშიში დაავადებებისგან დაცვის ერთადერთი გზაა.') WHERE id = '1d726360-db3e-4087-aa23-4eebeaf883e8';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ თქვენი ბავშვი უკვე ცდილობს დამოუკიდებლობის გამოვლენას და რაიმეს დაუხმარებლად გაკეთებას, ხელი არ უნდა შეუშალოთ. მისმა შეჩერებამ შესაძლოა შეარყიოს საკუთარი თავის რწმენა და ახალი რამის სწავლის სურვილიც დაუკარგოს. ისეთ სიტუაციებში, სადაც ბავშვს საკუთარი თავის დაზიანების საფრთხე არ ემუქრება, გირჩევთ, შორიდან დააკვირდეთ და საჭიროების გარეშე არ ჩაერიოთ. თუმცა სწორი წონასწორობის დაუცველობამ შესაძლოა მომავალში ბავშვის ზედმეტად ჯიუტი ქცევა განაპირობოს. ამიტომ ბავშვის საქმიანობაში ჩაურევლობა არ ნიშნავს, რომ ის სრულიად თავის ნებაზე უნდა მიუშვათ და მეთვალყურეობის გარეშე დატოვოთ. ამ თვეებში ბავშვმა შესაძლოა საკუთარი სურვილების დაკმაყოფილება დაჟინებით და დაუყოვნებლივ მოითხოვოს. ასეთ დროს უნდა ეცადოთ, ლოდინი ასწავლოთ. ბავშვისთვის სასურველი რამის მიღებამდე ლოდინის დრო თანდათან გაზარდეთ და შესაფერის მომენტში უთხარით: „მადლობა, რომ მოიცადე“. ეს ამ პროცესს მნიშვნელოვნად გაგიმარტივებთ.') WHERE id = '721c9809-540c-47c4-8190-d643e809029e';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენმა ბავშვმა უკვე დაიწყო თქვენთან ერთად ოჯახის სუფრასთან ჯდომა. ახლა მასაც შეუძლია მიირთვას ყველა ის საკვები, რომელსაც თქვენ მიირთმევთ. თუმცა არის ერთი რამ, რომელიც ბავშვისთვის მნიშვნელობას არასოდეს კარგავს: დედის რძე! განსაკუთრებით დამატებით კვებაზე გადასვლის პერიოდში, როდესაც რაციონს კალორიების სხვა წყაროც ემატება, ზოგიერთმა დედამ შესაძლოა რძის გამომუშავებას ადრინდელივით დიდი მნიშვნელობა აღარ მიანიჭოს. მიუხედავად იმისა, რძე ცოტა გაქვთ თუ ბევრი, მისი შემადგენლობა ბავშვის ჯანსაღი ფიზიკური და გონებრივი განვითარებისთვის ჯერ კიდევ ძალიან მნიშვნელოვანია. ამიტომ კიდევ გარკვეული ხნის განმავლობაში უნდა განაგრძოთ დაბალანსებულად კვება, კარგად დასვენება, საკმარისი ძილი და სტრესისგან თავის დაცვა. ამასთანავე, მაშინაც კი, თუ რძის რაოდენობა არ იზრდება, მისი შემადგენლობა ბავშვის განვითარების შესაბამისად იცვლება, ამიტომ რძის გამოსამუშავებლად თქვენს ორგანიზმს კვლავ დაახლოებით 500 კალორიის დამატებით მიღება სჭირდება. ორგანიზმის ენერგიის ამ დამატებითი მოთხოვნილების დასაკმაყოფილებლად კვების რაციონს შეგიძლიათ 2-3 სახეობის ხილი და რძის პროდუქტები დაუმატოთ.') WHERE id = 'd6098b08-62c8-4bb2-b4c1-b75ce5f1f080';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ნატიფი მოტორული უნარების განვითარების წყალობით, თქვენს ბავშვს უკვე შეუძლია ჭიქის გამოყენება დაიწყოს. თუ ბავშვი ამ ეტაპამდე საწოვარიან ბოთლს იყენებდა, სპეციალისტები 1 წლის ასაკის შემდეგ მისთვის ბოთლის გადაჩვევის დაწყებას გირჩევენ. საწოვარიანი ბოთლის ხანგრძლივად გამოყენებამ შესაძლოა მასზე ბავშვის დამოკიდებულება კიდევ უფრო გაზარდოს. თუმცა იმისთვის, რომ გადაჩვევის პროცესი ბავშვისთვის ტრავმული არ გახდეს, უმჯობესია, ის თანდათანობით წარმართოთ. მართალია, მიდგომები განსხვავებულია, მაგრამ საწოვარიანი ბოთლის გადაჩვევის პროცესი შესაძლოა 2 წლამდე გაგრძელდეს. თუმცა 2 წლის ასაკისთვის ბავშვს მასზე სრულად უნდა ჰქონდეს უარი ნათქვამი. თქვენს ხელშია, რომ ბავშვისთვის მოსაწყენი ეს პროცესი სახალისო გახადოთ. მაგალითად, ჭიქა, რომელზეც ბავშვისთვის ნაცნობი და საყვარელი პერსონაჟია გამოსახული, მას მოტივაციას გაუჩენს.') WHERE id = 'f6a48924-56e6-420c-9c9e-4191836f170a';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი დაბადების მომენტიდან გაკვირდებათ, თვალს ადევნებს თქვენს ქმედებებს და ამ ყველაფერს გონებაში იმახსოვრებს. სწორედ აქედან იწყება ბავშვის მიერ საკუთარი თავის აღმოჩენის გზა. ამიტომ ამ პერიოდში საკუთარ ქცევას განსაკუთრებული ყურადღება უნდა მიაქციოთ. თავდაპირველად ბავშვი მისაბაძ ადამიანებად, ანუ მის როლურ მოდელებად, ოჯახის უახლოეს წევრებს ირჩევს. დროთა განმავლობაში მან შესაძლოა უნებლიეთ გარშემო მყოფი სხვა ადამიანების მიბაძვაც დაიწყოს. ეს არჩევანი შეიძლება ბავშვის ინტერესების ცვლილებისა და განვითარების შესაბამისად შეიცვალოს. როგორც მშობელმა, თქვენ და თქვენმა პარტნიორმა სამაგალითო ქცევა უნდა გამოავლინოთ და ბავშვს უფრო ხშირად უნდა ჰქონდეს ურთიერთობა გარშემო მყოფ ადამიანებთან, რომელთაგანაც კარგი მაგალითის აღება შეუძლია. თუმცა, რადგან ბავშვის ცოდნის საფუძვლის ჩამოყალიბებაში უმთავრეს როლს ოჯახი ასრულებს, დასაწყისისთვის კარგი იქნება, პირველ რიგში საკუთარ უარყოფით ქცევებზე იმუშაოთ.') WHERE id = '0d87ed0c-727b-4e64-9ccc-fb3e890b1bf1';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'შესაძლოა, გაინტერესებდეთ, ამ თვის განმავლობაში რა აქტივობებით შეგიძლიათ დაკავდეთ თქვენს ბავშვთან ერთად. არსებობს მრავალი სახალისო აქტივობა, რომლებიც ორივეს სიამოვნებას მოგანიჭებთ და ამავდროულად ხელს შეუწყობს ბავშვის გონებრივ და ფიზიკურ განვითარებას. მაგალითად, შეგიძლიათ ბავშვს აჩვენოთ რაიმე ნივთი და შემდეგ ისეთ ადგილას დამალოთ, სადაც ის დაინახავს. ამის შემდეგ სთხოვეთ, მოგიტანოთ ეს ნივთი. ამგვარად, ბავშვი განივითარებს ხელისა და თვალის კოორდინაციას და თან ძალიან გაერთობა. როდესაც ნივთს მოგიტანთ, მადლობა გადაუხადეთ — ეს საფუძველს ჩაუყრის იმ სასარგებლო ჩვევებსაც, რომლებიც ბავშვმა მომავალში უნდა შეიძინოს. თამაშად შეგიძლიათ აქციოთ ყოველდღიური საქმიანობაც. მაგალითად, გარეთ გასასვლელად მომზადებისას დადექით სარკის წინ ისე, რომ ბავშვმა თქვენი ანარეკლი დაინახოს, დაუქნიეთ ხელი და წაახალისეთ, რომ იგივე ჟესტით გიპასუხოთ. ბავშვის მომდევნო კვების მომზადებამდე შეგიძლიათ პროდუქტები დაალაგოთ და გააცნოთ სიტყვებით: „ეს დიდია“, „ეს პატარაა“, „ეს ყვითელია“, „ეს ნარინჯისფერია“. კარგად გაერთეთ! 😊') WHERE id = '6301b867-ee49-4968-aaba-34f711fa6ee8';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის კვების დრო დადგა. საჭმელიც მზადაა, მაგიდაც გაწყობილია და ბავშვიც მზად არის. მაგრამ ეს რა არის? ბავშვი თქვენს დიდი მონდომებით მომზადებულ საჭმელს ჭამის ნაცვლად იატაკზე ყრის! თუ ეს ამბავი თქვენთვისაც ნაცნობია, უპირველეს ყოვლისა უნდა იცოდეთ, რომ მარტო არ ხართ. ერთ-ერთი მთავარი მიზეზი, რის გამოც ბავშვი საჭმელს იატაკზე ყრის, არის ის, რომ მან საგნების გადაადგილება აღმოაჩინა. ამ ეტაპზე ბავშვი ამას ცნობისმოყვარეობის გამო აკეთებს — მას სურს დააკვირდეს, რა მოხდება, როცა საჭმელს იატაკზე გადააგდებს. იმისთვის, რომ ეს ჩვევად ან თამაშად არ ექცეს, ნუ გამოეხმაურებით სიცილით ან ყვირილით. როცა ბავშვი ასე მოიქცევა, დაიხარეთ, რათა მასთან თვალით კონტაქტი დაამყაროთ და უთხარით, რომ ასე მოქცევა არ შეიძლება. თუ ის საჭმლის იატაკზე ყრას გააგრძელებს, გაბრაზების გარეშე შეგიძლიათ სკამიდან ჩამოსვათ და უთხრათ, რომ ჭამის დრო დასრულდა.') WHERE id = '10cae169-a8b4-4be4-bdf5-84293f56e461';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის ფეხის კუნთების უკეთ გასაძლიერებლად, სახლში მას რაც შეიძლება ხშირად წინდებით სიარულის საშუალება უნდა მისცეთ. სანამ თქვენი ბავშვი დაცემის გარეშე გარკვეული დროის განმავლობაში კარგად სიარულს შეძლებს, ყურადღება მიაქციეთ, რომ გარეთ ჩასაცმელი ფეხსაცმელი რბილი და მოქნილი იყოს. გავრცელებული მოსაზრების საპირისპიროდ, მყარძირიანმა ფეხსაცმელმა შესაძლოა ბავშვს ფეხი გადააბრუნებინოს. როგორი ყურადღებითაც არ უნდა იყოთ, სიარულის სწავლის პერიოდში ის ხშირად დაეცემა. თუ დაცემაზე მძაფრი რეაქცია არ გექნებათ, ბავშვი, თუ არაფერი ეტკინა, ტირილს არ დაიწყებს და დახმარებას არ მოგთხოვთ. თუ დაცემისას ბავშვს ეტკინა და ატირდა, მაშინვე ხელში აყვანის ნაცვლად, შეგიძლიათ მის გვერდით ჩაიმუხლოთ და მოეხვიოთ. ეს ძალიან მნიშვნელოვანია, რათა ბავშვმა სიარულის მცდელობა არ შეწყვიტოს და მოტივაცია არ დაკარგოს.') WHERE id = '4b5a6bf3-177f-49f1-b076-3c5623ae0a32';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ თვეში ექიმთან ვიზიტისას პედიატრი, რომლის მეთვალყურეობის ქვეშაც იმყოფებით, თქვენს ბავშვს სისხლის რამდენიმე ანალიზს დაუნიშნავს. ეს ანალიზები ძალიან მნიშვნელოვანია მრავალი მაჩვენებლის, განსაკუთრებით კი რკინის დონის, დეტალურად შესაფასებლად. რადგან ბავშვი სწრაფი ზრდისა და განვითარების ეტაპზეა, მის ორგანიზმს რკინა უფრო მეტად სჭირდება, ვიდრე ცხოვრების სხვა პერიოდებში. თუ ამ თვიდან ბავშვის კვების რაციონი საკმარისი რაოდენობით რკინას არ შეიცავს, შესაძლოა რკინის დეფიციტთან დაკავშირებული პრობლემები გამოვლინდეს. განსაკუთრებით რკინადეფიციტური ანემია ამ პერიოდში ერთ-ერთი ყველაზე გავრცელებული პრობლემაა. რკინის დეფიციტმა შესაძლოა შეაფერხოს ბავშვის გონებრივი განვითარება და გავლენა მოახდინოს კუნთების ფუნქციებზეც. ვინაიდან ამ მდგომარეობამ შეიძლება გონებრივი და ფიზიკური განვითარების გარკვეული შეფერხებები გამოიწვიოს, მასზე ყურადღების გამახვილება ძალიან მნიშვნელოვანია.') WHERE id = 'd8d155e1-a69b-4e80-a661-38a50b003754';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ თვიდან ბავშვის კუჭის მოცულობამ დაახლოებით 300 ml-ს მიაღწია. ეს ნიშნავს, რომ ბავშვს უკვე მეტი საკვების მიღება შეუძლია, ამიტომ შეგიძლიათ ულუფები თანდათან გაზარდოთ ისე, რომ მისი საჭმლის მომნელებელი სისტემა არ გადაიტვირთოს. მნიშვნელოვანია, რომ ბავშვმა საკვები ღირებულებით მდიდარი სეზონური ხილი და ბოსტნეული მიიღოს და ამავდროულად ჯანსაღი კვების ჩვევები გამოიმუშაოს. სკოლამდელ პერიოდში შაქრის ჭარბმა მიღებამ მომავალში შესაძლოა სიმსუქნე და მასთან დაკავშირებული მრავალი დაავადება გამოიწვიოს. ამიტომ, შაქრის ნაცვლად, რომელიც მხოლოდ ცარიელი კალორიების წყაროა, შეგიძლიათ ბავშვს ბუნებრივი მეთოდებით დამზადებული ბადაგი, ფინიკის სიროფი და კერატის სიროფი მისცეთ. გარდა ამისა, აღარ არსებობს მიზეზი, რომ ბავშვმა არ მიირთვას ის პროდუქტები, რომლებიც დამატებითი კვების დაწყებისას აკრძალულთა სიაში შედიოდა. შესაბამისად, 1 წლის ასაკიდან ბავშვის მენიუში უკვე შეგიძლიათ შეიტანოთ კვერცხის ცილა და ალერგენებად მიჩნეული პროდუქტები, როგორიცაა მარწყვი, კივი, პომიდორი, თხის რძე და ძროხის რძე.') WHERE id = '58dc36ac-5b7c-4362-80e3-ab066859eeea';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, '1980-იან წლებში ლაბორატორიულ პირობებში ჩატარებული კვლევების შედეგად გაჩნდა თეორია, რომ ადამიანები თავიანთი ტვინის მხოლოდ 10%-ს იყენებენ. დღეს, ტექნოლოგიების ეპოქაში, ბევრი ადამიანი ამ მოსაზრებას ჯერ კიდევ ჭეშმარიტებად მიიჩნევს. თუმცა, უახლესმა კვლევებმა დაამტკიცა, რომ ადამიანები ტვინის სრულ პოტენციალს იყენებენ. კვლევები აჩვენებს, რომ ადამიანის ტვინი ერთიანად მუშაობს, ყველა კავშირი ურთიერთქმედებს და მაშინაც კი, როდესაც კონკრეტულ დავალებას არ ვასრულებთ, ფონურად მრავალი პროცესი მიმდინარეობს. ტვინის განვითარების 70% დაბადებიდან პირველი 1 წლის განმავლობაში სრულდება. ანუ ამ ეტაპზე ბავშვის ტვინის განვითარება თითქმის ზრდასრული ადამიანის დონეს აღწევს. ამიტომ პატარას გონებრივი განვითარების ხელშესაწყობად ძალიან მნიშვნელოვანია, მასთან ერთად სხვადასხვა თამაში ითამაშოთ და მრავალფეროვანი აქტივობებით დაკავდეთ.') WHERE id = '6d097ab5-abec-41d4-95bf-d2757270dc79';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, '1 წლის შემდეგ იწყება ბავშვისთვის გარდამავალი ეტაპი, როდესაც მისი კვების თავისებურებებიც იცვლება. ამ პერიოდში ბავშვის ფიზიკური აქტივობა მნიშვნელოვნად იზრდება და მან შესაძლოა ჭამაზე უარი თქვას, რათა თამაშს მეტი დრო დაუთმოს. ამ ეტაპზე მადის დაქვეითება ხშირია, ხოლო ბავშვის ზრდის ტემპის შენელება მოსალოდნელი და ნორმალური მოვლენაა. ამიტომ ბავშვის კვების რაციონში საკმარისი რაოდენობით და რეგულარულად უნდა შეიტანოთ საკვების ძირითადი ჯგუფები: ხორცი, რძე და რძის პროდუქტები, ბოსტნეული, მარცვლეული, ცხიმები და ხილი. კალციუმის ყოველდღიური საჭიროების დასაკმაყოფილებლად ბავშვისთვის დაახლოებით ორი ჭიქა რძე ან იოგურტი საკმარისი იქნება. კუნთებისა და ძვლების განვითარებისთვის ცილა ერთ-ერთი უმთავრესი საკვები ნივთიერებაა, რომელიც ყოველდღიურ რაციონში უნდა შედიოდეს. ამიტომ ეცადეთ, კვირაში მინიმუმ 4 დღე მის მენიუში შეიტანოთ ცილით მდიდარი პროდუქტები, როგორიცაა ხორცი და ქათამი.') WHERE id = '1f14934f-6ba0-46b8-bd87-619dc02a6360';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'დღეს გთავაზობთ აქტივობას, რომელიც შეგიძლიათ ბავშვთან ერთად შეასრულოთ და ბევრი იხალისოთ: ავტობუსი, სატვირთო მანქანა, ტაქსი, ჯიპი, ბიიიიპ! 😊 ეს ძალიან მარტივი და სახალისო თამაშია, რომელიც არანაირ ხარჯსა თუ მომზადებას არ მოითხოვს. ეს აქტივობა ბავშვის ტვინს მრავალმხრივ გაააქტიურებს და თან მას ძალიან გაართობს. თითებით მონაცვლეობით შეეხეთ მის მარჯვენა და მარცხენა ლოყას, ნიკაპს, შუბლსა და ცხვირს — ეს ბავშვის ტვინში შეხების შეგრძნებას გაააქტიურებს. ხოლო როდესაც ბავშვს სთხოვთ, იგივე თქვენც გაგიკეთოთ, ეს ხელისა და თვალის კოორდინაციის განვითარებას ძალიან ეფექტურად შეუწყობს ხელს. ამ ეტაპზე ბავშვის თვალყურის დევნებისა და ყურადღების უნარებიც განვითარდება. ცოტა ხანში შეამჩნევთ, რომ თამაშის ყოველი გამეორებისას ბავშვი აღელვებული დაელოდება „ბიიიპ“ ნაწილს! 😊') WHERE id = 'dbf740cc-9b7e-4a4f-823f-1cca951d24d9';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის ყოველდღიური კალორიული საჭიროების დიდ ნაწილს ნახშირწყლების შემცველი საკვები შეადგენს. ამ ეტაპზე ბავშვის კვების რაციონში უნდა შეიტანოთ მაღალი საკვები ღირებულების მქონე, ჯანსაღი ნახშირწყლებით მდიდარი მარცვლეული. შეგიძლიათ ყოველდღიურად მისაცემი თეთრი ფქვილის პური ჩაანაცვლოთ მთლიანი ხორბლის, ჭვავის ან შვრიის ფქვილისგან დამზადებული პურით. თუმცა, თუ მენიუში ნახშირწყლებით მდიდარი კერძებია, მაგალითად, ფლავი ან მაკარონი, პურის რაოდენობა უნდა შეამციროთ. რადგან თითოეული ხილი განსხვავებულ ვიტამინებსა და მინერალებს შეიცავს, ეცადეთ, ბავშვს სეზონურად მოყვანილი ბუნებრივი ხილი მისცეთ. პატარასთვის მომზადებულ საკვებში ვიტამინების დანაკარგის შესამცირებლად შეგიძლიათ უპირატესობა ორთქლზე მომზადებას მიანიჭოთ. ასევე შეგიძლიათ საკვები მოხარშოთ ან ღუმელში გამოაცხოთ. თუმცა, ჯერჯერობით უმჯობესია, შეწვის მსგავს მეთოდებს მოერიდოთ.') WHERE id = '7d0f3469-adf8-4ed6-8ee6-cccf8034c80f';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ყველა აქტივობას, რომელსაც ბავშვთან ერთად ან მისთვის განახორციელებთ, გარკვეული მიზნები და საერთო საფუძველი აქვს. მათი მიზანია, ბავშვი როგორც ახლა, ისე ზრდასრულ ასაკში უფრო კომუნიკაბელური, თავდაჯერებული და საკუთარ თავსა და გარემოსთან ჰარმონიაში მყოფი ადამიანი გახდეს. ამ თვალსაზრისით, თანატოლებთან შექმნილ სათამაშო ჯგუფებს ბევრი დადებითი გავლენა აქვს. თამაშის ასაკში მყოფი ბავშვი ჯგუფში ურთიერთობის წყალობით ბუნებრივად, გართობის პროცესში სწავლობს. თანატოლებთან თამაში მას როგორც გაზიარების, ისე სხვა ბავშვებთან ურთიერთობის უნარებს უვითარებს. გარდა ამისა, საკუთარი ასაკის ბავშვებთან ერთად ყოფნა საზოგადოებრივი ცნობიერების საფუძველს უყრის. ამიტომ შეგიძლიათ ეცადოთ, ხშირად შეხვდეთ ახლობლებს, რომლებსაც თქვენი ბავშვის თანატოლი შვილები ჰყავთ.') WHERE id = '289e1ce5-6829-49f4-8414-fd82ef2d5291';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თითქმის ყველა ვიტამინს საკვებიდან ვიღებთ. ისინი ორგანიზმში მრავალ ფუნქციას ასრულებენ — მონაწილეობენ სისხლის წარმოქმნაში, იმუნიტეტის გაძლიერებით ინფექციებისგან გვიცავენ და ხელს უწყობენ ზრდასა და განვითარებას. ვიტამინებს შორის D ვიტამინს განსაკუთრებული მნიშვნელობა აქვს. ის კალციფეროლად წოდებული, ცხიმში ხსნადი ვიტამინია, რომელიც ღვიძლსა და ცხიმოვან ქსოვილში გროვდება. D ვიტამინი ორი ფორმით არსებობს — D2 და D3. მზის სხივებისა და საკვების მეშვეობით ორგანიზმში მოხვედრილი ეს ვიტამინი თირკმელებსა და ღვიძლში რამდენიმე პროცესს გადის, რის შემდეგაც ორგანიზმი მას იყენებს. ამ ეტაპზე D ვიტამინი ბავშვის ძვლებისა და კბილების განვითარებისა და ჯანმრთელობისთვის ძალიან მნიშვნელოვანია. D ვიტამინის გარეშე ბავშვის ძვლები საჭირო კალციუმსა და ფოსფორს ვერ ითვისებს. ამიტომ ბავშვს ყოველდღიურად დაახლოებით 20 წუთის განმავლობაში სჭირდება მზის სინათლე. ასევე სასარგებლო იქნება, ბავშვის კვების რაციონში საკმარისი რაოდენობით დაამატოთ D ვიტამინით მდიდარი რძე, აირანი, კეფირი, ყველი, იოგურტი, კარაქი, თინუსი, ორაგული და კვერცხის გული.') WHERE id = '567791cf-026f-48e1-a1ae-11fb0c471664';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ადამიანის ტვინი ორი ნაწილისგან — მარჯვენა და მარცხენა ნახევარსფეროებისგან შედგება. მარჯვენა ხელს ტვინის მარცხენა ნახევარსფერო მართავს, ხოლო მარცხენა ხელს — მარჯვენა ნახევარსფერო. ამ ეტაპზე თქვენი ბავშვი, დიდი ალბათობით, ორივე ხელს ერთნაირად იყენებს. მშობლებისთვის ერთ-ერთი საინტერესო საკითხია, როდის გახდება ცნობილი, ბავშვი მემარცხენეა თუ მემარჯვენე. ამ კითხვაზე ზუსტი პასუხი არ არსებობს, თუმცა ის, თუ რომელ ხელს გამოიყენებს ბავშვი უკეთ, მხოლოდ 3-4 წლის ასაკის შემდეგ შეიძლება დაზუსტდეს. მიუხედავად ამისა, ბავშვმა შესაძლოა გარკვეული ნიშნები უკვე გამოავლინოს. მაგალითად, როცა სთხოვთ შემობრუნებას, საათის ისრის საწინააღმდეგო მიმართულებით ტრიალი ან მიწოდებული ნივთის მარცხენა ხელით აღების მცდელობა მემარცხენეობის ადრეულ ნიშნებს მიეკუთვნება. მემარცხენეობა, როგორც წესი, გენეტიკურად განპირობებული ნორმალური მდგომარეობაა და იშვიათი გამონაკლისების გარდა, პრობლემას არ წარმოადგენს. თუ თქვენც და თქვენი პარტნიორიც მემარცხენეები ხართ, ბავშვის მემარცხენეობის ალბათობა დაახლოებით 50%-ია. თუ მხოლოდ ერთი თქვენგანია მემარცხენე, ეს მაჩვენებელი შეიძლება 25%-მდე შემცირდეს. თუ ფიქრობთ, რომ ბავშვი მემარცხენეა, არ უნდა აიძულოთ მარჯვენა ხელის გამოყენება, რადგან ამან შეიძლება სხვადასხვა პრობლემა, მათ შორის სწავლის სირთულეები გამოიწვიოს.') WHERE id = '75f0b847-2817-4187-947e-77f90574e166';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'დაბადებიდან დამატებითი კვების დაწყებამდე ბავშვს წყალი არ სჭირდება. თუ ბავშვს ძუძუთი კვებავთ, დედის რძის 90%-მდე წყლისგან შედგება და მის საჭიროებას სრულად აკმაყოფილებს. დედის რძის არარსებობის შემთხვევაში, თუ ხელოვნური საკვები სწორად არის მომზადებული, ბავშვს დამატებითი წყალი არ სჭირდება, გარდა იმ შემთხვევისა, როცა ექიმი სხვაგვარად გირჩევთ. თუმცა დამატებითი კვების დაწყებიდან, ანუ 6-ე თვიდან, ბავშვის ორგანიზმს თქვენ მიერ შეთავაზებული საკვების მოსანელებლად წყალი სჭირდება. წყლის საჭიროება ბავშვის მიერ მიღებული საკვების სახეობისა და რაოდენობის მიხედვით იზრდება. ეს მაჩვენებელი შეიძლება ასევე შეიცვალოს მისი წონის, სიმაღლისა და მიღებული დედის რძის ან ხელოვნური საკვების რაოდენობის მიხედვით. იმის დასადგენად, რამდენი წყალი მისცეთ ბავშვს, შეგიძლიათ შარდის ფერსა და სუნს დააკვირდეთ. უსუნო და ღია ყვითელი შარდი მიუთითებს, რომ ბავშვი საკმარისი რაოდენობის წყალს იღებს. ჭამის შემდეგ შეგიძლიათ ბავშვს წყალი იმდენი მისცეთ, რამდენიც სურს. თუ ბავშვს შეკრულობა აწუხებს, გახსოვდეთ, რომ შესაძლოა მიღებული წყლის რაოდენობის კიდევ უფრო გაზრდა გახდეს საჭირო.') WHERE id = '226f1510-b007-4bb8-8b57-95b8e4235edf';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი მოკლე დროში ძალიან სწრაფად გაიზარდა და განვითარდა. რა თქმა უნდა, ამას თავისი შედეგიც აქვს: ბავშვი საწოლში უკვე ვეღარ ეტევა! 😊 ამ ეტაპზე შეიძლება იფიქროთ, რომ მას უფრო დიდი საწოლი სჭირდება. თუმცა გირჩევთ, ამ გადაწყვეტილების მიღება არ იჩქაროთ. სანამ ბავშვი საწოლიდან გადმოძრომას არ დაიწყებს, საბავშვო საწოლი მისთვის უფრო უსაფრთხო იქნება. ძილის დროს ბავშვი ხშირად ტრიალდება, რამაც შეიძლება საწოლიდან გადმოვარდნა და სიმაღლესთან დაკავშირებული თავის ტრავმა გამოიწვიოს. ამიტომ ბავშვის საწოლის გადიდება ან გაფართოება მისი კომფორტისა და უსაფრთხოებისთვის უფრო გონივრული გამოსავალი შეიძლება იყოს. როცა ბავშვი გადმოძრომას დაიწყებს, შეიძლება გამოგადგეთ დამცავი გვერდები, რომლებიც საწოლის უსაფრთხოებას ზრდის. დამატებითი უსაფრთხოებისთვის საწოლის გარშემო იატაკზე ბალიშებიც შეგიძლიათ დააწყოთ.') WHERE id = 'b97f83a4-16ac-40bf-8c1e-c667c7b0e4af';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თამაში ბავშვს შესანიშნავ შესაძლებლობას აძლევს, აღმოაჩინოს საკუთარი ინტერესები, განივითაროს ახალი უნარები და პრაქტიკაში გამოიყენოს ისინი. ამიტომ სათამაშოებს ბავშვის განვითარებაში ძალიან მნიშვნელოვანი ადგილი უჭირავს. 1 წლის ასაკში ბავშვებს ძალიან მოსწონთ სათამაშოები, რომელთა ნაწილების განცალკევება, გაერთიანება, მიმაგრება, მოხსნა და შესაბამის ადგილას მოთავსება შეუძლიათ. ამიტომ ახალი სათამაშოების შეძენისას შეგიძლიათ უპირატესობა მრავალფუნქციურ სათამაშოებს მიანიჭოთ. ამ ასაკში ნებისმიერი ბიუჯეტისთვის შეგიძლიათ იპოვოთ „სიარულის დამხმარედ“ წოდებული პროდუქტები, რომლებიც ბავშვს სიარულისკენ უბიძგებს. ასევე გამოგადგებათ სათამაშოები, რომლებიც მის წარმოსახვას ავითარებს და აქტიურობისკენ უბიძგებს. ბავშვის სოციალური განვითარების ხელშესაწყობად შეგიძლიათ ისეთი სათამაშოებიც შეარჩიოთ, რომლებითაც ის თანატოლ ბავშვებთან და უფროსებთან ერთად შეძლებს თამაშს.') WHERE id = 'c3cee02b-ffb7-41f8-a78b-1e3c3739d873';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ თქვენს ავტომობილში ჯერ კიდევ არ გაქვთ ბავშვის სავარძელი, გირჩევთ, რაც შეიძლება მალე შეიძინოთ. სპეციალისტები ბავშვის დაბადებიდან 1 წლამდე ჩვილის ავტოსავარძლის, ხოლო 1 წლის შემდეგ, როცა ის უფრო აქტიურად მოძრაობას იწყებს, ბავშვის ავტოსავარძლის გამოყენებას გვირჩევენ. ავტომობილში ბავშვის სავარძელი მგზავრობისას ბავშვის დაზიანების რისკს 90%-ით ამცირებს. მისი წყალობით, შესაძლო ავტოსაგზაო შემთხვევის დროს ბავშვი დაცული იქნება ისეთი საფრთხეებისგან, როგორებიცაა ავტომობილიდან გადავარდნა, მოჭყლეტა და ძლიერი რყევა. თუ ბავშვის სავარძელი ავტომობილში მყარად არის დამაგრებული, თქვენს პატარას დისკომფორტის გარეშე შეეძლება მგზავრობა. გარდა ამისა, ჩვილის სავარძლისგან განსხვავებით, ბავშვის სავარძელი შეგიძლიათ დაამაგროთ არა მოძრაობის საპირისპიროდ, არამედ ავტომობილის მოძრაობის მიმართულებით. ამგვარად, შეგიძლიათ მინიმუმამდე შეამციროთ ბავშვის გულისრევა და მისცეთ საშუალება, თავისუფლად დააკვირდეს გარემოს.') WHERE id = 'bc4b0b1c-8079-4973-9564-32f3aa0c7c31';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ ეტაპზე თქვენი ბავშვი გარე სამყაროს შესასწავლად გრძნობებისა და მოტორული უნარების აქტიურად გამოყენებას იწყებს. რადგან ამ აღმოჩენების დროს წარმოსახვას იყენებს, მას ჯერ კიდევ არ შეუძლია რეალობისა და აბსტრაქტული ცნებების ერთმანეთისგან გარჩევა. ამის გამო, განსაკუთრებით ღამით, ტვინის ყველაზე აქტიურ, REM ძილის ფაზაში, შეიძლება კოშმარები ნახოს და ტირილით გაიღვიძოს. მართალია, REM ძილის ფაზის ხანგრძლივობა ყველაზე დიდი ახალშობილობის პერიოდშია, ამ ეტაპზე მისი თანდათანობით შემცირება ბავშვის განვითარების ბუნებრივი შედეგია. თუმცა, რადგან REM ფაზა ჯერ კიდევ ძილის მნიშვნელოვან ნაწილს შეადგენს, ტირილით გაღვიძებული ბავშვის დასამშვიდებლად მას რბილი ხმით უნდა ესაუბროთ, ზურგზე მოეფეროთ და მშვიდი სიტყვებით დაამშვიდოთ. ძილისა და სიფხიზლის ჯანსაღი რეჟიმის ჩამოყალიბება ბავშვის ტვინის განვითარების ერთ-ერთი უმნიშვნელოვანესი ნაწილია. ამის მიზეზი ისაა, რომ ძილის დროს ენდოგენური ნეირონული აქტივობა გრძელდება, რაც ბავშვის ტვინში ნერვულ კავშირებს ზრდის.') WHERE id = 'badf3432-f515-4611-b2dd-f57dfff399c0';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ძალიან მნიშვნელოვანია ბავშვის მოტორული უნარების განვითარება და ხელისა და თვალის კოორდინაციის ხელშეწყობა. ამიტომ, მხოლოდ თქვენ მიერ კვების ნაცვლად, ბავშვს საშუალება უნდა მისცეთ, თქვენთან ერთად იჯდეს სასადილო მაგიდასთან. წინ დაუდეთ კოვზი, ჩანგალი და ჭიქა, რათა დამოუკიდებლად ჭამა შეძლოს. ბავშვის თქვენთან ერთად სასადილო მაგიდასთან ჯდომა არა მხოლოდ სასიამოვნო დროის გატარების საშუალებას მოგცემთ, არამედ მისი მოტორული უნარების განვითარების ძალიან ეფექტური მეთოდიცაა. სუფრასთან ქცევის წესების სწავლება მნიშვნელოვნად დაგეხმარებათ, რომ ბავშვმა დამოუკიდებლად ჭამის ჩვევა გამოიმუშაოს, თავდაჯერებულობა შეიძინოს და ჯანსაღი კვების ჩვევები ჩამოიყალიბოს. ჯანსაღი კვების ჩვევების შეძენა მნიშვნელოვანია იმისთვისაც, რომ მომავალში ბავშვი სიმსუქნის მსგავს ჯანმრთელობის სერიოზულ პრობლემებს არ შეეჯახოს. გარდა ამისა, ეს ხელს უწყობს მის სოციალურ განვითარებას, ეხმარება, თავი ოჯახის სრულფასოვან წევრად იგრძნოს და თავდაჯერებულობა შეიძინოს.') WHERE id = 'a5a8bdd4-c15d-4e3c-b31c-fa8ddc4838d7';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში თქვენი ბავშვი შეიძლება განსაკუთრებით მორცხვად მოიქცეს, როდესაც ბევრი უცნობი ადამიანის გარემოცვაში ხვდება. 1 წლიდან ბავშვი უკვე აცნობიერებს, რომ დამოუკიდებელი პიროვნებაა და „მე“-ს ცნების ჩამოყალიბებას იწყებს. ზოგი ბავშვი სწრაფად ამყარებს ურთიერთობას როგორც თანატოლებთან, ისე უფროსებთან, ზოგი კი შეიძლება უფრო ფრთხილი იყოს. ასეთ ბავშვებს სხვებთან ურთიერთობის დასამყარებლად მეტი დრო და სიახლოვე სჭირდებათ. სოციალიზაციის უნარზე მოქმედი პიროვნული მახასიათებლები გენეტიკური და გარემო ფაქტორების გავლენით ყალიბდება. ბავშვის სოციალიზაციის, თავდაჯერებულობისა და ინიციატივიანობის ხელშესაწყობად რამდენიმე აქტივობა შეგიძლიათ გამოიყენოთ. მაგალითად, როდესაც ბავშვი სათამაშოებით თამაშობს, შეგიძლიათ მათ სხვადასხვა როლი მოარგოთ, მათი სახელით ისაუბროთ და ისინი თქვენს პატარას გააცნოთ. ეს აქტივობა ბავშვს სოციალიზაციისთვის საჭირო საბაზისო უნარების ჩამოყალიბებაში დაეხმარება.') WHERE id = '210da92e-a255-4ad9-bddd-29b5d33ece1b';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'კეთილი იყოს თქვენი და თქვენი ბავშვის თავგადასავლებით სავსე 13-ე თვე! თქვენი პატარა უკვე იმ ასაკშია, როცა ყველაფრის აღმოჩენა სურს. ამიტომ, რადგან მისი მოძრაობა ძველებურად შეზღუდული აღარ არის, მისი თავგადასავლებისადმი მიდრეკილება შეიძლება უფრო მეტად გამოვლინდეს. სახლში აქტიურად მოძრავი ბავშვისთვის ჟურნალის მაგიდა, მაღალი მაგიდა და მსხვრევადი ნივთები შეიძლება სერიოზული საფრთხის წყარო იყოს. ამიტომ ყველა სივრცე, სადაც ბავშვი იმყოფება, უსაფრთხო უნდა გახადოთ. ამ პერიოდში ძალიან გამოგადგებათ მისი ოთახის სათამაშო სივრცედ მოწყობა და იმ დროს, როცა მის გვერდით არ ხართ, ბავშვის უსაფრთხოების ღობეების ან მანეჟის გამოყენება. ბავშვის ზედმეტად შეზღუდვამ შეიძლება ახალი გამოცდილებების მიღების სურვილი და ენთუზიაზმი დაუკარგოს. ამიტომ თქვენს პატარას საშუალება უნდა მისცეთ, თქვენ მიერ განსაზღვრულ უსაფრთხო საზღვრებში თავისუფლად აკეთოს ის, რაც სურს.') WHERE id = '740aa0ca-f02e-440c-9265-f4789b505cbc';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, '13-ე თვეში ბავშვის საშუალო წონა, თუ ის ბიჭია, დაახლოებით 10.500 გრამია, ხოლო თუ გოგოა — დაახლოებით 9600 გრამი. თუმცა ბავშვის წონა შეიძლება 8000 გრამიდან 14.000 გრამამდე მერყეობდეს. ამ დიაპაზონის სიდიდეს მრავალი მიზეზი აქვს. სქესი განვითარების თავისებურებებზე მოქმედი ერთ-ერთი უმნიშვნელოვანესი ფაქტორია. გენეტიკური თვალსაზრისით, ნორმალურია, რომ ბიჭები გოგოებზე ფიზიკურად უფრო მსხვილები, მძიმეები და მაღლები იყვნენ. ორი სხვადასხვა სქესის ბავშვის ერთმანეთთან შედარება არასწორია, მაშინაც კი, თუ ისინი ორსულობის ერთსა და იმავე კვირაში და ერთნაირი წონით დაიბადნენ. განვითარების თვალსაზრისით ბუნებრივია, რომ გვიან ბავშვობის ასაკამდე ბიჭების ნერვული და ძვალ-კუნთოვანი სისტემების განვითარება გოგოებთან შედარებით უფრო სწრაფად მიმდინარეობდეს.') WHERE id = '89a0dfcb-42b6-4d7f-b880-5a576cebf0c5';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში თქვენთვის მარტივ მოქმედებებსაც კი შეიძლება ბავშვისთვის დიდი მნიშვნელობა ჰქონდეს. განსაკუთრებით ახლა, როცა ბავშვმა უკვე დაიწყო სიარული, მისთვის ერთ-ერთი საყვარელი საქმიანობა გარემოში ყველაფრის აღმოჩენაა. ამ თვეში მასთან ერთად შეგიძლიათ წაიკითხოთ ბევრი სურათითა და ილუსტრაციით გაფორმებული წიგნები, რომლებიც განსაკუთრებით მიიპყრობს მის ინტერესს. ეს საქმიანობა არა მხოლოდ მნიშვნელოვნად მიიქცევს ბავშვის ყურადღებას, არამედ სიტყვების გაგებისა და დამახსოვრების შესაძლებლობასაც მისცემს. ბავშვის მეტყველების განვითარებისთვის განსაკუთრებით სასარგებლოა, ხშირად ესმოდეს ახალი სიტყვა. თუ მასთან ერთად გაიმეორებთ სიტყვებს, რომლებიც თქვენგან მოისმინა და წარმოთქვა, ბავშვს წიგნების კითხვისა და მოსმენის სურვილი კიდევ უფრო გაუძლიერდება. სპეციალისტები მიიჩნევენ, რომ კითხვის ჩვევა ძალიან ადრეული ასაკიდან უნდა ჩამოყალიბდეს. ამიტომ ბავშვის განვითარებისთვის გირჩევთ, კითხვა შეაყვაროთ. სასიამოვნო და სახალისო კითხვას გისურვებთ! 😊') WHERE id = 'faa77562-7254-4896-90da-0246f097b6f8';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'საკმარისი რაოდენობის წყლის მიღება ბავშვისთვის ძალიან მნიშვნელოვანია. თუმცა უნდა გახსოვდეთ, რომ ისევე, როგორც ყველაფრის სიჭარბე, ზედმეტი წყალიც შეიძლება საზიანო იყოს. საჭიროებაზე მეტი წყლის მიღებამ შეიძლება ბავშვის ორგანიზმში ელექტროლიტებისა და მარილების ბალანსი დაარღვიოს. ამ ბალანსის დარღვევამ შესაძლოა ჯანმრთელობის სხვადასხვა პრობლემა, მათ შორის კრუნჩხვაც გამოიწვიოს. ამასთან, ამ პერიოდში ბავშვის თირკმელები ჯერ სრულად განვითარებული არ არის, ამიტომ ჭარბი წყლის მიღება მათზე დამატებით დატვირთვას ქმნის. ასეთ შემთხვევაში შეიძლება უარყოფითი გავლენა იქონიოს როგორც ბავშვის ზრდასა და განვითარებაზე, ისე მის ორგანოებსაც მიადგეს ზიანი. თუ ბავშვის კვებისთვის ხელოვნურ ნარევს (ფორმულას) იყენებთ, იმისთვის, რომ მან მეტი წყალი მიიღოს, ნარევში დამატებითი წყლის ჩასხმა მის კვებით ღირებულებასაც შეამცირებს. ამიტომ, თუ ბავშვს წყლის დალევა არ სურს, მნიშვნელოვანია, არ დააძალოთ. გახსოვდეთ, რომ ბავშვი თავად მიიღებს იმდენ წყალს, რამდენიც სჭირდება.') WHERE id = '410208cc-11e4-4f3d-94f0-5d9ad8d119dd';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მას შემდეგ, რაც ბავშვი ცხოვრების პირველ 1 წელს დაასრულებს, იწყება ინდივიდუალობის ჩამოყალიბებისა და საკუთარი თავის შეცნობის პროცესი. თუმცა ბავშვის ეს დამოუკიდებლობა არ ნიშნავს, რომ თქვენდამი მისი მიჯაჭვულობა მცირდება. ბავშვის გონებრივი განვითარება უკვე იმ დონეს აღწევს, რომ დაკარგვის შიშს აქტიურად აცნობიერებს. სწორედ ამით აიხსნება თქვენდამი მისი მიჯაჭვულობა, თქვენი წასვლისას ტირილი და იმ გარემოში განცდილი შფოთვა, სადაც თქვენ არ ხართ. დაკარგვის ძლიერმა შიშმა შეიძლება დაახლოებით კიდევ 6 თვის განმავლობაში განსაკუთრებით მგრძნობიარე პერიოდი გამოიწვიოს. ბავშვის ფსიქიკაზე უარყოფითი გავლენის თავიდან ასაცილებლად, ამ პერიოდში ყოველ ჯერზე, როცა მის გვერდით აღარ იქნებით, აუხსენით წასვლის მიზეზი და უთხარით, რომ დაბრუნდებით. მიუხედავად იმისა, რომ ბავშვს ჯერ პასუხისთვის საკმარისი სიტყვების მარაგი არ აქვს, ეჭვი ნუ შეგეპარებათ, რომ ის მიხვდება, რისი თქმა გსურთ.') WHERE id = 'fe0ff0cd-6498-4ce3-aae2-9c10c75f7fdb';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ თვიდან ბავშვის წონის მატება შეიძლება გარკვეული დროით შეჩერდეს და წონაში მცირედ კლებაც კი აღინიშნოს. შეიძლება გეგონოთ, რომ ბავშვი ძალიან ცოტას ჭამს, საჭმელს არჩევს, დამოუკიდებლად ჭამა უჭირს და კვებაზე უარს ამბობს. სპეციალისტების განმარტებით, ერთი წლის ასაკში ბავშვებს კვების მხრივ დროებითი უკუსვლა ახასიათებთ. ამის მიზეზი ამ პერიოდში მადის ცვლილებაა. რადგან ბავშვი უკვე თქვენ მიერ მიღებული სხვადასხვა საკვების ჭამას იწყებს, მისი კვების რეჟიმი თავიდან ყალიბდება. კიდევ ერთი მიზეზი შეიძლება იყოს ამ პერიოდში ბავშვის დამოუკიდებლობის განცდის გაძლიერება და საკვებზე უარის თქმა, რათა საკუთარი ინდივიდუალურობა დაგიმტკიცოთ. უპირველეს ყოვლისა, გირჩევთ გახსოვდეთ, რომ ეს დროებითი მდგომარეობაა და ბავშვის წონის მატების შეჩერებაზე ზედმეტად არ ინერვიულოთ. ასევე ძალიან მნიშვნელოვანია, ბავშვთან მიმართებით იძულებისა და ზედმეტი კონტროლისა თუ მოთხოვნების ნაცვლად უფრო მოქნილი და მიმღებლური დამოკიდებულება გქონდეთ. შეგიმჩნევიათ, რომ როცა ბავშვს სახელით მიმართავთ ან უხმობთ, ის შემობრუნდება და გიყურებთ?') WHERE id = '34ee7ef2-aae6-4a89-859e-a1e8fda8d8a3';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვი უკვე იწყებს იმ სიტყვების მნიშვნელობის გააზრებას, რომლებიც ხშირად ესმის. ამის წყალობით, მას უკვე შეუძლია საკუთარი სახელისა და ოჯახის წევრების სახელების ერთმანეთისგან გარჩევა და შესაბამისად რეაგირება. 12-18 თვის პერიოდში, როდესაც მეტყველება საკმაოდ სწრაფად ვითარდება, ბავშვმა შეიძლება განუწყვეტლივ დაიწყოს აზრიანი ან უაზრო სიტყვების წარმოთქმა. რადგან მათი წარმოთქმა უფრო მარტივია, ეს სიტყვები ძირითადად ხმოვნებისგან იქნება შედგენილი. ბავშვის მეტყველების განვითარების ხელშესაწყობად შეგიძლიათ ხშირად დაუსვათ კითხვები და თავადვე უპასუხოთ მათ. მალე შეამჩნევთ, რომ ბავშვიც იწყებს ამ ჩვევის ათვისებას. გარკვეული დროის შემდეგ ისიც დაიწყებს თქვენთვის თავისებურ ენაზე პასუხების გაცემას.') WHERE id = 'c2629557-3a23-4c47-8fc6-f9dc2e9fe09e';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ ეტაპზე სრულიად ნორმალურია, რომ ბავშვი მუდმივად მოძრაობდეს და გაჩერება არ სურდეს. ის უკვე გაცნობიერებულად იწყებს მოძრაობას და იმის დანახვა, რომ რაღაცის გაკეთება შეუძლია, ძალიან აღაფრთოვანებს. სამწუხაროდ, ამის მაგალითებია ტუალეტის ქაღალდის რულონების გაშლა, მაღლა მოთავსებული ნივთების იატაკზე გადმოყრა და წიგნის თაროების არევა! 😊 ბავშვის მიზანი აქ უწესრიგობის შექმნა ან რაიმეს დაზიანება კი არა, სამყაროს აღმოჩენაა. მისთვის ძალიან სახალისო სწავლის მეთოდია ყველაფრის ადგილიდან დაძვრა, იატაკზე დაგდება, წინ გადაგდება და გადაყირავება, რასაც იპოვის და რაც მის ინტერესს მიიპყრობს. ბავშვის ამ ენთუზიაზმის დასაკმაყოფილებლად სასარგებლო შეიძლება იყოს ერთმანეთში ჩასაწყობი და დასაშლელ-ასაწყობი სათამაშოების შეძენა. ამგვარად, სახლში ნივთებსაც დაიცავთ და პატარასაც აარიდებთ პოტენციურ საფრთხეებს ამ აღმოჩენების დროს.') WHERE id = 'ce527391-7cf1-440d-bee3-7d79e8fa2c65';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მას შემდეგ, რაც ბავშვმა ცხოვრების პირველი წელი დაასრულა, დროა მის კვების რაციონში დაამატოთ ისეთი პროდუქტები, როგორიცაა პომიდორი, რომელიც პირველ თვეებში ძლიერ ალერგენად ითვლება. ადვილად ხელმისაწვდომი ბუნებრივი პროდუქტებით შეგიძლიათ ბავშვს ძალიან ჯანსაღი და ნოყიერი სუპიც მოუმზადოთ. ამისთვის დაგჭირდებათ: 1-2 ცალი პომიდორი და წიწაკა, 1 ცალი სტაფილო, 1 ცალი ხახვი და 1 კბილი ნიორი, 1 ჭიქა მაწონი, ფქვილი, მცირე რაოდენობით კვლიავი და პიტნა. ყველა ბოსტნეული კარგად გარეცხეთ, შემდეგ წიწაკა დაჭერით და წყალში მოხარშეთ. ამის შემდეგ პომიდორი, სტაფილო, ნიორი და ხახვი მოხარშულ წიწაკასთან ერთად ხელის ბლენდერით დააბლენდერეთ. დარწმუნდით, რომ მასაში კოშტები არ დარჩა და დაელოდეთ მის გაგრილებას. მიღებულ მასას დაუმატეთ 1 ჭიქა მაწონი, სანელებლები და ბოლოს იმდენი ფქვილი, რომ ცომის კონსისტენცია მიიღოს. შემდეგ 3-4 საათით დაასვენეთ. როდესაც ცომის ნაჭრები გაშრება, კვლავ დააბლენდერეთ, რათა ფხვნილად იქცეს. თქვენი ბავშვისთვის უგემრიელესი ტარჰანა მზადაა. გემრიელად მიირთვით! 😊') WHERE id = '5d048a4f-b4b0-4727-ad67-5bbff6c67131';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ ფიქრობთ, რომ ბავშვი, რომელიც ამ პერიოდში ძალიან აქტიური უნდა იყოს, ზედმეტად ძილიანია და საკმარისი ენერგია არ აქვს, შესაძლოა საჭირო გახდეს B12 ვიტამინის დონის შემოწმება. B12 ვიტამინი, რომელსაც ციანოკობალამინსაც უწოდებენ, ორგანიზმში სისხლის წითელი უჯრედების წარმოქმნაში მონაწილეობს. მისმა დეფიციტმა შეიძლება გამოიწვიოს დაღლილობა, სისუსტე, ძილიანობა, უმადობა, კანის სიმშრალე და უსიცოცხლო იერი. დეფიციტი ასევე შეიძლება გამოვლინდეს წონის კლებით, წონის მატების შეჩერებითა და პირის ღრუში „აფთების“ სახელით ცნობილი წყლულებით. ბავშვის ორგანიზმში დაბადებისას დაგროვილი B12 ვიტამინის მარაგი, როგორც წესი, პირველი ექვსი თვის განმავლობაში მისი განვითარებისთვის საკმარისია. თუმცა მეექვსე თვიდან ეს მარაგი მნიშვნელოვნად იკლებს და თუ ბავშვი დამატებითი საკვებიდან საკმარისი რაოდენობით B12 ვიტამინს ვერ მიიღებს, მის განვითარებაში შესაძლოა გარკვეული შეფერხებები წარმოიშვას. ამიტომ ძალიან მნიშვნელოვანია, ბავშვის კვების რაციონში დაამატოთ B12 ვიტამინით მდიდარი ხორცი, ქათამი, თევზი, ღვიძლი, კვერცხი, რძე და რძის პროდუქტები.') WHERE id = '6f7d0c13-65dd-4b38-aa89-153bf2d87600';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვთან ერთად ავტომობილით მგზავრობისას არაერთი მნიშვნელოვანი საკითხი უნდა გაითვალისწინოთ. მათგან უმთავრესია ბავშვის უსაფრთხოებისთვის მისი ასაკის შესაბამისი ავტომობილის სავარძლის გამოყენება. გარდა ამისა, რადგან ბავშვი ძალიან აქტიურია, მგზავრობისას შესაძლოა ავტომობილის კარი გააღოს. ამას შეიძლება ძალიან სერიოზული შედეგები მოჰყვეს, ამიტომ უაღრესად მნიშვნელოვანია, ავტომობილში ბავშვებისგან კარის ჩამკეტი ყოველთვის გააქტიურებული გქონდეთ. შესაძლოა გაინტერესებდეთ, რა მახასიათებლები უნდა ჰქონდეს ბავშვის ავტომობილის სავარძელს. შერჩევისას პირველ რიგში ბავშვის ასაკი და წონა უნდა გაითვალისწინოთ. იმისათვის, რომ სავარძელმა თავისი დანიშნულება შეასრულოს, ძალიან მნიშვნელოვანია ბავშვის ასაკისა და წონის შესაბამისი მოდელის არჩევა. ასევე უნდა შეამოწმოთ შესაკრავი ღვედების სიმტკიცე და უპირატესობა მიანიჭოთ სტანდარტების შესაბამის მოდელებს, რომლებსაც ხუთწერტილიანი უსაფრთხოების ღვედი აქვს.') WHERE id = 'b1729ded-cafa-45bd-8d10-000cf5711478';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'დაბადებიდან პირველ თვეებში ბავშვის კუჭის მოცულობა ძალიან მცირეა. ამიტომ ნორმალურია, რომ ღამით ხშირად შივდებოდეს და იღვიძებდეს. თუმცა მე-4 თვის შემდეგ, კუჭის ზრდასთან ერთად, ბავშვი ღამის ძილის დროს უფრო იშვიათად იღვიძებს. მე-6 თვიდან კი ბავშვის განვითარებისთვის უწყვეტი ღამის ძილი აუცილებელია. თვეების განმავლობაში ჩამოყალიბებული ჩვევების გამო, შესაძლოა ღამით გაღვიძება გარკვეული ხნით კვლავ გაგრძელდეს. ახლა, მე-13 თვეში, ბავშვმა შეიძლება მაშინაც გაიღვიძოს, როდესაც არ შია, რადგან ეს უკვე ჩვევად აქვს ქცეული. ძველი ჩვევის დასაძლევად მას თქვენი დახმარება სჭირდება. თუ ძუძუთი კვებავთ, შესაძლოა დაგეხმაროთ, თუ ბავშვს უშუალოდ დაძინების წინ აჭმევთ ან მომდევნო ეტაპის რძის ნარევს მისცემთ. ამგვარად, დანაყრების შეგრძნება მთელი ღამის განმავლობაში უფრო დიდხანს შეუნარჩუნდება, ნაკლებად გაიღვიძებს და თანდათან ძილის რეჟიმის ჩამოყალიბებაშიც დაეხმარებით.') WHERE id = 'b85a9b65-ee9c-45ae-a0a7-601fc164c0a0';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ ბავშვის მარგალიტივით პატარა კბილებზე ლაქებს ან კარიესის საწყის ნიშნებს ამჩნევთ, გირჩევთ, ამ საკითხს სერიოზულად მოეკიდოთ. რადგან ეს მდგომარეობა განსაკუთრებით ხშირად ბოთლით კვებისას გვხვდება, სპეციალისტები მას „ბოთლის კარიესს“ უწოდებენ. ბოთლის კარიესისთვის დამახასიათებელია ზედა კბილებზე უფრო ხშირი განვითარება და მოკლე დროში სხვა კბილებზე გავრცელება. თავდაპირველად ეს პრობლემა თეთრი და ყვითელი ლაქების სახით ვლინდება, გარკვეული დროის შემდეგ კი ყავისფერ-შავ შეფერილობას იღებს. ამის მიზეზია ბავშვისთვის მიცემული რძის უშუალო კონტაქტი კბილებთან და შემდგომ პირის ღრუს მოუვლელობის გამო საკვების ნარჩენების კბილის ზედაპირზე დაგროვება. მიუხედავად იმისა, რომ ამგვარი კარიესის მკურნალობა შესაძლებელია, უმჯობესია მისი განვითარება თავიდანვე აიცილოთ. პრობლემის წარმოქმნის ან პროგრესირების თავიდან ასაცილებლად, ყოველი კვების შემდეგ ბავშვს კბილები თითზე ჩამოსაცმელი კბილის ჯაგრისით გაუწმინდეთ.') WHERE id = '5019f758-f1eb-4332-8fb6-b0119b339b94';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ძალიან მნიშვნელოვანია, ბავშვის ყოველდღიურ რეჟიმში თამაშსა და მოძრაობას საკმარისი დრო დაეთმოს. თამაში და ფიზიკური აქტივობა ხელს უწყობს ბავშვის სოციალიზაციას, სამყაროს შეცნობას, უნარების განვითარებასა და საკუთარი თავის გაცნობას. ამ პერიოდში ბავშვი ცდილობს, თავისი შესაძლებლობები აღმოაჩინოს და გაარკვიოს, რისი გაკეთება შეუძლია და რისი — არა. ეს ყველაფერი მნიშვნელოვან როლს ასრულებს ენობრივი და მეტყველების უნარების უკეთ გამოყენებაში, თავდაჯერებულობის ზრდასა და იმ ძირითადი უნარების განვითარებაში, რომლებიც მას მთელი ცხოვრების განმავლობაში დაეხმარება. დღის განმავლობაში ფიზიკური აქტივობა ბავშვს მადასაც გაუუმჯობესებს. თუმცა ზედმეტად დიდხანს ფხიზლად ყოფნამ და გადაღლამ შესაძლოა მის მადაზე უარყოფითად იმოქმედოს. კვების რეჟიმის დარღვევის თავიდან ასაცილებლად, ჭამამდე ბავშვს დაახლოებით 20 წუთით დასვენების საშუალება უნდა მისცეთ. ამგვარად, კვების დროს ბავშვის ყურადღება მხოლოდ საჭმელზე იქნება მიმართული და თქვენც საუკეთესო შედეგს მიიღებთ.') WHERE id = 'd077fdd8-cbeb-4397-8aed-7974e355456b';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის ზრდის პროცესი ყველაზე სწრაფად დედის საშვილოსნოში მიმდინარეობს. ამ პერიოდში ბავშვი მთელი ცხოვრების განმავლობაში განვითარების ყველაზე სწრაფ ეტაპს გადის. დაბადების შემდეგ სწრაფი ზრდა კიდევ გარკვეული ხნით გრძელდება, თუმცა განსაკუთრებით 1 წლის ასაკის შემდეგ წონის მატების ტემპი თანდათან იკლებს. ამ თვეებში ბავშვის მიერ საშუალოდ 100-150 გრამის მომატება ნორმად ითვლება; არ უნდა ელოდოთ, რომ ის, პირველი თვეების მსგავსად, 900-1000 გრამს მოიმატებს. დროდადრო წონის უცვლელობა ან მცირედ დაკლებაც კი შეიძლება ნორმალური იყოს. უნდა იცოდეთ, რომ ზრდის ტემპი 6-10 წლამდე აღარ დაჩქარდება. ჩვილობის გარდა, ზრდა მხოლოდ ამ ასაკობრივ პერიოდში ჩქარდება. ბავშვის წონის ასეთი ცვლილება შეიძლება იმითაც იყოს გამოწვეული, რომ დღის განმავლობაში ძალიან აქტიურია და ჭამისთვის დროის დათმობა არ სურს. თუ ექიმის მიერ ჩატარებული გეგმური შემოწმებებისა და სისხლის ანალიზების შედეგად ჯანმრთელობის რაიმე პრობლემა არ გამოვლენილა, სანერვიულო არაფერია.') WHERE id = '1bf4db64-14c4-4c92-9597-a3543f95396e';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის კვებისას შესაბამისი გემოს შერჩევა, საკვები ღირებულების გათვალისწინება და კვების დროის დაგეგმვა თქვენი პასუხისმგებლობაა. თუმცა თქვენ მიერ მომზადებული საკვების რაოდენობა თავად ბავშვმა უნდა განსაზღვროს. ასევე, მნიშვნელოვანია, კვების რეჟიმი მხოლოდ ძირითადი კვებებისგან არ შედგებოდეს და ბავშვმა მათ შორის წასახემსებელიც მიიღოს — ეს მისი მადის შენარჩუნებას შეუწყობს ხელს. თუ მეტი საკვების მისაღებად მასზე ზეწოლას მოახდენთ, ამან თქვენ შორის გარკვეული უარყოფითი გამოცდილება შეიძლება შექმნას. კვების ჩვევების ჩამოყალიბებისას მიღებული ასეთი გამოცდილების კვალი ბავშვს შესაძლოა მთელი ცხოვრება გაჰყვეს. რაც მეტად გაუჯიუტდებით, მით უფრო ძლიერ წინააღმდეგობას გაგიწევთ. ამიტომ დასაწყისში მცირე ულუფების მომზადება და შემდეგ ბავშვის მადისა და სურვილის მიხედვით მათი გაზრდა კარგი არჩევანი იქნება.') WHERE id = '540d6c51-7eac-42c0-8644-43d0623f6aca';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვმა უკვე დაიწყო გარემოს შესწავლა და განსაკუთრებით იმ ადგილებით ინტერესდება, რომელთაგანაც მის მოშორებას ცდილობთ. სააბაზანო, საპირფარეშო, სამზარეულო და, თუ სახლში გაქვთ, კიბე მისთვის სერიოზულ საფრთხეს შეიძლება წარმოადგენდეს. ამ ეტაპზე ბავშვს უკვე შეუძლია კიბეზე ასვლა, თუმცა ჩამოსვლას ჯერ სათანადოდ ვერ ახერხებს. ამიტომ აუცილებელია ზომების მიღება დაცემისა და ტრავმის რისკის შესამცირებლად. სახლში პატარასთვის უსაფრთხო გარემოს შესაქმნელად შეგიძლიათ სპეციალური საბავშვო დამცავი ჭიშკრები მოიძიოთ. სხვადასხვა სახის ჭიშკრის შერჩევისას რამდენიმე საკითხს უნდა მიაქციოთ ყურადღება: მისი სიმაღლე ბავშვის სიმაღლეზე მეტი უნდა იყოს. ასევე ძალიან გამოგადგებათ გამძლე, ჩასაკეტი მოდელები, რომელთა ადგილიდან მოხსნასაც ბავშვი ვერ შეძლებს.') WHERE id = '3e9a697a-9c74-4491-8b57-a79e63e4f840';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მიუხედავად იმისა, რომ ბავშვის კანი ისეთი თხელი აღარ არის, როგორიც დაბადებიდან პირველ თვეებში იყო, ის ჯერ კიდევ ძალიან მგრძნობიარეა. ამიტომ მის კანზე ზრუნვა იმავე ყურადღებით უნდა განაგრძოთ. მზის სხივები ბავშვისთვის ძალიან სასარგებლოა, თუმცა დღის გარკვეულ მონაკვეთში ისინი მისი მგრძნობიარე კანისთვის შესაძლოა სახიფათო იყოს. მზის მავნე ზემოქმედებისგან დასაცავად უმჯობესია, შუადღის საათებში, როდესაც მზე ყველაზე მაღლაა, გარეთ არ გახვიდეთ. თუ გასვლა აუცილებელია, ბავშვი ქუდით ან საბავშვო ქოლგით უნდა დაიცვათ, ან მისი კანისთვის შესაფერისი მზისგან დამცავი კრემი გამოიყენოთ. გარდა ამისა, განსაკუთრებული ყურადღება მიაქციეთ, რომ ბავშვის ტანსაცმელი ჰაერგამტარი ქსოვილისგან იყოს დამზადებული და ოფლიანობას არ იწვევდეს. კანთან უშუალო შეხებაში მყოფმა შეუფერებელმა ტანსაცმელმა შესაძლოა გაღიზიანება გამოიწვიოს. რადგან ამან შეიძლება ფორების დახშობა და ისეთი კანის პრობლემები გამოიწვიოს, როგორიცაა ოფლიანა, გირჩევთ, პრევენციული ზომები წინასწარ მიიღოთ.') WHERE id = 'baabf765-39b9-4839-adad-77a6c863f562';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ ეტაპზე ბავშვს უკვე დაახლოებით 3-4 კბილი აქვს. ეს კი ნიშნავს, რომ სტომატოლოგთან ვიზიტის დროა! მრავალწლიანი კვლევების საფუძველზე, ამერიკის პედიატრიის აკადემია რეკომენდაციას იძლევა, რომ ბავშვი პირველად სტომატოლოგმა დაახლოებით 1 წლის ასაკში გასინჯოს. კბილების ამოჭრის პერიოდში შემოწმებები შეიძლება უფრო ხშირად ჩატარდეს, ხოლო ყველა კბილის ამოსვლის შემდეგ — წელიწადში ორჯერ. ძალიან მნიშვნელოვანია, რომ ბავშვს სტომატოლოგიური შემოწმების არ შეეშინდეს და ამასთან დაკავშირებით ფობია არ განუვითარდეს. ამიტომ ექიმთან მისვლამდე კარგი იქნება, თუ ბავშვს აუხსნით, რა ელოდება. ამ ეტაპის გამოტოვებამ იმ მიზეზით, რომ ბავშვი ვერაფერს გაიგებს, შესაძლოა მომავალში სტომატოლოგის შიში გამოიწვიოს. ასევე ძალიან მნიშვნელოვანია, რომ თქვენ მიერ შერჩეული სტომატოლოგი ღიმილიანი და მომთმენი იყოს. ამიტომ შეგიძლიათ ახლობლებსა და ნაცნობებს ექიმის შესახებ ინფორმაცია გამოჰკითხოთ.') WHERE id = '0c5d07c7-c8fe-42d1-b69e-2a3e6839e46d';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვი უკვე მთლიანად გადავიდა მყარ საკვებზე. ამის წყალობით მასაც შეუძლია ადვილად მიირთვას ის საკვები, რომელსაც თქვენ იღებთ. თუმცა ზოგიერთი პროდუქტი ნაწლავებში აირების დაგროვებასა და შებერილობას იწვევს. ბუნებრივია, ეს მდგომარეობა ბავშვსაც შეეხება. თითოეული ორგანიზმი ერთსა და იმავე საკვებზე სხვადასხვაგვარად რეაგირებს. კომბოსტო, ყვავილოვანი კომბოსტო, ბროკოლი, პარკოსნები და რძის პროდუქტები, ზოგადად, იმ საკვებს მიეკუთვნება, რომელიც ხშირად აირების დაგროვებას იწვევს. თუმცა ეს არ ნიშნავს, რომ აღნიშნული პროდუქტები თქვენს ბავშვსაც აუცილებლად შეუქმნის პრობლემას. დაკვირვებით შეძლებთ განსაზღვროთ, რომელი კერძები იწვევს ბავშვში შებერილობასა და დისკომფორტს. აირების დაგროვების შემთხვევაში ბავშვის მუცლის მსუბუქი, ნაზი მოძრაობებით მასაჟი ან უთოთი გამთბარი პირსახოცის მუცელზე დადება შეიძლება ეფექტური გამოსავალი იყოს.') WHERE id = '9f63d50f-7166-4560-9204-76cd4e4af961';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'როგორც დედის მუცელში გატარებული პერიოდი, ისე გარესამყაროში ცხოვრების პირველი წლები ბავშვის განვითარებისთვის უმნიშვნელოვანეს საფუძველს ქმნის. მიუხედავად იმისა, რომ ხასიათის ჩამოყალიბება, როგორც წესი, 0-6 წლის ასაკში ხდება, დადგენილია, რომ ეს პროცესი სინამდვილეში ჯერ კიდევ ორსულობის პერიოდში იწყება. ეს უაღრესად მნიშვნელოვანი საკითხია, რადგან განსაზღვრავს, როგორი ადამიანი გახდება ბავშვი მომავალში და ცხოვრების როგორი წესი ექნება. ბავშვის ინდივიდუალურობის მიღება ძალიან მნიშვნელოვანია, რათა მომავალში მან სოციალურ გარემოსთან ადაპტაცია შეძლოს. ამიტომ მას გზა უნდა უჩვენოთ და არასოდეს მოაკლოთ ყურადღება და სიყვარული. სხვადასხვა მოვლენისას თქვენ მიერ გამოხატული შფოთვა და მღელვარება ბავშვისთვის შეიძლება მაგალითი გახდეს. ძალიან მნიშვნელოვანია, მასთან ბედნიერი ჩანდეთ, თქვენი სირთულეები მასზე არ გადაიტანოთ და კარგი მისაბაძი მაგალითი იყოთ. თქვენი ბედნიერება ბავშვის ბედნიერების ერთ-ერთი უმთავრესი წინაპირობაა. გახსოვდეთ: "ბედნიერი დედები, ბედნიერი ბავშვები!"😊') WHERE id = 'bc3f1891-4234-45fd-82e4-8d5e9ccf24f4';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ვინაიდან თევზის ცილა ცხოველური წარმოშობისაა, მისი ბიოშეღწევადობა, ანუ სხეულის ცილად გარდაქმნის ხარისხი, საკმაოდ მაღალია. ცილის ეს წყარო ერთ-ერთი უმნიშვნელოვანესი ნივთიერებაა ახალი ქსოვილების წარმოსაქმნელად ბავშვის სწრაფი ზრდისა და განვითარების პერიოდში. ამასთან, თევზში შემავალი ომეგა-3 ცხიმოვანი მჟავები ბავშვის ნერვული სისტემის განვითარებას მნიშვნელოვნად უწყობს ხელს. ბოლო წლებში ჩატარებული კვლევები აჩვენებს, რომ განსაკუთრებით იმ ბავშვებს, რომლებიც თევზს რეგულარულად მიირთმევენ, ინტელექტის მაჩვენებლები უფრო მაღალი აქვთ. აქ საუბარია IQ-ის დაახლოებით 10-15 ქულით ზრდაზე. ამიტომ ბავშვის მიერ კვირაში სულ მცირე 2-ჯერ თევზის რეგულარულად მიღება ძალიან მნიშვნელოვანია როგორც მისი ფიზიოლოგიური, ისე გონებრივი განვითარებისთვის. თევზმა საკვები ღირებულება რომ არ დაკარგოს, ბავშვისთვის საუკეთესო არჩევანი ღუმელში გამომცხვარი თევზი იქნება.') WHERE id = '981b41f5-021b-47c3-ab24-fd2239fed961';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი დღეს ადრე იწყებს და მთელი დღის განმავლობაში ძალიან აქტიურია! ეს კი ნიშნავს, რომ მას ბევრი ენერგია სჭირდება. ამიტომ საუზმე ბავშვის ყველა სხვა კვებაზე უფრო მნიშვნელოვანია. დღის პირველ საათებში მიღებული საუზმე მის მეტაბოლიზმს აამოქმედებს და მეტი ენერგიით უზრუნველყოფს. ბავშვის საუზმეში ენერგიის კარგ წყაროდ სხვადასხვა სახის ყველი შეგიძლიათ გამოიყენოთ. ამ მხრივ, ასანთის კოლოფის ზომის უმარილო თეთრი ყველი ან 3-4 ჩაის კოვზი უმარილო ხაჭო შესანიშნავი არჩევანი იქნება. თუ ბავშვს კვერცხზე ალერგია არ აქვს, შეგიძლიათ ერთი კვერცხითა და სრულმარცვლოვანი ხორბლის ფქვილით ძალიან გემრიელი ბლინებიც მოუმზადოთ. ზოგიერთ დილას კი სეზონური ხილით მომზადებული ხილის იოგურტი დიდწილად დააკმაყოფილებს მის მოთხოვნილებას ცილასა და ვიტამინებზე და დღის განმავლობაში საჭირო ენერგიით უზრუნველყოფს.') WHERE id = '89756ae1-dd1f-454f-b774-e30f54db7adf';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'გრიპი ბავშვებში ერთ-ერთი ყველაზე გავრცელებული ინფექციური დაავადებაა. ზედა სასუნთქ გზებზე მოქმედი ვირუსებით გამოწვეული ეს დაავადება იმ პრობლემებს შორისაა, რომლებსაც შესაძლოა დროდადრო ყველა ბავშვი შეხვდეს. როდესაც ბავშვს გრიპი აქვს, თქვენი ორგანიზმი დედის რძეში დამატებით ანტისხეულებს გამოიმუშავებს, რათა ბავშვის იმუნიტეტი გააძლიეროს და მის ორგანიზმს დაავადების გამომწვევ მიკროორგანიზმებთან ბრძოლაში დაეხმაროს. თუმცა, თუ ბავშვს ძუძუთი არ კვებავთ, სავარაუდო გრიპის დროსაც ბევრი რამის გაკეთება შეგიძლიათ. მაგალითად, თქვენ მიერ მომზადებული ქათმის ბულიონის წვნიანი გრიპით დაავადებული ბავშვისთვის საკმაოდ სასარგებლო იქნება. ამ პერიოდში ბავშვს ბევრი სითხე უნდა მისცეთ, რათა მისმა ორგანიზმმა დაავადებას ადვილად გაუმკლავდეს. ამიტომ ხშირად დაალევინეთ წყალი და შეგიძლიათ სეზონური ბოსტნეულითა და ქათმის ძვლის ბულიონით მომზადებული წვნიანებიც მისცეთ.') WHERE id = '0b73e61f-6698-462a-8b7e-eef178ac3033';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'რადგან ბავშვმა უკვე აქტიურად დაიწყო სიარული, მე-14 თვე მისთვის ადრეული ბავშვობის პერიოდში გადასვლას შეიძლება ნიშნავდეს. ამ თვეში ბავშვს გეგმური აცრა არ ეკუთვნის. თუმცა ექიმმა შესაძლოა რუტინული შემოწმებისთვის კლინიკაში დაგიბაროთ. ამ ვიზიტისას ბავშვის საერთო განვითარების შესაფასებლად გაზომავენ მის წონასა და სიმაღლეს, ხოლო ტვინის განვითარების შესაფასებლად — თავის გარშემოწერილობას. ექიმმა შესაძლოა ასევე დაგისვათ კითხვები ბავშვის კვების რეჟიმისა და ზოგიერთი ძირითადი უნარის შესახებ. მე-14 თვის ბავშვის განვითარების ცხრილის მიხედვით, ამ ასაკში ბიჭების საშუალო წონა 10.800 გრამია. 14 თვის გოგონების საშუალო წონა კი 10.100 გრამია. გახსოვდეთ, რომ ეს მაჩვენებლები შეიძლება მნიშვნელოვნად განსხვავდებოდეს. 14 თვის ბავშვებისთვის წონის უსაფრთხო დიაპაზონი 8300 გრამიდან 13.400 გრამამდეა. დღენაკლულ ბავშვებში კი მაჩვენებლები შესაძლოა ჯერ კიდევ ამ მნიშვნელობებზე დაბალი იყოს.') WHERE id = '65e79653-9811-4ac2-a32e-9c82ef7262dc';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი შესაძლოა პირველ თვეებთან შედარებით უფრო გამხდარი მოგეჩვენოთ. ზოგიერთი დედისთვის ეს საკმაოდ შემაშფოთებელია. თუმცა ბავშვის მოსალოდნელზე დაბალ წონას მრავალი განსხვავებული მიზეზი შეიძლება ჰქონდეს. მთავარი მიზეზი ბავშვის მადის მცირედით დაქვეითება და, შესაბამისად, მიღებული კალორიების შემცირებაა. ორგანიზმს ყოველდღიური ფუნქციებისთვის, როგორებიცაა საჭმლის მონელება, სუნთქვა და ნივთიერებათა გამოყოფა, კალორიების გარკვეული რაოდენობა სჭირდება. თუ ბავშვი ამ საჭიროებაზე ნაკლებ კალორიას იღებს, წონის მცირედით კლება ნორმალურია. განსაკუთრებით მას შემდეგ, რაც სიარული დაიწყო და მუდმივად მოძრაობს, მიღებული და დახარჯული კალორიები შესაძლოა ერთმანეთს ვერ აბალანსებდეს. ჩვეულებრივ, ბავშვს მადა რამდენიმე თვეში უბრუნდება. ამიტომ ამ პერიოდში წონის მცირედით კლება ნორმალურად მიიჩნევა.') WHERE id = '3ecdedd3-7b18-4dac-bf11-4e204ffa1806';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის ძალიან მგრძნობიარე კანისთვის დიდი მნიშვნელობა აქვს იმ შამპუნების შემადგენლობას, რომლებსაც მისი დაბანისას იყენებთ. ბავშვისთვის, რომლის იმუნური სისტემა ჯერ არ არის ისე განვითარებული, როგორც ზრდასრული ადამიანის, უპირატესობა უნდა მიანიჭოთ შამპუნებს, რომლებიც არ შეიცავს სპირტს, სურნელოვან დანამატებსა და შენახვის ვადის გასახანგრძლივებლად გამოყენებულ ქიმიურ ნივთიერებებს. შამპუნში შემავალ ზოგიერთ ქიმიურ ნივთიერებაზე ბავშვის ჯერ კიდევ ჩამოყალიბების პროცესში მყოფმა იმუნურმა სისტემამ შესაძლოა ალერგიული რეაქციით უპასუხოს. ასევე, შერჩეული შამპუნის pH-ის მაჩვენებელი ძალიან მნიშვნელოვანია კანის გარეთა შრის დაცვისა და ჯანმრთელობისთვის. ნეიტრალური, ანუ 7-ის ტოლი pH-ის მქონე შამპუნები ყველაზე უსაფრთხოდ მიიჩნევა, რადგან ბავშვის კანზე რეაქციას არ იწვევს. მიუხედავად იმისა, რომ ქაფის წარმოქმნა შესაძლოა სისუფთავისთვის მნიშვნელოვან თვისებად მოგეჩვენოთ, სინამდვილეში ეს მოსაზრება მცდარია. ამიტომ გირჩევთ, შამპუნებს შორის ისეთი პროდუქტები შეარჩიოთ, რომლებიც არ შეიცავს ქაფის წარმოსაქმნელად გამოყენებულ მავნე ქიმიურ ნივთიერებას — SLS-ს.') WHERE id = 'f8b0ec51-f351-462b-96a6-b82037c58e61';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'რამდენად ყურადღებითაც უნდა უვლიდეთ ბავშვს, ზოგჯერ ავადმყოფობა გარდაუვალია. იმის გამო, რომ მისი იმუნური სისტემა ჯერ სრულად არ არის ჩამოყალიბებული, გრიპმა და გაციებამ ბავშვის ორგანიზმზე ადვილად შეიძლება იმოქმედოს. ცხვირის გაჭედვა, მოუსვენრობა და საკვებზე უარის თქმა ბავშვის ავადმყოფობის პირველი ნიშნებია. ამას შესაძლოა დაემატოს მშრალი ხველა, დიარეა, სისუსტე და გაუჩერებელი ტირილის ეპიზოდები. როდესაც ბავშვი ავად გახდება, პირველ რიგში მისი სხეულის ტემპერატურა უნდა შეამოწმოთ და ეს გარკვეული შუალედებით გაიმეოროთ. სრულფასოვანი ძილი და უხვად დასვენება ბავშვს სწრაფად გამოჯანმრთელებაში დაეხმარება. ამ პერიოდში არ უნდა აიძულოთ ჭამა და უმჯობესია, უპირატესობა უფრო თხევად საკვებს მიანიჭოთ.') WHERE id = '9ef652c0-6810-47ad-9c0e-cf7c58bc940f';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'განსაკუთრებით სეზონების ცვლილებისას ბავშვს, რომლის სასუნთქი გზებიც ჯერ ძალიან ვიწროა, შესაძლოა ცხვირი ხშირად გაეჭედოს. ცხვირის გაჭედვა არა მხოლოდ სუნთქვას ართულებს, არამედ შეიძლება კვებისა და ძილის რეჟიმზეც იმოქმედოს, ამიტომ ამ საკითხს ყურადღება უნდა მიაქციოთ. თუ ბავშვს ცხვირი ხშირად ეჭედება, ამის მიზეზი შესაძლოა ადენოიდები, ჰაერის სიმშრალე ან ზოგიერთი ალერგიული მდგომარეობა იყოს. ამიტომ ოთახში, სადაც ბავშვი იმყოფება, შეგიძლიათ ჰაერის დამატენიანებელი გამოიყენოთ ან გათბობის რადიატორებზე სითბოგამძლე წყლის ჭურჭელი მოათავსოთ. წყლის აორთქლებასთან ერთად ოთახში ტენიანობა მოიმატებს და სიმშრალე შემცირდება. ცხვირის გაჭედვისას ბავშვის მდგომარეობის შესამსუბუქებლად შეგიძლიათ გამოიყენოთ აფთიაქში შეძენილი ან სახლში მომზადებული მარილიანი ხსნარი. მარილიანი ხსნარი არბილებს ბავშვის ცხვირის გამჭედავ ლორწოს და სასუნთქი გზების გასახსნელად ძალიან ეფექტური საშუალებაა.') WHERE id = '9c0cb79b-68bb-4505-a06f-a92e33fff4b9';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'სეზონური ხილისა და ბოსტნეულის მიღება ბავშვისთვის ვიტამინების მხრივ ძალიან მნიშვნელოვანია. ამასთანავე, კვების რაციონში რეგულარულად უნდა შეიტანოთ თევზი, რომელიც ორგანიზმისთვის საჭირო ცილისა და ომეგა-3 ცხიმოვანი მჟავების ერთ-ერთი საუკეთესო წყაროა. საზოგადოებაში ბავშვის მიერ თევზის მიღებასთან დაკავშირებით გარკვეული ეჭვები არსებობს. თუმცა სპეციალისტები ხაზგასმით აღნიშნავენ, რომ ახალი თევზი საფრთხეს არ წარმოადგენს. ამიტომ ბავშვისთვის დაკონსერვებული თევზის ნაცვლად შეგიძლიათ ახალი ზღვის თევზი შეარჩიოთ. გადაცდენისა და ყელში ფხის გაჩხერის რისკის გამო, უმჯობესია, ჯერჯერობით მოერიდოთ პატარა და ბევრფხიან თევზს. ასევე, ზღვის ფსკერზე მცხოვრებ თევზებში მძიმე მეტალები შესაძლოა უფრო მეტად დაგროვდეს, ამიტომ შეგიძლიათ უპირატესობა ზედაპირულ წყლებში მცხოვრებ თევზებს მიანიჭოთ.') WHERE id = '50c822ac-6408-41dd-b9a0-333f36a25421';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ვიცით, რომ განსაკუთრებით ზაფხულის თვეებში ბავშვის კანის გამოყელვის თავიდან ასაცილებლად ბევრ მეთოდს ცდით. ამ მიზნით გამოყენებული ერთ-ერთი საშუალება საბავშვო პუდრია. სპეციალისტები ფხვიერი პუდრის გამოყენებას არ გვირჩევენ, რადგან მან შესაძლოა ბავშვის ფილტვებზე მავნე გავლენა მოახდინოს. თუმცა, თუ ბავშვის მოვლისას პუდრს მაინც იყენებთ, რამდენიმე საკითხს უნდა მიაქციოთ ყურადღება. მაგალითად, უნდა მოერიდოთ ბრენდებს, რომელთა პროდუქტებიც შეიცავს ალუმინს, სურნელოვან დანამატებსა და კანცეროგენული მოქმედების კონსერვანტებს. თუ ფიქრობთ, რომ საბავშვო პუდრის მომზადება თავად შეგიძლიათ, სრულიად ბუნებრივ ვარიანტს შემოგთავაზებთ. დაგჭირდებათ მხოლოდ ნახევარი ჩაის ჭიქა სიმინდის სახამებელი და რამდენიმე წვეთი ბუნებრივი ეთერზეთი. სახამებელი ჩაყარეთ ჭურჭელში და ზეთი დააწვეთეთ. კოშტების წარმოქმნის თავიდან ასაცილებლად ნარევი შეგიძლიათ სამზარეულოს კომბაინში დაამუშაოთ. მომზადებული ნარევი ძველ პუდრის ჭურჭელში ან გამოუყენებელ, მსხვილნახვრეტებიან სამარილეში ჩაყარეთ. ბუნებრივი საბავშვო პუდრი მზადაა! 😊') WHERE id = '3120d7eb-f951-4312-bcfe-96b26a90343b';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში ბავშვის უმადობამ შესაძლოა ჯანსაღი წასახემსებლების რეცეპტების ძიებისკენ გიბიძგოთ. ეს გემრიელი და სასარგებლო საკვები ბავშვს ჭამის სურვილს გაუჩენს და დღის განმავლობაში საჭირო ენერგიით უზრუნველყოფს. ახლა კი გაგიზიარებთ ორცხობილის რეცეპტს, რომელიც ბავშვს ძალიან მოეწონება! 😊 ასევე შეგიძლიათ გაეცნოთ ასობით რეცეპტს ჩვენს განყოფილებაში „რეცეპტები“! საჭირო ინგრედიენტები ძალიან მარტივია: 200 გრამი სრულმარცვლოვანი ხორბლის ფქვილი, 100 გრამი კარაქი, 100 გრამი მანანის ბურღული, 1 ცალი დიდი ბანანი და 1 სუფრის კოვზი იოგურტი. ბანანი წვრილად დაჭერით და ჩანგლით კარგად დასრისეთ. ყველა ინგრედიენტი ერთმანეთს შეურიეთ და კარგად მოზილეთ. მომზადებულ ცომს დააფარეთ და მაცივარში დაახლოებით 20 წუთით გააჩერეთ. შემდეგ ცომს ბავშვისთვის საინტერესო ფორმები მიეცით და 180 გრადუსზე დაახლოებით 15-20 წუთის განმავლობაში გამოაცხვეთ. გემრიელად მიირთვით! 😊') WHERE id = '3bed5af2-3e1c-44f1-9796-6af7f86a01fc';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ვიცით, რომ თქვენც, ისევე როგორც ყველა სხვა დედას, გსურთ, ბავშვი საუკეთესოდ აღზარდოთ. იმის სწავლების საუკეთესო გზა, თუ როგორ გახდეს კარგი ადამიანი, არის, ყოველთვის საკუთარი მაგალითით აჩვენოთ, როგორ იქცევა კარგი ადამიანი. ბავშვი კარგი დამკვირვებელი და მიმბაძველია, ამიტომ ყურადღება ჯერ საკუთარ ქცევას, შემდეგ კი მის გარშემო მყოფ ადამიანებს უნდა მიაქციოთ. იმ ადამიანების ქცევა, რომლებსაც ბავშვი ხშირად ხედავს და რომლებთანაც ურთიერთობს, მისი ხასიათის საფუძველს ქმნის. ბავშვს, რომელიც უკვე დამოუკიდებლობას აფასებს და ინდივიდუალიზაციის ეტაპზეა, ზედმეტი შეზღუდვები არ უნდა დაუწესოთ. მისთვის სასურველი მოქმედების აკრძალვამ შესაძლოა უარყოფითი რეაქციები გამოიწვიოს. ეს რეაქციები შეიძლება გამოვლინდეს ხანმოკლე ტირილის ეპიზოდებით ან ბრაზის შეტევებით, რომელთა დროსაც მან შესაძლოა საკუთარ თავს ან გარშემო მყოფებს ზიანი მიაყენოს.') WHERE id = '60a3bb7b-e6b8-4840-8b06-634744d70eda';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის ნაწლავები, რომლებიც დაბადებამდე სტერილურ მდგომარეობაშია, მშობიარობის მეთოდის, გენეტიკური თავისებურებების, კვების ტიპისა და გარემოსთან კონტაქტის გავლენით გარკვეულ ცვლილებებს განიცდის. ყველა ეს ფაქტორი ბავშვის ნაწლავებში საჭმლის მონელების ხელშემწყობ, თითოეული ადამიანისთვის დამახასიათებელ დაახლოებით 500-ზე მეტი სახეობის ბაქტერიულ გარემოს აყალიბებს. ამ მრავალფეროვანი ბაქტერიების საერთო რაოდენობამ შეიძლება მილიარდებს მიაღწიოს. სწორედ ამიტომ ნაწლავის ფლორას სამედიცინო ენაზე დავიწყებულ ორგანოს უწოდებენ. ეს ბაქტერიები, რომლებიც განსაკუთრებით დიდი რაოდენობით გვხვდება მსხვილ ნაწლავსა და წვრილი ნაწლავის ბოლო ნაწილებში, ბავშვის ორგანიზმის შინაგანი წონასწორობის შენარჩუნებაში უმნიშვნელოვანეს როლს ასრულებს. ნაწლავის ფლორა ძალიან ნატიფ წონასწორობაზეა დაფუძნებული და მისმა დარღვევამ შეიძლება საჭმლის მონელებისა და აირების დაგროვების სერიოზული პრობლემები გამოიწვიოს. ამიტომ ძალიან მნიშვნელოვანია, ექიმის რეკომენდაციის გარეშე არ გამოიყენოთ ანტიბიოტიკები, რომლებმაც შესაძლოა ნაწლავის ფლორის წონასწორობა დაარღვიოს.') WHERE id = '2f472f69-49f6-4199-b448-65d485bc6ba1';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ ფიქრობთ, რომ ბავშვი ცოტას ჭამს და ამის გამო მცირე წონა აქვს, შეგიძლიათ მისი ასაკისთვის უსაფრთხო წონის დიაპაზონი შეამოწმოთ. თუ ბავშვის წონა ამ უსაფრთხო დიაპაზონზე დაბალია, ეს არ ნიშნავს, რომ მის განვითარებასთან დაკავშირებული პრობლემა არსებობს. შესაძლოა, უბრალოდ ექიმის უფრო ხშირი მეთვალყურეობა იყოს საჭირო. ყველა ბავშვს საკუთარი, ჯანსაღი ჰორმონული ბალანსი აქვს. ამიტომ ბავშვის დაახლოებით იმავე პერიოდში დაბადებულ თანატოლებთან შედარებას აზრი არ აქვს. 14 თვის ბავშვი შეიძლება ერთნაირად ჯანმრთელი იყოს როგორც 8 kq, ისე 13 kq წონის შემთხვევაში. თქვენი და თქვენი პარტნიორის აღნაგობა, ნივთიერებათა ცვლის სიჩქარე და სიმაღლე ბავშვის განვითარებაზე მოქმედი ძირითადი ფაქტორებია. მაგალითად, თუ ბავშვის მშობლები დაბლები არიან, ის შესაძლოა თანატოლებთან შედარებით დაბალი იყოს და, შესაბამისად, ნაკლებსაც იწონიდეს. ამასთანავე, თუ თქვენი ბავშვი ნაადრევად დაიბადა, მას თანატოლების სიმაღლისა და წონის დიაპაზონთან მისაახლოებლად ჯერ კიდევ დაახლოებით 2 წელი აქვს.') WHERE id = 'ee025328-9a30-44d7-887a-d226fa6d94ad';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, '14 თვის ბავშვის ფიზიკური განვითარებისას მოსალოდნელია, რომ წინა თვეებთან შედარებით უკეთ იაროს და ფეხზე უფრო დიდხანს იდგეს. დროთა განმავლობაში ეს ბავშვის თავდაჯერებულობას ზრდის და უფრო მეტი მოძრაობისკენ უბიძგებს. ყოველი წაქცევისას დახმარებამ ამ ეტაპზე შესაძლოა მის თავდაჯერებულობაზე უარყოფითად იმოქმედოს. ამიტომ, მიუხედავად იმისა, რომ ეს თქვენთვის რთული შეიძლება იყოს, უნდა ისწავლოთ, აუცილებლობის გარეშე არ ჩაერიოთ. როცა ბავშვი წაიქცევა, მასთან მისვლისას უარყოფითი რეაქცია არ უნდა გამოავლინოთ. პირიქით, უთხარით სიტყვები, რომლებიც კვლავ მოძრაობისკენ წაახალისებს. მასთან მისვლისას გაბრაზების ან სევდიანი გამომეტყველებით შეხედვის ნაცვლად შეგიძლიათ უთხრათ, რომ ყველაფერი რიგზეა და ის ამას შეძლებს. როცა ბავშვი ამას დამოუკიდებლად მოახერხებს, საფუძველი ჩაეყრება იმას, რომ მომავალში სირთულეებთან ეფექტურად გამკლავება შეძლოს.') WHERE id = '414824fb-64c6-4b3c-bb3a-769c24ddf66c';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენს ბავშვს შესაძლოა უკვე შეძენილი ჰქონდეს ახალი უნარები, მაგალითად, მისკენ ნასროლი ნივთის ან სათამაშოს დაჭერა და გაგორება. ეს ხელისა და თვალის განვითარებული კოორდინაციის შედეგია, რომლის სრულად ჩამოყალიბებასაც შეიძლება გარკვეული დრო დასჭირდეს. ამ კოორდინაციის გასაუმჯობესებლად შეგიძლიათ მასთან ერთად ძალიან სახალისო თამაშები ითამაშოთ. მაგალითად, აიღეთ ბავშვის საყვარელი ფერის საშუალო ზომის ბურთი და მის პირისპირ დაჯექით. მიაპყარით მისი ყურადღება ბურთისკენ და მისკენ გააგორეთ. მან შეიძლება ბურთი დაიჭიროს, თუმცა ჯერ ვერ შეძლოს თქვენკენ უკან გამოგორება. შესაძლოა, ბურთი ხელში აიღოს და გარკვეული ხნით დაათვალიეროს. შეგიძლიათ წაახალისოთ, რომ ბურთი უკან გამოგიგზავნოთ. ეს თამაში შეიძლება მალე ბავშვის საყვარელ გასართობად იქცეს. გაერთეთ! 😊') WHERE id = '6f46b0f1-1f3e-4425-a5dd-6eff8b819a96';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'როდესაც ბავშვი თქვენთვის სასურველად იქცევა, ჯილდოდ არასოდეს უნდა მისცეთ ჯანმრთელობისთვის საზიანო საკვები. ვაფლი, შოკოლადი, ჩიფსები და ტკბილეული კვლავ იმ პროდუქტების სიაშია, რომლებსაც ბავშვი უნდა მოერიდოს. ამის მიზეზი ამ შეფუთულ პროდუქტებში შემავალი ქიმიური ნივთიერებებია. მაგალითად, ყველა დამატკბობელმა, განსაკუთრებით კი ასპარტამმა, მომავალში შესაძლოა სიმსუქნე და ჯანმრთელობის სხვა პრობლემები გამოიწვიოს. ხელოვნურმა არომატიზატორებმა და საღებავებმა კი ბავშვებში შესაძლოა ყურადღების გაფანტვა და ჰიპერაქტიურობა გამოიწვიოს. ამ ნივთიერებებს ბავშვის ორგანიზმზე ტოქსიკური ზემოქმედებაც შეიძლება ჰქონდეს, რის გამოც ღვიძლის დაზიანების რისკი მაღალია. ამიტომ, ბავშვისთვის "ჯილდოს" სახელით მავნე მზა საკვების მიცემის ნაცვლად, შეგიძლიათ ისეთი ალტერნატივები შესთავაზოთ, რომლებიც მას გაახარებს და მის ჯანმრთელობას ზიანს არ მიაყენებს.') WHERE id = 'aa4f705b-b1bf-4a27-a480-8e278fc3f58d';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ ამ პერიოდში თქვენი ბავშვი ძალიან მოუსვენარია და ღამით ძილი დაერღვა, ამის მთავარი მიზეზი შესაძლოა საღეჭი კბილების ამოსვლის დაწყება იყოს. საღეჭი კბილები, ჩვეულებრივ, 20-ე თვემდე სრულად ამოდის, თუმცა მათი ამ თვეებში გამოჩენაც ნორმალურია. თუ წინა და ეშვის კბილები საკვების მოკბეჩას ემსახურება, საღეჭ კბილებს კვების პროცესში ძალიან მნიშვნელოვანი როლი აკისრია. ბრტყელი და ფართო ზედაპირის მქონე ეს კბილები საკვების უფრო ადვილად დაქუცმაცებას უწყობს ხელს. უსწორმასწორო ზედაპირისა და დიდი ზომის გამო საღეჭ კბილებზე ღეჭვის დატვირთვის დიდი ნაწილი მოდის. ამ პერიოდში ბავშვის დასამშვიდებლად შეგიძლიათ მისცეთ გრილი და მყარი საკვები, რომლის ხელში დაჭერასაც შეძლებს (მაგალითად, ცივი კიტრი ან სტაფილო).') WHERE id = '64b96eb8-8284-4d84-b6bb-5e9a619fbb8e';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ ეტაპზე ბავშვის ძილის რეჟიმი შეიძლება დღის განმავლობაში ფიზიკური აქტივობისა და კვების რეჟიმის მიხედვით შეიცვალოს. საშუალოდ, თქვენს ბავშვს ჯერ კიდევ 13-14 საათი უნდა ეძინოს. ეს დრო შეიძლება განაწილდეს ღამით 11-12 და დღისით 1-2 საათზე. ამ პერიოდში თქვენი ბავშვი შესაძლოა დღის ორი ძილიდან ერთ ძილზე გადავიდეს. ამისთვის უნდა დააკვირდეთ და, როცა მზად იქნება, გადასვლაში დაეხმაროთ. დღის ძილი მას დღის დარჩენილი ნაწილისთვის ენერგიის აღდგენაში ეხმარება. ამ ცვლილების მხარდასაჭერად დღის ძილი შეგიძლიათ დილით გაღვიძებიდან დაახლოებით 6-7 საათის შემდეგ დაგეგმოთ. ამგვარად, თქვენი ბავშვი დაღლილობასაც მოიხსნის და ღამის ძილის ხარისხსაც შეინარჩუნებს.') WHERE id = '7e899c41-bf02-4b4f-af49-2790f64d5c5f';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'სავსებით ნორმალურია, თუ ელით, რომ 14 თვის ბავშვი უფრო მეტს შეჭამს, ვიდრე დამატებითი კვების დაწყებისას ჭამდა. თუმცა გახსოვდეთ, რომ ბავშვის კუჭი ჯერ კიდევ პატარაა. ამიტომ დიდი ულუფების ნაცვლად, უმჯობესია, მან საკმარისი რაოდენობით დღეში 6-ჯერ მიირთვას — 3 ძირითადი და 3 შუალედური კვების სახით. ასეთი რეჟიმი ბავშვს მთელი დღის განმავლობაში ენერგიის შენარჩუნებაში ეხმარება და საჭმლის მონელების დარღვევას თავიდან აცილებს. თქვენი ბავშვი ჯერ კიდევ აყალიბებს კვების ჩვევებს. ჭამის იძულებამ შეიძლება გარკვეული პრობლემები გამოიწვიოს; საკვებზე უარის თქმის მიზეზი ყველაზე ხშირად სწორედ ეს ხდება. ბავშვი თანდათან დამოუკიდებელი ხდება და სურს, თავად გადაწყვიტოს, რას და რამდენს შეჭამს. ამიტომ ამ პერიოდში ძალიან მნიშვნელოვანია, კვების რეჟიმი ზედმეტი დაძალებისა და მასთან ჯიუტი დაპირისპირების გარეშე ჩამოაყალიბოთ.') WHERE id = 'afc54856-70b8-4f36-b450-98aa1aca2b83';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი დაბადების პირველივე წუთიდან დიდ ძალისხმევას დებს თქვენთან ურთიერთობის დასამყარებლად. გარკვეული პერიოდის განმავლობაში მას ამის გაკეთება მხოლოდ ტირილით შეეძლო. 2-3 თვის ასაკში ამას შეძახილები და ხმოვანი ბგერების წარმოთქმაც დაემატა. მალე ის სხვადასხვა უსიტყვო გამომეტყველებითაც ცდილობდა თქვენთან დაკავშირებას. ახლა კი გონებრივი განვითარებისა და ენობრივი უნარების წყალობით თქვენი ბავშვი უკვე იმ დონეზეა, რომ თქვენთან და გარემოსთან უფრო ეფექტურად იურთიერთოს. სიტყვათა მარაგის განვითარებასთან ერთად მას უკვე შეუძლია, თუნდაც მარტივად, აგიხსნათ, რა აწუხებს და გითხრათ, რა სურს. მიუხედავად იმისა, რომ თქვენი ბავშვი დამოუკიდებლობის ჩამოყალიბების ეტაპზეა, ურთიერთობის ეს უნარი მისი სოციალური განვითარებისთვის ძალიან მნიშვნელოვანია. ამიტომ ბავშვის როგორც ენობრივი უნარების, ისე სოციალური განვითარების მხარდასაჭერად შეგიძლიათ ხშირად უმღეროთ საბავშვო სიმღერები და დაათვალიერებინოთ სახალისო წიგნები. თუ ამას ძილის წინ ჩვევად აქცევთ, ბავშვი უკეთ მიხვდება, რომ ძილისთვის მომზადების დროა, და მისი სიტყვათა მარაგიც გამდიდრდება.') WHERE id = 'c526273a-8e7f-42a9-8d2b-ea1bf33fb5e7';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ კვირებში თქვენი ბავშვი განვითარების ახალი ნახტომის პერიოდში შევა. ამ პერიოდის განმავლობაში ის სრულიად ახალ გონებრივ და ფიზიოლოგიურ უნარებს შეიძენს. ამ ეტაპის დასრულების შემდეგ ბავშვს მოუნდება აღმოაჩინოს, რისი გაკეთება შეუძლია საკუთარი სხეულის გამოყენებით. ეს მოიცავს ისეთ ქცევებს, როგორიცაა მაღალ ადგილზე აძრომა, სირბილი, კიბეზე ასვლა-ჩამოსვლა, დამალვა და სურვილი, რომ იპოვოთ... 😊 მაგალითად; ის შეიძენს ახალ გონებრივ უნარებს — დაიწყებს თავის მოფერებასა და საყვარელი ქცევებით ყურადღების მიპყრობას, სათამაშოების ეჭვიანად დაცვას, გააზრებული გადაწყვეტილებების მიღებას, არჩევანის გაკეთებასა და „კი“ და „არა“ ცნებების სრულად გააზრებას. ამას დაემატება ისეთი ფიზიკური უნარებიც, როგორიცაა ფანქრისა და კოვზის სწორად დაჭერა, თქვენი მიბაძვა, როცა სახლის საქმეებს აკეთებთ, ნივთების ერთმანეთზე დაწყობა და შემდეგ დაშლა. ამ პერიოდში შესაძლოა ბავშვმა თავისი სურვილის გასატანად სიჯიუტეც გამოიჩინოს. ამას ყველაზე კარგად მაშინ შეამჩნევთ, როცა საფენის გამოცვლისას გაგექცევათ ან დაძინების სურვილის არქონისას იტირებს.') WHERE id = '6e4bf078-f30a-41d3-b0f1-e67a9a9faed1';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ თვეებში ჯანსაღი კვების ჩვევის ჩამოყალიბება თქვენი ბავშვის მომავალი წლებისთვის ძალიან მნიშვნელოვანია. კვლევების თანახმად, განსაკუთრებით განვითარებულ და განვითარებად ქვეყნებში, 5-17 წლის ასაკის ყოველი 10 ბავშვიდან 1-ს ჭარბი წონა ან სიმსუქნე აქვს. დიდი ძალისხმევა უნდა გამოიჩინოთ, რომ მომავალში ბავშვს ჯანსაღი კვების ჩვევა ჰქონდეს და ჩვენი დროის ერთ-ერთ გავრცელებულ დაავადებას — სიმსუქნეს — თავი აარიდოს. პირველ რიგში, არ უნდა დაგავიწყდეთ, რომ სხვა საკითხების მსგავსად, კვების მხრივაც ბავშვი თქვენგან აიღებს მაგალითს. იმისათვის, რომ ბავშვს ჯანსაღი კვების ჩვევა ჩამოუყალიბდეს, თქვენ და თქვენი პარტნიორი, როგორც მშობლები, მისთვის სწორი მეგზურები უნდა იყოთ. გახსოვდეთ, რომ ბავშვისთვის მთავარი მისაბაძი მაგალითი ოჯახია და ის გაიმეორებს იმას, რასაც თქვენგან ხედავს. ამიტომ ძალიან მნიშვნელოვანია, თქვენც არ მიირთვათ ის საკვები, რომელსაც ბავშვს არ აძლევთ და უკრძალავთ.') WHERE id = 'f7d2bdee-d2ae-49c1-a04e-221370278e9e';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ თქვენი ბავშვი თითს წოვს და ეს განსაკუთრებით ძილის დროს ხდება, შესაძლოა ამის მიზეზთან დაკავშირებით კითხვები გაგიჩნდეთ. რადგან ჩვილები ასაკობრივად ე.წ. ორალურ ფაზაში იმყოფებიან, სპეციალისტები თითის წოვას ნორმალურ მოვლენად მიიჩნევენ. ორალური ფაზა არის პერიოდი, როდესაც ბავშვი გარესამყაროს პირით შეიმეცნებს და ამ გზით ფსიქოლოგიურ კმაყოფილებას იღებს. 1 წლის ასაკთან მიახლოებული თითქმის ყველა ბავშვისთვის შეიძლება თითის წოვა ჩვევად იქცეს. ეს ქცევა დაახლოებით 6 თვის ასაკში პიკს აღწევს. 3-4 წლამდე ბავშვისთვის თითის წოვის აკრძალვამ შესაძლოა გარკვეული ფსიქოლოგიური პრობლემები გამოიწვიოს. მაგალითად, თუ ამ პროცესის დასრულებამდე შეუშლით ხელს, სკოლაში შესვლის ასაკში ბავშვმა პრობლემების დროს შესაძლოა კვლავ დაიწყოს თითის წოვა. ამიტომ გახსოვდეთ, რომ ეს ბავშვისთვის დამშვიდების საშუალება და განვითარების ნორმალური პროცესია; ნუ შეუშლით ხელს თითის წოვაში.') WHERE id = '31ea1093-e45e-4706-9187-09cec848711c';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის მეტყველების უნარის გასავითარებლად, შეგიძლიათ დღის განმავლობაში ესაუბროთ იმ მოქმედებებზე, რომლებსაც მასთან ერთად ასრულებთ. ეფექტური კომუნიკაციისთვის ძალიან მნიშვნელოვანია, საუბრისას ყოველთვის სახელით მიმართოთ და ხელი შეუწყოთ, რომ საკუთარი აზრების გამოხატვის დროს სახეში გიყუროთ. შესაძლოა, გარკვეული ხნის განმავლობაში ბავშვმა კომუნიკაციისას თვალით კონტაქტის მნიშვნელობა ვერ აღიქვას. ამ ეტაპზე მოთმინება გმართებთ, რათა ბავშვმა ყურადღება თქვენკენ მოაპყროს. ამ პერიოდში მას ყურადღების კონცენტრირება ძალიან მცირე ხნით შეუძლია. ამიტომ ნუ დააჩქარებთ და მიეცით დრო. თუმცა მნიშვნელოვანია, განაგრძოთ ძალისხმევა და ხშირად დაამყაროთ პირისპირ კომუნიკაცია ზომიერად, ზეწოლის გარეშე. ბავშვის ყურადღების მისაპყრობად შეგიძლიათ თითის თოჯინები ან მისი საყვარელი სათამაშოებიც გამოიყენოთ.') WHERE id = '3ce788c0-f070-45ad-81cb-f88068c7f73a';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'საკვებიდან ან დანამატის სახით მიღებული პრობიოტიკები დადებითად მოქმედებს ბავშვის საჭმლის მომნელებელი სისტემის ჯანმრთელობაზე. პრობიოტიკები ხელს უწყობს ნაწლავის ლორწოვანი გარსისა და სისტემური იმუნიტეტის რეგულირებას, ასევე სასარგებლო მიკროორგანიზმების ბალანსის შენარჩუნებას. მედიცინაში პრობიოტიკებად მიჩნეული მიკროორგანიზმებია ბიფიდობაქტერიები, ლაქტობაცილები და საფუარის ზოგიერთი სახეობა. ამ მიკროორგანიზმების ძირითადი თვისებაა ნაწლავის დაზიანების თავიდან აცილება და მისი დაცვა კუჭისა და ნაღვლის მჟავების ზემოქმედებისგან. ბავშვისთვის პრობიოტიკების სათანადო რაოდენობით მიწოდება ყველაზე მარტივად მის მიერ მიღებული საკვების საშუალებითაა შესაძლებელი. ამიტომ დღის განმავლობაში შეგიძლიათ მისცეთ იოგურტი, კეფირი და რძე. ამასთან, თუ ბავშვის იოგურტს სახლში თავად ამზადებთ, მომზადებისას შეგიძლიათ დაამატოთ გასაყიდად ხელმისაწვდომი, სპეციალურად ბავშვებისთვის განკუთვნილი პრობიოტიკური ფხვნილიც.') WHERE id = '4288b6eb-8c29-4319-9748-ef1056bfa3a6';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ ეტაპზე შეიძლება შეამჩნიოთ, რომ ბავშვის დღის ძილის ხანგრძლივობა შემცირდა. თუ 1-2 თვის წინ მას დღისით 1.5-2 საათი ეძინა, ახლა შეიძლება 1 საათის შემდეგ გაიღვიძოს. ამის ერთადერთი მიზეზი ბავშვის განვითარებასთან ერთად ძილის მოთხოვნილების ცვლილებაა. რამდენი ძილი სჭირდება მას, შეგიძლიათ ძილის პერიოდებს შორის ფხიზლად გატარებული დროის მიხედვით განსაზღვროთ. თუ დაღლილი არ ჩანს და ზოგადად კარგ ხასიათზეა, ეს ნიშნავს, რომ თქვენი ბავშვისთვის დღის განმავლობაში ერთხელ დაძინების პერიოდი დაიწყო. ზოგიერთი სპეციალისტი ამ ეტაპზე დაახლოებით 1.5-საათიანი ერთი ძილის ნაცვლად ორ 45-წუთიან ძილსაც ურჩევს. ამ საკითხზე უმჯობესია რჩევა იმ ექიმს ჰკითხოთ, რომელიც ბავშვის განვითარებას აკვირდება.') WHERE id = '6ba44648-3933-4291-9703-f585d3124ad2';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'საუზმე ბავშვისთვის ერთ-ერთი ყველაზე მნიშვნელოვანი კვებაა, რათა დღე ჯანსაღად და ენერგიულად დაიწყოს. თუ თქვენი ბავშვი უმადოა, შესაძლოა, სხვა დედებთან შედარებით ცოტა უფრო რთული ამოცანის წინაშე იდგეთ. ბავშვებს სახალისოდ გაფორმებული თეფშები ძალიან მოსწონთ. ამიტომ შეგიძლიათ მისთვის ფიგურებით გაფორმებული, ფერადი და საინტერესო თეფშები მოამზადოთ. მაგალითად, მომზადებული ომლეტით სახის ფორმა შექმნათ, ზეთისხილით თვალები გაუკეთოთ, ყველით კი — მომღიმარი პირი! დილის რძე ჩვეულებრივი ჭიქის ნაცვლად შეგიძლიათ მისი საყვარელი პერსონაჟის გამოსახულებიან ჭიქაში შესთავაზოთ. სახალისოდ გაფორმებული თეფშები, ფერადი ხელსახოცები და ბავშვებისთვის განკუთვნილი სპეციალური კოვზები და ჩანგლები ბავშვის ყურადღებას მიიპყრობს და ჭამის სურვილს გაუჩენს! 😊 ამ გზით იპოვით ეფექტურ საშუალებას, რომ ბავშვს საუზმე შეაყვაროთ. გემრიელად მიირთვით! 😊') WHERE id = '100e3bf4-7099-4e07-b464-4e8f9fc75448';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ თქვენი ბავშვი ჯერ არ დადის, სრულიად ბუნებრივია, რომ გარკვეულ შეშფოთებას გრძნობდეთ. თუმცა გახსოვდეთ, რომ ყველა ჯანმრთელი ბავშვი სიარულს საშუალოდ 12-18 თვის ასაკში იწყებს. ანუ ბავშვს პირველი ნაბიჯის გადასადგმელად ჯერ კიდევ დაახლოებით 4 თვე აქვს. ამასთან, ზოგიერთმა ბავშვმა სიარული შეიძლება 12 თვის ასაკამდეც დაიწყოს. გავრცელებული შეხედულების საპირისპიროდ, ბავშვების მიერ სიარულის დაწყების დრო ინტელექტთან არანაირ კავშირში არ არის. სიარულის დაწყების ასაკი გონებრივ განვითარებაზე კი არა, მსხვილი მოტორული უნარების განვითარებაზეა დამოკიდებული. მიჩნეულია, რომ ჭარბი წონა ბავშვებში განსაკუთრებით ანელებს ისეთ მსხვილ მოტორულ უნარებს, როგორებიცაა გადაბრუნება, ხოხვა და სიარული. თუ ის, რომ ბავშვი ჯერ კიდევ არ დადის, გაწუხებთ, კარგი იქნება, დააკვირდეთ მისი განვითარების სხვა ეტაპებსაც და ექიმს რჩევისთვის მიმართოთ. თუ გამოკვლევების შედეგები ნორმაშია, შეგიძლიათ მშვიდად კიდევ 4 თვე დაელოდოთ.') WHERE id = '5d51cb37-4895-49ef-9653-5387c0bc8578';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის ჯანსაღი გონებრივი და ფიზიოლოგიური განვითარებისთვის საკვებიდან მიღებული ვიტამინები და მინერალები ძალიან მნიშვნელოვანია. თუმცა იმისთვის, რომ ორგანიზმში მინერალებმა ჰომეოსტაზად წოდებული შინაგანი წონასწორობა უზრუნველყოს, მარეგულირებელი მექანიზმია საჭირო. ეს უმნიშვნელოვანესი მინერალი, რომელიც ორგანიზმში წყლისა და ყველა მინერალის ბალანსის შენარჩუნებას უწყობს ხელს, კალიუმია. კალიუმი ადამიანის ორგანიზმში გავრცელების მიხედვით მერვე ელემენტია. მაგალითად, დაახლოებით 60 კგ წონის ზრდასრული ადამიანის ორგანიზმში სულ 120 გრამი კალიუმია. ეს მინერალი ორგანიზმში სხვადასხვა ცილისა და ფერმენტის შემადგენლობაში გვხვდება. მისი სხვა ფუნქციებია კუნთების მუშაობის ხელშეწყობა და ნორმალური არტერიული წნევის შენარჩუნება. ამიტომ ძალიან მნიშვნელოვანია, ბავშვის კვების რაციონში კალიუმით მდიდარი საკვები შეიტანოთ. ასეთ საკვებს მიეკუთვნება კარტოფილი, თევზის სხვადასხვა სახეობა, სტაფილო, ისპანახი, გარგარი, ფინიკი, ბანანი და ისეთი პარკოსნები, როგორებიცაა ლობიო და ოსპი.') WHERE id = 'b49d44ad-509b-45da-b50c-13a1e54a66ac';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ თვეში ბავშვის ვაქცინაციის გრაფიკი შეიძლება ცოტა დატვირთული იყოს. თუმცა, რადგან მე-12 თვეში ძალიან მნიშვნელოვანი ინფექციური დაავადებების საწინააღმდეგო ვაქცინები კეთდება, გირჩევთ, კალენდარი ზედმიწევნით დაიცვათ. ესენია: წითელას, წითურას, ეპიდემიური პაროტიტის (ყბაყურას) და დამატებით, პნევმოკოკური ინფექციის საწინააღმდეგო ვაქცინები. პნევმოკოკური დაავადებები შეიძლება მძიმე და საშიში იყოს. ამ ბაქტერიამ შესაძლოა გამოიწვიოს სხვადასხვა პრობლემა — მსუბუქი დაავადებებიდან სისხლის მოწამვლასა და მენინგიტამდე. კონიუგირებული პნევმოკოკური ვაქცინა, რომელიც თქვენს ბავშვს გაუკეთდება, ხელს უწყობს ისეთი სერიოზული რისკების თავიდან აცილებას, როგორებიცაა მენინგიტი და სისხლის მოწამვლა. ასევე ცნობილია, რომ ის შუა ყურის ზოგიერთი ინფექციისგანაც იცავს. ამიტომ პნევმოკოკური ვაქცინა განსაკუთრებით რეკომენდებულია ჩვილებისა და ადრეული ასაკის ბავშვებისთვის. ვაქცინები, რომლებსაც ბავშვს ამ თვეში გაუკეთებთ, მთელი ცხოვრების განმავლობაში ამ დაავადებებთან დაკავშირებულ რისკს მინიმუმამდე შეამცირებს.') WHERE id = 'a0fe42da-edbb-44ae-9aba-92568413962b';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ ეტაპზე თქვენი ბავშვი უკვე კარგად იყენებს მიმიკებს. ყველაზე ხშირად მის სახეზე ცნობისმოყვარეობისა და ყურადღების გამომხატველი მიმიკები ჩნდება. გახსოვდეთ, რომ ბავშვი ჯერ კიდევ ცდის, შეცდომებისა და აღმოჩენების ეტაპზეა. როდესაც რაიმე ახალს აღმოაჩენს, მის ყურადღებას საინტერესო საგანი მიიპყრობს ან დიდი ხნის უნახავ სათამაშოს დაინახავს, თვალებს ფართოდ ახელს. ის საგანს თვალის მოუშორებლად აკვირდება და ხშირად ამ დროს პირიც ღია რჩება. ვინაიდან მისთვის საინტერესო ობიექტისკენ მთელი სხეულით სურს მიბრუნება, შესაძლოა ტაში დაუკრას ან აღელვება სხვა რეაქციებით გამოხატოს. ასეთ დროს ბავშვის შეზღუდვამ შეიძლება ძალიან მძაფრი რეაქცია, ტირილის შეტევა ან აგრესიული ქცევაც კი გამოიწვიოს. ამიტომ, თუ ბავშვს ზიანის მიყენების საფრთხე არ ემუქრება, უმჯობესია ხელი არ შეუშალოთ, ხოლო სახიფათო სიტუაციაში შესაბამისი საგანი მთლიანად მოაშოროთ.') WHERE id = '0ce5b94c-09e6-4a0f-95d7-434109b1665a';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის იმუნური სისტემის გაძლიერება მას შინაგანი და გარეგანი ფაქტორებით გამოწვეული ინფექციების მიმართ უფრო მდგრადს ხდის. ამიტომ ყოველდღიურად საკმარისი რაოდენობის ცილის მიღება ძლიერი იმუნური სისტემის შესანარჩუნებლად ძალიან მნიშვნელოვანია. ცილის დღიური მოთხოვნილების დაუკმაყოფილებლობამ ბავშვის ორგანიზმში ამინომჟავების დეფიციტი და უმადობა შეიძლება გამოიწვიოს. განსაკუთრებით ამ პერიოდში, როდესაც ბავშვი მსხვილ მოტორულ უნარებს აქტიურად იყენებს, მას ყოველდღიურად დაახლოებით 1200-1300 კალორია ენერგია და საშუალოდ 13 გრამი ცილა სჭირდება. ცილა 20 სხვადასხვა ამინომჟავისგან შედგება. ადამიანის ორგანიზმს მათგან 11-ის წარმოქმნა თავად შეუძლია, დანარჩენი 9 კი საკვებიდან უნდა მიიღოს. კვერცხი, რძე და რძის პროდუქტები, სხვადასხვა სახეობის თევზი, ქათამი და მჭლე წითელი ხორცი ცილის საუკეთესო წყაროებია. ამიტომ ეცადეთ, ბავშვის ყოველდღიური საუზმე კვერცხსა და რძის პროდუქტებს შეიცავდეს, ხოლო სადილსა და ვახშამზე მან მიიღოს ცხოველური წარმოშობის საკვები, რომელიც სრულფასოვანი ცილის წყაროდ მიიჩნევა.') WHERE id = '32913ce6-24a8-4d25-9cc1-6c3c071090db';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი ყოველდღიურად იზრდება, ახალ უნარებს იძენს და თავისი განვითარებით თქვენს გაოცებას განაგრძობს. ამ პერიოდში ის უკვე დამოუკიდებლად დგომას, ხოხვასა და სიარულს იწყებს. ახლად შეძენილმა უნარებმა, ენერგიის ხარჯვის ცვლილების გამო, შესაძლოა ძილის დროებითი გაუარესება გამოიწვიოს. თქვენი ამოცანაა, ყურადღებით დააკვირდეთ ბავშვის საჭიროებებს და მას საკმარისი დრო მისცეთ. ამ ასაკში ბავშვები დაახლოებით 4-5 საათის განმავლობაში ფხიზლობენ. ფხიზლად ყოფნის დროის გახანგრძლივება იმითაა განპირობებული, რომ ბავშვს ძილის დროს გამოყოფილი ზრდის ჰორმონი წინანდელი რაოდენობით აღარ სჭირდება. ამ გარდამავალ პერიოდში, ბავშვის ძილის რეჟიმის ხელახლა დაგეგმვისას, გახსოვდეთ, რომ ყველაზე მნიშვნელოვანი მის მიერ გამოხატული სიგნალებია.') WHERE id = '2406fe8c-a932-4659-944e-d34a90335aef';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'პირველი 3 წელი, ანუ 36 თვე, ბავშვის ნერვული სისტემის განვითარებისთვის განსაკუთრებით მგრძნობიარე პერიოდად მიიჩნევა. ამიტომ ამ პერიოდში მიღებულ საკვებს მისი ჯანსაღი ზრდისა და განვითარებისთვის ძალიან დიდი მნიშვნელობა აქვს. ზოგიერთი სპეციალისტი პირველი 3 წლის განმავლობაში ბავშვებისთვის ორგანული საკვების შერჩევას უწევს რეკომენდაციას. ორგანული საკვები ისეთი წესით უნდა იწარმოებოდეს, რომ მინდვრიდან ან ბაღიდან თქვენს ბავშვამდე მოხვედრის პროცესში მავნე ნივთიერებებით არ დაბინძურდეს. არაჯანსაღი კვება ჯანმრთელობის მრავალ პრობლემას შეიძლება უკავშირდებოდეს, თუმცა აუტიზმის გამომწვევ მიზეზად არ მიიჩნევა. არაბალანსებულმა კვებამ სასკოლო ასაკში შესაძლოა ხელი შეუწყოს ჭარბწონიანობასა და ჯანმრთელობის სხვა პრობლემებს. ამიტომ ბავშვისთვის პროდუქტების შეძენისას რეკომენდებულია, უპირატესობა მიანიჭოთ სანდო ორგანული ეტიკეტის მქონე და ნაკლებად დამუშავებულ ნატურალურ პროდუქტებს.') WHERE id = '87ccab00-63bc-4286-b706-8a9dd745c897';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ალბათ შეგიმჩნევიათ, როგორ ცდილობს ბავშვი აგიხსნათ რაიმე სიტუაცია ან გაჩვენოთ, რა აწუხებს. ბავშვების მოტორული უნარები და მეტყველების გაგების უნარი უფრო სწრაფად ვითარდება, ვიდრე ლაპარაკის უნარი. ამიტომ ისინი საკუთარი სურვილების გამოსახატავად გარკვეული ჟესტების გამოყენებას იწყებენ. ეს ნიშნავს, რომ ტირილი ბავშვის სურვილების გამოხატვის ერთადერთი გზა აღარ არის. მაგალითად, ამ პერიოდში, როცა ბავშვს შია, მან შეიძლება სამზარეულოსკენ მიგითითოთ, ხოლო თუ ახლოს წყლის ბოთლია, მისკენ გაიშვიროს თითი. ძალიან მნიშვნელოვანია, შეეცადოთ ბავშვის სურვილების გაგებას. თუმცა ყურადღება უნდა მიაქციოთ იმასაც, რომ მისი თხოვნა დაუყოვნებლივ და სიტყვების გარეშე არ შეასრულოთ. ბავშვის მეტყველების უნარის გასავითარებლად შეგიძლიათ მისი ჟესტები სიტყვებით გამოხატოთ. მაგალითად, როდესაც შორს მდებარე სათამაშოზე მიგითითებთ, ნაცვლად იმისა, რომ სათამაშო დაუყოვნებლივ მიაწოდოთ, სასარგებლო იქნება ჰკითხოთ: „თქვენი სათამაშო გინდათ?“, „რომელი სათამაშო გინდათ?“, „წითელი დათუნია გინდათ?“.') WHERE id = 'ab91ed36-9244-4c5f-8311-b066e05594f7';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'იოდი ერთ-ერთი მინერალია, რომელიც ბავშვის ორგანიზმის ჯანსაღი ზრდისა და ჩამოყალიბებისთვის ძალიან მნიშვნელოვანია. იოდი შეუცვლელი მინერალია, რომელიც ფარისებრი ჯირკვლის ჰორმონების წარმოქმნაში მონაწილეობს. ფარისებრი ჯირკვალი არეგულირებს ბავშვის ნივთიერებათა ცვლას და უშუალო გავლენას ახდენს მის გონებრივ და ფიზიკურ განვითარებაზე, მათ შორის ძილზე, მადაზე და ფსიქოემოციურ მდგომარეობაზე. თუ ორგანიზმი საკვებიდან საკმარის იოდს ვერ იღებს, შესაძლოა განვითარდეს ზრდისა და განვითარების შეფერხება, კოგნიტიური პრობლემები, აგრეთვე ფარისებრი ჯირკვლის გადიდებასთან დაკავშირებული ჩიყვი და კვანძები. მსოფლიოში იოდის დეფიციტის მქონე ბავშვების რაოდენობა საკმაოდ დიდია და ჩვენი ქვეყანაც იოდის დეფიციტის რისკის მქონე რეგიონებს მიეკუთვნება. ამიტომ ძალიან მნიშვნელოვანია, იცოდეთ ბავშვის იოდის დღიური მოთხოვნილება. ამ პერიოდში მას ყოველდღიურად დაახლოებით 80-120 მიკროგრამი იოდი სჭირდება. ეს დაახლოებით ორი ჯამი იოგურტისა და ერთი საშუალო ზომის ზღვის თევზის შესაბამისია, თუმცა იოდის შემცველობა პროდუქტების მიხედვით განსხვავდება. თუ თქვენი ბავშვი ამ საკვებს საკმარისი რაოდენობით არ იღებს, იოდიზებული მარილი გამოიყენეთ მხოლოდ მისი ასაკისთვის დასაშვები მცირე რაოდენობით და პედიატრის რეკომენდაციის შესაბამისად.') WHERE id = '522a3fe5-04bf-4e2d-9c55-d18ab04d51f1';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი შესაძლოა საშუალო სტატისტიკურ მაჩვენებელზე ნაკლები წონით დაიბადა. თუმცა განვითარების მხრივ ამ ეტაპზე ის უკვე დაეწია თანატოლებს. ამის მიზეზი ისაა, რომ დაბალი წონით დაბადებული ბავშვები გარკვეული პერიოდის განმავლობაში თანატოლებთან შედარებით 10-ჯერ უფრო სწრაფად იზრდებიან. მედიცინაში ამ პერიოდს catch up growth, ანუ ზრდაში დაწევა ეწოდება. თუ თქვენი ბავშვი დაბალი წონით დაიბადა და ახლა სუსტად გეჩვენებათ, ამის მიზეზი უკვე დაბადებისას მისი მცირე ზომა აღარ არის. ამ პერიოდში ბავშვი ძალიან მოძრავია და ინდივიდუალიზაციის პროცესის გამო შესაძლოა ჭამაზე უარი თქვას, რის გამოც ნაკლებ წონას მოიმატებს. გარდა ამისა, ბავშვის ზრდასა და განვითარებაში გენეტიკური თავისებურებები ერთ-ერთი უმნიშვნელოვანესი ფაქტორია. განვითარებაზე მოქმედ მნიშვნელოვან მიზეზებს შორისაა ასევე სქესსა და ჰორმონულ ბალანსზე დამოკიდებული ბაზალური მეტაბოლიზმის სიჩქარე.') WHERE id = '59294465-e7c2-4591-9517-a393a10bf2cb';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის პირის ღრუში არსებული სარძევე კბილები მის ცხოვრებაში ამოსული პირველი კბილებია. მათი ჩანასახები ღრძილებში ჯერ კიდევ იმ პირველ კვირებში ჩამოყალიბდა, როდესაც ორსულობის შესახებ შეიტყვეთ. ისინი საკმაოდ მგრძნობიარე და ნაზია, რადგან მუდმივი კბილების ამოსასვლელად ნიადაგს ამზადებს. მუდმივი კბილების ამოსვლამდე სარძევე კბილები ბავშვს ბგერების წარმოთქმასა და კვებაში მნიშვნელოვნად ეხმარება. ამ ეტაპზე ბავშვს შესაძლოა ზედა და ქვედა ორი საჭრელი კბილი უკვე სრულად ჰქონდეს ამოსული. ამასთან ერთად, შესაძლოა გვერდითი საჭრელი კბილებიც გამოჩნდეს. მალე ბავშვს ჯერ ქვედა, შემდეგ კი ზედა ძირითადი კბილები დაეწყება. ქვედა და ზედა ეშვების, ბოლოს კი უკანა ძირითადი კბილების ამოსვლით სარძევე კბილების სრული, 20-კბილიანი ნაკრები ჩამოყალიბდება.') WHERE id = '1aed127a-2b52-4500-bf43-b5b0cd18c968';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის ცილის დღიური მოთხოვნილების დაკმაყოფილებაში ცხოველური წარმოშობის საკვებს მნიშვნელოვანი ადგილი უჭირავს. თუმცა ზოგიერთ ბავშვს პერიოდულად შესაძლოა ხორცის ან რძის პროდუქტების მიღება არ სურდეს. ასეთ შემთხვევაში ბავშვის ცილის მოთხოვნილების დასაკმაყოფილებლად ალტერნატიული წყაროები უნდა შეარჩიოთ. გააზრებული და დაბალანსებული კვების გეგმის შედგენის შემთხვევაში ბავშვის ცილის მთელი მოთხოვნილების მცენარეული წყაროებით დაკმაყოფილებაც შესაძლებელია. მაგალითად, ერთი კვერცხი, რომელსაც ბავშვი საუზმეზე მიირთმევს, დაახლოებით 6 გრამ ცილას შეიცავს. ნახევარი ჭიქა მოხარშული ოსპი 9 გრამ, ხოლო ნახევარი ჭიქა მოხარშული ხმელი ლობიო 7-8 გრამ ცილას შეიცავს. ამასთან, თუ თქვენს ბავშვს გლუტენზე ალერგია აქვს, გლუტენის არმქონე 100 გრამ წიწიბურაში დაახლოებით 3-4 გრამი ცილაა. თუ პარკოსნებს ბრინჯთან ერთად შესთავაზებთ, ბავშვი ცილის დღიურ მოთხოვნილებას სრულად დაიკმაყოფილებს.') WHERE id = '499bb82a-5ed3-4d97-8a0a-6e47403d4ebc';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ალბათ ექიმისგან, გამოცდილი მეგობრებისგან და ახლობელი ადამიანებისგან ხშირად გსმენიათ ორგანული კვების შესახებ. თუმცა რამდენად კარგად აცნობიერებთ ორგანული პროდუქტების ადგილსა და მნიშვნელობას ბავშვის კვების რაციონში? ორგანული პროდუქტები გენეტიკურად არამოდიფიცირებული ბუნებრივი თესლის დათესვით მიიღება და თქვენს ბავშვამდე მისვლამდე ქიმიურ ნივთიერებებთან შეხების გარეშე, სრულიად ბუნებრივ პროცესებს გადის. ანუ ორგანული ეწოდება პროდუქტებს, რომლებიც დათესვისა და მორწყვის გარდა, სეზონური პირობების შესაბამისად, მთლიანად ბუნების ძალით იზრდება. ბოლო წლებში, განსაკუთრებით იმის გაცნობიერებამ, რომ გახშირებული დაავადებების წყარო შესაძლოა ხელოვნურად დამუშავებული საკვები იყოს, ბაზარზე მრავალი ორგანული პროდუქტის გამოჩენა განაპირობა. თუმცა არაკეთილსინდისიერი გაყიდვებისა და სარეკლამო პოლიტიკის გამო პროდუქტის "ორგანულის" სახელით გაყიდვა ყოველთვის არ ნიშნავს, რომ მისი წარმოების ყველა ეტაპი სრულიად ბუნებრივი იყო. ამიტომ ბავშვისთვის პროდუქტების შეძენისას ძალიან მნიშვნელოვანია, აირჩიოთ ოფიციალური უწყებების მიერ დამტკიცებული და შესაბამისი შემოწმებისა და სერტიფიცირების ორგანიზაციების მიერ კონტროლირებული პროდუქტები.') WHERE id = '20bbd1b6-86c2-409c-a96a-adb576836ee8';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'კეთილი იყოს თქვენი მობრძანება მე-15 თვეში, როდესაც ბავშვი საგნებზე უფრო ღრმად იწყებს ფიქრს! ძალიან მალე შეიძლება შეამჩნიოთ, რომ ბავშვი სათამაშოებით უფრო გააზრებულად თამაშობს. მან შეიძლება სცადოს სათამაშოების გამოკვება, დააძინოს ისინი ან სათამაშო მანქანები დანიშნულების შესაბამისად ატაროს. ამ ეტაპზე თქვენი ქცევები და მიმიკები ბავშვს ახალი უნარების ათვისებაში მნიშვნელოვნად ეხმარება. მაგალითად, ჭამის დროს თქვენზე დაკვირვებით მან შეიძლება კოვზი მხოლოდ პირთან კი აღარ მიიტანოს, არამედ იმის გააზრებაც დაიწყოს, რომ კოვზს მოსარევადაც იყენებენ. იმის გაგება, თუ როგორ და რა მიზნით გამოიყენება საგნები, ბავშვის მნიშვნელოვანი გონებრივი განვითარების დასტურია. ეს ნიშნავს, რომ ბავშვი უკვე იწყებს წინასწარ ფიქრს, როგორ მუშაობს სხვადასხვა რამ და რა შედეგი შეიძლება მოჰყვეს მის მოქმედებებს.') WHERE id = '0c49e00c-ebd6-4537-b4a6-d8dc95dd122b';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ხედავთ, როგორ იზრდება და ვითარდება ბავშვი დღითიდღე თქვენს თვალწინ. ამაში თქვენი წვლილი ფასდაუდებელია! 😊 მიუხედავად იმისა, რომ ექიმმა ამ თვეში გეგმურ შემოწმებაზე არ დაგიბარათ, ალბათ გაინტერესებთ, როგორი უნდა იყოს ბავშვის სიმაღლისა და წონის მაჩვენებლები. ჯანმოს სტანდარტების მიხედვით, 15 თვის გოგონების წონა სულ მცირე 7700 გრამი, ხოლო ბიჭების — სულ მცირე 8400 გრამი უნდა იყოს. ამ მაჩვენებლების ზედა ზღვარი გოგონებისთვის დაახლოებით 13.500 გრამია, ბიჭებისთვის კი — 14.300 გრამი. ამ თვეში გოგონების სიმაღლე 72.4 sm-დან 82.7 sm-მდეა, ბიჭების კი — 74.4 sm-დან 83.4 sm-მდე. ბავშვის მაჩვენებლების ამ დიაპაზონში ყოფნა, რა თქმა უნდა, ყველა დედის მსგავსად თქვენც ძალიან გაგახარებთ. თუმცა გვსურს შეგახსენოთ, რომ ყველა ეს მაჩვენებელი შეიძლება განსხვავდებოდეს ბავშვის სქესის, კვების რეჟიმის, მადისა და ისეთი მსხვილი მოტორული უნარების მიხედვით, როგორიცაა სიარული.') WHERE id = '0007e2fa-cabc-4226-900d-8ea2c472b6ea';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის გარემოში არსებული ყველა სტიმული — ხმა, სუნი, ფერი და შეხება — დაბადების მომენტიდანვე იწყებს მის მეხსიერებაში აღბეჭდვას. ბავშვის ნერვულ სისტემაში არსებული მილიარდობით ნეირონი ამ გარეგანი ზემოქმედებების დასაფიქსირებლად ერთმანეთთან კავშირების დამყარებას იწყებს. ამ ეტაპზე, რომელსაც სწავლის პროცესი ეწოდება, საფუძველი ეყრება გონებრივ ფუნქციებსა და ტვინის პოტენციალს, რომლებსაც ბავშვი მთელი ცხოვრების განმავლობაში გამოიყენებს. ამ თვალსაზრისით, ძალიან მნიშვნელოვანია, რომ ბავშვი მრავალფეროვან სტიმულებს შეხვდეს, ახალი რამ აღმოაჩინოს და თუნდაც პირველად მოისმინოს რომელიმე სიტყვა. ამ განვითარებას ხელს შეუწყობთ, თუ ბავშვს ხშირად წაუკითხავთ წიგნებს, ყოველდღიური საქმეების კეთებისას მოუყვებით, რას აკეთებთ, და ახალი აღმოჩენების შესაძლებლობას მისცემთ. მაგალითად, დაძინებამდე ნახევარი საათით ადრე შეგიძლიათ ერთად დაათვალიეროთ ბავშვებისთვის განკუთვნილი საინტერესო წიგნები და კითხვისას მიმიკებიც გამოიყენოთ. ამგვარად, არა მხოლოდ ძალიან სასიამოვნოდ გაატარებთ დროს, არამედ ბავშვის მხედველობით მეხსიერებასაც განავითარებთ და მომავალში მისი წარმოსახვის, შემოქმედებითი უნარებისა და სიტყვათა მარაგის ჩამოყალიბებას შეუწყობთ ხელს.') WHERE id = '194ef97e-d059-421e-9e85-a3e5c700d2ed';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი უკვე მხოლოდ სიარულით აღარ კმაყოფილდება და შესაძლოა უკან ნაბიჯის გადადგმასა და სირბილსაც ცდილობდეს. თუმცა, თუ ბავშვი ჯერ კიდევ არ დადის, ამაზე ნერვიულობა სრულიად ბუნებრივია. განსაკუთრებით თანატოლებთან შედარება, გარშემომყოფთა ზეწოლა და კითხვები შეიძლება შემაწუხებელი იყოს, მაშინაც კი, თუ თავად ფიქრობთ, რომ ბავშვს პრობლემა არ აქვს. ზოგიერთი ბავშვი სიარულს მანამდე არ ცდილობს, სანამ თავს სრულად მზად არ იგრძნობს. სხვები კი უფრო ადრე იწყებენ მცდელობას, მიუხედავად იმისა, რომ ხშირად ეცემიან. თუ ნაბიჯის გადადგმის მცდელობისას ბავშვი დაეცა ან ტკივილი განიცადა, სრულიად ბუნებრივია, რომ გარკვეული ხნით სიარულის შეეშინდეს. გარდა ამისა, თუ ბავშვი კარგად ხოხავს, შესაძლოა სიარულის დასაწყებად ძალისხმევის გაღების საჭიროებას ვერ გრძნობდეს. ამ ყველაფრის გათვალისწინებით, გვსურს შეგახსენოთ, რომ ბავშვს სიარული ზედმეტად არ უნდა დააძალოთ და ამისთვის ჯერ კიდევ მე-18 თვემდე გაქვთ დრო. 😊') WHERE id = 'fc2610d2-34cd-4a60-8b6c-84a8797e54a6';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში შეიძლება შეამჩნიოთ, რომ ბავშვი თქვენ ან ახლობლებს კბენს. კბენა ბავშვებში, ჩვეულებრივ, კბილების ამოსვლის პერიოდიდან იწყება და დაახლოებით 3 წლამდე გრძელდება — ეს დროებითი ჩვევაა. თავდაპირველად ბავშვმა შეიძლება ეს თამაშად აღიქვას, თუმცა გარკვეული ხნის შემდეგ კბენა საპასუხო ქცევად აქციოს. კბენისკენ მიდრეკილება ხშირად უფრო მეტად შეინიშნება ბავშვებში, რომლებსაც ხშირად უზღუდავენ მოქმედებას და რომელთა მშობლებიც მკაცრ წესებს უწესებენ. თუ მსგავს შემთხვევას აწყდებით, პირველ რიგში, მკვეთრი რეაქციისგან თავი უნდა შეიკავოთ და სიმშვიდე შეინარჩუნოთ. გავრცელებული შეხედულების საპირისპიროდ, ბავშვისთვის საპასუხოდ კბენა, რათა მას ეს ქცევა გადააჩვიოთ, არავითარ შემთხვევაში არ არის სწორი მეთოდი. შეეცადეთ გაიგოთ, რა პრობლემა იწვევს მის ასეთ ქცევას. როდესაც ბავშვი კბენას ცდილობს, შეგიძლიათ ხმის აუწევლად, მაგრამ მკაფიოდ უთხრათ „არა“ და მისი ყურადღება სხვა რამეზე გადაიტანოთ.') WHERE id = '32da4abc-32c4-45a0-9bb4-5ecb9adc28f3';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენს ბავშვს უკვე თითქმის ყველა სახის ხილის, ბოსტნეულისა და პარკოსნის ჭამა შეუძლია. თუმცა, არ უნდა დაგავიწყდეთ, რომ მისი საჭმლის მომნელებელი სისტემა თქვენსასთან შედარებით ჯერ კიდევ სრულად არ არის განვითარებული. ამიტომ უნდა გაითვალისწინოთ, რომ ბავშვის ორგანიზმმა შესაძლოა კვლავ გამოავლინოს რეაქცია ძროხის რძესა და ზოგიერთ ალერგენულ ხილზე. განსაკუთრებით ძროხის რძემ შეიძლება ზოგიერთ ბავშვში გამოიწვიოს ჭარბი აირების დაგროვება, მუცლის ტკივილი და ღებინება. ძროხის რძის ალერგია არის ბავშვის ორგანიზმის პათოლოგიური რეაქცია რძეში არსებულ ცილებზე. ამიტომ ზოგიერთი სპეციალისტი მიიჩნევს, რომ ბავშვს ძროხის რძე 2 წლამდე არ უნდა მისცეთ. გარდა ამისა, ისეთმა ხილმა, როგორიცაა მარწყვი, მანდარინი და ფორთოხალი, რომელთა ერთ წლამდე მიცემას სპეციალისტები ალერგენულობის გამო არ გვირჩევენ, შესაძლოა ბავშვში კვლავ გამოიწვიოს ალერგიული რეაქციები. ამიტომ, მაშინაც კი, თუ ბავშვს მისი განვითარების ეტაპისთვის შესაფერის საკვებს აძლევთ, პირველად გასასინჯი პროდუქტი მაინც სამდღიანი წესის დაცვით უნდა შესთავაზოთ. ასე უფრო მარტივად დაადგენთ, რომელ საკვებზე აქვს ბავშვს ალერგია.') WHERE id = 'd1d27c7e-e74b-46d9-99df-1056732e6f26';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი ფიზიოლოგიურად მუდმივად ვითარდება და იზრდება. გარემო ფაქტორებს განსაკუთრებული მნიშვნელობა აქვს ბავშვისთვის, რომელიც ზრდისა და განვითარების ჯერ კიდევ მეტად კრიტიკულ ეტაპზე იმყოფება. ამ პერიოდში ძალიან მგრძნობიარე ჰორმონულ და ნერვულ სისტემებზე ზოგიერთმა ქიმიურმა ნივთიერებამ შეიძლება სერიოზული გავლენა მოახდინოს. მაგალითად, სასოფლო-სამეურნეო წარმოების გასაზრდელად და მავნებლებისგან დასაცავად გამოყენებულმა პესტიციდებმა შეიძლება ზიანი მიაყენოს როგორც ადამიანს, ისე ბუნებას. ჯანმოს კვლევების თანახმად, ყოველწლიურად მილიონობით ადამიანი იწამლება სასოფლო-სამეურნეო პესტიციდებით. ასევე უკვე ცნობილია, რომ პლასტმასის ჭურჭელში არსებული BPA (ბისფენოლი A) ბავშვებში ყურადღების დეფიციტს იწვევს. ამიტომ ძალიან მნიშვნელოვანია, დარწმუნდეთ, რომ ბავშვისთვის გამოყენებული პლასტმასის პროდუქტები აუცილებლად BPA-ს არ შეიცავს.') WHERE id = 'd3a7bf68-2545-4f73-9f08-c29856b1742b';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ ამ ეტაპამდე მენსტრუაცია ჯერ კიდევ არ დაგწყებიათ, ამაზე ნერვიულობა სრულიად ბუნებრივია. თუმცა, ორგანიზმის ჰორმონული ბალანსის მიხედვით, მშობიარობიდან პირველი 24 თვის განმავლობაში მენსტრუაციის არქონა ნორმად მიიჩნევა. მენსტრუაციის დაწყების შემდეგაც შესაძლებელია, რომ დაახლოებით 12 თვის განმავლობაში ციკლი არარეგულარული იყოს და სისხლდენის რაოდენობა იცვლებოდეს. ზოგადად, მეძუძურ დედებს მენსტრუაცია უფრო გვიან ეწყებათ, ვიდრე ქალებს, რომლებიც ბავშვს ძუძუთი არ კვებავენ. თუმცა, ეს ერთადერთ კრიტერიუმად არ უნდა ჩაითვალოს. ძუძუთი კვების პერიოდში თავის ტვინის ჰიპოთალამუსის არეში გამომუშავებული ჰორმონები — პროლაქტინი და ოქსიტოცინი — კვერცხუჯრედის მომწიფებას ანელებს. ამ თვიდან ბავშვის საკვები საჭიროებების ნახევარი მყარი საკვებით კმაყოფილდება, ამიტომ ჰორმონების დონის გარკვეული შემცირების შედეგად შესაძლოა მენსტრუაცია დაგეწყოთ. თუმცა, თუ ძუძუთი კვების დასრულებიდან 3 თვის შემდეგაც არ გექნებათ მენსტრუაცია, სასურველია, გინეკოლოგს მიმართოთ.') WHERE id = '7d00f7d8-ae72-4092-bee7-fb933ce52595';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'რკინა, რომელიც ბავშვის სისხლში არსებული ჟანგბადის ქსოვილებამდე მიწოდებას უზრუნველყოფს, ერთ-ერთი უმნიშვნელოვანესი მინერალია. რკინის დეფიციტის მქონე ბავშვებში უმადობა ერთ-ერთი ყველაზე გავრცელებული პრობლემაა. ასევე ხშირად გვხვდება ტირილისას გალურჯება და სუნთქვის შეჩერება. თუ შეამჩნევთ, რომ ბავშვი მოუსვენარი და გაღიზიანებულია და ყურადღების მოკრებას ვერ ახერხებს, შეგიძლიათ ექიმს საჭირო ანალიზების ჩატარება სთხოვოთ. გავრცელებული მოსაზრებით, 1-3 წლის ბავშვებმა დღეში დაახლოებით 7 მგ რკინა უნდა მიიღონ. ამიტომ ბავშვის კვების რაციონში უფრო ხშირად უნდა შეიტანოთ ისეთი პროდუქტები, როგორიცაა წითელი და თეთრი ხორცი, თევზი, კვერცხი და რძე. თუ ფიქრობთ, რომ ბავშვს წითელი და თეთრი ხორცის მონელება უჭირს, შეგიძლიათ ისინი რეგულარულად დაუმატოთ ბოსტნეულის კერძებს. გახსოვდეთ, რომ ყველა სახის პარკოსანი, ლობიო, ისპანახი, სტაფილო, კარტოფილი და ჩირი, საკმარისი რაოდენობით მიღების შემთხვევაში, ასევე დაეხმარება ბავშვს ცილის ყოველდღიური საჭიროების დაკმაყოფილებაში.') WHERE id = '8d2b01ca-6cc3-467d-9372-bc9b93da9f40';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'იწერთ სადმე ბავშვის მიერ წარმოთქმულ პირველ სიტყვებს? თუ არა, მათი მშვენიერ მოგონებად შენახვა შესანიშნავი იდეაა! 😊 ერთი წლის ასაკის შესრულების შემდეგ ბავშვს უკვე მრავალი სიტყვის თქმა შეუძლია. თუმცა ამ თვის განმავლობაში მათგან ჯერ კიდევ მხოლოდ მცირე ნაწილია გააზრებული სიტყვა. გააზრებული სიტყვების გამოყენების დაწყება ნიშნავს, რომ ბავშვს ყურადღების მისაქცევად ტირილი თანდათან აღარ დასჭირდება. 😊 ბავშვის ენობრივი და მეტყველების უნარების გასავითარებლად არ დაგავიწყდეთ მასთან თამაში და ბევრი საუბარი. ცნობილია, რომ ბავშვებს, რომლებიც ადამიანებით გარემოცულ, აქტიურ სოციალურ გარემოში იზრდებიან და რომლებთანაც ბევრს საუბრობენ, მეტყველება უფრო სწრაფად უვითარდებათ. ამიტომ, ბავშვს ახალი სიტყვის შესასწავლად შეგიძლიათ ხშირად ავარჯიშოთ, ხოლო როდესაც იმ სიტყვის წარმოთქმას შეძლებს, რომლის სწავლებასაც ცდილობთ, ჩახუტებით წაახალისოთ. ასევე ძილის წინ ბავშვისთვის წიგნის წაკითხვა ძალიან სასარგებლო იქნება როგორც თქვენთვის, ისე მისთვის.') WHERE id = '68b3d7fb-f868-4d9c-8326-d2aa2fa33869';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის კვებისას მნიშვნელოვანია, რომ მან საკმარისი რაოდენობით მიიღოს იოდი — მინერალი, რომელიც ყველა მეტაბოლური პროცესის მარეგულირებელ ფარისებრ ჯირკვალს სჭირდება. იოდი ფარისებრი ჯირკვლის ჰორმონების შემადგენელი ნაწილია, ეს ჰორმონები კი ბავშვის ტვინის განვითარებისა და ჯანსაღი ზრდის უმნიშვნელოვანესი საფუძველია. ამ მინერალის ბალანსი ძალიან ფაქიზია და როგორც ნაკლებმა, ისე საჭიროზე მეტმა მიღებამ შეიძლება მრავალი პრობლემა გამოიწვიოს. ეს მინერალი ზღვებში გვხვდება, თუმცა წყლის აორთქლებისა და ნალექის სახით ნიადაგში მოხვედრის შედეგად მცენარეებშიც არის. მიუხედავად ამისა, იოდის ყველაზე მნიშვნელოვანი წყარო თევზი და ზღვის პროდუქტებია. იოდის მნიშვნელოვანი რაოდენობა ასევე გვხვდება ისპანახში, გოგრაში, ნიორსა და ზოგიერთ პარკოსანში. თუ ბავშვი ამ პროდუქტების ჭამაზე უარს ამბობს, შეგიძლიათ სეზონზე ბევრი მარწყვი მიირთვათ. გარდა ამისა, ორი პატარა ჯამი იოგურტი, ერთი ჭიქა რძე და საუზმეზე მიცემული ერთი კვერცხი მისი იოდის ყოველდღიური საჭიროების საკმარისად დაკმაყოფილებას უზრუნველყოფს.') WHERE id = 'e59fa1f2-cb77-40ca-b9d1-6dbc6abcb2a5';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვთან დროის გატარებისას რამდენიმე საკითხს უნდა მიაქციოთ ყურადღება. მათგან ყველაზე მნიშვნელოვანია, მასთან ყოფნის დროს როგორც ფიზიკურად, ისე გონებრივად მხოლოდ ბავშვზე იყოთ კონცენტრირებული. მაგალითად, თუ მისთვის წიგნის კითხვისას ან კუბებისგან კოშკის ერთად აშენებისას თან ტელევიზორს უყურებთ ან ტელეფონით ხართ დაკავებული, ეს მას კონცენტრაციაში ხელს შეუშლის. ამის გამო ბავშვმა შეიძლება ყურადღება სრულად ვერ მოიკრიბოს, ერთად გატარებული დრო ნაკლებად ხარისხიანი გახდეს და ის მალე მოიწყინოს. თუ ფიქრობთ, „როგორ გავატარო ბავშვთან ხარისხიანი დრო?“, შეგვიძლია ეს მოკლე მაგალითით აგიხსნათ. უპირველეს ყოვლისა, დარწმუნდით, რომ ბავშვი დანაყრებულია და საფენი სუფთა აქვს. მიეცით საშუალება, წიგნებიდან ერთ-ერთი თავად აირჩიოს. შერჩეული წიგნი ისე წაუკითხეთ, რომ გვერდებს ხედავდეს და თვალყურს გადევნებდეთ. მისთვის საინტერესო სურათზე ან გვერდზე უფრო დიდხანს შეჩერდით და ეცადეთ, მისი ინტერესის გამომწვევი დეტალი აღწერითი წინადადებებით აუხსნათ. სასიამოვნო გართობას გისურვებთ! 😊') WHERE id = '0c72e589-c1b8-4d06-947f-ca255a690b32';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში, ინდივიდუალურ პიროვნებად ჩამოყალიბების პროცესში, ბავშვს შეიძლება გადაწყვეტილებების დამოუკიდებლად მიღება მოუნდეს. ერთ-ერთი ასეთი სურვილია, რომ კვების სკამის ნაცვლად მისთვის ჩვეული წესით, წამოწოლილმა ჭამოს. მიუხედავად იმისა, რომ ეს ნებისმიერ ასაკში სარისკოა, წამოწოლილ მდგომარეობაში კვება განსაკუთრებით დიდ საფრთხეს ჩვილობის პერიოდში ქმნის. საჭმლის მომნელებელ და სასუნთქ სისტემებს შორის, ენის ძირის უკანა ნაწილში მდებარე ხრტილი დამცავ ფუნქციას ასრულებს და საკვების სასუნთქ გზებში მოხვედრას უშლის ხელს. წამოწოლილ მდგომარეობაში კვებისას ეს ხრტილი თავის ფუნქციას სრულად კარგავს. ამის გამო მიღებული საკვები შესაძლოა საყლაპავის ნაცვლად სასუნთქ მილში მოხვდეს. წამოწოლილ მდგომარეობაში ნებისმიერი საკვების მიღება სარისკოა. ამასთანავე, განსაკუთრებით მყარ საკვებზე გადასვლის პერიოდში, ძალიან მნიშვნელოვანია მხოლოდ კვების სკამის გამოყენება. გარდა ამისა, თუ ბავშვი ტელევიზორს უყურებს ან სხვა რამით არის დაკავებული, საკვებზე სრულად ვერ კონცენტრირდება, რის გამოც აღნიშნულმა დამცავმა მექანიზმმა შესაძლოა სათანადოდ ვერ იმუშაოს. ამიტომ ერთ-ერთი უმნიშვნელოვანესი საკითხი, რომელსაც ყურადღება უნდა მიაქციოთ, არის ის, რომ ჭამის დროს ბავშვი მხოლოდ საკვებზე იყოს კონცენტრირებული და კვების პროცესი მხოლოდ კვების სკამში დაასრულოს.') WHERE id = 'a96b4d14-328a-4913-8705-3d205531513b';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ზოგიერთ პერიოდში, გადატანილი დაავადებების გამო, ბავშვის სხეულის ტემპერატურამ შეიძლება მოიმატოს, ანუ მას სიცხე ჰქონდეს. ბავშვის ტემპერატურის გარკვეული ინტერვალებით კონტროლი შესაძლო დაავადების ადრეული დიაგნოსტიკისთვის ძალიან მნიშვნელოვანია. სხეულის ტემპერატურის მატებისას ორგანიზმი ჩვეულებრივზე მეტი ენერგიის ხარჯვას იწყებს. სისხლის მიმოქცევისა და სასუნთქი სისტემები უფრო სწრაფად მუშაობს. ამასთანავე, სიცხის დროს ხელებსა და ფეხებში სისხლძარღვები ვიწროვდება, ამიტომ ამ უბნებს ნაკლები სისხლი მიეწოდება. სასიცოცხლოდ მნიშვნელოვან ორგანოებში, როგორიცაა ტვინი, გული და ღვიძლი, კი სისხლის ნაკადი იმატებს. ეს ნიშნავს, რომ სიცხის დროს ბავშვს მეტი ჟანგბადი და სითხე სჭირდება. როდესაც იგრძნობთ, რომ ბავშვს სიცხე აუწია, შეგიძლიათ სახსრებზე თბილი წყლითა და ბამბით კომპრესი დაადოთ, სითხის საჭიროების დასაკმაყოფილებლად წყალი დაალევინოთ და ყურადღება მიაქციოთ, რომ თხლად ეცვას. მთავარი, რასაც ყურადღება უნდა მიაქციოთ, ისაა, რომ ბავშვის ტემპერატურამ 38.5°C-ს არ გადააჭარბოს. თუ ტემპერატურა ამ ნიშნულს მიაღწევს, კრუნჩხვის რისკის გამო სასიცოცხლოდ მნიშვნელოვანია, ბავშვი დროის დაკარგვის გარეშე უახლოეს სამედიცინო დაწესებულებაში წაიყვანოთ.') WHERE id = 'e1d2295d-b294-489f-9966-9998c1e7d923';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ ფიქრობთ, რომ რაიმე მოვლენის საპასუხოდ ბავშვი საკუთარ თავს ან გარშემომყოფებს ფიზიკურ ზიანს აყენებს, უნდა შეეცადოთ პრობლემის ძირითადი მიზეზის პოვნას. მაგალითად, თუ ბავშვი თქვენთვის აშკარა მიზეზის გარეშე ურტყამს, კბენს, ქაჩავს ან ხელს კრავს საკუთარ თავს ან სხვებს, ამის მიზეზი შესაძლოა ყურადღების მიპყრობის სურვილი იყოს. ასეთი ქცევა ხშირად გვხვდება ბავშვებში, რომლებსაც არ სურთ მშობლების ყურადღების სხვებისთვის გაზიარება. ახალი და-ძმის ან გარემოში სხვა ბავშვის გამოჩენამ, ასევე ბავშვის უარყოფამ მაშინ, როდესაც მას თქვენთან დროის გატარება სურს, შეიძლება ასეთი ქცევის განვითარებას შეუწყოს ხელი. ზოგიერთი სპეციალისტის აზრით, ბავშვისთვის მოსაბეზრებელი აქტივობების ზედმეტად ხშირად გამეორებამ, მუდმივად ერთსა და იმავე გარემოში ყოფნამ, სოციალიზაციის ნაკლებობამ და მისთვის უჩვეულო ხმაურმა, სუნმა თუ გემომაც კი შეიძლება ეს პრობლემა გამოიწვიოს. ასეთ შემთხვევებში ბავშვმა არ იცის, როგორ მოიქცეს, და მისთვის გაუგებარ ემოციებს ერთგვარ ენერგიად გარდაქმნის, რის გამოც შესაძლოა ზიანის მიყენებისკენ გახდეს მიდრეკილი. ასეთი ქცევის შემდეგ ბავშვის დადანაშაულების ნაცვლად, უმჯობესია, გაგებით მოეკიდოთ. თუ ფიქრობთ, რომ პრობლემასთან დამოუკიდებლად გამკლავება გიჭირთ, კარგი გადაწყვეტილება იქნება სპეციალისტისთვის დახმარების თხოვნა.') WHERE id = '3c27d24b-b488-40e8-9ae3-4a71940c8781';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ტრადიციულ სოფლის მეურნეობაში გამოყენებული ქიმიური ნივთიერებების დიდი ნაწილი ბავშვის ორგანიზმის ცხიმოვან ქსოვილში გროვდება. ბავშვის ჩამოყალიბების პერიოდიდან, ანუ ჯერ კიდევ დაბადებამდე და დაბადებიდან პირველი 36 თვის განმავლობაში, ზრდა და ცხიმოვანი უჯრედების წარმოქმნა განსაკუთრებით სწრაფად მიმდინარეობს. ამ პერიოდებში ქიმიური ნივთიერებების ზემოქმედება შეიძლება მომავალში ბავშვის ჯანმრთელობაზე სერიოზულად მოქმედ ერთ-ერთ ფაქტორად იქცეს. არაორგანული ხილისა და ბოსტნეულის ყველაზე დიდ საფრთხეს მათში დარჩენილი პესტიციდების ნარჩენები წარმოადგენს. ბავშვის ორგანიზმი თქვენსაზე ბევრად მგრძნობიარე და დაუცველია. ამიტომ ბავშვის ორგანიზმს ამ პესტიციდების ნარჩენების უსაფრთხოდ გამოდევნა არ შეუძლია. ამ ინფორმაციის გათვალისწინებით, ჯანდაცვის ორგანიზაციები და პედიატრები ბავშვის ჯანმრთელობისთვის კრიტიკულად მნიშვნელოვან პერიოდებში განსაკუთრებით ორგანული პროდუქტების მიღებას გვირჩევენ. ამიტომ ბავშვის ჯანმრთელობისთვის ხილისა და ბოსტნეულის არჩევისას უპირატესობა ორგანულ პროდუქტებს უნდა მიანიჭოთ.') WHERE id = '130cff01-0ee0-4d85-a9f9-730114f30e31';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ ბავშვისთვის აქამდე ძილის ჩვევის ჩამოყალიბება ვერ შეძელით, ახლა შესაძლოა შედარებით რთული პერიოდი გელოდოთ. ბავშვები, რომლებსაც რწევით, ხელში ჩახუტებულებს ან კვების დროს ეძინებათ, გარკვეული პერიოდის შემდეგ ამ რიტუალების მუდმივად გაგრძელებას ითხოვენ. მაგალითად, თუ მე-6 თვეში ბავშვს დასაძინებლად 15 წუთი არწევდით, ახლა შესაძლოა მხოლოდ 60-წუთიანი რწევის შემდეგ ჩაეძინოს. ამასთანავე, თუ ბავშვი ხშირად იღვიძებს და დამოუკიდებლად ხელახლა ჩაძინება არ შეუძლია, მისი ძილის ხარისხი შეიძლება მნიშვნელოვნად გაუარესდეს. ძილის სწავლება ბავშვს ჩაძინებასა და უწყვეტად ძილში ეხმარება. სპეციალისტებს ძილის სწავლების შესახებ განსხვავებული მოსაზრებები და მეთოდები აქვთ. თითოეულ მეთოდს თავისი უპირატესობები და უარყოფითი მხარეები გააჩნია, რადგან ძილის სწავლების ერთი უნივერსალური ტექნიკა, რომელიც ყველა ბავშვს მოერგება, არ არსებობს. ძილის სწავლების საკითხზე შეგიძლიათ დახმარებისთვის ექიმს ან ძილის სპეციალისტს მიმართოთ, შეარჩიოთ თქვენთვის და თქვენი ბავშვისთვის ყველაზე შესაფერისი ტექნიკა და მისი გამოყენება დაიწყოთ.') WHERE id = 'ac9afa68-79a2-47e7-9eb6-1a18006b8d77';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ ეტაპზე ბავშვის სეზონური, მრავალფეროვანი და დაბალანსებული კვება ძალიან მნიშვნელოვანია არა მხოლოდ მისი ზრდისთვის, არამედ იმისთვისაც, რომ მომავალში, ხანდაზმულ ასაკშიც კი, ჯანსაღად იცხოვროს. ამ პერიოდში საკვებიდან მიღებულ კალციუმს ბავშვის ორგანიზმი ზრდის პერიოდის დასრულებამდე ძლიერი ძვლოვანი სტრუქტურის ჩამოსაყალიბებლად იყენებს. ბავშვის ჯანსაღი განვითარებისთვის კალციუმი ასევე აუცილებელია კუნთების შეკუმშვისთვის, ნერვული სისტემის გამართული მუშაობისა და ზოგიერთი ჰორმონის ფუნქციონირებისთვის. როდესაც ამ ფუნქციების შესასრულებლად ორგანიზმს საკმარისი კალციუმი არ აქვს, ის ძვლებში არსებულ კალციუმს იყენებს. კალციუმის არასაკმარისად მიღებისას ან სხვადასხვა მიზეზით ორგანიზმში მისი შეწოვის დარღვევის შემთხვევაში შეიძლება განვითარდეს ისეთი პრობლემები, როგორიცაა ოსტეოპოროზი, ძვლების ადვილად მოტეხილობა და კბილების კარიესი. ამიტომ ბავშვის კვების რაციონში კალციუმით მდიდარი პროდუქტები დაბალანსებულად და რეგულარულად უნდა შედიოდეს. ამ ეტაპზე ბავშვის ყოველდღიური მოთხოვნილება კალციუმზე დაახლოებით 500 მგ-ია. ეს დაახლოებით 2 ჭიქა რძის ეკვივალენტური რაოდენობაა.') WHERE id = '5c393b52-f9a1-4c68-a9cf-d1637f40a2ce';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი უკვე იმ დონემდე განვითარდა, რომ წვრილი მოტორული უნარებიდან ერთ-ერთს — თითის წვერებით მოჭერას (პინცეტურ ჩავლებით მოძრაობას) — მარტივად ასრულებს. ეს ნიშნავს, რომ განსაკუთრებით ჭამის დროს ბავშვს უკვე შეუძლია კოვზის თავისუფლად და სწორად დაჭერა. ამ უნარის შეძენის შემდეგ ბავშვისთვის უკვე შეგიძლიათ ფერადი ფანქრები და გასაფერადებელი წიგნებიც შეიძინოთ! 😊 გაფერადება ხელს უწყობს არა მხოლოდ ბავშვის წვრილი კუნთების განვითარებას, არამედ აუმჯობესებს ხელისა და თვალის კოორდინაციასაც. ამ მეტად სასიამოვნო აქტივობის წყალობით ბავშვს უვითარდება ყურადღების კონცენტრირების უნარი და ის ფერების შესწავლას იწყებს. ამ პერიოდში გაფერადებისას ბავშვმა შესაძლოა გამოყენებული ნივთების შესასწავლად ისინი პირში ჩაიდოს და ჭამა სცადოს. ამიტომ გაფერადების დროს ბავშვი არასოდეს დატოვოთ მარტო და განსაკუთრებული ყურადღება მიაქციეთ შესაძენი ნივთების ხარისხს. სასიამოვნო გართობას გისურვებთ! 😊') WHERE id = '238df585-4e45-41a7-a863-82dc10a5f6bf';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში ბავშვის დგომის პოზამ შეიძლება ზოგჯერ შეგაშფოთოთ. განსაკუთრებით ბავშვები, რომლებიც სიარულს ახლა სწავლობენ, წონასწორობის შენარჩუნებას წინ გადახრილი ტანით ცდილობენ. ასეთი პოზა შეიძლება გაგრძელდეს მანამ, სანამ ბავშვი სრულად დაეუფლება სიარულს და წონასწორობის შენარჩუნებაში თავდაჯერებული გახდება. ასევე, როგორც ბავშვების უმრავლესობის შემთხვევაში, შესაძლოა შეამჩნიოთ, რომ დგომისა და ნაბიჯების გადადგმის ეტაპზე თქვენს ბავშვს ტერფები გარეთ აქვს მიბრუნებული. ამის მიზეზი მენჯ-ბარძაყის მიდამოში შემაერთებელი ქსოვილების ჯერ კიდევ სირბილეა. შედეგად, ბავშვს შესაძლოა ფეხების სწორ პოზიციაში დაჭერა არ შეეძლოს. როდესაც ბავშვი ორი წლის ასაკს მიუახლოვდება, ეს ქსოვილები თანდათან გამყარდება და ის შეძლებს ფეხების სათანადო პოზიციაში დაჭერას. თუ სიარულის სწავლის ეტაპზე ბავშვს ამ ან სხვა განსხვავებულ ნიშნებს შეამჩნევთ, შეგიძლიათ ექიმს მიმართოთ.') WHERE id = '8f8df060-6fb0-4f3e-9d13-5fa9a316d2ab';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუთია ძალიან მნიშვნელოვანია, რადგან ის შედის იმ ანტისხეულების შემადგენლობაში, რომლებიც ბავშვის ორგანიზმში ინფექციებთან ბრძოლისას წარმოიქმნება. თუთიის წყალობით, ჯერ კიდევ განვითარებადი იმუნური სისტემა უფრო ძლიერდება, ხოლო ორგანიზმში წარმოქმნილი დაზიანებები სწრაფად ხორცდება. სპეციალისტების აზრით, ბავშვის ამ ასაკობრივ ჯგუფს დღეში საშუალოდ 3 მგ თუთია სჭირდება. ბავშვის კვების რაციონში თუთიის შემცველი პროდუქტების დამატებით შეგიძლიათ ხელი შეუწყოთ მისი იმუნური სისტემის გაძლიერებას. ქათამი, წითელი ხორცი, ლობიო, ყველის სხვადასხვა სახეობა, იოგურტი და სრულმარცვლოვანი პროდუქტები თუთიის საუკეთესო წყაროებს შორისაა. ამასთანავე, პრობიოტიკები, რომლებიც ბავშვის ნაწლავის ფლორის დაცვას უწყობს ხელს, თუთიის შემცველობის მხრივაც საკმაოდ მნიშვნელოვანია. ამიტომ ბავშვის კვების რაციონში შეგიძლიათ დაამატოთ მაღალი პრობიოტიკური ღირებულების მქონე რძის პროდუქტები, როგორიცაა იოგურტი და კეფირი.') WHERE id = '60910a3a-5d54-4db7-a85a-700511cdfbaf';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თუ ბავშვს ცალკე ოთახი აქვს, იქ არსებული ხალიჩის სისუფთავეს განსაკუთრებული ყურადღება უნდა მიაქციოთ. თუ არ გსურთ, რომ ხალიჩა ხშირად დაბინძურდეს, უპირველესად ის რეგულარულად მტვერსასრუტით უნდა გაწმინდოთ. თუმცა, რადგან თქვენი ბავშვი გარემოს შეცნობის სურვილითაა სავსე, რამდენიც არ უნდა გაწმინდოთ, ხალიჩაზე ლაქების გაჩენა გარდაუვალია. ასეთ შემთხვევებში მაშინვე ძლიერ ქიმიურ საშუალებებს ნუ გამოიყენებთ. თავდაპირველად სცადეთ მხოლოდ თბილი წყლით მექანიკური გაწმენდა. ყინულისა და ორთქლის საწმენდი აპარატის გამოყენებაც უსაფრთხო მეთოდებია მსუბუქი ლაქებისთვის. თუ ლაქები არ ქრება, ძლიერი ქიმიური საშუალებების ნაცვლად შეგიძლიათ სახლში მომზადებული ნარევი გამოიყენოთ. ერთი ფინჯანი თეთრი ძმრისა და ორი ფინჯანი წყლის შერევით ლაქების ადვილად გაწმენდაა შესაძლებელი. თუ ლაქები მაინც არ ამოვიდა, ნარევს შეგიძლიათ დაუმატოთ არაუმეტეს ერთი სუფრის კოვზი ჭურჭლის სარეცხი სითხე.') WHERE id = '2dc63046-9c98-4c12-82b7-0078c136176f';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'შესაძლოა, გაღელვებდეთ, რომ ბავშვს, განსაკუთრებით ზოგიერთ დღეებში, ბრაზის შეტევები (ისტერიკა) აქვს. ეს ჩვეულებრივ მაშინ ხდება, როცა მისი სურვილები არ სრულდება. ასეთი ბრაზის შეტევები უფრო ხშირად ახლად ფეხადგმულ ბავშვებში გვხვდება, შეიძლება 1 წლის შემდეგ დაიწყოს და პერიოდულად 4 წლამდე გაგრძელდეს. ბოლო კვლევების თანახმად, 1-4 წლის ბავშვების 85%-ს მსგავსი მდგომარეობა ერთხელ მაინც გამოუცდია. ამიტომ, როცა თქვენი ბავშვი ბრაზდება, თავს ნუ დაადანაშაულებთ და გახსოვდეთ, რომ ეს ბუნებრივი პროცესია. ასეთ სიტუაციაში რამდენიმე მნიშვნელოვანი საკითხი უნდა გაითვალისწინოთ. თუ მის გარშემო არის ნივთები, რომლებმაც შეიძლება ზიანი მიაყენოს, ბავშვი დაუყოვნებლივ უსაფრთხო ადგილას გადაიყვანეთ. ჩაეხუტეთ, უსაფრთხოების განცდა შეუქმენით და ყურადღების გადატანა სცადეთ. თუ არცერთი ეს მეთოდი არ იმუშავებს, გვერდიდან ნუ მოშორდებით, მაგრამ სანამ არ დამშვიდდება, მასთან პირდაპირ კომუნიკაციაში ნუ შეხვალთ.') WHERE id = 'e1849b6d-7712-4f59-9d5f-7999fc0f6ae5';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის ჯანსაღი ზრდისთვის კვების რაციონში ერთ-ერთი მნიშვნელოვანი ნივთიერება სელენია. სელენი მნიშვნელოვან როლს ასრულებს ბავშვის თმისა და ფრჩხილების სტრუქტურის შენარჩუნებასა და მათ სიჯანსაღეში. ამასთანავე, ანტიოქსიდანტური თვისებების წყალობით, ის ბავშვის იმუნური სისტემისთვის მეტად სასარგებლოა. ამ სარგებელს სელენი ორგანიზმში უჯრედების დამაზიანებელი და დამაბერებელი თავისუფალი რადიკალების განეიტრალებით უზრუნველყოფს. სელენი ასევე ხელს უწყობს ფარისებრი ჯირკვლის ნორმალურ ფუნქციონირებას, რომელიც ბავშვის ჰორმონალურ ბალანსს არეგულირებს. ის ფარისებრ ჯირკვალს აუტოიმუნური შეტევებისგან იცავს და ჰაშიმოტოს დაავადების განვითარებას უშლის ხელს. ამიტომ ბავშვის მენიუში შეგიძლიათ დაამატოთ სელენით მდიდარი რძე და რძის პროდუქტები, თევზი, შავი ყურძენი, ბროკოლი, ნიგოზი და მარცვლეული პროდუქტები.') WHERE id = '385a4e35-463b-400b-a449-47047191ef07';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში თქვენს ბავშვს უკვე სრულიად დამოუკიდებლად უნდა შეეძლოს ჯდომა. ძალიან იშვიათად შეიძლება წონასწორობა დაკარგოს და წაიქცეს, თუმცა ამ პერიოდში განვითარებული მსხვილი მოტორული უნარებისა და კუნთოვანი მასის წყალობით, წონასწორობის დაკარგვისას ხელებზე დაყრდნობით თავის დაცვა უნდა შეძლოს. ამ თვეებში ბავშვის ტანის კუნთები საგრძნობლად ძლიერდება. შეგიძლიათ დააკვირდეთ, როგორ იხრება ხშირად, იღებს იატაკზე დავარდნილ სათამაშოს, დაღლილობისას ადვილად ჯდება ჩაცუცქულ მდგომარეობაში, როგორ ბრუნდება მუცელზე და როგორ გადადის მჯდომარე მდგომარეობიდან მწოლიარე მდგომარეობაში (და პირიქით). გაზრდილი მოძრავობის გამო, ერთი მნიშვნელოვანი საკითხი უნდა გაითვალისწინოთ: თუ ჯერ კიდევ იყენებთ, დროა, ბავშვის გამოსაცვლელი მაგიდა მოაშოროთ. საფენის გამოცვლისას ბავშვი შეიძლება თქვენთვის მოულოდნელი სისწრაფით გადაბრუნდეს, რამაც შეიძლება დაცემა ან თავის ტრავმა გამოიწვიოს. ამიტომ უფრო უსაფრთხოა, საფენი ფართო საწოლზე ან დივანზე გამოუცვალოთ და ქვემოთ სპეციალური საფენი დაუფინოთ.') WHERE id = '174ec7ea-cdae-4336-8a3e-e5772a684836';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი უკვე ნამდვილ პატარა მკვლევრად იქცა და ახლა სურს, საფუძვლიანად შეისწავლოს ყველა ნივთი, რომელიც მის ყურადღებას მიიქცევს, მიუხედავად იმისა, შეესაბამება თუ არა ის მის ასაკს. ნატიფი მოტორული უნარების წყალობით, ბავშვი ცდილობს შეამოწმოს, რისი გაკეთება შეუძლია ხელში აღებული ნივთებით. მათ შორისაა შერხევა, ერთმანეთზე მირტყმა, კედელზე მიჯახება, ერთი ხელიდან მეორეში გადატანა, სროლა და კბენა... 😊 თუ საფრთხე არ იქმნება და ბავშვი საკუთარ თავს არ აზიანებს, მისი განვითარებისთვის მნიშვნელოვანია, ზედმეტად არ ჩაერიოთ. ამ პერიოდში ბავშვი დიდ ინტერესს გამოიჩენს ბორბლებიანი სათამაშოების, ასაწყობ-დასაშლელი კუბებისა და მოძრავი ჭოჭინის ტიპის ნივთების მიმართ. ბავშვის საყვარელ აქტივობებს შორისაა ისეთი ნახვრეტებიანი ნივთების აღმოჩენაც, რომლებშიც თითების შეყოფა შეუძლია. ამიტომ აუცილებელია, ბავშვისგან შორს შეინახოთ ისეთი ნივთები, რომლებმაც შეიძლება საფრთხე შეუქმნას, მაგალითად, ელექტროროზეტები და სახეხი.') WHERE id = '044883c1-c92f-4911-bbe8-6d91510fdfdd';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენი ბავშვი პირდაპირ ითვისებს თქვენი და თქვენი ოჯახის კვების ჩვევებს. ამიტომ, რაც უფრო გვიან გააცნობთ მას შაქარს, შაქრის შემცველ პროდუქტებსა და შეფუთულ საკვებს, მით უკეთესი იქნება მისი ჯანმრთელობისთვის. ხილსა და რძეში არსებული ბუნებრივი შაქარი სრულიად საკმარისია მისი ენერგეტიკული მოთხოვნილების დასაკმაყოფილებლად. დამატებული შაქარი ბავშვის განვითარებას არანაირ სარგებელს არ აძლევს, ამასთან, შეიძლება ჩვევად იქცეს და მომავალში მრავალი დაავადების განვითარებას შეუწყოს ხელი. სპეციალისტები გვირჩევენ, განსაკუთრებით 0-3 წლის ასაკში, ბავშვები შაქარსა და დამატებული შაქრის შემცველ საკვებს მოვარიდოთ — სასურველია, სკოლის ასაკამდეც კი. თუ თქვენი ბავშვი ამ ეტაპამდე ტკბილ საკვებს მიეჩვია, შეგიძლიათ სახლში ბადაგით ან თაფლით დატკბობილი ნატურალური კექსები მოამზადოთ. ამგვარად, ბავშვი ყოველდღიურ ენერგეტიკულ მოთხოვნილებასაც დაიკმაყოფილებს და მავნე პროდუქტების ნაცვლად ბუნებრივ, დანამატების გარეშე მომზადებულ საკვებსაც მიიღებს.') WHERE id = '165f1f49-0759-4859-99bf-4fd465d6fe2b';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'იმისთვის, რომ თქვენს ბავშვს უფრო ჯანსაღად ეძინოს, პირველი ნაბიჯი ძილის წინ განსაზღვრული რუტინის შექმნაა. ასეთი რუტინა მის განვითარებაში მნიშვნელოვან როლს ასრულებს; ყოველდღიური აქტივობების განსაზღვრული თანმიმდევრობით გამეორება ბავშვს შეგუებას მნიშვნელოვნად გაუადვილებს. მიუხედავად იმისა, რომ რუტინის ჩამოყალიბება 4-6 თვის ასაკში უფრო მარტივია, ჯერ კიდევ არ დაგიგვიანიათ. მაგალითად, შეგიძლიათ შეარჩიოთ ისეთი აქტივობები, რომლებიც ბავშვს ძილის წინ მოსწონს და ამშვიდებს — ბანაობა, წიგნის წაკითხვა ან იავნანას სიმღერა. ამგვარად, ყოველი დაძინების წინ ამ თანმიმდევრობის დანახვისას ბავშვი მიხვდება, რომ ძილის დრო მოვიდა და დასაძინებლად უნდა მოემზადოს. აქ მთავარია მოთმინება, თანმიმდევრულობის დაცვა და ყოველდღე ერთნაირად გაგრძელება. ამასთან, თუ ბავშვს საწოლში მაშინ ჩააწვენთ, როდესაც უკვე ძალიან ეძინება, ის დამოუკიდებლად ჩაძინებას უფრო მარტივად ისწავლის. ამიტომ კარგად უნდა დააკვირდეთ და სწორად შეარჩიოთ მომენტი, როდესაც მას ძილი მოერევა.') WHERE id = 'e72c175e-57e8-4db2-8440-4cf54e9693fe';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის ძვლების ჯანსაღი განვითარებისთვის ყველაზე მნიშვნელოვანი ნივთიერება, უდავოდ, კალციუმია. კალციუმის საუკეთესო წყარო კი, განსაკუთრებით მცირეწლოვანი ბავშვებისთვის, რძეა. თუ თქვენს ბავშვს ძროხის რძეზე ალერგია არ აქვს და ექიმმა ნება დაგრთოთ, შეგიძლიათ მისთვის რძის მიცემა დაიწყოთ. რძე შეიცავს წყალს, ცხიმს, ცილას, ნახშირწყლებს, მინერალებსა და ვიტამინებს. უფრო ზუსტად, დაახლოებით 200 ml-იან ერთ ჭიქა რძეში 300 მგ კალციუმი, 9 გრამი ნახშირწყალი, 6 გრამი ცილა და 6 გრამი ცხიმია. რძე როგორც ზრდის, ისე განვითარების პერიოდში ძალიან ღირებული საკვებია. როგორც კალციუმის ერთ-ერთი უმდიდრესი წყარო, ის ხელს უწყობს კბილებისა და ძვლების ჩამოყალიბებას და მომავალში ძვლის სიმკვრივის შემცირების პრევენციას. შეგიძლიათ თქვენს ბავშვს დღეში დაახლოებით 2 ჭიქა რძე მისცეთ. თუმცა სიფრთხილე გმართებთ: განსაკუთრებით მაშინ, როდესაც დღიური რაოდენობა 500 ml-ს აღემატება, რძემ შეიძლება შეკრულობა და სისხლნაკლებობა (ანემია) გამოიწვიოს, ამიტომ მნიშვნელოვანია რაოდენობის სწორად განსაზღვრა.') WHERE id = 'be6e1172-84f7-42b6-b5e2-965f7afc4dd1';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის ტემპერატურამ სხვადასხვა მიზეზით შეიძლება მოიმატოს. ბუნებრივია, სრულიად ნორმალურია, თუ შიშობთ, რომ სიცხემ ბავშვს შეიძლება ზიანი მიაყენოს. ვაქცინაციის შემდეგ, კბილების ამოჭრის პერიოდში ან სხვადასხვა სახის შეუძლოდ ყოფნისას სხეულის ტემპერატურა შეიძლება ნორმაზე მაღალი იყოს. სინამდვილეში, ბავშვის სხეულის ტემპერატურა მუდმივი არ არის და დღის განმავლობაში გარკვეული რიტმით იცვლება. დილით ადრე ის შეიძლება 36 °C იყოს, დღის განმავლობაში კი — დაახლოებით 37,5 °C. ეს ცვლილებები უკავშირდება მოძრაობას, ტანსაცმლის სისქეს, ჰაერის ტემპერატურას, ძილს ან მიღებულ საკვებს. თუ იღლიის ქვეშ გაზომილი ტემპერატურა 37,2 °C-ზე, ხოლო რექტალურად გაზომილი — 38 °C-ზე მაღალია, ეს ნიშნავს, რომ ბავშვს სიცხე აქვს. გასათვალისწინებელია, რომ თუ ბავშვი ავად არ არის (მაგალითად, მხოლოდ კბილები ამოსდის), ტემპერატურა ჩვეულებრივ 38°C-ს არ აღემატება.') WHERE id = 'f4068428-56c5-4d18-9814-d5b4a6624690';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ალბათ უკვე შენიშნეთ, რამდენად სწრაფად გადის დღეები ამდენ საზრუნავსა და ფუსფუსში. თქვენ და თქვენმა ბავშვმა ერთად უკვე სრულად განვლეთ 16 თვე. 😊 ამ თვიდან ბავშვის გონებრივი ფუნქციები კიდევ უფრო განვითარდება. გაუმჯობესდება ისეთი უნარები, როგორებიცაა სწავლა, აღქმა, გაგება, ყურადღება, კონცენტრაცია და ინფორმაციის დამახსოვრება. მას უკვე შეუძლია დამახსოვრებული ინფორმაციის მარტივად გახსენება, ახალ გამოცდილებაში გამოყენება და ძველი და ახალი ცოდნის ერთმანეთთან დაკავშირებით თავისებური დასკვნების გამოტანა. მაგალითად, ჭამის დასრულების შემდეგ შეიძლება თეფში ამოაბრუნოს, თავზე დაიდოს და თქვას, რომ ეს ქუდია! 😊 სიარულისას ან ხოხვისას შეიძლება გაგონილი ცხოველების ხმები გაიმეოროს და მოინდომოს დარწმუნება, რომ თქვენ უყურებთ. მოკლედ, გარემოზე დაკვირვებითა და მისი შესწავლით მიღებულ ცოდნას ბავშვი ყოველდღიურ ცხოვრებაში ხშირად გამოიყენებს! 😊') WHERE id = '1cad17cc-eef5-4325-b0db-c446928d37c9';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, '16 თვის ასაკში ბავშვის საშუალო წონა გოგონებისთვის 9800 გრამია, ბიჭებისთვის კი — 10.500 გრამი. ბუნებრივია, ეს რიცხვები საშუალო მაჩვენებლებია და ქვედა და ზედა ზღვარი შეიძლება განსხვავებული იყოს. მიახლოებითი გამოთვლით, მოსალოდნელია, რომ 16 თვის ბავშვის წონა სულ მცირე 8250 გრამი იყოს. სიმაღლე კი გოგონებისთვის 73.3-83.9 სმ-ის, ხოლო ბიჭებისთვის 75.4-85.1 სმ-ის ფარგლებში უნდა იყოს. ამ თვის განმავლობაში, თუ ეს ჯერ არ მომხდარა, ბავშვისთვის უკვე ჩვევად ქცეული დღეში ორჯერ ძილი შეიძლება შეიცვალოს ერთი, უფრო ხანგრძლივი შუადღის ძილით. ბავშვის გონება ყოველ წამს ახალ ინფორმაციას ითვისებს. მის ძალიან აქტიურ და შეუჩერებლად მომუშავე ტვინს ამ ინფორმაციის დასამახსოვრებლად დასვენება სჭირდება. ამ თვალსაზრისით, დღის ძილი ბავშვს შესაძლებლობას აძლევს, გაიაზროს ნასწავლი, დაისვენოს და დღის დარჩენილი ნაწილისთვის ენერგია მოიკრიბოს. დღის ძილისთვის მნიშვნელობის მინიჭება და, თუ ეს ჯერ არ გაგიკეთებიათ, ჯანსაღი ძილის რეჟიმის ჩამოყალიბება მისი განვითარებისთვის ერთ-ერთი ყველაზე ეფექტური ნაბიჯია.') WHERE id = 'f1142bfa-de01-40ac-811f-43d85ed0de50';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ვიტამინების სარგებელი ბავშვის ჯანმრთელობისთვის განუზომელია. განსაკუთრებით B ჯგუფის ვიტამინების კომპლექსი მნიშვნელოვან როლს ასრულებს ბავშვის ორგანიზმში მრავალი სასიცოცხლო ფუნქციის მხარდაჭერაში. ისინი აქტიურად მონაწილეობენ ჰორმონების, სისხლის წითელი უჯრედების, ფერმენტებისა და ნეირონების წარმოქმნაში. ვიტამინების ეს ჯგუფი არეგულირებს ნახშირწყლების, ცილების და ცხიმების ცვლას და ბავშვის ორგანიზმში შინაგანი წონასწორობის შენარჩუნებას უწყობს ხელს. ეს ვიტამინები მონაწილეობენ სეროტონინის წარმოქმნაში და პირდაპირ გავლენას ახდენენ ბავშვის ძილის რეჟიმზე, განწყობასა და ტკივილის მიმართ მგრძნობელობაზე. ყოველივე ამის გამო, B ვიტამინის დეფიციტმა ბავშვში შესაძლოა ძილის პრობლემები და ცენტრალური ნერვული სისტემის ფუნქციონირების დარღვევა გამოიწვიოს. ბავშვისთვის B ვიტამინის მცენარეული წყაროებია: მზესუმზირა, თხილი, ნიგოზი, ფისტა, ნუში და სხვა კაკლეული, სოკო, პომიდორი, მწვანეფოთლოვანი ბოსტნეული, კარტოფილი, ფორთოხალი და ბანანი. ცხოველური წარმოშობის წყაროებია წითელი და თეთრი ხორცი, თევზი, ღვიძლი, რძე, კვერცხი, იოგურტი და კეფირი.') WHERE id = '43eb5d6e-1eaa-45a1-946e-ca86a7cd935b';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ბავშვის იმუნურ სისტემაზე, განსაკუთრებით ზამთრის თვეებსა და სეზონების ცვლილებისას, შესაძლოა უარყოფითად იმოქმედოს სხვადასხვა ფაქტორმა. აუცილებელია ბავშვის დაცვა ისეთი დაავადებებისგან, როგორებიცაა გრიპი და გაციება, რომლებიც იმუნიტეტს სწრაფად ასუსტებს. ამისთვის, უპირველეს ყოვლისა, უნდა დარწმუნდეთ, რომ ბავშვი საკმარის სითხეს იღებს, ხოლო მისი კვების რაციონი სეზონური ხილისა და ბოსტნეულის მიხედვით შეადგინოთ. ზამთრის თვეებში შეგიძლიათ ბავშვს უხვად მისცეთ C ვიტამინით მდიდარი საკვები, როგორიცაა სტაფილო, მწვანეფოთლოვანი ბოსტნეული, ფორთოხალი და მანდარინი. ეს ბავშვის იმუნურ სისტემას ინფექციებთან მებრძოლი სისხლის თეთრი უჯრედების რაოდენობის გაზრდაში ეხმარება, რის შედეგადაც ორგანიზმს ვირუსების განეიტრალება უფრო მარტივად შეუძლია. იმუნიტეტის გაძლიერებისთვის ასევე მნიშვნელოვანია ბავშვის მოწესრიგებული ძილის რეჟიმი და ხარისხიანი ძილი. გარდა ამისა, ბავშვის ორგანიზმის ბაქტერიებისგან დასაცავად ძალიან მნიშვნელოვანია, რეგულარულად ხელების დაბანის ჩვევა გამოუმუშაოთ, განსაკუთრებით გარედან სახლში დაბრუნების შემდეგ.') WHERE id = 'ff4f941f-2940-4484-b3f8-3aa7fa73b47c';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თევზი მაღალი ხარისხის ცილებს შეიცავს და ამავდროულად მდიდარია ბავშვის ორგანიზმისთვის ძალიან მნიშვნელოვანი ამინომჟავებით. თევზი ხელს უწყობს განსაკუთრებით ბავშვის ტვინისა და მხედველობის განვითარებას, ამიტომ მის კვების რაციონში ის კვირაში მინიმუმ 2-ჯერ უნდა შეიტანოთ. თუმცა ბავშვისთვის თევზის შერჩევისას რამდენიმე კრიტერიუმი უნდა გაითვალისწინოთ. მაგალითად, რადგან ბავშვის ორგანიზმი ძალიან მგრძნობიარეა, თავი უნდა აარიდოთ ფსკერის თევზებს, რომლებიც შესაძლოა მძიმე მეტალებს შეიცავდეს. მათ ნაცვლად ზედაპირულ წყლებში მობინადრე თევზი შეარჩიეთ და ყურადღება მიაქციეთ, რომ თევზი ახალი და სეზონის შესაბამისი იყოს. ასევე, დახრჩობის რისკის თავიდან ასაცილებლად ძალიან მნიშვნელოვანია, ბავშვისთვის განკუთვნილ თევზში ფხები არ იყოს. ხელოვნური ნარევის ან დედის რძის მიღება ბავშვისთვის თევზის ჭამას ხელს არ უშლის. მთავარი, რასაც ყურადღება უნდა მიაქციოთ, თევზის სიახლეა.') WHERE id = '143d7d0e-c659-4393-ad66-6a71451d969a';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ძვირფასო დედა, არავითარ შემთხვევაში არ უნდა დაუშვათ, რომ თქვენ ან სხვებმა ბავშვის გვერდით მოწიოთ — ამ საკითხში უკომპრომისო უნდა იყოთ. თამბაქოს კვამლი უამრავ ტოქსიკურ ნივთიერებას შეიცავს, რომლებიც ორგანიზმის ფუნქციებს სერიოზულ ზიანს აყენებს. გახსოვდეთ, რომ ეს მავნე ნივთიერებები ადვილად ვრცელდება არა მხოლოდ ჰაერით, არამედ ტანსაცმლისა და ამოსუნთქული ჰაერის მეშვეობითაც. რადგან ბავშვი ზრდასრულებთან შედარებით უფრო ხშირად სუნთქავს, ის კვამლის მიმართ მეტად მგრძნობიარეა. ბავშვის პასიური მოწევის ზემოქმედების ქვეშ ყოფნა, ხანმოკლე იქნება თუ ხანგრძლივი, მის ჯანმრთელობას დიდ საფრთხეს უქმნის. კვლევები აჩვენებს, რომ ბავშვებს, რომლებიც ადრეულ ასაკში თამბაქოს კვამლის ზემოქმედების ქვეშ იმყოფებოდნენ, უფრო ხშირად აღენიშნებათ ფილტვის ფუნქციის დაქვეითება, სასუნთქი გზების დაავადებები, როგორიცაა ასთმა და ბრონქიტი, ასევე ყურის ინფექციები.') WHERE id = '5e114626-fa98-4af5-a54c-9bc73d395ef6';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'მართალია, შეიძლება გახარებდეთ, რომ ბავშვი მის წინ დადებულ ყველაფერს მადიანად მიირთმევს, მაგრამ მთავარი მიზანი მხოლოდ მისი დანაყრება კი არა, განვითარებისთვის ყველაზე სასარგებლო საკვების მიცემა უნდა იყოს. მაგალითად, ბავშვის ორგანიზმს თქვენთან შედარებით ყოველდღიურად 6-ჯერ მეტი D ვიტამინი სჭირდება. ახალი ძვლოვანი ქსოვილის წარმოქმნისთვის მას ზრდასრულებთან შედარებით 4-ჯერ მეტი კალციუმი და 4-ჯერ მეტი C ვიტამინი ესაჭიროება. ასევე მაღალია თუთიისა და რკინის საჭიროებაც. ამიტომ ბავშვის პატარა კუჭი არ უნდა გაავსოთ ძნელად მოსანელებელი პურით ან თითქმის მხოლოდ წყლისგან შემდგარი, დაბალი კვებითი ღირებულების სუპებით. განსაკუთრებით პური არის ძნელად მოსანელებელი საკვები ბავშვისთვის, რომლის ნივთიერებათა ცვლა ჯერ სრულად ჩამოყალიბებული არ არის, და ის ორგანიზმის რეალურ მოთხოვნილებას ვიტამინებზე ვერ აკმაყოფილებს.') WHERE id = 'f03f7ef6-1201-4627-b01c-144e9eca5d2c';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამ პერიოდში, როდესაც ბავშვი სიარულს სწავლობს, ყველაზე სწორი არჩევანია, თავი აარიდოთ "ხოდუნოკის" (ჭოჭინას) გამოყენებას. ამერიკის პედიატრიის აკადემია კატეგორიულად არ უწევს რეკომენდაციას ჭოჭინას გამოყენებას ბავშვის მიერ სიარულის სწავლის პროცესში. ამის მიზეზი ისაა, რომ ბავშვი, რომელიც ფიზიკურად ჯერ სრულად მზად არ არის, ჭოჭინით გადაადგილებისას კუნთებს სათანადოდ ვერ აკონტროლებს. ამან შესაძლოა არა მხოლოდ კუნთების განვითარება შეაფერხოს, არამედ ხერხემლის პრობლემები და მენჯ-ბარძაყის სახსრების დაზიანებაც გამოიწვიოს. ჭოჭინა ძირითადად ბავშვის მხოლოდ წვივის კუნთებს ამუშავებს, მაშინ როცა დამოუკიდებლად სიარულისთვის ბარძაყისა და ფეხის ზედა ნაწილის კუნთებია მნიშვნელოვანი. რადგან ბავშვს ჭოჭინით სასურველ ადგილამდე მარტივად მისვლა შეუძლია, დამოუკიდებლად სიარულის მცდელობის საჭიროებას ვეღარ გრძნობს. ამიტომ სპეციალისტები ჭოჭინას გამოყენებას არ გირჩევენ.') WHERE id = '3fc30308-235c-40fd-b135-b2614f8aa914';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'B6 ვიტამინის, ანუ პირიდოქსინის შემცველი საკვები ბავშვის ყოველდღიურ მენიუში აუცილებლად უნდა შედიოდეს. B ჯგუფის ვიტამინებს მიკუთვნებული B6 უხვად გვხვდება როგორც ცხოველური, ისე მცენარეული წარმოშობის საკვებში, ამიტომ მისი მიღება საკვებიდან მარტივად შეიძლება. წყალში ადვილად ხსნადი ეს ვიტამინი სინათლის მიმართ ძალიან მგრძნობიარეა. B6 ვიტამინი უშუალოდ მონაწილეობს ბავშვის ორგანიზმში ცილების, ცხიმებისა და ნახშირწყლების ცვლაში და ძალიან მნიშვნელოვანია იმუნური სისტემის გამართული მუშაობისთვის. ამ ვიტამინის არასაკმარისი მიღებისას შეიძლება გაჩნდეს წყლულები ტუჩებსა და ენაზე, განვითარდეს სისხლნაკლებობა (ანემია), ზრდა-განვითარების შეფერხება და თირკმლის კენჭები. თუ ბავშვი დედის რძის ნაცვლად ხელოვნური ნარევით (ფორმულით) იკვებებოდა, მას B6 ვიტამინზე უფრო მეტი მოთხოვნილება აქვს. ამ ვიტამინის მიღება შესაძლებელია წითელი ხორციდან, ღვიძლიდან, მთლიანი მარცვლეულისა და პარკოსნებისგან, ამიტომ ეს პროდუქტები ხშირად უნდა შეიტანოთ ბავშვის რაციონში.') WHERE id = '77912752-b7a9-497a-99ba-585af752ea41';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'ამერიკის პედიატრიის აკადემიის თანახმად, ბავშვებს უმი თხილეულის მიღება დამატებით კვებაზე გადასვლის შემდეგ, 6-ცე თვიდან შეუძლიათ. თუმცა ჩვენს ქვეყანაში, თხილეულის ალერგიული პოტენციალის გათვალისწინებით, გავრცელებულია მოსაზრება, რომ მისი მიცემა პირველი 1 წლის განმავლობაში არ არის რეკომენდებული. ამ ეტაპზე კი, თუ ექიმს საპირისპირო არ უთქვამს და ბავშვს თხილეულზე ალერგია არ აქვს, მისი მიღება, განსაკუთრებით წასახემსებლად, ძალიან სასარგებლოა. როგორც ცნობილია, თხილეული ვიტამინებით, ანტიოქსიდანტებითა და უჯრედისით მდიდარი თესლეულია. ის ასევე უხვად შეიცავს ცილებს, ცხიმებსა და ისეთ მინერალებს, როგორიცაა მაგნიუმი, მანგანუმი და ქრომი. ამიტომ თხილეული ხელს უწყობს ბავშვის ზრდას, განვითარებასა და სწავლის უნარს. თუ ბავშვისთვის აქამდე თხილეული არ მიგიციათ, კარგი დასაწყისი შეიძლება ნიგოზი იყოს. ნიგოზი ომეგა-3-ით მდიდარია და სხვა სახეობის თხილეულთან შედარებით ნაკლებად ალერგიული პროდუქტია. ბავშვის განვითარების დონის გათვალისწინებით, თუ ფიქრობთ, რომ თხილეული მისთვის ზედმეტად მაგარი იქნება, შეგიძლიათ მცირე ხნით წყალში დაალბოთ. უპირატესობა უნდა მიანიჭოთ უმ თხილეულს და არა მოხალულს.') WHERE id = '6d0c5ce7-8563-49c1-be57-a0288743f236';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'თქვენს ბავშვს უკვე სურს, მშობლების მსგავსად, თავად გადაწყვიტოს, როდის და რა გააკეთოს. დამოუკიდებელ პიროვნებად ჩამოყალიბების ამ ეტაპზე ბავშვმა შეიძლება კვებისა და თამაშის დროის თავად განსაზღვრა სცადოს. როდესაც მიხვდება, რომ ძილის დრო მოვიდა, მაგრამ დაძინება არ სურს, შეიძლება მკვეთრად გააპროტესტოს და თამაში განაგრძოს. ასეთ დროს ბავშვს გაგებით უნდა მოეკიდოთ და ეცადოთ აუხსნათ, რომ გაბრაზება გამოსავალი არ არის. თუ ეს ბრაზი თქვენდამი ან საკუთარი თავის მიმართ ფიზიკურ აგრესიაში გადაიზრდება, შეგიძლიათ უთხრათ, რომ ასეთი ქცევა არასწორია და ტკივილს იწვევს. როდესაც ბავშვი იმდენად აღგზნებულია, რომ აღარ გისმენთ, შესაძლოა საკმარისად ეფექტური იყოს მკაფიოდ და მოკლედ თქმა, შემდეგ კი რეაქციის გარეშე დარჩენა. დასჯა ან ქმედებაზე საპასუხო ქმედება ამ დროს არა მხოლოდ არ იმუშავებს, არამედ მდგომარეობასაც გააუარესებს. ამიტომ, თუ არ იცით, როგორ მოიქცეთ ბავშვთან ასეთ სიტუაციაში, შეგიძლიათ სპეციალისტს მიმართოთ დახმარებისთვის.') WHERE id = '0e7d27d6-207f-40c2-bf3a-a953c053ee08';
UPDATE public.baby_daily_info SET info_ka = COALESCE(info_ka, 'იმის გაცნობიერებამ, რომ ბავშვმა ყოველდღიურად ყველა საკვები ნივთიერება საკმარისი რაოდენობით უნდა მიიღოს, შეიძლება ზოგჯერ დიდხანს გაფიქრებინოთ, რა მოუმზადოთ. ასეთ დროს პატარა და სახალისო ბოსტნეულის კექსების მომზადება არა მხოლოდ დააკმაყოფილებს ბავშვის ბოსტნეულის მოთხოვნილებას, არამედ მის ყურადღებასაც მიიპყრობს და ჭამის სურვილს გაუჩენს. მაგალითად: ყაბაყით, სტაფილოთი, კარტოფილითა და ბანანით მომზადებული კექსები, უჯრედისის შემცველობის წყალობით, ბავშვის საჭმლის მომნელებელი სისტემის მუშაობის მოწესრიგებას შეუწყობს ხელს. ბავშვისთვის განკუთვნილ პატარა ჯამში მოთავსებულ იოგურტში რკინით გამდიდრებული მარცვლეულისა და სეზონური ხილის დამატებაც შესანიშნავი კერძის იდეაა! 😊 სეზონური ხილი ერთ-ერთი საუკეთესო საკვები ჯგუფია, რომელიც ბავშვის ჯანსაღი წასახემსებლებისთვის შეგიძლიათ შეარჩიოთ. ამასთანავე, ბავშვის კალციუმზე მოთხოვნილების დასაკმაყოფილებლად დაჭრილ ხილს შეგიძლიათ გემრიელი ყველიც დაუმატოთ. ასე ბავშვს შესთავაზებთ კერძს, რომელიც ერთდროულად გემრიელიცაა და მისი განვითარებისთვისაც ძალიან სასარგებლო. გემრიელად მიირთვით! 😊') WHERE id = 'c5f5b4e2-b06a-4f2f-a220-d6fd136cfc41';